INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bash0C7/picotorokko/PicoRuby Development Constraints', 'PicoRuby Development Constraints', 'bash0C7', 'picotorokko', 'community', 'PicoRuby Development Constraints bash0C7 picotorokko community PicoRuby Development Constraints helps developers optimize memory usage for PicoRuby applications on ESP32 microcontrollers, ensuring efficient performance within strict limits. PicoRuby 开发约束是指在 ESP32 微控制器上开发 PicoRuby 应用时的内存和运行时限制 PicoRuby 開発制約は、ESP32 マイクロコントローラー上で PicoRuby アプリケーションを開発する際のメモリと実行時制約 PicoRuby 개발 제약 조건은 ESP32 마이크로 컨트롤러에서 PicoRuby 애플리케이션을 개발할 때의 메모리 및 실행 시간 제한을 말합니다 PicoRuby Development Constraints es un kit de desarrollo para aplicaciones PicoRuby que ejecutan en dispositivos ESP32 con microcontrolador ESP32 PicoRuby Development Constraints est un kit de développement pour les applications PicoRuby exécutées sur les appareils ESP32 avec microcontrôleur ESP32 PicoRuby Development Constraints ist ein Entwicklungskit für PicoRuby-Anwendungen, die auf ESP32-Geräten mit ESP32-Mikrocontroller ausgeführt werden O PicoRuby Development Constraints é um kit de desenvolvimento para aplicações PicoRuby que rodam no R2P2-ESP32 com dispositivo de microcontrolador ESP32. PicoRuby Development Constraints - это набор для разработки приложений PicoRuby, работающих на R2P2-ESP32 с устройством микроконтроллера ESP32 для ИИ Агентов PicoRuby Development Constraints هو مجموعة تطوير لتطبيقات PicoRuby التي تعمل على R2P2-ESP32 مع جهاز متحكم دقيق ESP32 لأدوات الذكاء الاصطناعي PicoRuby Development Constraints tutorial how to optimize PicoRuby memory usage PicoRuby vs CRuby comparison ESP32 microcontroller development PicoRuby Development Constraints setup guide R2P2-ESP32 device programming PicoRuby 开发 ESP32 微控制器 内存限制 运行时性能 AI エージェント开发 PicoRuby 应用开发 Enforces total heap limit of 520KB for efficient memory management Avoids deep recursion in favor of iterative solutions for nesting depth Optimizes string handling through pre-allocation and avoiding repeated concatenation Utilizes fixed-size arrays when possible to minimize dynamic growth during tight loops Provides comparison of PicoRuby and CRuby features for informed development decisions PicoRuby Development Constraints is a development kit for building PicoRuby applications on R2P2-ESP32 devices with ESP32 microcontrollers, addressing memory and runtime limitations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('JasonPaff/head-shakers/e2e-testing', 'community', 'JasonPaff', 'head-shakers', 'JasonPaff/head-shakers', 'e2e-testing', 0, 0, 23, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:53.088Z', '7e98c04e562089716aa5213864ee0f19cbdf3565603f565a8da13aa9ac51c279', '{"id":"JasonPaff/head-shakers/e2e-testing","name":"e2e-testing","description":{"en":"The e2e-testing skill provides end-to-end testing conventions for validating complete user flows with browser automation using Playwright, benefiting developers and QA engineers.","zh":"E2E 测试技能提供了使用 Playwright 的端到端测试约定，用于验证完整的用户流程","ja":"E2E テストスキルは Playwright を使用した端から端までのテスト規約を提供し、完全なユーザーフローを検証する","ko":"E2E 테스트 스킬은 Playwright를 사용한 종단간 테스트 규약을 제공하여 완전한 사용자 흐름을 검증합니다","es":"El skill de pruebas e2e proporciona convenciones de testing con Playwright para validar flujos de usuario completos","fr":"Le skill de tests e2e fournit des conventions de testing avec Playwright pour valider les flux d''utilisateur complets","de":"Das E2E-Testing-Skill bietet Testkonventionen mit Playwright, um komplexe Benutzerflüsse zu validieren","pt":"O skill de testes E2E fornece convenções de testes com Playwright para validação de fluxos de usuário","ru":"Навык E2E-тестирования предоставляет конвенции для тестирования с Playwright для проверки пользовательских потоков","ar":"مهارة الاختبارات من النهاية إلى النهاية توفر اتفاقيات للاختبار مع Playwright لتحقق من تدفقات المستخدم"},"seo":{"title":{"en":"e2e-testing: End-to-End Testing Setup Guide | AI Agent Skill","zh":"E2E 测试技能：Playwright 自动化测试设置指南","ja":"E2E テストスキル：Playwright を使用した自動テストのベストプラクティス","ko":"E2E 테스트 스킬: Playwright 자동화 테스트 설정 가이드","es":"Guía de configuración de pruebas e2e con Playwright","fr":"Guide de mise en place des tests e2e avec Playwright","de":"E2E-Testing-Setup-Leitfaden mit Playwright","pt":"Guia de Configuração de Testes E2E 