INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('finlaysonstudio/jaypie/ticket', 'ticket', 'finlaysonstudio', 'jaypie', 'community', 'ticket finlaysonstudio jaypie community The Ticket skill enables developers to work on GitHub issues end-to-end, using JavaScript, AWS, and the JSON:API specification. It benefits developers by streamlining issue tracking and resolution. Ticket Skill是一种事件驱动架构，中心使用JavaScript、AWS和JSON:API规范，用于GitHub问题的端到端处理 Ticket Skillは、JavaScript、AWS、JSON:API仕様を中心としたイベント駆動アーキテクチャで、GitHubの問題を端から端まで処理するために使用されます Ticket Skill은 JavaScript, AWS, JSON:API 규격을 중심으로 한 이벤트 驱動 아키텍처로 GitHub 문제를 끝까지 처리하는 데 사용됩니다 El ticket utiliza una arquitectura de eventos basada en JavaScript, AWS y la especificación JSON:API para gestionar GitHub issues de manera eficiente Le ticket utilise une architecture d''événements basée sur JavaScript, AWS et la spécification JSON:API pour gérer les problèmes GitHub de manière efficace Das Ticket verwendet eine ereignisgesteuerte Architektur basierend auf JavaScript, AWS und der JSON:API-Spezifikation für eine effiziente GitHub-Issue-Verwaltung A skill Ticket é uma arquitetura de eventos que utiliza JavaScript, AWS e JSON:API para gerenciar issues no GitHub. Ela permite trabalhar com issues de forma eficiente Навык Ticket - это событийная архитектура, которая использует JavaScript, AWS и JSON:API для управления проблемами в GitHub. Она позволяет работать с проблемами эффективно مهارة التذكرة هي هندسة حدث تستخدم جافا سكريبت وأمازون ويب سيرفس و JSON:API لإدارة المشاكل في جيت هاب. وهي تمكن من العمل مع المشاكل بفعالية how to use ticket ticket setup guide event-driven architecture with JSON:API github issue tracking with aws ticket alternative to jira ticket vs trello installing ticket for ai agents ticket tutorial for developers json:api specification for ticket Ticket Skill 事件驱动架构 JSON:API规范 JavaScript AWS GitHub AIエージェント 自动化测试 分支管理 Fetches GitHub issues using GitHub MCP Validates issue status to prevent duplicate work Writes failing tests to confirm issue reports Creates branches for fixes or features using Git Investigates and proposes solutions before implementation Ticket is an event-driven architecture centered around JavaScript, AWS, and the JSON:API specification, designed to manage GitHub issues efficiently.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xnopre/copro-tickets-tracker/accessibility-checker', 'community', 'xnopre', 'copro-tickets-tracker', 'xnopre/copro-tickets-tracker', 'accessibility-checker', 0, 0, 23, '2026-03-08T01:57:15.353Z', '2026-03-08T02:03:57.377Z', '3c3605379fc0ebe4234a5be3f380ea21e8a1cc347cdeb0e1b06effb622eeacd7', '{"id":"xnopre/copro-tickets-tracker/accessibility-checker","name":"accessibility-checker","description":{"en":"The accessibility-checker skill verifies WCAG 2.1 Level AA accessibility of React and HTML components, generating a structured report with scoring. It benefits developers in ensuring their components meet accessibility standards.","zh":"Accessibility Checker 是一个验证 React 和 HTML 组件无障碍性的工具，确保 WCAG 2.1 Level AA 标准的符合性。","ja":"アクセシビリティ チェッカーは、React と HTML コンポーネントの無障碍性を検証するツールで、WCAG 2.1 Level AA 準拠を確保します。","ko":"접근성 체커는 React와 HTML 컴포넌트의 접근성을 검증하는 도구로 WCAG 2.1 Level AA 표준을 준수합니다.","es":"Accessibility Checker verifica la accesibilidad de componentes React y HTML según las normas WCAG 2.1 Nivel AA. Genera informes estructurados para mejorar la experiencia del usuario","fr":"L''Accessibility Checker vérifie l''accessibilité des composants React et HTML selon les normes WCAG 2.1 Niveau AA. Il génère des rapports structurés pour améliorer l''expérience utilisateur","de":"Der Accessibility Checker überprüft die Barrierefreiheit von React- und HTML-Komponenten nach den Richtlinien WCAG 2.1 Stufe AA. Er erstellt strukturierte Berichte, um die Benutzererfahrung zu verbessern","pt":"O accessibility-checker é uma ferramenta que verifica a acessibilidade de componentes React e HTML de acordo com as regras WCAG 2.1 Level AA","ru":"ИИ Агент accessibility-checker проверяет доступность компонентов React и HTML на основе правил WCAG 2.1 Level AA","ar":"أداة الفحص الإلكترونية accessibility-checker تحقق من توافق مكونات React و HTML مع معايير WCAG 2.1 Level AA"},"seo":{"title":{"en":"accessibility-checker: WCAG 2.1 Compliance Setup Guide | ...","zh":"Accessibility Checker 设置指南 - 验证 React 和 HTML 组件的无障碍性","ja":"アクセシビリティ チェッカーのベスト プラクティス - React と HTML コンポーネントの WCAG 2....","ko":"접근성 체커 설정 가이드 - React와 HTML 컴포넌트의 WCAG 2.1_LEVEL_AA驗證","es":"Guía de configuración de Accessibility Checker para React","fr":"Guide de mise en place de l''Accessibility Checker pour le...","de":"Einrichtungsleitfaden für Accessibility Checker in React ...","pt":"Guia de Configuração do accessibility-checker para React","ru":"ИИ Агент accessibility-checker: Настройка и Правила","ar":"دليل إعداد أداة الفحص الإلكترونية accessibility-checker"},"description":{"en":"Verify React and HTML components'' accessibility with our AI agent skill. Learn how to implement WCAG 2.1 Level AA standards and generate structured reports","zh":"使用 Accessibility Checker 验证 React 和 HTML 组件的无障碍性，确保 WCAG 2.1 Level AA 标准的符合性，AIエージェント","ja":"アクセシビリティ チェッカーを使用して、React と HTML コンポーネントの無障碍性を検証し、WCAG 2.1 Level AA 準拠を確保します。AIエージェント","ko":"접근성 체커를 사용하여 React와 HTML 컴포넌트의 접근성을 검증하고 WCAG 2.1 Level AA 표준을 준수합니다. AI 도구","es":"Aprende a verificar la accesibilidad de tus componentes React y HTML con Accessibility Checker. Obtén informes estructurados y mejora la experiencia del usuario","fr":"Découvrez comment vérifier l''accessibilité de vos composants React et HTML avec l''Accessibility Checker. Générez des rapports structurés et améliorez l''expér...","de":"Erfahren Sie, wie Sie die Barrierefreiheit Ihrer React- und HTML-Komponenten mit dem Accessibility Checker überprüfen. Erstellen Sie strukturierte Berichte u...","pt":"Aprenda a configurar o accessibility-checker para garantir a acessibilidade WCAG 2.1 Level AA em componentes React e HTML","ru":"Узнайте, как настроить ИИ Агент accessibility-checker для проверки доступности компонентов React и HTML","ar":"تعرف على كيفية إعداد أداة الفحص الإلكترونية accessibility-checker لضمان توافق مكونات React و HTML مع معايير WCAG 2.1 Level AA"},"definition":{"en":"accessibility-checker is a skill that verifies the accessibility of React and HTML components against WCAG 2.1 Level AA standards, providing a detailed report","zh":"Accessibility Checker 是一个用于验证 Web 应用程序无障碍性的工具，特别是 React 和 HTML 组件。","ja":"アクセシビリティ チェッカーは、Web アプリケーションの無障碍性を検証するツールで、特に React と HTML コンポーネントの場合です。","ko":"접근성 체커는 Web 애플리케이션의 접근성을 검증하는 도구로 특히 React와 HTML 컴포넌트의 경우입니다.","es":"Herramienta de verificación de accesibilidad para componentes React y HTML que sigue las normas WCAG 2.1","fr":"Outil de vérification de l''accessibilité pour les composants React et HTML conformes aux normes WCAG 2.1","de":"Werkzeug zur Überprüfung der Barrierefreiheit von React- und HTML-Komponenten nach den WCAG 2.1-Richtlinien","pt":"O accessibility-checker é uma ferramenta que verifica a acessibilidade de componentes web","ru":"ИИ Агент accessibility-checker - это инструмент, проверяющий доступность веб-компонентов","ar":"أداة الفحص الإلكترونية accessibility-checker هي أداة لتحقق من توافق مكونات الويب"},"features":{"en":["Verifies semantic HTML and ARIA attributes for accessibility compliance","Checks forms, focus, and dates for WCAG 2.1 Level AA conformity","Generates a structured report with scoring for accessibility evaluation","References rules documented in .claude/rules/accessibility.md for precise criteria","Supports React and HTML components for accessibility checking"],"zh":["验证 React 和 HTML 组件的无障碍性","支持 WCAG 2.1 Level AA 标准","语义 HTML 和 ARIA 属性检查","表单、焦点和日期检查","生成结构化报告和评分"],"ja":["React と HTML コンポーネントの無障碍性を検証","WCAG 2.1 Level AA 準拠をサポート","シマンティック HTML と ARIA 属性のチェック","フォーム、フォーカス、日付のチェック","構造化レポートと評価の生成"],"ko":["React와 HTML 컴포넌트의 접근성을 검증","WCAG 2.1 Level AA 표준을 지원","의미론적 HTML과 ARIA 속성 체크","폼, 포커스, 날짜 체크","구조화된 보고서와 평가 생성"],"es":["Verificación de la accesibilidad según las normas WCAG 2.1 Nivel AA","Compatibilidad con componentes React y HTML","Generación de informes estructurados con puntuación","Soporte para atributos ARIA y HTML semántico","Verificación de formularios y enfoque","Cumplimiento de las fechas y los criterios de accesibilidad"],"fr":["Vérification de l''accessibilité selon les normes WCAG 2.1 Niveau AA","Compatibilité avec les composants React et HTML","Génération de rapports structurés avec notation","Prise en charge des attributs ARIA et du HTML sémantique","Vérification des formulaires et de la mise au point","Respect des dates et des critères d''accessibilité"],"de":["Überprüfung der Barrierefreiheit nach den Richtlinien WCAG 2.1 Stufe AA","Kompatibilität mit React- und HTML-Komponenten","Erstellung von strukturierten Berichten mit Punktzahl","Unterstützung für ARIA-Attribute und semantisches HTML","Überprüfung von Formularen und Fokus","Einhaltung von Terminen und Barrierefreiheitskriterien"],"pt":["Verificação de acessibilidade de componentes React e HTML","Compatibilidade com as regras WCAG 2.1 Level AA","Geração de relatórios estruturados com pontuação","Suporte a semantic HTML e atributos ARIA","Verificação de formulários e foco"],"ru":["Проверка доступности компонентов React и HTML","Совместимость с правилами WCAG 2.1 Level AA","Генерация структурированных отчетов с оценкой","Поддержка семантического HTML и атрибутов ARIA","Проверка форм и фокуса"],"ar":["التحقق من توافق مكونات React و HTML","التوافق مع معايير WCAG 2.1 Level AA","إعداد تقارير منظم مع التقييم","دعم HTML الدلالي والسمات ARIA","التحقق من النماذج والتركيز"]},"keywords":{"en":["how to use accessibility-checker","accessibility-checker setup guide","WCAG 2.1 Level AA compliance","accessibility-checker vs Lighthouse","accessibility-checker install","what is accessibility-checker","accessibility-checker alternative","accessibility-checker for React","accessibility-checker for HTML"],"zh":["Accessibility Checker","无障碍性验证","React","HTML","WCAG 2.1","AIエージェント","Web 접근성","无障碍性检查"],"ja":["アクセシビリティ チェッカー","無障碍性検証","React","HTML","WCAG 2.1","AIエージェント","Web 無障碍性","無障碍性チェック"],"ko":["접근성 체커","접근성 검증","React","HTML","WCAG 2.1","AI 도구","Web 접근성","접근성 체크"],"es":["Accessibility Checker","verificación de accesibilidad","WCAG 2.1","React","HTML","ARIA","informes de accesibilidad","mejora de la experiencia del usuario","herramientas de accesibilidad"],"fr":["Accessibility Checker","vérification de l''accessibilité","WCAG 2.1","React","HTML","ARIA","rapports d''accessibilité","amélioration de l''expérience utilisateur","outils d''accessibilité"],"de":["Accessibility Checker","Überprüfung der Barrierefreiheit","WCAG 2.1","React","HTML","ARIA","Barrierefreiheitsberichte","Verbesserung der Benutzererfahrung","Barrierefreiheitstools"],"pt":["accessibility-checker","WCAG 2.1 Level AA","React","HTML","acessibilidade web","ferramentas de acessibilidade","desenvolvimento web acessível"],"ru":["ИИ Агент accessibility-checker","WCAG 2.1 Level AA","React","HTML","доступность веб-сайтов","инструменты доступности","разработка доступных веб-сайтов"],"ar":["أداة الفحص الإلكترونية accessibility-checker","WCAG 2.1 Level AA","React","HTML","توافق مواقع الويب","أدوات الفحص الإلكترونية","تطوير مواقع الويب المتوافقة"]}},"owner":"xnopre","repo":"copro-tickets-tracker","repoPath":"xnopre/copro-tickets-tracker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.353Z","topics":[],"category":"community","skillMd":{"name":"accessibility-checker","description":"Verify accessibility (WCAG 2.1 Level AA) of React components. Use when creating UI components, forms, or when the user requests accessibility verification.","bodyPreview":"# Accessibility Checker\n\nYou verify WCAG 2.1 Level AA accessibility of React and HTML components.\n\n## Reference\n\nAll accessibility rules (semantic HTML, ARIA attributes, forms, focus, dates) are documented in `.claude/rules/accessibility.md`.\n\n**You MUST read this file** to understand the exact criteria to verify.\n\n## Your Role\n\n1. Read the provided component\n2. Verify each criterion defined in `.claude/rules/accessibility.md`\n3. Generate a structured report with scoring\n\n## Analysis Report\n\nAft","body":"# Accessibility Checker\n\nYou verify WCAG 2.1 Level AA accessibility of React and HTML components.\n\n## Reference\n\nAll accessibility rules (semantic HTML, ARIA attributes, forms, focus, dates) are documented in `.claude/rules/accessibility.md`.\n\n**You MUST read this file** to understand the exact criteria to verify.\n\n## Your Role\n\n1. Read the provided component\n2. Verify each criterion defined in `.claude/rules/accessibility.md`\n3. Generate a structured report with scoring\n\n## Analysis Report\n\nAfter verification, generate a structured report. See [examples.md](./examples.md) for the complete template.\n\n## Resources\n\n- [WCAG 2.1 Guidelines](https://www.w3.org/WAI/WCAG21/quickref/)\n- [ARIA Authoring Practices](https://www.w3.org/WAI/ARIA/apg/)\n- See [CLAUDE.md](../../../CLAUDE.md) for complete project rules\n\n## See Also\n\n- **[test-writer](../test-writer/SKILL.md)** — Write accessibility tests (ARIA attributes, semantic HTML, keyboard navigation) to verify WCAG compliance automatically. Pair with accessibility-checker for comprehensive coverage.\n"},"lastSynced":"2026-03-08T02:03:57.377Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing advanced accessibility auditing capabilities for React and HTML components.","zh":"适用于需要高级可访问性审计功能的前端代理，特别是针对 React 和 HTML 组件。","ja":"React および HTML コンポーネントの高度なアクセシビリティ監査機能を必要とするフロントエンド エージェントに最適です。","ko":"React 및 HTML 구성 요소에 대한 고급 접근성 감사 기능이 필요한 프런트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes frontend que necesitan capacidades de auditoría de accesibilidad avanzadas para React y componentes HTML.","fr":"Parfait pour les agents frontend ayant besoin de fonctionnalités d''audit d''accessibilité avancées pour React et les composants HTML.","de":"Perfekt für Frontend-Agents, die erweiterte Barrierefreiheits-Prüfkapazitäten für React und HTML-Komponenten benötigen.","pt":"Perfeito para Agentes Frontend que precisam de capacidades avançadas de auditoria de acessibilidade para React e componentes HTML.","ru":"Идеально подходит для агентов Frontend, которым необходимы расширенные возможности аудита доступности для React и компонентов HTML.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى قدرات متقدمة للتدقيق من حيث إمكانية الوصول إلى مكونات React و HTML."},"recommendation":{"en":"Empowers agents to verify WCAG 2.1 Level AA accessibility standards, utilizing semantic HTML, ARIA attributes, and generating structured reports with scoring, all based on criteria defined in `.claude/rules/accessibility.md`.","zh":"赋予代理验证 WCAG 2.1 Level AA 可访问性标准的能力，利用语义 HTML、ARIA 属性，并生成带有评分的结构化报告，所有这些都基于 `.claude/rules/accessibility.md` 中定义的标准。","ja":"WCAG 2.1 Level AA アクセシビリティ標準を検証するエージェントの能力を提供し、セマンティック HTML、ARIA 属性を使用し、スコアリングを含む構造化レポートを生成します。これらはすべて、`.claude/rules/accessibility.md` で定義された基準に基づいています。","ko":"WCAG 2.1 Level AA 접근성 표준을 검증할 수 있는 에이전트의 능력을 제공하며, 의미론적 HTML, ARIA 속성을 사용하여 점수화된 구조화된 보고서를 생성하며, 모든 것은 `.claude/rules/accessibility.md`에서 정의된 기준에 기반합니다.","es":"Habilita a los agentes a verificar los estándares de accesibilidad WCAG 2.1 Nivel AA, utilizando HTML semántico, atributos ARIA y generando informes estructurados con puntuación, todos basados en los criterios definidos en `.claude/rules/accessibility.md`.","fr":"Permet aux agents de vérifier les normes d''accessibilité WCAG 2.1 Niveau AA, en utilisant du HTML sémantique, des attributs ARIA et en générant des rapports structurés avec notation, le tout basé sur les critères définis dans `.claude/rules/accessibility.md`.","de":"Ermöglicht es den Agenten, die Barrierefreiheitsstandards WCAG 2.1 Stufe AA zu überprüfen, indem sie semantisches HTML, ARIA-Attribute und strukturierte Berichte mit Bewertung verwenden, alle basierend auf den in `.claude/rules/accessibility.md` definierten Kriterien.","pt":"Habilita os agentes a verificar padrões de acessibilidade WCAG 2.1 Nível AA, utilizando HTML semântico, atributos ARIA e gerando relatórios estruturados com pontuação, todos baseados nos critérios definidos em `.claude/rules/accessibility.md`.","ru":"Наделяет агентов возможностью проверять стандарты доступности WCAG 2.1 Уровень AA, используя семантический HTML, атрибуты ARIA и генерируя структурированные отчеты со счетом, все на основе критериев, определенных в `.claude/rules/accessibility.md`.","ar":"يمنح الوكلاء القدرة على التحقق من معايير إمكانية الوصول WCAG 2.1 المستوى AA، باستخدام HTML الدلالي وسمات ARIA وتوليد تقارير منظمّة مع التقييم، وكل ذلك يستند إلى المعايير المحددة في `.claude/rules/accessibility.md`."},"useCases":{"en":["Automating accessibility audits for React components","Generating compliance reports for HTML elements","Debugging accessibility issues in web applications"],"zh":["自动化 React 组件的可访问性审计","为 HTML 元素生成合规报告","调试 Web 应用中的可访问性问题"],"ja":["React コンポーネントのアクセシビリティ監査を自動化する","HTML 要素のコンプライアンス レポートを生成する","Web アプリケーションのアクセシビリティの問題をデバッグする"],"ko":["React 구성 요소의 접근성 감사 자동화","HTML 요소의 규정 준수 보고서 생성","웹 애플리케이션의 접근성 문제 디버깅"],"es":["Automatizar auditorías de accesibilidad para componentes React","Generar informes de cumplimiento para elementos HTML","Depurar problemas de accesibilidad en aplicaciones web"],"fr":["Automatiser les audits d''accessibilité pour les composants React","Générer des rapports de conformité pour les éléments HTML","Déboguer les problèmes d''accessibilité dans les applications Web"],"de":["Automatisieren von Barrierefreiheits-Prüfungen für React-Komponenten","Generieren von Konformitätsberichten für HTML-Elemente","Beheben von Barrierefreiheitsproblemen in Webanwendungen"],"pt":["Automatizar auditorias de acessibilidade para componentes React","Gerar relatórios de conformidade para elementos HTML","Depurar problemas de acessibilidade em aplicativos web"],"ru":["Автоматизировать аудит доступности для компонентов React","Генерировать отчеты о соответствии для элементов HTML","Отладить проблемы доступности в веб-приложениях"],"ar":["تحويل تدقيق إمكانية الوصول تلقائيًا لمكونات React","توليد تقارير 符合 لمكونات HTML","تصحيح الأعطال المتعلقة بإمكانية الوصول في التطبيقات الإلكترونية"]},"limitations":{"en":["Requires knowledge of `.claude/rules/accessibility.md` criteria","Limited to React and HTML components","WCAG 2.1 Level AA standards only"],"zh":["需要了解 `.claude/rules/accessibility.md` 中的标准","仅限 React 和 HTML 组件","仅支持 WCAG 2.1 Level AA 标准"],"ja":["`.claude/rules/accessibility.md` の基準を理解する必要がある","React および HTML コンポーネントのみ","WCAG 2.1 Level AA 標準のみをサポートする"],"ko":["`.claude/rules/accessibility.md`의 기준을 이해해야 함","React 및 HTML 구성 요소만","WCAG 2.1 Level AA 표준만 지원"],"es":["Requiere conocimiento de los criterios de `.claude/rules/accessibility.md`","Limitado a componentes React y HTML","Estándares WCAG 2.1 Nivel AA solo"],"fr":["Nécessite une connaissance des critères de `.claude/rules/accessibility.md`","Limité aux composants React et HTML","Normes WCAG 2.1 Niveau AA uniquement"],"de":["Benötigt Kenntnis der Kriterien in `.claude/rules/accessibility.md`","Begrenzt auf React- und HTML-Komponenten","WCAG 2.1-Stufe-AA-Standards nur"],"pt":["Requer conhecimento dos critérios definidos em `.claude/rules/accessibility.md`","Limitado a componentes React e HTML","Padrões WCAG 2.1 Nível AA apenas"],"ru":["Требует знания критериев, определенных в `.claude/rules/accessibility.md`","Ограничен компонентами React и HTML","Только стандарты WCAG 2.1 Уровень AA"],"ar":["يتطلب معرفة بالمعايير المحددة في `.claude/rules/accessibility.md`","محدود بمكونات React و HTML","معايير WCAG 2.1 المستوى AA فقط"]},"version":4},"contentHash":"3c3605379fc0ebe4234a5be3f380ea21e8a1cc347cdeb0e1b06effb622eeacd7","qualityScore":23}');
