INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xnopre/copro-tickets-tracker/accessibility-checker', 'accessibility-checker', 'xnopre', 'copro-tickets-tracker', 'community', 'accessibility-checker xnopre copro-tickets-tracker community The accessibility-checker skill verifies WCAG 2.1 Level AA accessibility of React and HTML components, generating a structured report with scoring. It benefits developers in ensuring their components meet accessibility standards. Accessibility Checker 是一个验证 React 和 HTML 组件无障碍性的工具，确保 WCAG 2.1 Level AA 标准的符合性。 アクセシビリティ チェッカーは、React と HTML コンポーネントの無障碍性を検証するツールで、WCAG 2.1 Level AA 準拠を確保します。 접근성 체커는 React와 HTML 컴포넌트의 접근성을 검증하는 도구로 WCAG 2.1 Level AA 표준을 준수합니다. Accessibility Checker verifica la accesibilidad de componentes React y HTML según las normas WCAG 2.1 Nivel AA. Genera informes estructurados para mejorar la experiencia del usuario L''Accessibility Checker vérifie l''accessibilité des composants React et HTML selon les normes WCAG 2.1 Niveau AA. Il génère des rapports structurés pour améliorer l''expérience utilisateur Der Accessibility Checker überprüft die Barrierefreiheit von React- und HTML-Komponenten nach den Richtlinien WCAG 2.1 Stufe AA. Er erstellt strukturierte Berichte, um die Benutzererfahrung zu verbessern O accessibility-checker é uma ferramenta que verifica a acessibilidade de componentes React e HTML de acordo com as regras WCAG 2.1 Level AA ИИ Агент accessibility-checker проверяет доступность компонентов React и HTML на основе правил WCAG 2.1 Level AA أداة الفحص الإلكترونية accessibility-checker تحقق من توافق مكونات React و HTML مع معايير WCAG 2.1 Level AA how to use accessibility-checker accessibility-checker setup guide WCAG 2.1 Level AA compliance accessibility-checker vs Lighthouse accessibility-checker install what is accessibility-checker accessibility-checker alternative accessibility-checker for React accessibility-checker for HTML Accessibility Checker 无障碍性验证 React HTML WCAG 2.1 AIエージェント Web 접근성 无障碍性检查 Verifies semantic HTML and ARIA attributes for accessibility compliance Checks forms, focus, and dates for WCAG 2.1 Level AA conformity Generates a structured report with scoring for accessibility evaluation References rules documented in .claude/rules/accessibility.md for precise criteria Supports React and HTML components for accessibility checking accessibility-checker is a skill that verifies the accessibility of React and HTML components against WCAG 2.1 Level AA standards, providing a detailed report');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('workadventure/workadventure/translate', 'community', 'workadventure', 'workadventure', 'workadventure/workadventure', 'translate', 0, 0, 23, '2026-03-08T01:57:15.370Z', '2026-03-08T02:04:26.875Z', 'fe60f66f88cda7425fca2402811b83224d421cfad62b393b296a3882802bf130', '{"id":"workadventure/workadventure/translate","name":"translate","description":{"en":"Translate is a collaborative web application that simplifies internationalization workflows for developers, using commands like `npm run i18n:diff` to identify missing keys","zh":"Translate 是一个多语言支持的协作网页应用，使用 i18n diff 命令来管理多语言键值","ja":"Translate は多言語対応のコラボレーションウェブアプリケーションで、i18n diff コマンドを使用して多言語キーの管理を行います","ko":"Translate 는 다국어 지원协作 웹 애플리케이션으로, i18n diff 명령을 사용하여 다국어 키 값을 관리합니다","es":"El skill translate permite la colaboración en aplicaciones web mediante la traducción de claves de internacionalización","fr":"Le skill translate permet la collaboration dans les applications web via la traduction de clés d''internationalisation","de":"Das translate-Skill ermöglicht die Zusammenarbeit in Webanwendungen durch die Übersetzung von Internationalisierungsschlüsseln","pt":"A ferramenta de tradução do agente de IA é uma aplicação web colaborativa que executa i18n diff e edita arquivos de locale","ru":"Инструмент перевода ИИ Агентов - это совместное веб-приложение, которое выполняет i18n diff и редактирует файлы локали","ar":"أداة الترجمة للوكلاء الذكية هي تطبيق ويب تعاوني يقوم بتشغيل i18n diff و تحرير ملفات اللغة المحلية"},"seo":{"title":{"en":"Translate: i18n Workflow Setup Guide | AI Agent Skill","zh":"Translate 设定指南 - 多语言支持和 i18n 工作流","ja":"Translate セットアップガイド - 多言語対応と i18n ワークフロー","ko":"Translate 설정 가이드 - 다국어 지원 및 i18n 워크플로우","es":"Guía de configuración de translate para Herramientas de I...","fr":"Guide de configuration de translate pour Outils d''Intelli...","de":"Konfigurationsleitfaden für translate bei KI-Tools","pt":"Guia de Configuração do Ferramenta de Tradução de Agente ...","ru":"Настройка Перевода ИИ Агентов: Руководство","ar":"دليل إعداد أداة الترجمة للوكلاء الذكية"},"description":{"en":"Streamline your i18n workflow with Translate - learn how to run i18n diff, manage locale files, and optimize translations with a few simple commands","zh":"了解 Translate 的技术细节，包括 i18n diff 命令和多语言支持","ja":"Translate の技術的詳細を学び、i18n diff コマンドや多言語対応についてご紹介します","ko":"Translate 의 기술적 세부 사항을 알아보세요. i18n diff 명령 및 다국어 지원에 대해介绍합니다","es":"Aprende a configurar translate en tu aplicación web colaborativa y optimiza la experiencia del usuario con nuestra guía paso a paso","fr":"Découvrez comment configurer translate dans votre application web collaborative et améliorez l''expérience utilisateur avec notre guide étape par étape","de":"Erfahren Sie, wie Sie translate in Ihrer kollaborativen Webanwendung konfigurieren und die Benutzererfahrung optimieren können","pt":"Aprenda a configurar a ferramenta de tradução para agentes de IA, incluindo i18n diff e edição de arquivos de locale","ru":"Узнайте, как настроить инструмент перевода для ИИ Агентов, включая i18n diff и редактирование файлов локали","ar":"تعلم كيفية إعداد أداة الترجمة للوكلاء الذكية، بما في ذلك i18n diff و تحرير ملفات اللغة المحلية"},"definition":{"en":"Translate is a collaborative web application presented as a 16-bit RPG video game, streamlining i18n workflows","zh":"Translate 是一种多语言支持的 AI 工具，使用 i18n 技术来管理多语言内容","ja":"Translate は多言語対応の AI エージェントで、i18n 技術を使用して多言語コンテンツを管理します","ko":"Translate 는 다국어 지원 AI 도구로, i18n 기술을 사용하여 다국어 콘텐츠를 관리합니다","es":"El skill translate es una función que permite la traducción de claves de internacionalización en aplicaciones web colaborativas","fr":"Le skill translate est une fonction qui permet la traduction de clés d''internationalisation dans les applications web collaboratives","de":"Das translate-Skill ist eine Funktion, die die Übersetzung von Internationalisierungsschlüsseln in kollaborativen Webanwendungen ermöglicht","pt":"A ferramenta de tradução é uma tecnologia que permite a tradução de textos em diferentes idiomas","ru":"Инструмент перевода - это технология, которая позволяет переводить тексты на различные языки","ar":"أداة الترجمة هي تكنولوجيا تمكن من ترجمة النصوص إلى لغات مختلفة"},"features":{"en":["Runs i18n diff to list missing keys via `npm run i18n:diff` command","Supports single locale checks with `npm run i18n:diff -- <locale>`","Allows scripted/batched edits across locale files to reduce context churn","Enables spot-checking of one locale after batch edits","Manages locale files under `play/src/i18n/<locale>/` directory"],"zh":["使用 i18n diff 命令来识别缺失的多语言键值","支持多语言编辑和批量编辑","使用 Node.js 和 sed 脚本来自动化多语言编辑","支持多语言文件结构和内容确认","使用 npm run i18n:diff 命令来运行 i18n diff"],"ja":["i18n diff コマンドを使用して不足している多言語キーの識別","多言語編集とバッチ編集のサポート","Node.js と sed スクリプトを使用した多言語編集の自動化","多言語ファイル構造と内容の確認のサポート","npm run i18n:diff コマンドを使用して i18n diff を実行"],"ko":["i18n diff 명령을 사용하여 다국어 키 값의 부족을 식별","다국어 편집과 일괄 편집 지원","Node.js 와 sed 스크립트를 사용하여 다국어 편집 자동화","다국어 파일 구조와 내용 확인 지원","npm run i18n:diff 명령을 사용하여 i18n diff 실행"],"es":["Ejecución de i18n diff para listar claves faltantes","Edición por lotes de claves de internacionalización","Confirmación de estructura de archivos de locale","Uso de comandos npm para la configuración de translate","Compatibilidad con múltiples locales"],"fr":["Exécution de i18n diff pour lister les clés manquantes","Édition par lots de clés d''internationalisation","Confirmation de la structure des fichiers de locale","Utilisation de commandes npm pour la configuration de translate","Compatibilité avec plusieurs locales"],"de":["Ausführung von i18n diff zur Auflistung fehlender Schlüssel","Batch-Bearbeitung von Internationalisierungsschlüsseln","Bestätigung der Struktur von Locale-Dateien","Verwendung von npm-Befehlen für die Konfiguration von translate","Unterstützung für mehrere Locale"],"pt":["Execução de i18n diff para listar chaves ausentes","Edição de arquivos de locale em diferentes idiomas","Uso de comandos npm para gerenciar a tradução","Suporte a múltiplos idiomas","Integração com aplicativos web colaborativos"],"ru":["Выполнение i18n diff для списка отсутствующих ключей","Редактирование файлов локали на разных языках","Использование команд npm для управления переводом","Поддержка нескольких языков","Интеграция с совместными веб-приложениями"],"ar":["تشغيل i18n diff لاستعراض المفاتيح الناقصة","تحرير ملفات اللغة المحلية باللغات المختلفة","استخدام أوامر npm لإدارة الترجمة","دعم اللغات المتعددة","التكامل مع التطبيقات الويب التعاونية"]},"keywords":{"en":["how to use translate","translate setup guide","i18n workflow optimization","translate alternative","translate vs localization tools","npm run i18n diff","translate install","what is translate","translate for developers","i18n diff command"],"zh":["Translate 设定","i18n diff 命令","多语言支持","AI 工具","协作网页应用","Node.js","sed 脚本","npm run i18n:diff"],"ja":["Translate セットアップ","i18n diff コマンド","多言語対応","AI エージェント","コラボレーションウェブアプリケーション","Node.js","sed スクリプト","npm run i18n:diff"],"ko":["Translate 설정","i18n diff 명령","다국어 지원","AI 도구","协作 웹 애플리케이션","Node.js","sed 스크립트","npm run i18n:diff"],"es":["Herramientas de Inteligencia Artificial","translate en aplicaciones web","i18n diff","npm run i18n:diff","configuración de translate","colaboración en aplicaciones web","traducción de claves de internacionalización"],"fr":["Outils d''Intelligence Artificielle","translate dans les applications web","i18n diff","npm run i18n:diff","configuration de translate","collaboration dans les applications web","traduction de clés d''internationalisation"],"de":["KI-Tools","translate in Webanwendungen","i18n diff","npm run i18n:diff","Konfiguration von translate","Zusammenarbeit in Webanwendungen","Übersetzung von Internationalisierungsschlüsseln"],"pt":["ferramenta de tradução","agente de IA","i18n diff","edição de arquivos de locale","tradução de textos","tecnologia de tradução","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["инструмент перевода","ИИ Агенты","i18n diff","редактирование файлов локали","перевод текстов","технология перевода","разработка программного обеспечения","инструменты разработки"],"ar":["أداة الترجمة","الوكلاء الذكية","i18n diff","تحرير ملفات اللغة المحلية","ترجمة النصوص","تكنولوجيا الترجمة","تطوير البرمجيات","أدوات التطوير"]}},"owner":"workadventure","repo":"workadventure","repoPath":"workadventure/workadventure","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.370Z","topics":[],"category":"community","skillMd":{"name":"translate","description":"Fill missing WorkAdventure i18n translations by running the i18n diff in play/ and updating locale files under play/src/i18n. Use when asked to run npm run i18n:diff, fix missing translation keys, or complete locale modules.","bodyPreview":"# Translate\n\n## Workflow\n\n1. Run the i18n diff to list missing keys.\n   - Command: `cd play && npm run i18n:diff`\n   - Single locale: `cd play && npm run i18n:diff -- <locale>`\n2. If multiple locales are missing the same keys, prefer a single, scripted/batched edit across locale files to reduce context churn (e.g., a small node/sed script), then spot-check one locale.\n3. Open the reported locale files under `play/src/i18n/<locale>/` only as needed to confirm structure.\n4. For each missing key:","body":"# Translate\n\n## Workflow\n\n1. Run the i18n diff to list missing keys.\n   - Command: `cd play && npm run i18n:diff`\n   - Single locale: `cd play && npm run i18n:diff -- <locale>`\n2. If multiple locales are missing the same keys, prefer a single, scripted/batched edit across locale files to reduce context churn (e.g., a small node/sed script), then spot-check one locale.\n3. Open the reported locale files under `play/src/i18n/<locale>/` only as needed to confirm structure.\n4. For each missing key:\n   - Look at the `en-US` translation first. If unsure, look at the `fr-FR` translation too.\n   - If unsure, ask the user precisions before translating.\n5. Re-run the diff command until it reports no missing translations.\n\n## Conventions\n\n- `en-US` is the source of truth. Use it to find the canonical string and structure.\n- Preserve formatting, placeholders, and variable names exactly (e.g., `{name}`, `{count}`).\n- Keep file formatting consistent with the existing module (4 spaces, newline at EOF).\n"},"lastSynced":"2026-03-08T02:04:26.875Z","agentAnalysis":{"suitability":{"en":"Ideal for Multilingual Agents requiring streamlined internationalization workflows and npm command integration.","zh":"适合需要简化国际化工作流程和npm命令集成的多语言代理。","ja":"マルチリンガルエージェントがストリームライン化された国際化ワークフローとnpmコマンド統合を必要とする場合に最適です。","ko":"다국어 에이전트가简化된 국제화 워크플로 및 npm 명령 통합을 필요로 할 때 적합합니다.","es":"Ideal para agentes multilingües que requieren flujos de trabajo de internacionalización optimizados y integración de comandos npm.","fr":"Idéal pour les agents multilingues nécessitant des flux de travail d''internationalisation rationalisés et une intégration de commandes npm.","de":"Ideal für mehrsprachige Agenten, die optimierte Internationalisierungsworkflows und npm-Befehlsintegration erfordern.","pt":"Ideal para Agentes Multilíngues que exigem fluxos de trabalho de internacionalização otimizados e integração de comandos npm.","ru":"Идеально для Мультяшных Агентов, требующих оптимизированных рабочих процессов интернационализации и интеграции команд npm.","ar":"مثالي لعميل متعدد اللغات الذي يتطلب تيار عمل دولي موحد وتكامل أوامر npm."},"recommendation":{"en":"Empowers agents to automate i18n diff analysis using commands like `npm run i18n:diff`, simplifying the identification of missing keys across multiple locales, and leveraging node/sed scripts for batched edits.","zh":"赋予代理人使用命令（如`npm run i18n:diff`）自动执行i18n差异分析的能力，简化跨多个语言环境缺失键的识别，并利用node/sed脚本进行批量编辑。","ja":"エージェントがコマンド（例： `npm run i18n:diff`）を使用してi18n差分分析を自動化する機能を提供し、複数のロケール間で欠落しているキーの識別を簡素化し、node/sedスクリプトを使用してバッチ編集を行う。","ko":"에이전트가 명령어（예: `npm run i18n:diff`）를 사용하여 i18n 차이 분석을 자동화 할 수 있는 기능을 제공하여 여러 로케일 간에 누락 된 키를 식별하는 것을 단순화하고 node/sed 스크립트를 사용하여 일괄 편집을 수행한다.","es":"Habilita a los agentes a automatizar el análisis de diferencias i18n utilizando comandos como `npm run i18n:diff`, simplificando la identificación de claves ausentes en varios locales, y aprovechando scripts node/sed para ediciones por lotes.","fr":"Permet aux agents d''automatiser l''analyse des différences i18n à l''aide de commandes comme `npm run i18n:diff`, simplifiant l''identification des clés manquantes dans plusieurs locales, et exploitant les scripts node/sed pour les éditions par lots.","de":"Ermöglicht es Agenten, die i18n-Diff-Analyse mithilfe von Befehlen wie `npm run i18n:diff` zu automatisieren, wodurch die Identifizierung fehlender Schlüssel in mehreren Ländern vereinfacht und node/sed-Skripte für Chargenbearbeitungen genutzt werden.","pt":"Habilita agentes a automatizar a análise de diferenças i18n usando comandos como `npm run i18n:diff`, simplificando a identificação de chaves ausentes em vários locais, e aproveitando scripts node/sed para edições em lote.","ru":"Наделяет агентов возможностью автоматизировать анализ различий i18n с помощью команд, таких как `npm run i18n:diff`, что упрощает выявление отсутствующих ключей в нескольких локализациях, и использует скрипты node/sed для пакетных правок.","ar":"تمكّن الوكيل من автоматية تحليل الفروقات i18n باستخدام أوامر مثل `npm run i18n:diff`، مبسطًا تحديد المفاتيح الناقصة عبر عدة مواقع، واستخدام سكريبتات node/sed للتعديلات المجمعة."},"useCases":{"en":["Automating i18n diff analysis to identify missing keys","Generating batched edits for multiple locales using node/sed scripts","Streamlining internationalization workflows for developers"],"zh":["自动执行i18n差异分析以识别缺失的键","使用node/sed脚本为多个语言环境生成批量编辑","简化开发人员的国际化工作流程"],"ja":["i18n差分分析を自動化して欠落しているキーを識別する","複数のロケールのバッチ編集をnode/sedスクリプトを使用して生成する","開発者の国際化ワークフローを簡素化する"],"ko":["i18n 차이 분석을 자동화하여 누락 된 키를 식별하는 것","node/sed 스크립트를 사용하여 여러 로케일의 일괄 편집을 생성하는 것","개발자를 위한 국제화 워크플로우를 단순화하는 것"],"es":["Automatizar el análisis de diferencias i18n para identificar claves ausentes","Generar ediciones por lotes para varios locales utilizando scripts node/sed","Optimizar los flujos de trabajo de internacionalización para los desarrolladores"],"fr":["Automatiser l''analyse des différences i18n pour identifier les clés manquantes","Générer des éditions par lots pour plusieurs locales à l''aide de scripts node/sed","Rationaliser les flux de travail d''internationalisation pour les développeurs"],"de":["Automatisierung der i18n-Diff-Analyse zur Identifizierung fehlender Schlüssel","Erzeugen von Chargenbearbeitungen für mehrere Länder mit node/sed-Skripten","Optimierung der Internationalisierungsworkflows für Entwickler"],"pt":["Automatizar a análise de diferenças i18n para identificar chaves ausentes","Gerar edições em lote para vários locais usando scripts node/sed","Otimizar fluxos de trabalho de internacionalização para desenvolvedores"],"ru":["Автоматизировать анализ различий i18n для выявления отсутствующих ключей","Генерировать пакетные правки для нескольких локализаций с помощью скриптов node/sed","Оптимизировать рабочие процессы интернационализации для разработчиков"],"ar":["تأتمتة تحليل الفروقات i18n لتحديد المفاتيح الناقصة","توليد تعديلات مجمعة لمواقع متعددة باستخدام سكريبتات node/sed","تسهيل سير عمل التدويل للمطوّرين"]},"limitations":{"en":["Requires npm environment","Limited to locale files under `play/src/i18n/<locale>/`"],"zh":["需要npm环境","仅限于`play/src/i18n/<locale>/`下的语言环境文件"],"ja":["npm環境が必要","`play/src/i18n/<locale>/`以下のロケールファイルに限定される"],"ko":["npm 환경이 필요함","`play/src/i18n/<locale>/`하위의 로케일 파일로 제한됨"],"es":["Requiere entorno npm","Limitado a archivos de locale bajo `play/src/i18n/<locale>/`"],"fr":["Nécessite un environnement npm","Limité aux fichiers de locale sous `play/src/i18n/<locale>/`"],"de":["Benötigt npm-Umgebung","Begrenzt auf Locale-Dateien unter `play/src/i18n/<locale>/`"],"pt":["Exige ambiente npm","Limitado a arquivos de locale em `play/src/i18n/<locale>/`"],"ru":["Требует среды npm","Ограничен файлами локализации в `play/src/i18n/<locale>/`"],"ar":["يتطلب بيئة npm","محدود بملفات التدويل في `play/src/i18n/<locale>/`"]},"version":4},"contentHash":"fe60f66f88cda7425fca2402811b83224d421cfad62b393b296a3882802bf130","qualityScore":23}');
