INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('workadventure/workadventure/translate', 'translate', 'workadventure', 'workadventure', 'community', 'translate workadventure workadventure community Translate is a collaborative web application that simplifies internationalization workflows for developers, using commands like `npm run i18n:diff` to identify missing keys Translate 是一个多语言支持的协作网页应用，使用 i18n diff 命令来管理多语言键值 Translate は多言語対応のコラボレーションウェブアプリケーションで、i18n diff コマンドを使用して多言語キーの管理を行います Translate 는 다국어 지원协作 웹 애플리케이션으로, i18n diff 명령을 사용하여 다국어 키 값을 관리합니다 El skill translate permite la colaboración en aplicaciones web mediante la traducción de claves de internacionalización Le skill translate permet la collaboration dans les applications web via la traduction de clés d''internationalisation Das translate-Skill ermöglicht die Zusammenarbeit in Webanwendungen durch die Übersetzung von Internationalisierungsschlüsseln A ferramenta de tradução do agente de IA é uma aplicação web colaborativa que executa i18n diff e edita arquivos de locale Инструмент перевода ИИ Агентов - это совместное веб-приложение, которое выполняет i18n diff и редактирует файлы локали أداة الترجمة للوكلاء الذكية هي تطبيق ويب تعاوني يقوم بتشغيل i18n diff و تحرير ملفات اللغة المحلية how to use translate translate setup guide i18n workflow optimization translate alternative translate vs localization tools npm run i18n diff translate install what is translate translate for developers i18n diff command Translate 设定 i18n diff 命令 多语言支持 AI 工具 协作网页应用 Node.js sed 脚本 npm run i18n:diff Runs i18n diff to list missing keys via `npm run i18n:diff` command Supports single locale checks with `npm run i18n:diff -- <locale>` Allows scripted/batched edits across locale files to reduce context churn Enables spot-checking of one locale after batch edits Manages locale files under `play/src/i18n/<locale>/` directory Translate is a collaborative web application presented as a 16-bit RPG video game, streamlining i18n workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eclipse-rdf4j/rdf4j/mvnf', 'community', 'eclipse-rdf4j', 'rdf4j', 'eclipse-rdf4j/rdf4j', 'mvnf', 0, 0, 23, '2026-03-08T01:57:15.371Z', '2026-03-08T02:04:27.055Z', '861d2721ad2c42506e3aafd8006dffa6334c0c33627fa25f37cffd67cdcdbeaf', '{"id":"eclipse-rdf4j/rdf4j/mvnf","name":"mvnf","description":{"en":"mvnf is a skill that automates Maven tests with repeatable commands and provides useful failure pointers for Java developers. It supports running module test suites, unit tests, and integration tests.","zh":"mvnf是一种运行Maven测试的工具，支持可重复的命令和有用的失败指针，适用于Eclipse RDF4J开发","ja":"mvnfはMavenテストを実行するツールで、再現可能なコマンドと有用的な失敗ポインターをサポートします。Eclipse RDF4J開発向け","ko":"mvnf는 Maven 테스트를 실행하는 도구로, 반복 가능한 명령과 유용한 실패 포인터를 지원하며 Eclipse RDF4J 개발에 적합합니다","es":"mvnf es una herramienta para ejecutar pruebas de Maven con comandos repetibles y útiles indicadores de fallos. Permite ejecutar pruebas unitarias y de integración con facilidad.","fr":"mvnf est un outil pour exécuter des tests Maven avec des commandes répétitives et des indicateurs de défaillance utiles. Il permet d''exécuter des tests unitaires et d''intégration avec facilité.","de":"mvnf ist ein Tool zum Ausführen von Maven-Tests mit wiederholbaren Befehlen und nützlichen Fehlernachweisen. Es ermöglicht die Ausführung von Unit-Tests und Integrations-Tests mit Leichtigkeit.","pt":"O mvnf é uma ferramenta que permite executar testes Maven com comandos repetíveis e ponteiros de falha úteis. É ideal para desenvolvedores que precisam testar seus projetos de forma eficiente.","ru":"ИИ Агент mvnf - это инструмент, который позволяет запускать тесты Maven с повторяющимися командами и полезными указателями на сбой. Он идеален для разработчиков, которым необходимо тестировать свои проекты эффективно.","ar":"mvnf هو أداة تسمح بتشغيل اختبارات Maven مع أوامر قابلة للتكرار وملحقات فشل مفيدة. وهي مثالية للمطورين الذين يحتاجون إلى اختبار مشاريعهم بفعالية"},"seo":{"title":{"en":"mvnf: Maven Test Automation Setup Guide | AI Agent Skill","zh":"mvnf.setup指南：Eclipse RDF4J Maven测试","ja":"mvnfセットアップガイド：Eclipse RDF4J Mavenテスト","ko":"mvnf 설정 가이드: Eclipse RDF4J Maven 테스트","es":"mvnf: Guía de configuración para pruebas de Maven con com...","fr":"mvnf: Guide de démarrage pour les tests Maven avec comman...","de":"mvnf: Einrichtungsleitfaden für Maven-Tests mit wiederhol...","pt":"Guia de Configuração mvnf: Executando Testes Maven com Co...","ru":"ИИ Агент mvnf: Настройка и запуск тестов Maven с повторяю...","ar":"دليل إعداد mvnf: تشغيل اختبارات Maven مع أوامر قابلة للتكرار"},"description":{"en":"Streamline your Maven testing workflow with mvnf. Learn how to run repeatable tests and get useful failure pointers. Get started with mvnf today!","zh":"使用mvnf运行Maven测试，实现可重复的命令和有用的失败指针，提高开发效率","ja":"mvnfを使用してMavenテストを実行し、再現可能なコマンドと有用的な失敗ポインターを実現します","ko":"mvnf를 사용하여 Maven 테스트를 실행하고 반복 가능한 명령과 유용한 실패 포인터를 구현하여 개발 효율성을 높입니다","es":"Aprende a ejecutar pruebas de Maven con mvnf, incluyendo pruebas unitarias y de integración con comandos personalizados","fr":"Découvrez comment exécuter des tests Maven avec mvnf, y compris des tests unitaires et d''intégration avec des commandes personnalisées","de":"Erfahren Sie, wie Sie Maven-Tests mit mvnf ausführen, einschließlich Unit-Tests und Integrations-Tests mit benutzerdefinierten Befehlen","pt":"Aprenda a usar o mvnf para executar testes Maven de forma eficiente com comandos repetíveis e ponteiros de falha úteis","ru":"Узнайте, как использовать ИИ Агент mvnf для запуска тестов Maven с повторяющимися командами и полезными указателями на сбой","ar":"تعرف على كيفية استخدام mvnf لتشغيل اختبارات Maven بفعالية مع أوامر قابلة للتكرار وملحقات فشل مفيدة"},"definition":{"en":"mvnf is a Maven test automation tool that enables repeatable testing with useful failure pointers for Java developers using Eclipse RDF4J.","zh":"mvnf是一种Maven测试运行工具，提供可重复的命令和有用的失败指针","ja":"mvnfはMavenテストを実行するツールで、再現可能なコマンドと有用的な失敗ポインターを提供します","ko":"mvnf는 Maven 테스트를 실행하는 도구로, 반복 가능한 명령과 유용한 실패 포인터를 제공합니다","es":"mvnf es una herramienta de línea de comandos para ejecutar pruebas de Maven de manera eficiente","fr":"mvnf est un outil de ligne de commande pour exécuter des tests Maven de manière efficace","de":"mvnf ist ein Kommandozeilen-Tool zum effizienten Ausführen von Maven-Tests","pt":"O mvnf é uma ferramenta de teste que executa testes Maven com comandos repetíveis e fornece ponteiros de falha úteis","ru":"ИИ Агент mvnf - это инструмент тестирования, который запускает тесты Maven с повторяющимися командами и предоставляет полезные указатели на сбой","ar":"mvnf هو أداة اختبار تنفذ اختبارات Maven مع أوامر قابلة للتكرار وتوفر ملحقات فشل مفيدة"},"features":{"en":["Runs a module''s full test suite using `python3 .codex/skills/mvnf/scripts/mvnf.py core/sail/shacl`","Supports running unit test classes or methods with automatic module detection","Enables running integration tests using Failsafe with `--it` flag","Provides useful failure pointers for debugging and troubleshooting","Utilizes Python 3 for test automation scripts","Compatible with Eclipse RDF4J for scalable RDF data processing"],"zh":["运行Maven测试","支持可重复的命令","提供有用的失败指针","支持单元测试和集成测试","支持Python脚本"],"ja":["Mavenテストの実行","再現可能なコマンドのサポート","有用的な失敗ポインターの提供","ユニットテストと統合テストのサポート","Pythonスクリプトのサポート"],"ko":["Maven 테스트 실행","반복 가능한 명령 지원","유용한 실패 포인터 제공","단위 테스트와 통합 테스트 지원","Python 스크립트 지원"],"es":["Ejecución de pruebas unitarias con comandos personalizados","Ejecución de pruebas de integración con Failsafe","Compatibilidad con comandos repetibles para pruebas de Maven","Indicadores de fallos útiles para la depuración","Soporte para la ejecución de pruebas de módulos específicos"],"fr":["Exécution de tests unitaires avec des commandes personnalisées","Exécution de tests d''intégration avec Failsafe","Compatibilité avec des commandes répétitives pour les tests Maven","Indicateurs de défaillance utiles pour le débogage","Prise en charge de l''exécution de tests de modules spécifiques"],"de":["Ausführung von Unit-Tests mit benutzerdefinierten Befehlen","Ausführung von Integrations-Tests mit Failsafe","Kompatibilität mit wiederholbaren Befehlen für Maven-Tests","Nützliche Fehlernachweise für die Fehlersuche","Unterstützung für die Ausführung von Tests für spezifische Module"],"pt":["Executa testes Maven com comandos repetíveis","Fornece ponteiros de falha úteis para identificar erros","Permite executar testes unitários e de integração","Suporta a execução de testes em módulos específicos","Oferece opções de linha de comando para personalizar a execução de testes"],"ru":["Запускает тесты Maven с повторяющимися командами","Предоставляет полезные указатели на сбой для выявления ошибок","Позволяет запускать юнит-тесты и интеграционные тесты","Поддерживает запуск тестов в конкретных модулях","Предлагает опции командной строки для настройки запуска тестов"],"ar":["تنفذ اختبارات Maven مع أوامر قابلة للتكرار","توفر ملحقات فشل مفيدة لتحديد الأخطاء","تمكن من تشغيل اختبارات الوحدة وتكامل","تدعم تشغيل الاختبارات في وحدات محددة","تقدم خيارات سطر الأوامر لتخصيص تشغيل الاختبارات"]},"keywords":{"en":["how to use mvnf","mvnf setup guide","mvnf alternative","mvnf vs Maven","mvnf install","what is mvnf","mvnf tutorial","mvnf integration testing","mvnf unit testing","mvnf automation"],"zh":["mvnf","Maven测试","Eclipse RDF4J","可重复的命令","失败指针","Python脚本","Maven测试运行","开发工具"],"ja":["mvnf","Mavenテスト","Eclipse RDF4J","再現可能なコマンド","失敗ポインター","Pythonスクリプト","Mavenテスト実行","開発ツール"],"ko":["mvnf","Maven 테스트","Eclipse RDF4J","반복 가능한 명령","실패 포인터","Python 스크립트","Maven 테스트 실행","개발 도구"],"es":["mvnf","Maven","pruebas de Maven","pruebas unitarias","pruebas de integración","Failsafe","comandos repetibles","indicadores de fallos","herramientas de desarrollo"],"fr":["mvnf","Maven","tests Maven","tests unitaires","tests d''intégration","Failsafe","commandes répétitives","indicateurs de défaillance","outils de développement"],"de":["mvnf","Maven","Maven-Tests","Unit-Tests","Integrations-Tests","Failsafe","wiederholbare Befehle","Fehlernachweise","Entwicklertools"],"pt":["mvnf","testes maven","comandos repetíveis","ponteiros de falha","desenvolvimento de software","ferramentas de teste","execução de testes","maven"],"ru":["mvnf","тесты maven","повторяющиеся команды","указатели на сбой","разработка программного обеспечения","инструменты тестирования","запуск тестов","maven"],"ar":["mvnf","اختبارات مافن","أوامر قابلة للتكرار","ملحقات فشل","تطوير البرمجيات","أدوات الاختبار","تشغيل الاختبارات","مافن"]}},"owner":"eclipse-rdf4j","repo":"rdf4j","repoPath":"eclipse-rdf4j/rdf4j","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.371Z","topics":[],"category":"community","skillMd":{"name":"mvnf","description":"Run Maven tests in this repo with a consistent workflow (module clean, root -Pquick clean install to refresh .m2_repo, then module verify or a single test class/method). Use when asked to run tests/verify in the rdf4j multi-module build or when the user says mvnf.","bodyPreview":"# mvnf\n\nRun Maven tests with repeatable commands and useful failure pointers.\n\n## Quick start\n\n- Run a module''s full test suite:\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py core/sail/shacl`\n- Run a unit test class or method (module auto-detected):\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py ShaclSailTest`\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py ShaclSailTest#testSomething`\n- Run an integration test (Failsafe):\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py --it ShaclSailIT#testS","body":"# mvnf\n\nRun Maven tests with repeatable commands and useful failure pointers.\n\n## Quick start\n\n- Run a module''s full test suite:\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py core/sail/shacl`\n- Run a unit test class or method (module auto-detected):\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py ShaclSailTest`\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py ShaclSailTest#testSomething`\n- Run an integration test (Failsafe):\n  - `python3 .codex/skills/mvnf/scripts/mvnf.py --it ShaclSailIT#testSomething`\n\n## What it does\n\n1. `mvn -o -Dmaven.repo.local=.m2_repo -pl <module> clean`\n2. `mvn -T 1C -o -Dmaven.repo.local=.m2_repo -Pquick clean install`\n3. `mvn -o -Dmaven.repo.local=.m2_repo -pl <module> verify` (optionally with `-Dtest=` / `-Dit.test=`)\n\nIf the test run fails, it prints the list of Surefire/Failsafe report files under the module''s `target/*-reports/` directories.\n\n## Options\n\n- `--module <path>`: Force the module when the test class name exists in multiple modules.\n- `--it`: Treat the selector as an integration test and pass it via `-Dit.test=...`.\n- `--no-offline`: Run Maven commands without `-o` (useful if offline resolution fails).\n"},"lastSynced":"2026-03-08T02:04:27.055Z","agentAnalysis":{"suitability":{"en":"Perfect for Java Development Agents needing automated Maven testing with repeatable commands and useful failure pointers.","zh":"非常适合需要自动化Maven测试的Java开发代理，具有可重复的命令和有用的故障指针。","ja":"Java開発エージェントが自動化されたMavenテストを必要とする場合に適しています。繰り返し実行可能なコマンドと有用な故障ポインターを提供します。","ko":"자동화된 Maven 테스트가 필요한 Java 개발 에이전트에 적합합니다. 반복 가능한 명령과 유용한 故障 포인터를 제공합니다.","es":"Perfecto para agentes de desarrollo de Java que necesitan pruebas de Maven automatizadas con comandos repetibles y punteros de fallo útiles.","fr":"Parfait pour les agents de développement Java nécessitant des tests Maven automatisés avec des commandes répétitives et des pointeurs de défaillance utiles.","de":"Perfekt für Java-Entwicklungsagenten, die automatisierte Maven-Tests mit wiederholbaren Befehlen und nützlichen Fehlerzeigern benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Java que necessitam de testes automatizados do Maven com comandos repetíveis e ponteiros de falha úteis.","ru":"Идеально подходит для агентов разработки Java, требующих автоматизированного тестирования Maven с повторяющимися командами и полезными указателями на сбой.","ar":"مثالي للوكلاء التطوير الجافا الذين يحتاجون إلى اختبارات مافن الآلية مع أوامر قابلة للتكرار ونقاط فشل مفيدة."},"recommendation":{"en":"Empowers agents to run Maven tests with precision, supporting module test suites, unit tests, and integration tests via Python scripts, utilizing Maven''s test suite capabilities and providing informative failure messages.","zh":"赋予代理运行Maven测试的精确度，支持模块测试套件、单元测试和集成测试，通过Python脚本利用Maven的测试套件能力，并提供有意义的故障消息。","ja":"エージェントがMavenテストを精密に実行できるようにし、モジュールテストスイート、ユニットテスト、統合テストをPythonスクリプトでサポートし、Mavenのテストスイート機能を利用し、情報のある故障メッセージを提供します。","ko":"에이전트가 Maven 테스트를 정밀하게 실행할 수 있도록 하며, 모듈 테스트套件, 유닛 테스트, 통합 테스트를 Python 스크립트로 지원하며, Maven의 테스트套件 기능을 활용하며, 정보가 포함된 故障 메시지를 제공합니다.","es":"Habilita a los agentes a ejecutar pruebas de Maven con precisión, admitiendo suites de pruebas de módulos, pruebas unitarias y pruebas de integración a través de scripts de Python, utilizando las capacidades de la suite de pruebas de Maven y proporcionando mensajes de error informativos.","fr":"Permet aux agents d''exécuter des tests Maven avec précision, en prenant en charge les suites de tests de modules, les tests unitaires et les tests d''intégration via des scripts Python, en utilisant les capacités de la suite de tests de Maven et en fournissant des messages d''erreur informatifs.","de":"Ermächtigt Agenten, Maven-Tests mit Präzision auszuführen, indem Module-Test-Suiten, Unit-Tests und Integration-Tests über Python-Skripte unterstützt werden, die Maven-Test-Suite-Funktionen nutzen und informative Fehlermeldungen bereitstellen.","pt":"Habilita os agentes a executar testes do Maven com precisão, suportando conjuntos de testes de módulos, testes unitários e testes de integração por meio de scripts Python, utilizando as capacidades do conjunto de testes do Maven e fornecendo mensagens de falha informativas.","ru":"Наделяет агентов возможностью запускать тесты Maven с точностью, поддерживая наборы тестов модулей, модульные тесты и интеграционные тесты через скрипты Python, используя возможности набора тестов Maven и предоставляя информативные сообщения об ошибках.","ar":"تمكّن الوكلاء من تشغيل اختبارات مافن بدقة، ودعم مجموعات اختبارات الوحدات واختبارات الوحدات واختبارات التكامل من خلال سكريبتات بايثون، واستخدام قدرات مجموعة اختبارات مافن وتوفير رسائل فشل إعلامية."},"useCases":{"en":["Automating module test suites for Java projects","Running unit tests for specific classes or methods with auto-detected modules","Executing integration tests using Failsafe for comprehensive testing"],"zh":["为Java项目自动化模块测试套件","使用自动检测模块运行特定类或方法的单元测试","使用Failsafe执行综合测试的集成测试"],"ja":["Javaプロジェクトのモジュールテストスイートを自動化する","自動検出モジュールを使用して特定のクラスまたはメソッドのユニットテストを実行する","Failsafeを使用して包括的なテストを行うための統合テストを実行する"],"ko":["Java 프로젝트를 위한 모듈 테스트套件 자동화","자동으로检测한 모듈을 사용하여 특정 클래스 또는 메서드의 유닛 테스트 실행","Failsafe를 사용하여 포괄적인 테스트를进行하는 통합 테스트 실행"],"es":["Automatizar suites de pruebas de módulos para proyectos de Java","Ejecutar pruebas unitarias para clases o métodos específicos con módulos autodetectados","Ejecutar pruebas de integración utilizando Failsafe para pruebas exhaustivas"],"fr":["Automatiser les suites de tests de modules pour les projets Java","Exécuter des tests unitaires pour des classes ou des méthodes spécifiques avec des modules autodétectés","Exécuter des tests d''intégration en utilisant Failsafe pour des tests exhaustifs"],"de":["Automatisieren von Modultest-Suiten für Java-Projekte","Ausführen von Unit-Tests für bestimmte Klassen oder Methoden mit autodetektierten Modulen","Ausführen von Integrationstests mit Failsafe für umfassende Tests"],"pt":["Automatizar conjuntos de testes de módulos para projetos Java","Executar testes unitários para classes ou métodos específicos com módulos auto-detectados","Executar testes de integração usando Failsafe para testes abrangentes"],"ru":["Автоматизировать наборы тестов модулей для проектов Java","Запускать модульные тесты для конкретных классов или методов с автоматически обнаруженными модулями","Выполнять интеграционные тесты с помощью Failsafe для всестороннего тестирования"],"ar":["أتمتة مجموعات اختبارات الوحدات لمشاريع الجافا","تشغيل اختبارات الوحدات لclasses أو أساليب محددة مع وحدات محددة ذاتيًا","تشغيل اختبارات التكامل باستخدام Failsafe للاختبارات الشاملة"]},"limitations":{"en":["Requires Python 3 to execute mvnf.py scripts","Limited to Java projects using Maven for testing","Dependent on Maven''s test suite and Failsafe integration test capabilities"],"zh":["需要Python 3来执行mvnf.py脚本","仅限于使用Maven进行测试的Java项目","依赖于Maven的测试套件和Failsafe集成测试能力"],"ja":["mvnf.pyスクリプトを実行するためにPython 3が必要","Mavenを使用してテストを行うJavaプロジェクトのみ","MavenのテストスイートおよびFailsafe統合テスト機能に依存"],"ko":["mvnf.py 스크립트를 실행하기 위해 Python 3가 필요","Maven을 사용하여 테스트를进行하는 Java 프로젝트만","Maven의 테스트套件 및 Failsafe 통합 테스트 기능에 의존"],"es":["Requiere Python 3 para ejecutar scripts mvnf.py","Limitado a proyectos de Java que utilizan Maven para pruebas","Dependiente de las capacidades de la suite de pruebas de Maven y la integración de pruebas de Failsafe"],"fr":["Nécessite Python 3 pour exécuter des scripts mvnf.py","Limité aux projets Java utilisant Maven pour les tests","Dépendant des capacités de la suite de tests de Maven et de l''intégration de tests de Failsafe"],"de":["Benötigt Python 3, um mvnf.py-Skripte auszuführen","Begrenzt auf Java-Projekte, die Maven für Tests verwenden","Abhängig von den Funktionen der Maven-Test-Suite und der Failsafe-Integrationstest-Funktion"],"pt":["Exige Python 3 para executar scripts mvnf.py","Limitado a projetos Java que usam Maven para testes","Dependente das capacidades do conjunto de testes do Maven e da integração de testes Failsafe"],"ru":["Требует Python 3 для выполнения скриптов mvnf.py","Ограничен проектами Java, использующими Maven для тестирования","Зависит от возможностей набора тестов Maven и интеграции тестов Failsafe"],"ar":["يتطلب بايثون 3 لتشغيل سكريبتات mvnf.py","محدود بمشاريع الجافا التي تستخدم مافن للاختبارات","يعتمد على قدرات مجموعة اختبارات مافن وتكامل اختبارات Failsafe"]},"version":4},"contentHash":"861d2721ad2c42506e3aafd8006dffa6334c0c33627fa25f37cffd67cdcdbeaf","qualityScore":23}');
