INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('eclipse-rdf4j/rdf4j/mvnf', 'mvnf', 'eclipse-rdf4j', 'rdf4j', 'community', 'mvnf eclipse-rdf4j rdf4j community mvnf is a skill that automates Maven tests with repeatable commands and provides useful failure pointers for Java developers. It supports running module test suites, unit tests, and integration tests. mvnf是一种运行Maven测试的工具，支持可重复的命令和有用的失败指针，适用于Eclipse RDF4J开发 mvnfはMavenテストを実行するツールで、再現可能なコマンドと有用的な失敗ポインターをサポートします。Eclipse RDF4J開発向け mvnf는 Maven 테스트를 실행하는 도구로, 반복 가능한 명령과 유용한 실패 포인터를 지원하며 Eclipse RDF4J 개발에 적합합니다 mvnf es una herramienta para ejecutar pruebas de Maven con comandos repetibles y útiles indicadores de fallos. Permite ejecutar pruebas unitarias y de integración con facilidad. mvnf est un outil pour exécuter des tests Maven avec des commandes répétitives et des indicateurs de défaillance utiles. Il permet d''exécuter des tests unitaires et d''intégration avec facilité. mvnf ist ein Tool zum Ausführen von Maven-Tests mit wiederholbaren Befehlen und nützlichen Fehlernachweisen. Es ermöglicht die Ausführung von Unit-Tests und Integrations-Tests mit Leichtigkeit. O mvnf é uma ferramenta que permite executar testes Maven com comandos repetíveis e ponteiros de falha úteis. É ideal para desenvolvedores que precisam testar seus projetos de forma eficiente. ИИ Агент mvnf - это инструмент, который позволяет запускать тесты Maven с повторяющимися командами и полезными указателями на сбой. Он идеален для разработчиков, которым необходимо тестировать свои проекты эффективно. mvnf هو أداة تسمح بتشغيل اختبارات Maven مع أوامر قابلة للتكرار وملحقات فشل مفيدة. وهي مثالية للمطورين الذين يحتاجون إلى اختبار مشاريعهم بفعالية how to use mvnf mvnf setup guide mvnf alternative mvnf vs Maven mvnf install what is mvnf mvnf tutorial mvnf integration testing mvnf unit testing mvnf automation mvnf Maven测试 Eclipse RDF4J 可重复的命令 失败指针 Python脚本 Maven测试运行 开发工具 Runs a module''s full test suite using `python3 .codex/skills/mvnf/scripts/mvnf.py core/sail/shacl` Supports running unit test classes or methods with automatic module detection Enables running integration tests using Failsafe with `--it` flag Provides useful failure pointers for debugging and troubleshooting Utilizes Python 3 for test automation scripts Compatible with Eclipse RDF4J for scalable RDF data processing mvnf is a Maven test automation tool that enables repeatable testing with useful failure pointers for Java developers using Eclipse RDF4J.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rehno-lindeque/wip/nixos-install', 'community', 'rehno-lindeque', 'wip', 'rehno-lindeque/wip', 'nixos-install', 0, 0, 23, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:29.055Z', 'f52d52b7c0694ce58cf8ddfa242517b3d86036a9b81be6b548bc0894f336fd43', '{"id":"rehno-lindeque/wip/nixos-install","name":"nixos-install","description":{"en":"The nixos-install skill provides a step-by-step guide for installing NixOS, with a focus on incremental and hardware-specific approaches. It benefits developers and users looking for a declarative installation method.","zh":"NixOS 安装是一个工作中的项目，提供了 declarative 方法和硬件特定命令的安装步骤。包括 Apple Silicon 等子技能。","ja":"NixOS インストールは進行中のプロジェクトであり、宣言的アプローチとハードウェア固有のコマンドのインストール手順を提供します。Apple Silicon などのサブスキルを含みます。","ko":"NixOS 설치는 진행 중인 프로젝트로 선언적 접근법과 하드웨어 특정 명령의 설치 단계를 제공합니다. Apple Silicon 등의 하위 기능을 포함합니다.","es":"NixOS es un sistema operativo que se puede instalar de manera incremental, con un enfoque declarativo. Descubre los pasos verificados para hardware específico.","fr":"NixOS est un système d''exploitation qui peut être installé de manière incrémentale, avec une approche déclarative. Découvrez les étapes vérifiées pour le matériel spécifique.","de":"NixOS ist ein Betriebssystem, das inkrementell installiert werden kann, mit einem deklarativen Ansatz. Entdecken Sie die verifizierten Schritte für hardware-spezifische Installationen.","pt":"O NixOS Install é um guia de instalação passo a passo para desenvolvedores, incluindo comandos de instalação específicos para hardware e abordagem declarativa.","ru":"NixOS Install - это пошаговое руководство по установке для разработчиков, включая команды установки для конкретного оборудования и декларативный подход.","ar":"NixOS Install هو دليل تركيب خطوة بخطوة للبرمجة، بما في ذلك أوامر التثبيت المحددة للأجهزة والنهج الإعلاني."},"seo":{"title":{"en":"nixos-install: Incremental Setup Guide | AI Agent Skill","zh":"NixOS 安装指南：declarative 方法和硬件特定命令","ja":"NixOS インストール ガイド：宣言的アプローチとハードウェア固有のコマンド","ko":"NixOS 설치 가이드: 선언적 접근법과 하드웨어 특정 명령","es":"Guía de instalación de NixOS: Mejores prácticas para desa...","fr":"Guide d''installation de NixOS : Bonnes pratiques pour les...","de":"NixOS-Installationsleitfaden: Best Practices für Entwickler","pt":"Guia de Instalação NixOS: Melhores Práticas para Desenvol...","ru":"ИИ Агенты: Руководство по Установке NixOS для Разработчиков","ar":"دليل تركيب NixOS: إرشادات وتوجيهات للبرمجة"},"description":{"en":"Discover the nixos-install skill, a work-in-progress approach to NixOS installation. Learn how to use it and explore its features.","zh":"了解 NixOS 安装的步骤和最佳实践，包括 declarative 方法和硬件特定命令，AIエージェント","ja":"NixOS インストールの手順とベストプラクティスを紹介します。宣言的アプローチとハードウェア固有のコマンドを含みます。AIエージェント","ko":"NixOS 설치의 단계와 모범 사례를 알아보세요. 선언적 접근법과 하드웨어 특정 명령을 포함합니다. AI 도구","es":"Aprenda a instalar NixOS de manera incremental con nuestro enfoque declarativo y descubra los pasos verificados para hardware específico","fr":"Découvrez comment installer NixOS de manière incrémentale avec notre approche déclarative et explorez les étapes vérifiées pour le matériel spécifique","de":"Erfahren Sie, wie Sie NixOS inkrementell installieren können, mit unserem deklarativen Ansatz und entdecken Sie die verifizierten Schritte für hardware-spezi...","pt":"Aprenda a instalar NixOS com nosso guia passo a passo, incluindo comandos de instalação específicos para hardware e abordagem declarativa","ru":"Узнайте, как установить NixOS с помощью нашего пошагового руководства, включая команды установки для конкретного оборудования и декларативный подход","ar":"تعلم كيفية تركيب NixOS باستخدام دليلنا الخطوة بخطوة، بما في ذلك أوامر التثبيت المحددة للأجهزة والنهج الإعلاني"},"definition":{"en":"nixos-install is a skill for installing NixOS, an incremental and hardware-specific approach to setting up the NixOS operating system.","zh":"NixOS 安装是指使用 declarative 方法和硬件特定命令来安装 NixOS 操作系统的过程。","ja":"NixOS インストールは、宣言的アプローチとハードウェア固有のコマンドを使用して NixOS オペレーティングシステムをインストールするプロセスです。","ko":"NixOS 설치는 선언적 접근법과 하드웨어 특정 명령을 사용하여 NixOS 운영 체제를 설치하는 과정입니다.","es":"NixOS es un sistema operativo que utiliza un enfoque declarativo para la instalación","fr":"NixOS est un système d''exploitation qui utilise une approche déclarative pour l''installation","de":"NixOS ist ein Betriebssystem, das einen deklarativen Ansatz für die Installation verwendet","pt":"O NixOS Install é um conjunto de etapas para instalar NixOS em diferentes hardwares","ru":"NixOS Install - это набор шагов для установки NixOS на различном оборудовании","ar":"NixOS Install هو مجموعة من الخطوات لتركيب NixOS على أجهزة مختلفة"},"features":{"en":["Provides incremental installation steps for NixOS","Includes hardware-specific install commands in sub-skills","Supports declarative approach to installation","Allows for updating and verifying installation steps","Includes sub-skills for specific hardware, such as apple-silicon","Enables recording of verified installation steps"],"zh":["declarative 方法","硬件特定命令","Apple Silicon 子技能","增量安装","可更新步骤"],"ja":["宣言的アプローチ","ハードウェア固有のコマンド","Apple Silicon サブスキル","インクリメンタルインストール","更新可能な手順"],"ko":["선언적 접근법","하드웨어 특정 명령","Apple Silicon 하위 기능","증분 설치","업데이트 가능한 단계"],"es":["Instalación incremental","Enfoque declarativo","Pasos verificados para hardware específico","Compatibilidad con hardware como Apple Silicon","Reemplazo de instaladores con un enfoque declarativo"],"fr":["Installation incrémentale","Approche déclarative","Étapes vérifiées pour le matériel spécifique","Compatibilité avec le matériel comme Apple Silicon","Remplacement des installateurs avec une approche déclarative"],"de":["Inkrementelle Installation","Deklarativer Ansatz","Verifizierte Schritte für hardware-spezifische Installationen","Kompatibilität mit Hardware wie Apple Silicon","Ersetzen von Installationsprogrammen durch einen deklarativen Ansatz"],"pt":["Comandos de instalação específicos para hardware","Abordagem declarativa para instalação","Guia passo a passo para desenvolvedores","Suporte a diferentes plataformas de hardware","Atualizações regulares com novos passos verificados"],"ru":["Команды установки для конкретного оборудования","Декларативный подход к установке","Пошаговое руководство для разработчиков","Поддержка различных платформ оборудования","Регулярные обновления с новыми проверенными шагами"],"ar":["أوامر التثبيت المحددة للأجهزة","النهج الإعلاني لتركيب","دليل خطوة بخطوة للبرمجة","دعم منصات أجهزة مختلفة","تحديثات منتظمة مع خطوات جديدة تم التحقق منها"]},"keywords":{"en":["how to use nixos-install","nixos-install setup guide","nixos-install alternative","nixos-install vs guix","nixos-install install","what is nixos-install","nixos-install documentation","nixos-install tutorial","nixos-install best practices"],"zh":["NixOS 安装","declarative 方法","硬件特定命令","AIエージェント","Apple Silicon","增量安装","NixOS 安装指南"],"ja":["NixOS インストール","宣言的アプローチ","ハードウェア固有のコマンド","AIエージェント","Apple Silicon","インクリメンタルインストール","NixOS インストールガイド"],"ko":["NixOS 설치","선언적 접근법","하드웨어 특정 명령","AI 도구","Apple Silicon","증분 설치","NixOS 설치 가이드"],"es":["NixOS","instalación de NixOS","enfoque declarativo","instalación incremental","hardware específico","Apple Silicon","desarrollo de software","sistemas operativos","herramientas de desarrollo"],"fr":["NixOS","installation de NixOS","approche déclarative","installation incrémentale","matériel spécifique","Apple Silicon","développement de logiciels","systèmes d''exploitation","outils de développement"],"de":["NixOS","NixOS-Installation","deklarativer Ansatz","inkrementelle Installation","hardware-spezifische Installationen","Apple Silicon","Software-Entwicklung","Betriebssysteme","Entwicklungstools"],"pt":["nixos install","guia de instalação nixos","comandos de instalação nixos","abordagem declarativa nixos","desenvolvedores nixos","plataformas de hardware nixos","instalação nixos em macbookpro2025"],"ru":["nixos install","руководство по установке nixos","команды установки nixos","декларативный подход nixos","разработчики nixos","платформы оборудования nixos","установка nixos на macbookpro2025"],"ar":["nixos install","دليل تركيب nixos","أوامر التثبيت nixos","النهج الإعلاني nixos","برمجة nixos","منصات أجهزة nixos","تركيب nixos على macbookpro2025"]}},"owner":"rehno-lindeque","repo":"wip","repoPath":"rehno-lindeque/wip","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"nixos-install","description":"Install or reimage NixOS from live media; progressively disclose per-hardware steps. Trigger when in a live/rescue shell preparing a fresh install.","bodyPreview":"# NixOS Install (incremental)\n\nStart here; branch into sub-skills (e.g., `apple-silicon`) when the hardware requires it.\n\nMeta: only record steps we have actually performed; after each new verified step, update this skill or the appropriate sub-skill.\n\n## Steps we have confirmed\n- Hardware-specific install commands live in sub-skills (e.g., see `apple-silicon` for macbookpro2025).\n\n## To-do (fill in after we perform them)\n- Entirely replace our hacky installer with the declarative approach descr","body":"# NixOS Install (incremental)\n\nStart here; branch into sub-skills (e.g., `apple-silicon`) when the hardware requires it.\n\nMeta: only record steps we have actually performed; after each new verified step, update this skill or the appropriate sub-skill.\n\n## Steps we have confirmed\n- Hardware-specific install commands live in sub-skills (e.g., see `apple-silicon` for macbookpro2025).\n\n## To-do (fill in after we perform them)\n- Entirely replace our hacky installer with the declarative approach described by Michael Stapelberg (2025-06-01) for new systems: https://michael.stapelberg.ch/posts/2025-06-01-nixos-installation-declarative/ — adopt once we’ve run it end-to-end.\n- ARM/PinePhone installer\n\n## References\n- See sub-skill references (e.g., `apple-silicon/links.md`) and open only when blocked.\n"},"lastSynced":"2026-03-08T02:04:29.055Z","agentAnalysis":{"suitability":{"en":"Ideal for Declarative Configuration Agents requiring incremental and hardware-specific NixOS installation approaches.","zh":"适合需要增量和硬件特定 NixOS 安装方法的声明式配置代理。","ja":"宣言的構成エージェントに適しており、増分的およびハードウェア固有の NixOS インストールアプローチを必要とする。","ko":"선언적 구성 에이전트에 적합하며, 증분 및 하드웨어 특정 NixOS 설치 접근 방식을 필요로 함.","es":"Ideal para agentes de configuración declarativa que requieren enfoques de instalación de NixOS incrementales y específicos del hardware.","fr":"Idéal pour les agents de configuration déclarative nécessitant des approches d''installation de NixOS incrémentielles et spécifiques au matériel.","de":"Ideal für deklarative Konfigurationsagenten, die inkrementelle und hardware-spezifische NixOS-Installationsansätze erfordern.","pt":"Ideal para Agentes de Configuração Declarativa que exigem abordagens de instalação incrementais e específicas de hardware do NixOS.","ru":"Идеально для агентов декларативной конфигурации, требующих инкрементальных иhardware-специфичных подходов к установке NixOS.","ar":"مثالي لعمليات التهيئة الإعلانية التي تتطلب نهج التثبيت المتزايد والخاص بالأجهزة من NixOS."},"recommendation":{"en":"Empowers agents to perform declarative installations of NixOS, leveraging incremental steps and hardware-specific commands, such as those for Apple Silicon, to ensure a reliable and efficient setup process using the NixOS configuration language.","zh":"赋予代理执行 NixOS 的声明性安装，利用增量步骤和硬件特定命令（如 Apple Silicon），以确保可靠高效的设置过程，使用 NixOS 配置语言。","ja":"エージェントが NixOS の宣言的インストールを実行できるようにし、増分的ステップとハードウェア固有のコマンド（Apple Silicon など）を利用して、信頼性が高く効率的な設定プロセスを実現する、NixOS 構成言語を使用して。","ko":"에이전트가 NixOS의 선언적 설치를 수행할 수 있도록 하며, 증분 단계 및 하드웨어 특정 명령(예: Apple Silicon)을 활용하여, 신뢰할 수 있고 효율적인 설정 프로세스를 보장하며, NixOS 구성 언어를 사용함.","es":"Habilita a los agentes a realizar instalaciones declarativas de NixOS, aprovechando los pasos incrementales y los comandos específicos del hardware, como los de Apple Silicon, para garantizar un proceso de configuración confiable y eficiente utilizando el lenguaje de configuración de NixOS.","fr":"Permet aux agents d''effectuer des installations déclaratives de NixOS, en exploitant les étapes incrémentielles et les commandes spécifiques au matériel, telles que celles pour Apple Silicon, pour assurer un processus de configuration fiable et efficace en utilisant le langage de configuration de NixOS.","de":"Ermächtigt Agenten, deklarative Installationen von NixOS durchzuführen, indem inkrementelle Schritte und hardware-spezifische Befehle, wie z.B. für Apple Silicon, genutzt werden, um einen zuverlässigen und effizienten Konfigurationsprozess unter Verwendung der NixOS-Konfigurationssprache zu gewährleisten.","pt":"Habilita os agentes a realizar instalações declarativas do NixOS, aproveitando etapas incrementais e comandos específicos de hardware, como aqueles para Apple Silicon, para garantir um processo de configuração confiável e eficiente usando a linguagem de configuração do NixOS.","ru":"Наделяет агентов возможностью выполнять декларативные установки NixOS, используя инкрементальные шаги и команды, специфичные для аппаратного обеспечения, такие как те, которые для Apple Silicon, чтобы обеспечить надежный и эффективный процесс настройки с использованием языка конфигурации NixOS.","ar":"يمنح الوكلاء القدرة على أداء عمليات تثبيت إعلانية ل NixOS، مستفيدة من الخطوات المتزايدة والأوامر الخاصة بالأجهزة، مثل تلك الموجودة في Apple Silicon، لضمان عملية إعداد موثوقة وفعاله باستخدام لغة تكوين NixOS."},"useCases":{"en":["Installing NixOS on diverse hardware configurations, including Apple Silicon devices","Creating incremental installation scripts for reproducible environments","Debugging hardware-specific issues during the NixOS installation process"],"zh":["在多样化的硬件配置上安装 NixOS，包括 Apple Silicon 设备","创建用于可复现环境的增量安装脚本","在 NixOS 安装过程中调试硬件特定问题"],"ja":["多様なハードウェア構成、Apple Silicon デバイスを含む、NixOS のインストール","再現可能な環境のための増分的インストールスクリプトの作成","NixOS インストールプロセス中にハードウェア固有の問題をデバッグ"],"ko":["다양한 하드웨어 구성에서 NixOS 설치, Apple Silicon 장치를 포함","재현 가능한 환경을 위한 증분 설치 스크립트 생성","NixOS 설치 과정에서 하드웨어 특정 문제 디버깅"],"es":["Instalar NixOS en diversas configuraciones de hardware, incluidos dispositivos Apple Silicon","Crear scripts de instalación incrementales para entornos reproducibles","Depurar problemas específicos del hardware durante el proceso de instalación de NixOS"],"fr":["Installer NixOS sur diverses configurations matérielles, y compris les appareils Apple Silicon","Créer des scripts d''installation incrémentiels pour des environnements reproductibles","Déboguer les problèmes spécifiques au matériel lors du processus d''installation de NixOS"],"de":["NixOS auf verschiedenen Hardware-Konfigurationen installieren, einschließlich Apple-Silicon-Geräten","Inkrementale Installations-Skripte für reproduzierbare Umgebungen erstellen","Hardware-spezifische Probleme während des NixOS-Installationsprozesses debuggen"],"pt":["Instalar o NixOS em configurações de hardware diversas, incluindo dispositivos Apple Silicon","Criar scripts de instalação incrementais para ambientes reprodutíveis","Depurar problemas específicos de hardware durante o processo de instalação do NixOS"],"ru":["Установка NixOS на различные конфигурации оборудования, включая устройства Apple Silicon","Создание инкрементальных скриптов установки для воспроизводимых сред","Отладка аппаратно-специфичных проблем во время процесса установки NixOS"],"ar":["تثبيت NixOS علىconfigurações متنوعة من الأجهزة، بما في ذلك أجهزة Apple Silicon","إنشاء سكريبتات تثبيت متزايدة لبيئات قابلة للتكرار","تصحيح الأخطاء الخاصة بالأجهزة أثناء عملية تثبيت NixOS"]},"limitations":{"en":["Requires hardware-specific installation commands","NixOS configuration knowledge necessary","Incremental approach may require additional steps for complex setups"],"zh":["需要硬件特定安装命令","需要 NixOS 配置知识","增量方法可能需要复杂设置的额外步骤"],"ja":["ハードウェア固有のインストールコマンドが必要","NixOS 構成の知識が必要","増分的アプローチでは、複雑なセットアップの追加ステップが必要となる可能性"],"ko":["하드웨어 특정 설치 명령 필요","NixOS 구성 지식 필요","증분 접근 방식은 복잡한 설정의 추가 단계가 필요할 수 있음"],"es":["Requiere comandos de instalación específicos del hardware","Conocimiento de la configuración de NixOS necesario","El enfoque incremental puede requerir pasos adicionales para configuraciones complejas"],"fr":["Nécessite des commandes d''installation spécifiques au matériel","Connaissances de la configuration de NixOS nécessaires","L''approche incrémentielle peut nécessiter des étapes supplémentaires pour des configurations complexes"],"de":["Benötigt hardware-spezifische Installationsbefehle","NixOS-Konfigurationskenntnisse erforderlich","Der inkrementelle Ansatz kann für komplexe Konfigurationen zusätzliche Schritte erfordern"],"pt":["Exige comandos de instalação específicos de hardware","Conhecimento de configuração do NixOS necessário","Abordagem incremental pode exigir etapas adicionais para configurações complexas"],"ru":["Требует команд установки, специфичных для аппаратного обеспечения","Необходимо знание конфигурации NixOS","Инкрементальный подход может потребовать дополнительных шагов для сложных настроек"],"ar":["يتطلب أوامر تثبيت خاصة بالأجهزة","معرفة تكوين NixOS ضرورية","النهج المتزايد قد يتطلب خطوات إضافية لإعدادات معقدة"]},"version":4},"contentHash":"f52d52b7c0694ce58cf8ddfa242517b3d86036a9b81be6b548bc0894f336fd43","qualityScore":23}');
