INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rehno-lindeque/wip/nixos-install', 'nixos-install', 'rehno-lindeque', 'wip', 'community', 'nixos-install rehno-lindeque wip community The nixos-install skill provides a step-by-step guide for installing NixOS, with a focus on incremental and hardware-specific approaches. It benefits developers and users looking for a declarative installation method. NixOS 安装是一个工作中的项目，提供了 declarative 方法和硬件特定命令的安装步骤。包括 Apple Silicon 等子技能。 NixOS インストールは進行中のプロジェクトであり、宣言的アプローチとハードウェア固有のコマンドのインストール手順を提供します。Apple Silicon などのサブスキルを含みます。 NixOS 설치는 진행 중인 프로젝트로 선언적 접근법과 하드웨어 특정 명령의 설치 단계를 제공합니다. Apple Silicon 등의 하위 기능을 포함합니다. NixOS es un sistema operativo que se puede instalar de manera incremental, con un enfoque declarativo. Descubre los pasos verificados para hardware específico. NixOS est un système d''exploitation qui peut être installé de manière incrémentale, avec une approche déclarative. Découvrez les étapes vérifiées pour le matériel spécifique. NixOS ist ein Betriebssystem, das inkrementell installiert werden kann, mit einem deklarativen Ansatz. Entdecken Sie die verifizierten Schritte für hardware-spezifische Installationen. O NixOS Install é um guia de instalação passo a passo para desenvolvedores, incluindo comandos de instalação específicos para hardware e abordagem declarativa. NixOS Install - это пошаговое руководство по установке для разработчиков, включая команды установки для конкретного оборудования и декларативный подход. NixOS Install هو دليل تركيب خطوة بخطوة للبرمجة، بما في ذلك أوامر التثبيت المحددة للأجهزة والنهج الإعلاني. how to use nixos-install nixos-install setup guide nixos-install alternative nixos-install vs guix nixos-install install what is nixos-install nixos-install documentation nixos-install tutorial nixos-install best practices NixOS 安装 declarative 方法 硬件特定命令 AIエージェント Apple Silicon 增量安装 NixOS 安装指南 Provides incremental installation steps for NixOS Includes hardware-specific install commands in sub-skills Supports declarative approach to installation Allows for updating and verifying installation steps Includes sub-skills for specific hardware, such as apple-silicon Enables recording of verified installation steps nixos-install is a skill for installing NixOS, an incremental and hardware-specific approach to setting up the NixOS operating system.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('0boluan0/Notes_on_Economic_Statistics/today', 'community', '0boluan0', 'Notes_on_Economic_Statistics', '0boluan0/Notes_on_Economic_Statistics', 'today', 0, 0, 23, '2026-03-08T01:57:15.372Z', '2026-03-08T02:04:31.402Z', '9027cd7d40f211b5a96ce3773b140f7f309f8aba8ff3964f3855f4be9b46507c', '{"id":"0boluan0/Notes_on_Economic_Statistics/today","name":"today","description":{"en":"The today skill creates a completed daily note with three ordered modules and saves it to the study-log folder. It benefits developers who want to automate their daily note-taking workflow.","zh":"使用AI工具创建每日记录，包括模板解析和文件保存。该工具使用特定的模板和文件夹结构来组织记录。","ja":"AIエージェントを使用して日常の記録を作成します。特定のテンプレートとフォルダ構造を使用して記録を整理します。","ko":"AI 도구를 사용하여 일일 노트를 생성합니다. 특정 템플릿과 폴더 구조를 사용하여 기록을 구성합니다.","es":"La habilidad ''today'' crea una nota diaria con tres módulos ordenados y la guarda en la carpeta de registro de estudios. Utiliza plantillas y archivos de salida personalizados.","fr":"La fonctionnalité ''today'' crée une note quotidienne avec trois modules ordonnés et la sauvegarde dans le dossier de suivi d''études. Elle utilise des modèles et des fichiers de sortie personnalisés.","de":"Die ''today''-Funktion erstellt eine tägliche Notiz mit drei geordneten Modulen und speichert sie im Lernfortschrittsordner. Sie verwendet benutzerdefinierte Vorlagen und Ausgabedateien.","pt":"O Today é uma ferramenta que cria notas diárias automatizadas com três módulos ordenados e as salva em uma pasta de registro de estudos","ru":"Today - это инструмент, который создает автоматические дневные заметки с тремя упорядоченными модулями и сохраняет их в папке учета обучения","ar":"اليوم هو أداة لإنشاء ملاحظات يومية آلية مع ثلاث وحدات مرتبة وتحفظها في مجلد سجل الدراسة"},"seo":{"title":{"en":"today: Automated Daily Note Generation for AI Agents | AI...","zh":"今日日志创建指南 - 使用AI工具自动化日常记录","ja":"Today Setup Guide - AIエージェントによる日常の記録自動化","ko":"오늘의 기록 생성 가이드 - AI 도구를 사용한 일일 노트 자동화","es":"Configuración de la habilidad ''today'' para notas diarias","fr":"Guide d''installation de la fonctionnalité ''today'' pour le...","de":"Einrichtung der ''today''-Funktion für tägliche Notizen","pt":"Guia de Configuração do Today: Crie Notas Diárias Automat...","ru":"Настройка Today: Создание автоматических дневных заметок ...","ar":"إعداد اليوم: إنشاء ملاحظات يومية آلية باستخدام أدوات الذك..."},"description":{"en":"Discover how to streamline your daily note-taking with the today skill. Learn how to automate your workflow and get started with our setup guide.","zh":"了解如何使用AI工具创建每日记录，包括模板解析和文件保存。提高生产力，简化日常记录流程。","ja":"AIエージェントを使用して日常の記録を作成する方法について説明します。テンプレート解析とファイル保存を含みます。","ko":"AI 도구를 사용하여 일일 노트를 생성하는 방법에 대해 알아보세요. 템플릿 파싱 및 파일 저장과 같은 기능을 포함합니다.","es":"Aprende a configurar la habilidad ''today'' para crear notas diarias con módulos ordenados y guardarlas en la carpeta de registro de estudios","fr":"Découvrez comment installer la fonctionnalité ''today'' pour créer des notes quotidiennes avec des modules ordonnés et les enregistrer dans le dossier de suivi...","de":"Erfahren Sie, wie Sie die ''today''-Funktion einrichten, um tägliche Notizen mit geordneten Modulen zu erstellen und sie im Lernfortschrittsordner zu speichern","pt":"Aprenda a configurar o Today para criar notas diárias automatizadas com módulos ordenados e salvar em uma pasta de registro de estudos","ru":"Узнайте, как настроить Today для создания автоматических дневных заметок с упорядоченными модулями и сохранить их в папке учета обучения с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد اليوم لإنشاء ملاحظات يومية آلية مع وحدات مرتبة و حفظها في مجلد سجل الدراسة باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"today is a skill that automates the creation of daily notes using a template and saves them to a specified folder, utilizing a specific filename format.","zh":"今日日志创建是一种使用AI工具自动化日常记录的功能，通过解析模板和保存文件来实现。","ja":"Todayは、AIエージェントを使用して日常の記録を作成する機能です。テンプレートの解析とファイルの保存を使用して実現します。","ko":"오늘의 기록 생성은 AI 도구를 사용하여 일일 노트를 자동화하는 기능으로, 템플릿 파싱과 파일 저장을 통해 구현됩니다.","es":"La habilidad ''today'' es una función que crea notas diarias con módulos ordenados y las guarda en una carpeta de registro de estudios","fr":"La fonctionnalité ''today'' est une fonction qui crée des notes quotidiennes avec des modules ordonnés et les sauvegarde dans un dossier de suivi d''études","de":"Die ''today''-Funktion ist eine Funktion, die tägliche Notizen mit geordneten Modulen erstellt und sie in einem Lernfortschrittsordner speichert","pt":"O Today é uma ferramenta de automação que cria notas diárias com módulos ordenados","ru":"Today - это инструмент автоматизации, который создает дневные заметки с упорядоченными модулями","ar":"اليوم هو أداة أوتوماتيكية لإنشاء ملاحظات يومية مع وحدات مرتبة"},"features":{"en":["Resolves required paths using template 00_inbox/日记模版.md or fallback template 00_inbox/日记模板.md","Determines today''s target filename using the format YYYY-MM-DD——<DayAbbrev>.md","Saves daily notes to the 99_学习情况记录 folder","Uses the Overview & Study Record.md file for overview purposes","Automates daily note creation using a workflow triggered by the /today command"],"zh":["使用特定的模板（00_inbox/日记模版.md）来创建每日记录","支持模板解析和文件保存","将记录保存在指定的文件夹（99_学习情况记录）中","使用特定的文件格式（YYYY-MM-DD——<DayAbbrev>.md）来命名记录","支持多种文件格式和结构"],"ja":["特定のテンプレート（00_inbox/日记模板.md）を使用して日常の記録を作成","テンプレート解析とファイル保存をサポート","記録を指定されたフォルダ（99_学习情况记录）に保存","特定のファイル形式（YYYY-MM-DD——<DayAbbrev>.md）を使用して記録を命名","複数のファイル形式と構造をサポート"],"ko":["특정 템플릿（00_inbox/日记模板.md）을 사용하여 일일 노트를 생성","템플릿 파싱과 파일 저장을 지원","기록을 지정된 폴더（99_学习情况记录）에 저장","특정 파일 형식（YYYY-MM-DD——<DayAbbrev>.md）을 사용하여 기록을命名","複数의 파일 형식과 구조를 지원"],"es":["Crea notas diarias con tres módulos ordenados","Utiliza plantillas personalizadas para notas diarias","Guarda notas en la carpeta de registro de estudios","Soporta formato de archivo personalizado","Utiliza la carpeta ''99_学习情况记录'' para el registro de estudios","兼容 con la herramienta de línea de comandos (CLI)"],"fr":["Crée des notes quotidiennes avec trois modules ordonnés","Utilise des modèles personnalisés pour les notes quotidiennes","Sauvegarde les notes dans le dossier de suivi d''études","Prend en charge le format de fichier personnalisé","Utilise le dossier ''99_学习情况记录'' pour le suivi d''études","Compatible avec l''outil de ligne de commande (CLI)"],"de":["Erstellt tägliche Notizen mit drei geordneten Modulen","Verwendet benutzerdefinierte Vorlagen für tägliche Notizen","Speichert Notizen im Lernfortschrittsordner","Unterstützt benutzerdefiniertes Dateiformat","Verwendet den Ordner ''99_学习情况记录'' für den Lernfortschritt","Kompatibel mit der Kommandozeilen-Schnittstelle (CLI)"],"pt":["Criação de notas diárias automatizadas","Módulos ordenados para organização","Salvar notas em pasta de registro de estudos","Uso de template de nota diária personalizado","Compatibilidade com CLI para automação"],"ru":["Создание автоматических дневных заметок","Упорядоченные модули для организации","Сохранение заметок в папке учета обучения","Использование пользовательского шаблона дневной заметки","Совместимость с CLI для автоматизации"],"ar":["إنشاء ملاحظات يومية آلية","وحدات مرتبة لتنظيم الملاحظات","حفظ الملاحظات في مجلد سجل الدراسة","استخدام قالب ملاحظة يومية مخصص","التوافق مع CLI للاوتوماتيكية"]},"keywords":{"en":["how to use today skill","today skill setup guide","automated daily note generation","today skill alternative","today skill vs manual note-taking","today skill install","what is today skill","today skill for ai agents","today skill workflow automation"],"zh":["AI工具","日常记录","模板解析","文件保存","今日日志创建","自动化日常记录","生产力工具","日志创建指南"],"ja":["AIエージェント","日常の記録","テンプレート解析","ファイル保存","Today","日常の記録自動化","生産性ツール","記録作成ガイド"],"ko":["AI 도구","일일 노트","템플릿 파싱","파일 저장","오늘의 기록 생성","일일 노트 자동화","생산성 도구","기록 생성 가이드"],"es":["habilidad today","notas diarias","módulos ordenados","plantillas personalizadas","registro de estudios","herramienta de línea de comandos","Agente de IA","Herramientas de productividad"],"fr":["fonctionnalité today","notes quotidiennes","modules ordonnés","modèles personnalisés","suivi d''études","outil de ligne de commande","Agent IA","Outils de productivité"],"de":["Funktion today","tägliche Notizen","geordnete Module","benutzerdefinierte Vorlagen","Lernfortschritt","Kommandozeilen-Schnittstelle","KI-Agent","Produktivitätstools"],"pt":["today","notas diárias automatizadas","módulos ordenados","registro de estudos","automação de notas","CLI","ferramentas de produtividade","gestão de tempo"],"ru":["today","автоматические дневные заметки","упорядоченные модули","учет обучения","автоматизация заметок","CLI","инструменты производительности","управление временем","ИИ Агенты"],"ar":["اليوم","ملاحظات يومية آلية","وحدات مرتبة","سجل الدراسة","أوتوماتيكية الملاحظات","CLI","أدوات الإنتاجية","إدارة الوقت","أدوات الذكاء الاصطناعي"]}},"owner":"0boluan0","repo":"Notes_on_Economic_Statistics","repoPath":"0boluan0/Notes_on_Economic_Statistics","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.372Z","topics":[],"category":"community","skillMd":{"name":"today","description":"Generate todays journal note when the user says /today or asks for a daily log. Use template `00_inbox/日记模版.md` (fallback `00_inbox/日记模板.md`), create the note in `99_学习情况记录`, add a Chinese-first global situation dashboard (map + a concise table summary + finance/tech bullets under the map) for the latest 24 hours, list unfinished tasks from existing notes in `99_学习情况记录`, and list todays tasks extracted from `Overview & Study Record.md` as markdown checkboxes.","bodyPreview":"# Today\n\n## Overview\n\nCreate one completed daily note with three ordered modules and save it to the study-log folder.\n\nUse this workflow every time the user asks for `/today`.\n\n## Workflow\n\n1. Resolve required paths.\n   - Prefer template `00_inbox/日记模版.md`.\n   - If missing, fallback to `00_inbox/日记模板.md`.\n   - Use output folder `99_学习情况记录`.\n   - Use overview file `Overview & Study Record.md`.\n\n2. Determine today''s target filename.\n   - Format: `YYYY-MM-DD——<DayAbbrev>.md` (for example `2026-02-0","body":"# Today\n\n## Overview\n\nCreate one completed daily note with three ordered modules and save it to the study-log folder.\n\nUse this workflow every time the user asks for `/today`.\n\n## Workflow\n\n1. Resolve required paths.\n   - Prefer template `00_inbox/日记模版.md`.\n   - If missing, fallback to `00_inbox/日记模板.md`.\n   - Use output folder `99_学习情况记录`.\n   - Use overview file `Overview & Study Record.md`.\n\n2. Determine today''s target filename.\n   - Format: `YYYY-MM-DD——<DayAbbrev>.md` (for example `2026-02-02——Mon.md`).\n   - If the file already exists, update it in place instead of creating a duplicate.\n\n3. Build module 1 (global dashboard, concise table + finance/tech bullets, Chinese-first).\n   - Run:\n     - `python3 .codex/skills/today/scripts/build_news_dashboard.py --date YYYY-MM-DD`\n   - The script creates a static SVG map in `98_attachment/dashboards` and prints the full module 1 markdown to stdout.\n   - Data source: default is `--source auto` (try World Monitor RSS digest, then fallback to GDELT). Override with `--source worldmonitor|gdelt` or env `TODAY_NEWS_SOURCE`.\n   - Use the printed markdown block directly (it already includes map embed + heat-weighted summary table + finance/tech bullets).\n   - Optional: add `--translate` and set `LIBRETRANSLATE_URL` to enable machine translation for the Chinese lines.\n   - If translation is not enabled or is inaccurate, translate the summaries manually before saving the note.\n   - Follow `references/news-format.md`.\n\n4. Build module 2 and module 3 (tasks) with the helper script.\n   - Run:\n     - `python3 .codex/skills/today/scripts/extract_today_tasks.py --date YYYY-MM-DD`\n   - Use the generated markdown block directly.\n   - If the script reports missing data, insert explicit placeholders instead of guessing.\n\n5. Compose the final note.\n   - Start from the resolved diary template content.\n   - Place module order exactly:\n     - Module 1: Global Situation Dashboard (Chinese-first)\n     - Module 2: Unfinished Tasks (from old diaries)\n     - Module 3: Today''s Tasks (from overview plan)\n   - Use markdown checkboxes (`- [ ]`) for all task bullets.\n\n6. Save and verify.\n   - Confirm file is under `99_学习情况记录`.\n   - Confirm all three modules exist.\n   - Confirm module 1 includes the map embed, summary table, and finance/tech bullets within latest 24 hours.\n\n## Notes\n\n- Do not edit `.obsidian/` files.\n- Do not fabricate news. If data is insufficient, state that clearly in the note.\n- Keep wording concise and execution-focused.\n"},"lastSynced":"2026-03-08T02:04:31.402Z","agentAnalysis":{"suitability":{"en":"Ideal for Note-taking Agents requiring automated daily log generation with markdown file handling.","zh":"适合需要自动化每日日志生成和markdown文件处理的笔记代理。","ja":"毎日のログ生成とmarkdownファイルの処理を自動化するためのノートエージェントに最適です。","ko":"자동화된 일일 로그 생성 및 마크다운 파일 처리가 필요한 노트 에이전트에 적합합니다.","es":"Ideal para agentes de toma de notas que requieren la generación automática de registros diarios con manejo de archivos markdown.","fr":"Idéal pour les agents de prise de notes nécessitant la génération automatisée de journaux quotidiens avec une gestion de fichiers markdown.","de":"Ideal für Notiz-Agents, die eine automatisierte tägliche Protokollgenerierung mit Markdown-Dateihandling erfordern.","pt":"Ideal para Agentes de Notas que exigem geração automática de registros diários com manipulação de arquivos markdown.","ru":"Идеально для Агентов заметок, требующих автоматическую генерацию ежедневных журналов с обработкой файлов markdown.","ar":"مثالي لعمليات ملاحظة الوكيل التي تتطلب جيل يومي آلي مع معالجة ملفات markdown."},"recommendation":{"en":"Empowers agents to create completed daily notes with three ordered modules, utilizing markdown templates and saving them to a specified study-log folder, leveraging file formats like .md and folder structures.","zh":"赋予代理创建完成的每日笔记的能力，利用三个有序模块，使用markdown模板，并将其保存到指定的学习日志文件夹中，利用文件格式如.md和文件夹结构。","ja":"エージェントに毎日のノートを完了する能力を与え、3つの順序付きモジュールを使用して、markdownテンプレートを使用し、それを指定された学習ログフォルダーに保存する機能を提供し、.mdなどのファイル形式やフォルダ構造を利用します。","ko":"에이전트가 완성된 일일 노트를 생성할 수 있는 기능을 제공하며, 세 가지 순서대로 된 모듈을 사용하여 마크다운 템플릿을 사용하고, 지정된 학습 로그 폴더에 저장하며, .md와 같은 파일 형식 및 폴더 구조를 활용합니다.","es":"Habilita a los agentes a crear notas diarias completas con tres módulos ordenados, utilizando plantillas markdown y guardándolas en una carpeta de registro de estudio especificada, aprovechando formatos de archivo como .md y estructuras de carpetas.","fr":"Permet aux agents de créer des notes quotidiennes complètes avec trois modules ordonnés, en utilisant des modèles markdown et en les sauvegardant dans un dossier de journal d''étude spécifié, en exploitant des formats de fichiers comme .md et des structures de dossiers.","de":"Ermächtigt Agenten, tägliche Notizen mit drei geordneten Modulen zu erstellen, indem sie Markdown-Vorlagen verwenden und sie in einem bestimmten Studien-Log-Verzeichnis speichern, wobei Dateiformate wie .md und Verzeichnisstrukturen genutzt werden.","pt":"Habilite os agentes a criar notas diárias concluídas com três módulos ordenados, utilizando modelos markdown e salvando-os em uma pasta de registro de estudos especificada, aproveitando formatos de arquivo como .md e estruturas de pasta.","ru":"Наделяет агентов возможностью создавать завершенные ежедневные заметки с тремя упорядоченными модулями, использующими шаблоны markdown и сохраняющими их в указанной папке учета обучения, используя форматы файлов как .md и структуры папок.","ar":"يمنح الوكيل القدرة على إنشاء ملاحظات يومية مكتملة مع ثلاث وحدات مترتبة، باستخدام قوالب markdown و حفظها في مجلد سجل دراسي محدد، واستغلال تنسيقات الملفات مثل .md و هيكل المجلدات."},"useCases":{"en":["Automating daily note-taking workflows","Generating study records with custom templates","Organizing files in a study-log folder"],"zh":["自动化每日笔记工作流程","使用自定义模板生成学习记录","在学习日志文件夹中组织文件"],"ja":["毎日のノートワークフローを自動化する","カスタムテンプレートを使用して学習レコードを生成する","学習ログフォルダーでファイルを整理する"],"ko":["일일 노트 워크플로를 자동화하는 것","사용자 정의 템플릿을 사용하여 학습 기록을 생성하는 것","학습 로그 폴더에서 파일을 조직하는 것"],"es":["Automatización de flujos de trabajo de toma de notas diarias","Generación de registros de estudio con plantillas personalizadas","Organización de archivos en una carpeta de registro de estudio"],"fr":["Automatisation des flux de travail de prise de notes quotidiennes","Génération d''enregistrements d''étude avec des modèles personnalisés","Organisation de fichiers dans un dossier de journal d''étude"],"de":["Automatisierung von täglichen Notiz-Workflows","Erstellung von Studienaufzeichnungen mit benutzerdefinierten Vorlagen","Organisation von Dateien in einem Studien-Log-Verzeichnis"],"pt":["Automatizar fluxos de trabalho de notas diárias","Gerar registros de estudo com modelos personalizados","Organizar arquivos em uma pasta de registro de estudos"],"ru":["Автоматизировать рабочие процессы заметок за день","Генерировать записи обучения с пользовательскими шаблонами","Организовывать файлы в папке учета обучения"],"ar":["التحكم الآلي في سير عمل ملاحظات اليومية","توليد سجلات الدراسة مع قوالب مخصصة","تنظيم الملفات في مجلد سجل الدراسي"]},"limitations":{"en":["Requires access to file system for reading and writing markdown files","Dependent on specific template files like 00_inbox/日记模版.md or 00_inbox/日记模板.md"],"zh":["需要访问文件系统以读取和写入markdown文件","依赖于特定的模板文件，如00_inbox/日记模版.md或00_inbox/日记模板.md"],"ja":["markdownファイルを読み書きするためにファイルシステムへのアクセスが必要","00_inbox/日记模版.mdまたは00_inbox/日记模板.mdなどの特定のテンプレートファイルに依存する"],"ko":["마크다운 파일을 읽고 쓰기 위해 파일 시스템에 접근할 수 있어야 함","00_inbox/일기模板.md 또는 00_inbox/일기模板.md와 같은 특정 템플릿 파일에 의존함"],"es":["Requiere acceso al sistema de archivos para leer y escribir archivos markdown","Dependiente de archivos de plantilla específicos como 00_inbox/日记模版.md o 00_inbox/日记模板.md"],"fr":["Nécessite un accès au système de fichiers pour lire et écrire des fichiers markdown","Dépendant de fichiers de modèle spécifiques comme 00_inbox/日记模版.md ou 00_inbox/日记模板.md"],"de":["Benötigt Zugriff auf das Dateisystem zum Lesen und Schreiben von Markdown-Dateien","Abhängig von bestimmten Vorlagendateien wie 00_inbox/日记模版.md oder 00_inbox/日记模板.md"],"pt":["Exige acesso ao sistema de arquivos para leitura e gravação de arquivos markdown","Dependente de arquivos de modelo específicos como 00_inbox/日记模版.md ou 00_inbox/日记模板.md"],"ru":["Требует доступа к файловой системе для чтения и записи файлов markdown","Зависит от определенных файлов шаблонов, таких как 00_inbox/日记模版.md или 00_inbox/日记模板.md"],"ar":["يتطلب الوصول إلى نظام الملفات للقراءة والكتابة من ملفات markdown","يعتمد على ملفات نموذجية محددة مثل 00_inbox/日记模版.md أو 00_inbox/日记模板.md"]},"version":4},"contentHash":"9027cd7d40f211b5a96ce3773b140f7f309f8aba8ff3964f3855f4be9b46507c","qualityScore":23}');
