INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('0boluan0/Notes_on_Economic_Statistics/today', 'today', '0boluan0', 'Notes_on_Economic_Statistics', 'community', 'today 0boluan0 Notes_on_Economic_Statistics community The today skill creates a completed daily note with three ordered modules and saves it to the study-log folder. It benefits developers who want to automate their daily note-taking workflow. 使用AI工具创建每日记录，包括模板解析和文件保存。该工具使用特定的模板和文件夹结构来组织记录。 AIエージェントを使用して日常の記録を作成します。特定のテンプレートとフォルダ構造を使用して記録を整理します。 AI 도구를 사용하여 일일 노트를 생성합니다. 특정 템플릿과 폴더 구조를 사용하여 기록을 구성합니다. La habilidad ''today'' crea una nota diaria con tres módulos ordenados y la guarda en la carpeta de registro de estudios. Utiliza plantillas y archivos de salida personalizados. La fonctionnalité ''today'' crée une note quotidienne avec trois modules ordonnés et la sauvegarde dans le dossier de suivi d''études. Elle utilise des modèles et des fichiers de sortie personnalisés. Die ''today''-Funktion erstellt eine tägliche Notiz mit drei geordneten Modulen und speichert sie im Lernfortschrittsordner. Sie verwendet benutzerdefinierte Vorlagen und Ausgabedateien. O Today é uma ferramenta que cria notas diárias automatizadas com três módulos ordenados e as salva em uma pasta de registro de estudos Today - это инструмент, который создает автоматические дневные заметки с тремя упорядоченными модулями и сохраняет их в папке учета обучения اليوم هو أداة لإنشاء ملاحظات يومية آلية مع ثلاث وحدات مرتبة وتحفظها في مجلد سجل الدراسة how to use today skill today skill setup guide automated daily note generation today skill alternative today skill vs manual note-taking today skill install what is today skill today skill for ai agents today skill workflow automation AI工具 日常记录 模板解析 文件保存 今日日志创建 自动化日常记录 生产力工具 日志创建指南 Resolves required paths using template 00_inbox/日记模版.md or fallback template 00_inbox/日记模板.md Determines today''s target filename using the format YYYY-MM-DD——<DayAbbrev>.md Saves daily notes to the 99_学习情况记录 folder Uses the Overview & Study Record.md file for overview purposes Automates daily note creation using a workflow triggered by the /today command today is a skill that automates the creation of daily notes using a template and saves them to a specified folder, utilizing a specific filename format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Metta-AI/tribal-village/lint-fix', 'community', 'Metta-AI', 'tribal-village', 'Metta-AI/tribal-village', 'lint-fix', 0, 0, 23, '2026-03-08T01:57:15.373Z', '2026-03-08T02:04:31.870Z', '9ec767447c3747fffebbd83ceb81420e0ef19629ecedd01ce540631c7e0d1283', '{"id":"Metta-AI/tribal-village/lint-fix","name":"lint-fix","description":{"en":"The lint-fix skill automates code refactoring by running the lint autofix command and summarizing edits. It benefits developers by limiting changes to relevant files.","zh":"lint-fix 是一个自动代码修复工具，能够自动运行 lint 命令和修复代码","ja":"lint-fix は、AIエージェントを使用したコード自動修正ツールです","ko":"lint-fix는 코드 자동 수정을 위한 도구로 lint 명령을 자동으로 실행하고 코드를 수정합니다","es":"lint-fix es una herramienta que automatiza la corrección de errores en el código. Se ejecuta mediante el comando ''metta lint --fix'' y permite corregir errores de manera automática.","fr":"lint-fix est un outil qui automatise la correction des erreurs dans le code. Il s''exécute via la commande ''metta lint --fix'' et permet de corriger les erreurs de manière automatique.","de":"lint-fix ist ein Tool, das die Korrektur von Fehlern im Code automatisiert. Es wird über den Befehl ''metta lint --fix'' ausgeführt und ermöglicht die automatische Korrektur von Fehlern.","pt":"O Lint Fix é uma ferramenta que automatiza a correção de erros de código, melhorando a qualidade do projeto. Ele executa comandos de lint e corrige erros automaticamente.","ru":"Lint Fix - это инструмент, который автоматизирует исправление ошибок кода, улучшая качество проекта. Он выполняет команды lint и исправляет ошибки автоматически с помощью ИИ Агентов.","ar":"أداة لينت fikس هي أداة تلقائية لتصحيح الأخطاء في الكود، وتحسين جودة المشروع. أنها تنفذ أوامر لينت وتصلح الأخطاء تلقائيًا باستخدام أدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"lint-fix: Automated Code Refactoring Setup Guide | AI Age...","zh":"lint-fix Setup Guide: 自动代码修复工具","ja":"lint-fix のベストプラクティス: AIエージェントによるコード自動修正","ko":"lint-fix 설치 가이드: 코드 자동 수정을 위한 최적의 도구","es":"Guía de configuración de lint-fix para desarrolladores","fr":"Configurer lint-fix: Guide pratique pour les développeurs","de":"Einrichten von lint-fix: Leitfaden für Entwickler","pt":"Guia de Configuração do Lint Fix: Melhores Práticas para ...","ru":"ИИ Агенты: Настройка Lint Fix для Автоматического Исправл...","ar":"إعداد أداة لينت fikس: دليل للمطورين لتحسين جودة الكود"},"description":{"en":"Discover how to automate code linting and fixing with lint-fix. Learn how to setup and use metta lint --fix to streamline your development workflow","zh":"了解 lint-fix 的工作流程和自动代码修复功能，优化您的开发体验","ja":"lint-fix の機能とワークフローを確認し、コードの自動修正を実現する","ko":"lint-fix의 자동 코드 수정 기능과 워크플로우를 알아보고 개발 효율을 높여보세요","es":"Aprende a utilizar lint-fix para automatizar la corrección de errores en tu código. Descubre cómo configurar y ejecutar lint-fix de manera efectiva.","fr":"Découvrez comment utiliser lint-fix pour automatiser la correction des erreurs dans votre code. Apprenez à configurer et exécuter lint-fix de manière efficace.","de":"Erfahren Sie, wie Sie lint-fix verwenden, um Fehler in Ihrem Code zu automatisieren. Entdecken Sie, wie Sie lint-fix effektiv konfigurieren und ausführen.","pt":"Aprenda a configurar o Lint Fix para automatizar a correção de erros de código e melhorar a qualidade do seu projeto","ru":"Узнайте, как настроить Lint Fix для автоматического исправления ошибок кода и улучшения качества вашего проекта с помощью ИИ Агентов","ar":"اكتشف كيفية إعداد أداة لينت fikس لتصحيح الأخطاء تلقائيًا وتحسين جودة مشروعك باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"lint-fix is a skill that automates the process of fixing lint errors using the metta lint --fix command","zh":"lint-fix 是一个自动代码修复工具，用于运行 lint 命令和修复代码错误","ja":"lint-fix は、コードの自動修正を実現する AIエージェントツールです","ko":"lint-fix는 코드의 자동 수정을 위한 도구로 코드 오류를 수정하는 기능을 제공합니다","es":"lint-fix es una herramienta de automatización de corrección de errores que utiliza el comando ''metta lint --fix'' para corregir errores en el código.","fr":"lint-fix est un outil d''automatisation de correction d''erreurs qui utilise la commande ''metta lint --fix'' pour corriger les erreurs dans le code.","de":"lint-fix ist ein Tool zur Automatisierung der Fehlerkorrektur, das den Befehl ''metta lint --fix'' verwendet, um Fehler im Code zu korrigieren.","pt":"O Lint Fix é uma ferramenta de correção automática de erros de código que melhora a qualidade do projeto","ru":"Lint Fix - это инструмент автоматического исправления ошибок кода, который улучшает качество проекта с помощью ИИ Агентов","ar":"أداة لينت fikس هي أداة لتصحيح الأخطاء تلقائيًا في الكود، وتحسين جودة المشروع باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Runs the lint autofix command using metta lint --fix","Summarizes edits and re-runs lint if needed","Limits changes to relevant files","Confirms the lint command and allowlist paths","Manually fixes remaining lint failures"],"zh":["自动运行 lint 命令","代码自动修复功能","支持 allowlist 路径","手动修复剩余的 lint 错误","代码修改总结和重新运行 lint"],"ja":["lint コマンドの自動実行","コードの自動修正機能","allowlist パスのサポート","残りの lint エラーの手動修正","コード変更の要約と lint の再実行"],"ko":["lint 명령의 자동 실행","코드 자동 수정 기능","allowlist 경로 지원","남은 lint 오류의 수동 수정","코드 수정 요약과 lint 재실행"],"es":["Ejecuta el comando ''metta lint --fix'' para corregir errores de manera automática","Permite corregir errores en archivos relevantes","Resume los cambios realizados y vuelve a ejecutar lint si es necesario","Utiliza allowlist paths para personalizar la corrección de errores","Corrige errores de manera automática y manual","Integra con herramientas de desarrollo como metta"],"fr":["Exécute la commande ''metta lint --fix'' pour corriger les erreurs de manière automatique","Permet de corriger les erreurs dans les fichiers pertinents","Résume les modifications apportées et réexécute lint si nécessaire","Utilise les chemins allowlist pour personnaliser la correcti