INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mufengbufeng/opence/opence-plan', 'opence-plan', 'mufengbufeng', 'opence', 'community', 'opence-plan mufengbufeng opence community The opence-plan skill provides a straightforward approach to development, favoring minimal implementations and adding complexity only when necessary, benefiting AI agent developers. Opence-plan是一种遵循简单和可扩展原则的AI工具开发框架，帮助开发者创建高效的AI解决方案 Opence-planは、シンプルさとスケーラビリティを重視したAIエージェント開発フレームワークです Opence-plan은 단순성과 확장성을 강조하는 AI 에이전트 개발 프레임워크로 개발자가 효율적인 AI 솔루션을 구축하도록 도와줍니다 opence-plan es un enfoque minimalista para implementar agentes de IA, que prioriza la simplicidad y la claridad opence-plan est une approche minimaliste pour mettre en œuvre les outils d''IA, qui donne la priorité à la simplicité et à la clarté opence-plan ist ein minimalistsicher Ansatz für die Implementierung von KI-Agents, der Einfachheit und Klarheit priorisiert O Opence-Plan é uma habilidade que ajuda desenvolvedores a criar implementações mínimas e evitar complexidade desnecessária. Aprenda a configurá-lo com nossas melhores práticas. Opence-Plan - это навык, который помогает разработчикам создавать минимальные реализации и избегать ненужной сложности. Узнайте, как настроить его с нашим руководством. Opence-Plan هو مهارة تساعد المطورين على إنشاء التنفيذات المعدلة وتجنب التعقيد غير الضروري. تعرف على كيفية إعدادها باستخدام أفضل الممارسات لتنمية أدوات الذكاء الاصطناعي. how to use opence-plan opence-plan setup guide opence-plan alternative opence-plan vs other development approaches opence-plan install what is opence-plan opence-plan best practices opence-plan for AI agents opence-plan development methodology Opence-plan AI工具开发 简单和可扩展 紧密范围的更改 清晰的编码约定 AIエージェント opence/AGENTS.md Implements guardrails for minimal implementations Scoped changes to requested outcomes Refers to opence/AGENTS.md for conventions and clarifications Identifies vague details and prompts follow-up questions Utilizes ls opence and opence update commands for directory management opence-plan is a development approach that emphasizes simplicity, scoped changes, and clear communication, following conventions outlined in opence/AGENTS.md');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('claushaas/palette-kit/color-pipeline-implementer', 'community', 'claushaas', 'palette-kit', 'claushaas/palette-kit', 'color-pipeline-implementer', 0, 0, 23, '2026-03-08T01:57:15.377Z', '2026-03-08T02:05:24.298Z', 'ca046027bd0f085f1f5b6e878e2a791c854574ef78fed81bf8ca1832ea53d442', '{"id":"claushaas/palette-kit/color-pipeline-implementer","name":"color-pipeline-implementer","description":{"en":"The color-pipeline-implementer skill helps developers implement color pipeline stages, including parsing, normalization, and semantic resolution. It benefits developers working with color manipulation and OKLCH color space.","zh":"Color Pipeline Implementer技能用于实现和调整颜色管道阶段，包括解析、归一化和基本验证","ja":"Color Pipeline Implementerスキルは、カラーパイプラインステージの実装と調整に使用され、解析、正規化、基本的な検証が含まれます","ko":"컬러 파이프라인 구현을 위한 Color Pipeline Implementer 스킬은 파이프라인 단계의 구현과 조정을 위한 것으로, 파싱, 정규화, 기본 검증 등을 포함","es":"El implementador de tubería de color es un agente de AI que ayuda a implementar y ajustar las etapas de la tubería de color, utilizando tecnologías como OKLCH y RGB","fr":"L''implémenteur de pipeline de couleur est un outil d''agent d''IA qui aide à mettre en œuvre et à ajuster les étapes du pipeline de couleur, en utilisant des technologies telles que OKLCH et RGB","de":"Der Farbpipeline-Implementierer ist ein KI-Tool, das hilft, die Farbpipeline-Stufen zu implementieren und anzupassen, unter Verwendung von Technologien wie OKLCH und RGB","pt":"O Color Pipeline Implementer é uma ferramenta para implementar e ajustar as etapas da pipeline de cores. Ele oferece funcionalidades como análise e normalização de cores","ru":"ИИ Агент Color Pipeline Implementer - это инструмент для реализации и настройки этапов цветовой трубы. Он предлагает функции, такие как анализ и нормализация цветов","ar":"أداة تحويل خط أنابيب الألوان هي أداة لتنفيذ وتعديل مراحل خط أنابيب الألوان. توفر ميزات مثل تحليل وتنظيم الألوان"},"seo":{"title":{"en":"color-pipeline-implementer: Setup Guide for AI Agents | A...","zh":"颜色管道实施指南 - Color Pipeline Implementer","ja":"カラーパイプライン実装セットアップガイド - AIエージェント","ko":"컬러 파이프라인 구현 방법 - Color Pipeline Implementer","es":"Implementador de tubería de color: Guía de configuración","fr":"Implémenteur de pipeline de couleur: Meilleures pratiques","de":"Farbpipeline-Implementierer: Einrichtungsleitfaden","pt":"Guia de Configuração do Color Pipeline Implementer","ru":"Руководство по настройке ИИ Агента Color Pipeline Impleme...","ar":"دليل إعداد أداة تحويل خط أنابيب الألوان"},"description":{"en":"Discover how to implement the color pipeline stages with the color-pipeline-implementer skill. Learn how to parse, normalize, and resolve colors with OKLCH a...","zh":"了解如何使用Color Pipeline Implementer技能来实现和调整颜色管道阶段，包括解析、归一化和基本验证","ja":"Color Pipeline Implementerスキルを使用してカラーパイプラインステージを実装および調整する方法について学びます","ko":"컬러 파이프라인 구현을 위한 Color Pipeline Implementer 스킬을 사용하여 파이프라인 단계를 구현하고 조정하는 방법","es":"Aprende a implementar la tubería de color con nuestro agente de AI Herramientas, incluyendo parsing, normalización y escalas básicas","fr":"Découvrez comment mettre en œuvre le pipeline de couleur avec notre outil d''agent d''IA, y compris l''analyse, la normalisation et les échelles de base","de":"Erfahren Sie, wie Sie die Farbpipeline mit unserem KI-Tool implementieren, einschließlich Parsing, Normalisierung und Basis-Skalen","pt":"Aprenda a implementar e ajustar as etapas da pipeline de cores com o Color Pipeline Implementer. Veja como configurar a análise e normalização de cores","ru":"Узнайте, как реализовать и настроить этапы цветовой трубы с помощью ИИ Агента Color Pipeline Implementer. Прочитайте о конфигурации анализа и нормализации цв...","ar":"تعرف على كيفية تنفيذ وتعديل مراحل خط أنابيب الألوان باستخدام أداة تحويل خط أنابيب الألوان. اقرأ حول إعداد تحليل وتنظيم الألوان"},"definition":{"en":"color-pipeline-implementer is a skill that assists in implementing and adjusting color pipeline stages using OKLCH color space and TypeScript.","zh":"Color Pipeline Implementer是实现和调整颜色管道阶段的技能","ja":"Color Pipeline Implementerは、カラーパイプラインステージの実装と調整を行うスキルです","ko":"컬러 파이프라인 구현은 파이프라인 단계를 구현하고 조정하는 스킬","es":"Un implementador de tubería de color es un agente de AI que ayuda a implementar y ajustar las etapas de la tubería de color","fr":"Un implémenteur de pipeline de couleur est un outil d''agent d''IA qui aide à mettre en œuvre et à ajuster les étapes du pipeline de couleur","de":"Ein Farbpipeline-Implementierer ist ein KI-Tool, das hilft, die Farbpipeline-Stufen zu implementieren und anzupassen","pt":"O Color Pipeline Implementer é uma ferramenta que implementa a pipeline de cores para análise e normalização de cores","ru":"ИИ Агент Color Pipeline Implementer - это инструмент, который реализует цветовую трубу для анализа и нормализации цветов","ar":"أداة تحويل خط أنابيب الألوان هي أداة تنفذ خط أنابيب الألوان لتحليل وتنظيم الألوان"},"features":{"en":["Implements parsing of hex/rgb colors to OKLCH in src/utils/parseColor.ts","Normalizes colors by clamping L/C/H values and applying defaults in src/engine/normalize.ts","Resolves semantic colors using base scales in src/engine","Preserves alpha channel during color parsing","Follows v0.3 documentation for color pipeline implementation","Reads spec-v0.3.md and roadmap-v0.3.md for workflow planning"],"zh":["实现hex/rgb到OKLCH的解析","实现L/C/H的clamp和默认值","基本验证和错误处理","使用src/utils/parseColor.ts和src/engine/normalize.ts","支持颜色管道的各个阶段"],"ja":["hex/rgbからOKLCHへの解析を実装","L/C/Hのクランプとデフォルト値を実装","基本的な検証とエラー処理","src/utils/parseColor.tsとsrc/engine/normalize.tsを使用","カラーパイプラインの各段階をサポート"],"ko":["hex/rgb를 OKLCH로 파싱","L/C/H를 클램프하고 기본값을 설정","기본적인 검증과 오류 처리","src/utils/parseColor.ts와 src/engine/normalize.ts 사용","컬러 파이프라인의 각 단계 지원"],"es":["Parsing de colores hex y RGB a OKLCH","Normalización de colores con clamp L/C/H","Implementación de escalas básicas y resolución semántica","Uso de la versión 0.3 de la documentación como fuente de verdad","Integración con tecnologías como OKLCH y RGB"],"fr":["Analyse des couleurs hex et RGB en OKLCH","Normalisation des couleurs avec clamp L/C/H","Mise en œuvre d''échelles de base et de résolution sémantique","Utilisation de la version 0.3 de la documentation comme source de vérité","Intégration avec des technologies telles que OKLCH et RGB"],"de":["Parsing von Farben hex und RGB in OKLCH","Normalisierung von Farben mit clamp L/C/H","Implementierung von Basis-Skalen und semantischer Auflösung","Verwendung der Version 0.3 der Dokumentation als Quelle der Wahrheit","Integration mit Technologien wie OKLCH und RGB"],"pt":["Análise de cores em formato hex/rgb para OKLCH","Normalização de cores com clamp L/C/H e validação básica","Implementação de escalas de base e resolução semântica","Leitura de arquivos de especificação em src/planning/spec-v0.3.md","Implementação de parsing em src/utils/parseColor.ts","Normalização em src/engine/normalize.ts"],"ru":["Анализ цветов в формате hex/rgb для OKLCH","Нормализация цветов с зажимом L/C/H и базовой валидацией","Реализация базовых масштабов и семантической разрядки","Чтение файлов спецификации в src/planning/spec-v0.3.md","Реализация парсинга в src/utils/parseColor.ts","Нормализация в src/engine/normalize.ts"],"ar":["تحليل الألوان في تنسيق hex/rgb إلى OKLCH","تنظيم الألوان مع حارس L/C/H والتحقق الأساسي","تنفيذ المقاييس الأساسية والتحليل الدلالي","قراءة ملفات المواصفات في src/planning/spec-v0.3.md","تنفيذ تحليل في src/utils/parseColor.ts","تنظيم في src/engine/normalize.ts"]},"keywords":{"en":["how to use color-pipeline-implementer","color-pipeline-implementer setup guide","color-pipeline-implementer alternative","color-pipeline-implementer vs OKLCH","implementing color pipeline stages","OKLCH color space tutorial","color-pipeline-implementer install","TypeScript color manipulation","color pipeline implementation best practices"],"zh":["颜色管道实施","Color Pipeline Implementer","颜色管道阶段","解析和归一化","基本验证","AI工具","AIエージェント"],"ja":["カラーパイプライン実装","Color Pipeline Implementer","カラーパイプラインステージ","解析と正規化","基本的な検証","AIエージェント","AIツール"],"ko":["컬러 파이프라인 구현","Color Pipeline Implementer","파이프라인 단계","파싱과 정규화","기본적인 검증","AI 에이전트","AI 도구"],"es":["implementador de tubería de color","agente de AI","tubería de color","OKLCH","RGB","normalización de colores","escalas básicas","resolución semántica"],"fr":["implémenteur de pipeline de couleur","outil d''agent d''IA","pipeline de couleur","OKLCH","RGB","normalisation des couleurs","échelles de base","résolution sémantique"],"de":["Farbpipeline-Implementierer","KI-Tool","Farbpipeline","OKLCH","RGB","Normalisierung von Farben","Basis-Skalen","semantische Auflösung"],"pt":["color pipeline implementer","análise de cores","normalização de cores","OKLCH","hex/rgb","escalas de base","resolução semântica","parseColor.ts","normalize.ts"],"ru":["ИИ Агент Color Pipeline Implementer","анализ цветов","нормализация цветов","OKLCH","hex/rgb","базовые масштабы","семантическая разрядка","parseColor.ts","normalize.ts"],"ar":["أداة تحويل خط أنابيب الألوان","تحليل الألوان","تنظيم الألوان","OKLCH","hex/rgb","المقاييس الأساسية","التحليل الدلالي","parseColor.ts","normalize.ts"]}},"owner":"claushaas","repo":"palette-kit","repoPath":"claushaas/palette-kit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.377Z","topics":[],"category":"community","skillMd":{"name":"color-pipeline-implementer","description":"Implement or adjust the core color pipeline (parse, normalize, scale, resolve) guided by src/planning/spec-v0.3.md and src/planning/roadmap-v0.3.md.","bodyPreview":"# Color Pipeline Implementer\n\nUse this skill when implementing or adjusting the color pipeline stages. Use the v0.3 docs as the source of truth.\n\n## Workflow\n\n1. Read `src/planning/spec-v0.3.md` and the relevant phase in `src/planning/roadmap-v0.3.md`.\n2. Implement parsing in `src/utils/parseColor.ts` (hex/rgb to OKLCH, preserve alpha).\n3. Implement normalization in `src/engine/normalize.ts` (clamp L/C/H, defaults, basic validation).\n4. Implement base scales and semantic resolution in `src/engin","body":"# Color Pipeline Implementer\n\nUse this skill when implementing or adjusting the color pipeline stages. Use the v0.3 docs as the source of truth.\n\n## Workflow\n\n1. Read `src/planning/spec-v0.3.md` and the relevant phase in `src/planning/roadmap-v0.3.md`.\n2. Implement parsing in `src/utils/parseColor.ts` (hex/rgb to OKLCH, preserve alpha).\n3. Implement normalization in `src/engine/normalize.ts` (clamp L/C/H, defaults, basic validation).\n4. Implement base scales and semantic resolution in `src/engine/` as per spec ordering.\n5. Add focused tests for each stage before moving to the next change.\n\n## Guardrails\n\n- Keep logic incremental; avoid skipping phase boundaries.\n- Preserve output contracts (`ResolvedColor`, `ColorMeta`) as defined in `src/types`.\n- Keep BaseResolvedColor runtime shape stable.\n- Prefer small PR-sized changes with clear acceptance criteria.\n"},"lastSynced":"2026-03-08T02:05:24.298Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual Design Agents needing advanced color manipulation and OKLCH color space capabilities.","zh":"非常适合需要高级颜色操作和OKLCH颜色空间功能的视觉设计代理。","ja":"ビジュアルデザインエージェントが高度な色操作およびOKLCH色空間機能を必要とする場合に最適です。","ko":"고급 색상 조작 및 OKLCH 색상 공간 기능이 필요한 시각 디자인 에이전트에 적합합니다.","es":"Perfecto para agentes de diseño visual que necesitan manipulación de color avanzada y capacidades de espacio de color OKLCH.","fr":"Parfait pour les agents de conception visuelle nécessitant une manipulation de couleur avancée et des capacités d''espace de couleur OKLCH.","de":"Perfekt für visuelle Designagenten, die eine erweiterte Farbmanipulation und OKLCH-Farbraumfunktionen benötigen.","pt":"Perfeito para Agentes de Design Visual que precisam de manipulação avançada de cores e capacidades de espaço de cor OKLCH.","ru":"Идеально подходит для агентов визуального дизайна, требующих продвинутой манипуляции цветом и возможностей пространства цвета OKLCH.","ar":"مثالي للوكلاء التصميم المرئي الذين يحتاجون إلى تعامل متقدم بالألوان وقدرات مساحة اللون OKLCH."},"recommendation":{"en":"Empowers agents to implement color pipeline stages, including parsing, normalization, and semantic resolution, using OKLCH color space and TypeScript, while preserving alpha channels and performing basic validation.","zh":"赋予代理实现颜色管道阶段的能力，包括解析、归一化和语义解析，使用OKLCH色空间和TypeScript，同时保留alpha通道并执行基本验证。","ja":"OKLCH色空間とTypeScriptを使用して、パース、正規化、セマンティック解決を含むカラーパイプラインの段階を実装するエージェントの能力を提供します。また、アルファチャンネルを保持し、基本的な検証を実行します。","ko":"OKLCH 색상 공간 및 TypeScript를 사용하여 파싱, 정규화, 의미 분석을 포함한 색상 파이프 라인 단계를 구현하는 에이전트의 기능을 제공합니다. 또한 알파 채널을 유지하고 기본 유효성 검사를 수행합니다.","es":"Habilita a los agentes a implementar etapas de canalización de color, incluyendo análisis, normalización y resolución semántica, utilizando el espacio de color OKLCH y TypeScript, preservando canales alfa y realizando una validación básica.","fr":"Permet aux agents de mettre en œuvre des étapes de pipeline de couleur, y compris l''analyse, la normalisation et la résolution sémantique, en utilisant l''espace de couleur OKLCH et TypeScript, en préservant les canaux alpha et en effectuant une validation de base.","de":"Ermöglicht es Agenten, Farbpipeline-Stadien zu implementieren, einschließlich Parsing, Normalisierung und semantischer Auflösung, unter Verwendung des OKLCH-Farbraums und TypeScript, während Alpha-Kanäle erhalten und eine grundlegende Validierung durchgeführt werden.","pt":"Permite que os agentes implementem etapas do pipeline de cores, incluindo análise, normalização e resolução semântica, usando o espaço de cor OKLCH e TypeScript, preservando canais alfa e realizando validação básica.","ru":"Наделяет агентов возможностью реализовать этапы цветового конвейера, включая парсинг, нормализацию и семантическое разрешение, используя пространство цвета OKLCH и TypeScript, сохраняя альфа-каналы и выполняя базовую валидацию.","ar":"يسمح للوكلاء بتنفيذ مراحل أنابيب الألوان، بما في ذلك تحليل وتنميط ودقة دلالية، باستخدام مساحة اللون OKLCH وTypeScript، مع الحفاظ على قنوات ألفا والتحقق من الصحة الأساسي."},"useCases":{"en":["Implementing color parsing from hex/rgb to OKLCH","Normalizing color values with clamping and default settings","Resolving semantic colors using base scales"],"zh":["实现从十六进制/rgb到OKLCH的颜色解析","使用夹持和默认设置对颜色值进行归一化","使用基准比例解析语义颜色"],"ja":["16進数/RGBからOKLCHへのカラー解析の実装","クランプとデフォルト設定を使用したカラー値の正規化","ベーススケールを使用したセマンティックカラーの解析"],"ko":["16진수/RGB에서 OKLCH로의 색상 파싱 구현","클램핑 및 기본 설정을 사용한 색상 값 정규화","베이스 스케일을 사용한 의미 색상 해석"],"es":["Implementar el análisis de color de hex/rgb a OKLCH","Normalizar valores de color con bloqueo y configuraciones predeterminadas","Resolver colores semánticos utilizando escalas base"],"fr":["Mettre en œuvre l''analyse de couleur de hex/rgb à OKLCH","Normaliser les valeurs de couleur avec blocage et paramètres par défaut","Résoudre les couleurs sémantiques en utilisant des échelles de base"],"de":["Implementierung der Farbanalyse von hex/rgb in OKLCH","Normalisierung von Farbwerten mit Blockierung und Standard-Einstellungen","Auflösung semantischer Farben unter Verwendung von Basis-Skalen"],"pt":["Implementar análise de cores de hex/rgb para OKLCH","Normalizar valores de cores com ajuste e configurações padrão","Resolver cores semânticas usando escalas base"],"ru":["Реализовать парсинг цветов из hex/rgb в OKLCH","Нормализовать значения цвета с зажимом и настройками по умолчанию","Разрешить семантические цвета, используя базовые шкалы"],"ar":["تنفيذ تحليل الألوان من十六ية/أحمر-أخضر-أزرق إلى OKLCH","تنميط قيم الألوان مع تثبيت وإعدادات افتراضية"," حل الألوان الدلالية باستخدام السلالم الأساسية"]},"limitations":{"en":["Requires access to src/planning/spec-v0.3.md and src/planning/roadmap-v0.3.md documentation","TypeScript environment needed","OKLCH color space specific"],"zh":["需要访问src/planning/spec-v0.3.md和src/planning/roadmap-v0.3.md文档","需要TypeScript环境","OKLCH颜色空间特定"],"ja":["src/planning/spec-v0.3.mdおよびsrc/planning/roadmap-v0.3.mdのドキュメントへのアクセスが必要","TypeScript環境が必要","OKLCH色空間固有"],"ko":["src/planning/spec-v0.3.md 및 src/planning/roadmap-v0.3.md 문서에 대한 액세스가 필요합니다","TypeScript 환경이 필요합니다","OKLCH 색상 공간에 특정"],"es":["Requiere acceso a la documentación src/planning/spec-v0.3.md y src/planning/roadmap-v0.3.md","Entorno de TypeScript necesario","Específico del espacio de color OKLCH"],"fr":["Nécessite un accès à la documentation src/planning/spec-v0.3.md et src/planning/roadmap-v0.3.md","Environnement TypeScript nécessaire","Spécifique à l''espace de couleur OKLCH"],"de":["Erfordert Zugriff auf die Dokumentation src/planning/spec-v0.3.md und src/planning/roadmap-v0.3.md","TypeScript-Umgebung erforderlich","Spezifisch für den OKLCH-Farbraum"],"pt":["Requer acesso à documentação src/planning/spec-v0.3.md e src/planning/roadmap-v0.3.md","Ambiente TypeScript necessário","Específico do espaço de cor OKLCH"],"ru":["Требует доступа к документации src/planning/spec-v0.3.md и src/planning/roadmap-v0.3.md","Необходимо окружение TypeScript","Специфичен для пространства цвета OKLCH"],"ar":["يتطلب الوصول إلى توثيق src/planning/spec-v0.3.md و src/planning/roadmap-v0.3.md","بيئة TypeScript ضرورية","محدد لمساحة اللون OKLCH"]},"version":4},"contentHash":"ca046027bd0f085f1f5b6e878e2a791c854574ef78fed81bf8ca1832ea53d442","qualityScore":23}');
