INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('claushaas/palette-kit/color-pipeline-implementer', 'color-pipeline-implementer', 'claushaas', 'palette-kit', 'community', 'color-pipeline-implementer claushaas palette-kit community The color-pipeline-implementer skill helps developers implement color pipeline stages, including parsing, normalization, and semantic resolution. It benefits developers working with color manipulation and OKLCH color space. Color Pipeline Implementer技能用于实现和调整颜色管道阶段，包括解析、归一化和基本验证 Color Pipeline Implementerスキルは、カラーパイプラインステージの実装と調整に使用され、解析、正規化、基本的な検証が含まれます 컬러 파이프라인 구현을 위한 Color Pipeline Implementer 스킬은 파이프라인 단계의 구현과 조정을 위한 것으로, 파싱, 정규화, 기본 검증 등을 포함 El implementador de tubería de color es un agente de AI que ayuda a implementar y ajustar las etapas de la tubería de color, utilizando tecnologías como OKLCH y RGB L''implémenteur de pipeline de couleur est un outil d''agent d''IA qui aide à mettre en œuvre et à ajuster les étapes du pipeline de couleur, en utilisant des technologies telles que OKLCH et RGB Der Farbpipeline-Implementierer ist ein KI-Tool, das hilft, die Farbpipeline-Stufen zu implementieren und anzupassen, unter Verwendung von Technologien wie OKLCH und RGB O Color Pipeline Implementer é uma ferramenta para implementar e ajustar as etapas da pipeline de cores. Ele oferece funcionalidades como análise e normalização de cores ИИ Агент Color Pipeline Implementer - это инструмент для реализации и настройки этапов цветовой трубы. Он предлагает функции, такие как анализ и нормализация цветов أداة تحويل خط أنابيب الألوان هي أداة لتنفيذ وتعديل مراحل خط أنابيب الألوان. توفر ميزات مثل تحليل وتنظيم الألوان how to use color-pipeline-implementer color-pipeline-implementer setup guide color-pipeline-implementer alternative color-pipeline-implementer vs OKLCH implementing color pipeline stages OKLCH color space tutorial color-pipeline-implementer install TypeScript color manipulation color pipeline implementation best practices 颜色管道实施 Color Pipeline Implementer 颜色管道阶段 解析和归一化 基本验证 AI工具 AIエージェント Implements parsing of hex/rgb colors to OKLCH in src/utils/parseColor.ts Normalizes colors by clamping L/C/H values and applying defaults in src/engine/normalize.ts Resolves semantic colors using base scales in src/engine Preserves alpha channel during color parsing Follows v0.3 documentation for color pipeline implementation Reads spec-v0.3.md and roadmap-v0.3.md for workflow planning color-pipeline-implementer is a skill that assists in implementing and adjusting color pipeline stages using OKLCH color space and TypeScript.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Birdiz/Birdiz/plan-confirm-workflow', 'community', 'Birdiz', 'Birdiz', 'Birdiz/Birdiz', 'plan-confirm-workflow', 0, 0, 23, '2026-03-08T01:57:15.379Z', '2026-03-08T02:05:32.896Z', 'b649fd7d8d9d277f917c168c9ae4afa1472b0b384dca50295f12f2437925d290', '{"id":"Birdiz/Birdiz/plan-confirm-workflow","name":"plan-confirm-workflow","description":{"en":"The plan-confirm-workflow skill helps developers clarify project scope and assumptions, produce concise implementation plans, and request explicit confirmation before making file changes.","zh":"Plan Confirm Workflow 是一种优化代码编辑流程的技术，通过明确范围和假设、产生实现计划、请求确认等步骤提高开发效率","ja":"Plan Confirm Workflow は、コード編集の効率を上げるための技術で、範囲と仮定の明確化、実装計画の作成、確認の依頼などを通じて開発プロセスを最適化します","ko":"Plan Confirm Workflow는 코드 편집 프로세스를 최적화하는 기술로, 범위와 가정을 명확히 하고, 구현 계획을 수립하며, 확인을 요청하여 개발 프로세스를 개선합니다","es":"El flujo de trabajo de planificación y confirmación es una herramienta de AI Agent que ayuda a los desarrolladores a clarificar el alcance y las suposiciones antes de editar código","fr":"Le workflow de planification et de confirmation est un outil d''agent IA qui aide les développeurs à clarifier la portée et les hypothèses avant de modifier le code","de":"Der Plan-Confirm-Workflow ist ein AI-Tool, das Entwicklern hilft, den Umfang und die Annahmen vor der Kodierung zu klären","pt":"O Plan Confirm Workflow é uma abordagem para clarificar o escopo e as suposições antes de editar códigos, produzir um plano de implementação conciso e solicitar confirmação explícita","ru":"Plan Confirm Workflow - это подход для уточнения объема и предположений перед редактированием кода, создания краткого плана реализации и запроса явного подтверждения","ar":"عمل تأكيد الخطة هو نهج لتوضيح النطاق والافتراضات قبل تحرير الشفرات، وإنتاج خطة تنفيذ موجزة وطلب التأكيد الصريح"},"seo":{"title":{"en":"plan-confirm-workflow: Implementation Planning Guide for ...","zh":"Plan Confirm Workflow 设置指南 - 优化代码编辑流程","ja":"Plan Confirm Workflow のベストプラクティス - AIエージェントを活用する","ko":"Plan Confirm Workflow 설정 가이드 - 효율적인 코드 편집","es":"Guía de configuración del flujo de trabajo de planificaci...","fr":"Guide de mise en place du workflow de planification et de...","de":"Einrichtungsleitfaden für den Plan-Confirm-Workflow","pt":"Guia de Configuração do Plan Confirm Workflow para Desenv...","ru":"ИИ Агенты: Настройка Plan Confirm Workflow для Разработчиков","ar":"دليل إعداد عمل تأكيد الخطة للمطورين"},"description":{"en":"Streamline your workflow with plan-confirm-workflow. Learn how to clarify scope, produce implementation plans, and request confirmation before editing code.","zh":"了解 Plan Confirm Workflow 的技术细节，优化代码编辑流程，提高开发效率","ja":"Plan Confirm Workflow のしくみを理解し、AIエージェントを活用してコード編集の効率を上げる","ko":"Plan Confirm Workflow 설정 가이드를 통해 효율적인 코드 편집과 개발 프로세스를 구축하세요","es":"Aprende a configurar y optimizar tu flujo de trabajo con la herramienta de AI Agent para desarrolladores","fr":"Découvrez comment configurer et optimiser votre workflow avec l''outil d''agent IA pour les développeurs","de":"Erfahren Sie, wie Sie Ihren Workflow mit dem AI-Tool für Entwickler konfigurieren und optimieren","pt":"Aprenda a configurar o Plan Confirm Workflow para melhorar a colaboração e a eficiência no desenvolvimento de software","ru":"Узнайте, как настроить Plan Confirm Workflow для улучшения сотрудничества и эффективности при разработке программного обеспечения","ar":"تعرف على كيفية إعداد عمل تأكيد الخطة لتحسين التعاون والفعالية في تطوير البرمجيات"},"definition":{"en":"plan-confirm-workflow is a systematic approach to implementation planning, involving scope clarification, step-by-step planning, and confirmation requests.","zh":"Plan Confirm Workflow 是一种代码编辑流程优化技术，用于提高开发效率和代码质量","ja":"Plan Confirm Workflow は、コード編集の効率と品質を向上させるための技術です","ko":"Plan Confirm Workflow는 코드 편집 프로세스를 최적화하고 개발 효율과 코드 품질을 높이는 기술입니다","es":"Un flujo de trabajo de planificación y confirmación es un proceso que ayuda a los desarrolladores a planificar y confirmar sus tareas antes de comenzar a codificar","fr":"Un workflow de planification et de confirmation est un processus qui aide les développeurs à planifier et à confirmer leurs tâches avant de commencer à coder","de":"Ein Plan-Confirm-Workflow ist ein Prozess, der Entwicklern hilft, ihre Aufgaben zu planen und zu bestätigen, bevor sie mit der Kodierung beginnen","pt":"O Plan Confirm Workflow é uma técnica de desenvolvimento de software que envolve a clarificação do escopo e a criação de um plano de implementação antes de editar códigos","ru":"Plan Confirm Workflow - это техника разработки программного обеспечения, включающая уточнение объема и создание плана реализации перед редактированием кода","ar":"عمل تأكيد الخطة هو تقنية في تطوير البرمجيات تتضمن توضيح النطاق وإنتاج خطة تنفيذ قبل تحرير الشفرات"},"features":{"en":["Clarifies scope and assumptions before editing code","Produces concise implementation plans with concrete steps","Includes validation strategies using lint, typecheck, and tests","Requests explicit confirmation before making file changes","Highlights unknowns that affect implementation","Breaks work into concrete steps with affected files and services"],"zh":["明确范围和假设","产生实现计划","请求确认","包含代码验证策略（lint、typecheck、测试）","提高代码编辑效率"],"ja":["範囲と仮定の明確化","実装計画の作成","確認の依頼","コード検証戦略（lint、typecheck、テスト）を含む","コード編集の効率化"],"ko":["범위와 가정을 명확히 함","구현 계획을 수립함","확인을 요청함","코드 검증 전략（lint、typecheck、테스트）을 포함함","코드 편집의 효율성을 높임"],"es":["Clarificación del alcance y las suposiciones antes de editar","Creación de un plan de implementación conciso","Inclusión de una estrategia de validación","Solicitud de confirmación explícita antes de realizar cambios","Identificación de dependencias y restricciones","Highlight de desconocidos que afectan la implementación"],"fr":["Clarification de la portée et des hypothèses avant de modifier","Création d''un plan d''implémentation concis","Inclusion d''une stratégie de validation","Demande de confirmation explicite avant de réaliser des modifications","Identification des dépendances et des contraintes","Highlight des inconnues qui affectent l''implémentation"],"de":["Klärung des Umfangs und der Annahmen vor der Kodierung","Erstellung eines konkreten Implementierungsplans","Einbeziehung einer Validierungsstrategie","Anfrage einer expliziten Bestätigung vor Änderungen","Identifizierung von Abhängigkeiten und Einschränkungen","Hervorhebung von Unbekannten, die die Implementierung beeinflussen"],"pt":["Clarificação do escopo e suposições antes de editar códigos","Criação de um plano de implementação conciso","Solicitação de confirmação explícita antes de fazer alterações","Inclusão de estratégia de validação (lint, typecheck, tests)","Identificação de dependências e restrições","Destaque de desconhecidos que afetam a implementação"],"ru":["Уточнение объема и предположений перед редактированием кода","Создание краткого плана реализации","Запрос явного подтверждения перед внесением изменений","Включение стратегии валидации (lint, typecheck, tests)","Определение зависимостей и ограничений","Выделение неизвестных, влияющих на реализацию"],"ar":["توضيح النطاق والافتراضات قبل تحرير الشفرات","إنتاج خطة تنفيذ موجزة","طلب التأكيد الصريح قبل إجراء التعديلات","إدراج استراتيجية التحقق (lint, typecheck, tests)","تحديد الاعتماديات والقيود","تأكيد مجهول التي تؤثر على التنفيذ"]},"keywords":{"en":["how to use plan-confirm-workflow","plan-confirm-workflow setup guide","what is plan-confirm-workflow","plan-confirm-workflow alternative","plan-confirm-workflow vs agile methodology","plan-confirm-workflow install","implementation planning for AI agents","code review workflow","project scope clarification"],"zh":["Plan Confirm Workflow","代码编辑流程优化","开发效率提高","代码质量提高","AI 工具","代码验证策略","lint","typecheck","测试"],"ja":["Plan Confirm Workflow","コード編集の効率化","開発プロセスの最適化","AIエージェント","コード検証戦略","lint","typecheck","テスト"],"ko":["Plan Confirm Workflow","코드 편집 프로세스 최적화","개발 효율성提高","코드 품질提高","AI 툴","코드 검증 전략","lint","typecheck","테스트"],"es":["flujo de trabajo de planificación y confirmación","herramienta de AI Agent para desarrolladores","configuración de workflow","optimización de flujo de trabajo","desarrollo de software","planificación de tareas","validación de código","implementación de software","agentes de IA para desarrolladores"],"fr":["workflow de planification et de confirmation","outil d''agent IA pour les développeurs","configuration de workflow","optimisation de flux de travail","développement de logiciels","planification de tâches","validation de code","implémentation de logiciels","agents d''IA pour les développeurs"],"de":["Plan-Confirm-Workflow","AI-Tool für Entwickler","Workflow-Konfiguration","Workflow-Optimierung","Software-Entwicklung","Aufgabenplanung","Code-Validierung","Software-Implementierung","AI-Agenten für Entwickler"],"pt":["plan confirm workflow","desenvolvimento de software","colaboração","eficiência","configuração","guia de configuração","melhor práticas","técnica de desenvolvimento","clarificação do escopo"],"ru":["plan confirm workflow","разработка программного обеспечения","сотрудничество","эффективность","настройка","руководство по настройке","лучшие практики","техника разработки","уточнение объема"],"ar":["عمل تأكيد الخطة","تطوير البرمجيات","التعاون","الفعالية","إعداد","دليل الإعداد","أفضل الممارسات","تقنية التطوير","توضيح النطاق"]}},"owner":"Birdiz","repo":"Birdiz","repoPath":"Birdiz/Birdiz","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.379Z","topics":[],"category":"community","skillMd":{"name":"plan-confirm-workflow","description":"Plan first and request user confirmation before implementation. Use when the user wants explicit validation before code changes, risky refactors, migrations, or any multi-step change where approval is required before building.","bodyPreview":"# Plan Confirm Workflow\n\n1. Clarify scope and assumptions before editing:\n- Restate the requested outcome.\n- Identify constraints and dependencies.\n- Highlight unknowns that affect implementation.\n\n2. Produce a concise implementation plan:\n- Break work into concrete steps.\n- Include affected files/services.\n- Include validation strategy (lint, typecheck, tests).\n\n3. Request explicit confirmation:\n- Ask for a clear go/no-go before making file changes.\n- Do not edit code before confirmation.\n\n4. A","body":"# Plan Confirm Workflow\n\n1. Clarify scope and assumptions before editing:\n- Restate the requested outcome.\n- Identify constraints and dependencies.\n- Highlight unknowns that affect implementation.\n\n2. Produce a concise implementation plan:\n- Break work into concrete steps.\n- Include affected files/services.\n- Include validation strategy (lint, typecheck, tests).\n\n3. Request explicit confirmation:\n- Ask for a clear go/no-go before making file changes.\n- Do not edit code before confirmation.\n\n4. After confirmation, execute exactly the approved plan:\n- If new risks appear, pause and re-confirm.\n- Keep the user updated as milestones are completed.\n\n5. Close with validation evidence:\n- Report commands run and outcomes.\n- List changed files and behavior impact.\n"},"lastSynced":"2026-03-08T02:05:32.896Z","agentAnalysis":{"suitability":{"en":"Ideal for Development Agents requiring structured project planning and confirmation workflows.","zh":"适合需要结构化项目规划和确认工作流的开发代理。","ja":"構造化されたプロジェクト計画と確認ワークフローを必要とする開発エージェントに最適です。","ko":"구조화된 프로젝트 계획 및 확인 워크플로가 필요한 개발 에이전트에 적합합니다.","es":"Ideal para agentes de desarrollo que requieren una planificación de proyectos estructurada y flujos de trabajo de confirmación.","fr":"Idéal pour les agents de développement nécessitant une planification de projet structurée et des flux de travail de confirmation.","de":"Ideal für Entwicklungssagenten, die eine strukturierte Projektplanung und Bestätigungsworkflows erfordern.","pt":"Ideal para Agentes de Desenvolvimento que exigem planejamento de projetos estruturado e fluxos de trabalho de confirmação.","ru":"Идеально для агентов разработки, требующих структурированного планирования проектов и рабочих процессов подтверждения.","ar":"مثالية لعميل التطوير الذي يتطلب تخطيط مشروع منظم وعمليات عمل للتأكيد."},"recommendation":{"en":"Empowers agents to clarify project scope and assumptions, produce concise implementation plans, and request explicit confirmation before making file changes, ensuring validation through lint, typecheck, and tests.","zh":"赋予代理人阐明项目范围和假设、产生简洁的实现计划、并在修改文件之前请求明确确认的能力，从而通过lint、typecheck和测试确保验证。","ja":"エージェントにプロジェクトの範囲と仮定を明確化し、簡潔な実装計画を生成し、コードファイルを編集する前に明示的な確認を要求する機能を提供し、lint、typecheck、テストを介して検証を確実に行います。","ko":"에이전트가 프로젝트 범위와 가정을 명확히 하고, 간결한 구현 계획을 생성하며, 코드 파일을 편집하기 전에 명시적인 확인을 요청하여 lint, typecheck 및 테스트를 통해 검증을 보장하는 기능을 제공합니다.","es":"Habilita a los agentes a aclarar el alcance del proyecto y los supuestos, producir planes de implementación concisos y solicitar una confirmación explícita antes de realizar cambios en los archivos, garantizando la validación a través de lint, typecheck y pruebas.","fr":"Permet aux agents de clarifier la portée du projet et les hypothèses, de produire des plans de mise en œuvre concis et de demander une confirmation explicite avant d''apporter des modifications aux fichiers, en garantissant la validation via lint, typecheck et tests.","de":"Ermächtigt die Agenten, den Projektumfang und die Annahmen zu klären, präzise Implementierungspläne zu erstellen und eine explizite Bestätigung anzufordern, bevor Dateien geändert werden, wodurch die Validierung durch lint, typecheck und Tests gewährleistet wird.","pt":"Habilita os agentes a esclarecer o escopo do projeto e as suposições, produzir planos de implementação concisos e solicitar confirmação explícita antes de fazer alterações nos arquivos, garantindo a validação por meio de lint, typecheck e testes.","ru":"Наделяет агентов возможностью уточнить объем проекта и предположения, создать краткие планы реализации и запросить явное подтверждение перед внесением изменений в файлы, обеспечивая проверку через lint, typecheck и тесты.","ar":"تمكّن الوكيل من توضيح نطاق المشروع والافتراضات، وإنتاج خطط تنفيذ موجزة، وطلب التأكيد الصريح قبل تعديل ملفات الملفات، مما يضمن التحقق من خلال lint و typecheck والاختبارات."},"useCases":{"en":["Automating project scope clarification","Generating step-by-step implementation plans","Requesting confirmation before editing code files"],"zh":["自动化项目范围明确化","生成分步式实现计划","编辑代码文件前请求确认"],"ja":["プロジェクト範囲の明確化の自動化","ステップバイステップの実装計画の生成","コードファイルの編集前に確認を要求"],"ko":["프로젝트 범위 명확화 자동화","단계별 구현 계획 생성","코드 파일 편집 전 확인 요청"],"es":["Automatización de la clarificación del alcance del proyecto","Generación de planes de implementación paso a paso","Solicitud de confirmación antes de editar archivos de código"],"fr":["Automatisation de la clarification de la portée du projet","Génération de plans de mise en œuvre étape par étape","Demande de confirmation avant d''éditer les fichiers de code"],"de":["Automatisierung der Projektscope-Klärung","Erstellung von schrittweisen Implementierungsplänen","Anforderung von Bestätigung vor der Bearbeitung von Code-Dateien"],"pt":["Automatizar a clarificação do escopo do projeto","Gerar planos de implementação passo a passo","Solicitar confirmação antes de editar arquivos de código"],"ru":["Автоматизировать уточнение объема проекта","Генерировать пошаговые планы реализации","Запрашивать подтверждение перед редактированием файлов кода"],"ar":["تأتمتة توضيح نطاق المشروع","إنتاج خطط تنفيذ خطوة بخطوة","طلب التأكيد قبل تحرير ملفات التعليمات البرمجية"]},"limitations":{"en":["Requires explicit confirmation before file changes","Needs clear restatement of requested outcomes and identification of constraints"],"zh":["需要在文件更改前获得明确确认","需要明确的结果重述和约束识别"],"ja":["ファイルの変更前に明示的な確認が必要","要求された結果の明確な再述と制約の識別が必要"],"ko":["파일 변경 전 명시적인 확인이 필요","요청된 결과의 명확한 재설명과 제약 식별이 필요"],"es":["Requiere una confirmación explícita antes de realizar cambios en los archivos","Necesita una restatement clara de los resultados solicitados y la identificación de las restricciones"],"fr":["Nécessite une confirmation explicite avant d''apporter des modifications aux fichiers","Nécessite une reformulation claire des résultats demandés et l''identification des contraintes"],"de":["Erfordert eine explizite Bestätigung vor der Änderung von Dateien","Benötigt eine klare Wiederholung der angeforderten Ergebnisse und die Identifizierung von Einschränkungen"],"pt":["Exige confirmação explícita antes de alterações nos arquivos","Necessita de uma reformulação clara dos resultados solicitados e identificação das restrições"],"ru":["Требует явного подтверждения перед внесением изменений в файлы","Требует четкого переформулирования запрошенных результатов и идентификации ограничений"],"ar":["يتطلب التأكيد الصريح قبل تعديل الملفات","يحتاج إلى إعادة صياغة واضحة للنتائج المطلوبة وتحديد القيود"]},"version":4},"contentHash":"b649fd7d8d9d277f917c168c9ae4afa1472b0b384dca50295f12f2437925d290","qualityScore":23}');
