INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Birdiz/Birdiz/plan-confirm-workflow', 'plan-confirm-workflow', 'Birdiz', 'Birdiz', 'community', 'plan-confirm-workflow Birdiz Birdiz community The plan-confirm-workflow skill helps developers clarify project scope and assumptions, produce concise implementation plans, and request explicit confirmation before making file changes. Plan Confirm Workflow 是一种优化代码编辑流程的技术，通过明确范围和假设、产生实现计划、请求确认等步骤提高开发效率 Plan Confirm Workflow は、コード編集の効率を上げるための技術で、範囲と仮定の明確化、実装計画の作成、確認の依頼などを通じて開発プロセスを最適化します Plan Confirm Workflow는 코드 편집 프로세스를 최적화하는 기술로, 범위와 가정을 명확히 하고, 구현 계획을 수립하며, 확인을 요청하여 개발 프로세스를 개선합니다 El flujo de trabajo de planificación y confirmación es una herramienta de AI Agent que ayuda a los desarrolladores a clarificar el alcance y las suposiciones antes de editar código Le workflow de planification et de confirmation est un outil d''agent IA qui aide les développeurs à clarifier la portée et les hypothèses avant de modifier le code Der Plan-Confirm-Workflow ist ein AI-Tool, das Entwicklern hilft, den Umfang und die Annahmen vor der Kodierung zu klären O Plan Confirm Workflow é uma abordagem para clarificar o escopo e as suposições antes de editar códigos, produzir um plano de implementação conciso e solicitar confirmação explícita Plan Confirm Workflow - это подход для уточнения объема и предположений перед редактированием кода, создания краткого плана реализации и запроса явного подтверждения عمل تأكيد الخطة هو نهج لتوضيح النطاق والافتراضات قبل تحرير الشفرات، وإنتاج خطة تنفيذ موجزة وطلب التأكيد الصريح how to use plan-confirm-workflow plan-confirm-workflow setup guide what is plan-confirm-workflow plan-confirm-workflow alternative plan-confirm-workflow vs agile methodology plan-confirm-workflow install implementation planning for AI agents code review workflow project scope clarification Plan Confirm Workflow 代码编辑流程优化 开发效率提高 代码质量提高 AI 工具 代码验证策略 lint typecheck 测试 Clarifies scope and assumptions before editing code Produces concise implementation plans with concrete steps Includes validation strategies using lint, typecheck, and tests Requests explicit confirmation before making file changes Highlights unknowns that affect implementation Breaks work into concrete steps with affected files and services plan-confirm-workflow is a systematic approach to implementation planning, involving scope clarification, step-by-step planning, and confirmation requests.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Crainax/War3Lib/zinc-unittest', 'community', 'Crainax', 'War3Lib', 'Crainax/War3Lib', 'zinc-unittest', 0, 0, 23, '2026-03-08T01:57:15.376Z', '2026-03-08T02:05:51.773Z', 'fd6f5965420e867b59a40e1fe6cb8e0c03df3626ac0e762b35ebe0bc96b3e6d4', '{"id":"Crainax/War3Lib/zinc-unittest","name":"zinc-unittest","description":{"en":"The zinc-unittest skill automates War3 map testing for developers, utilizing Lua tasks and Jass templates to ensure efficient and reproducible testing. It benefits developers working with War3 maps by simplifying the testing process.","zh":"zinc-unittest是一个自动化测试工具，用于War3 Maps Library的开发，通过脚本生成测试用例","ja":"zinc-unittestはWar3 Maps Libraryの開発に使用される自動化テストツールです。 Luaスクリプトを使用してテストケースを生成します","ko":"zinc-unittest는 War3 Maps Library 개발을 위한 자동화 테스트 도구입니다. Lua 스크립트를 사용하여 테스트 케이스를 생성합니다","es":"zinc-unittest es una herramienta para pruebas unitarias que utiliza Lua y War3Lib. Permite establecer un flujo de trabajo para generar tests de forma eficiente","fr":"zinc-unittest est un outil de tests unitaires qui utilise Lua et War3Lib. Il permet d''établir un workflow pour générer des tests de manière efficace","de":"zinc-unittest ist ein Tool für Einheitenprüfungen, das Lua und War3Lib verwendet. Es ermöglicht die Einrichtung eines Workflows, um Tests effizient zu generieren","pt":"O zinc-unittest é uma ferramenta para desenvolvedores que facilita a criação de testes unitários para bibliotecas de mapeamento de War3","ru":"zinc-unittest - это инструмент для разработчиков, который упрощает создание юнит-тестов для библиотек карт War3","ar":"zinc-unittest هو أداة لمنشئي التطبيقات التي تسهل إنشاء اختبارات وحدة لمكتبات رسم الخرائط War3"},"seo":{"title":{"en":"zinc-unittest: Automated War3 Map Testing Setup Guide | A...","zh":"zinc-unittest 工作流设置指南","ja":"zinc-unittest Setup Guide - AIエージェントのテスト自動化","ko":"zinc-unittest 설정 가이드 - 자동화된 테스트 워크플로","es":"Guía de configuración de zinc-unittest para pruebas unita...","fr":"Guide de configuration de zinc-unittest pour les tests un...","de":"Konfigurationsleitfaden für zinc-unittest-Einheitenprüfungen","pt":"Guia de Configuração do zinc-unittest para Desenvolvedores","ru":"Настройка zinc-unittest: Руководство для Разработчиков ИИ...","ar":"دليل إعداد zinc-unittest لمنشئي أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how zinc-unittest streamlines War3 map testing with Lua tasks and Jass templates. Get started with our setup guide and optimize your workflow today!","zh":"了解如何使用zinc-unittest实现自动化测试，提高开发效率","ja":"AIエージェントを使用した自動化テストのためのzinc-unittest設定方法","ko":"자동화된 테스트를 위한 zinc-unittest 설정 방법과 개발 효율성 향상을 알아보세요","es":"Aprende a configurar zinc-unittest para pruebas unitarias con Lua y War3Lib. Descubre cómo establecer el flujo de trabajo y generar tests","fr":"Découvrez comment configurer zinc-unittest pour les tests unitaires avec Lua et War3Lib. Apprenez à établir le workflow et générer des tests","de":"Erfahren Sie, wie Sie zinc-unittest für Einheitenprüfungen mit Lua und War3Lib konfigurieren. Entdecken Sie, wie Sie den Workflow einrichten und Tests generi...","pt":"Aprenda a configurar o zinc-unittest para desenvolver testes unitários eficazes para bibliotecas de mapeamento de War3","ru":"Узнайте, как настроить zinc-unittest для создания эффективных юнит-тестов для библиотек карт War3 с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد zinc-unittest لإنشاء اختبارات وحدة فعالة لمكتبات رسم الخرائط War3 باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"zinc-unittest is a skill that automates the testing of War3 maps using a Lua-based workflow and Jass templates, ensuring minimal changes and reproducibility.","zh":"zinc-unittest是一种自动化测试工具，用于辅助War3 Maps Library的开发","ja":"zinc-unittestは、War3 Maps Libraryの開発を支援する自動化テストツールです","ko":"zinc-unittest는 War3 Maps Library 개발을 지원하는 자동화 테스트 도구입니다","es":"zinc-unittest es una herramienta de pruebas unitarias que utiliza Lua y War3Lib para generar tests de forma automática","fr":"zinc-unittest est un outil de tests unitaires qui utilise Lua et War3Lib pour générer des tests de manière automatisée","de":"zinc-unittest ist ein Tool für Einheitenprüfungen, das Lua und War3Lib verwendet, um Tests automatisch zu generieren","pt":"O zinc-unittest é uma ferramenta de teste unitário para desenvolvedores de bibliotecas de mapeamento de War3","ru":"zinc-unittest - это юнит-тестовый инструмент для разработчиков библиотек карт War3","ar":"zinc-unittest هو أداة اختبار وحدة لمطوري مكتبات رسم الخرائط War3"},"features":{"en":["Generates Xxx_Test.j files using the create_ut.sh script","Creates Xxx.cfg files with external dependency injection and [chain] basics","Supports material editing with optional Xxx.w3a, Xxx.w3u, and Xxx.w3i files","Utilizes Lua/tasks/TaskCreateUT.lua for automated testing","Leverages Jass/template/UTTemplate for consistent testing templates","Runs bash scripts for automated testing and dependency management"],"zh":["自动化测试用例生成","Lua脚本支持","War3 Maps Library集成","脚本化测试工作流","模板化测试用例创建","自动化依赖注入"],"ja":["自動化テストケース生成","Luaスクリプトのサポート","War3 Maps Libraryとの統合","スクリプト化されたテストワークフロー","テンプレートベースのテストケース作成","自動化された依存性の注入"],"ko":["자동화된 테스트 케이스 생성","Lua 스크립트 지원","War3 Maps Library 통합","스크립트화된 테스트 워크플로","템플릿 기반의 테스트 케이스 생성","자동화된 의존성 주입"],"es":["Generación de tests unitarios con Lua","Integración con War3Lib para pruebas de juego","Establecimiento de un flujo de trabajo para pruebas eficientes","Uso de plantillas para generar tests de forma automática","Compatibilidad con archivos de configuración para personalizar las pruebas"],"fr":["Génération de tests unitaires avec Lua","Intégration avec War3Lib pour les tests de jeu","Établissement d''un workflow pour des tests efficaces","Utilisation de modèles pour générer des tests de manière automatisée","Compatibilité avec les fichiers de configuration pour personnaliser les tests"],"de":["Generierung von Einheitenprüfungen mit Lua","Integration mit War3Lib für Spieltests","Einrichtung eines Workflows für effiziente Prüfungen","Verwendung von Vorlagen für die automatische Generierung von Tests","Kompatibilität mit Konfigurationsdateien für die Anpassung der Prüfungen"],"pt":["Criação de testes unitários para bibliotecas de mapeamento de War3","Integração com Lua e Jass","Uso de scripts de tarefas para criar testes","Suporte a arquivos de configuração e dependências","Geração de testes unitários com base em templates"],"ru":["Создание юнит-тестов для библиотек карт War3","Интеграция с Lua и Jass","Использование скриптов задач для создания тестов","Поддержка файлов конфигурации и зависимостей","Генерация юнит-тестов на основе шаблонов"],"ar":["إنشاء اختبارات وحدة لمكتبات رسم الخرائط War3","التكامل مع Lua و Jass","استخدام سكريبتات المهام لإنشاء الاختبارات","دعم الملفات التكوينية والاعتماديات","جénération de tests unitaires basés sur des modèles"]},"keywords":{"en":["how to use zinc-unittest","zinc-unittest setup guide","War3 map testing automation","Lua task automation","Jass template testing","zinc-unittest vs manual testing","zinc-unittest install","what is zinc-unittest","zinc-unittest alternative","zinc-unittest tutorial"],"zh":["zinc-unittest","War3 Maps Library","自动化测试","Lua脚本","脚本化测试","模板化测试","依存性注入","AI工具","自动化开发"],"ja":["zinc-unittest","War3 Maps Library","自動化テスト","Luaスクリプト","スクリプト化されたテスト","テンプレートベースのテスト","依存性の注入","AIエージェント","自動化開発"],"ko":["zinc-unittest","War3 Maps Library","자동화된 테스트","Lua 스크립트","스크립트화된 테스트","템플릿 기반의 테스트","의존성 주입","AI 도구","자동화된 개발"],"es":["zinc-unittest","pruebas unitarias","Lua","War3Lib","tests de juego","generación de tests","flujo de trabajo","plantillas de tests","configuración de pruebas"],"fr":["zinc-unittest","tests unitaires","Lua","War3Lib","tests de jeu","génération de tests","workflow","modèles de tests","configuration de tests"],"de":["zinc-unittest","Einheitenprüfungen","Lua","War3Lib","Spieltests","Generierung von Tests","Workflow","Vorlagen für Tests","Konfiguration von Prüfungen"],"pt":["zinc-unittest","teste unitário","bibliotecas de mapeamento de War3","desenvolvimento de jogos","Lua","Jass","script de tarefas","configuração de dependências"],"ru":["zinc-unittest","юнит-тест","библиотеки карт War3","разработка игр","Lua","Jass","скрипт задач","конфигурация зависимостей","ИИ Агенты"],"ar":["zinc-unittest","اختبار وحدة","مكتبات رسم الخرائط War3","تطوير الألعاب","Lua","Jass","سكريبتات المهام","تكوين الاعتماديات","أدوات الذكاء الاصطناعي"]}},"owner":"Crainax","repo":"War3Lib","repoPath":"Crainax/War3Lib","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.376Z","topics":[],"category":"community","skillMd":{"name":"zinc-unittest","description":"War3Lib 的 Zinc 单元测试流程规范（.j + .cfg + _Test.j + 可选 w3a/w3u/w3i）：使用 TaskCreateUT.lua 生成测试壳、维护 cfg 注入与 chain 依赖、使用 UnitTestFramwork.assert 断言与 Trace 日志输出。用于创建/重构 Jass 模块单测时。","bodyPreview":"# Zinc Unit Test Workflow (War3Lib)\n\n按以下顺序执行，保持最小改动和可复现。\n\n## 1. 建立三件套文件\n\n1. 以目标模块 `Xxx.j` 为中心，确认同目录存在：`Xxx.cfg`、`Xxx_Test.j`。\n2. `Xxx.cfg` 不存在时创建，并补齐：公开 API 关键词 + `[chain]` 基础依赖。\n3. 需要物编辅助测试时，按需创建同名扩展文件：`Xxx.w3a`(技能)、`Xxx.w3u`(单位)、`Xxx.w3i`(物品)。\n\n说明：`cfg` 前半段用于外部 dependency 注入关键词；`[chain]` 是该库底层依赖，用于递归注入。\n\n## 2. 生成或刷新 `_Test.j`（必须走任务脚本）\n\n优先复用项目脚本，不手写测试壳。\n\n1. 运行：`bash .codex/skills/zinc-unittest/scripts/create_ut.sh <Xxx.j>`。\n2. 该流程会调用 `Lua/tasks/TaskCreateUT.lua`，并使用模板 `Jass/template/UTTemplate.","body":"# Zinc Unit Test Workflow (War3Lib)\n\n按以下顺序执行，保持最小改动和可复现。\n\n## 1. 建立三件套文件\n\n1. 以目标模块 `Xxx.j` 为中心，确认同目录存在：`Xxx.cfg`、`Xxx_Test.j`。\n2. `Xxx.cfg` 不存在时创建，并补齐：公开 API 关键词 + `[chain]` 基础依赖。\n3. 需要物编辅助测试时，按需创建同名扩展文件：`Xxx.w3a`(技能)、`Xxx.w3u`(单位)、`Xxx.w3i`(物品)。\n\n说明：`cfg` 前半段用于外部 dependency 注入关键词；`[chain]` 是该库底层依赖，用于递归注入。\n\n## 2. 生成或刷新 `_Test.j`（必须走任务脚本）\n\n优先复用项目脚本，不手写测试壳。\n\n1. 运行：`bash .codex/skills/zinc-unittest/scripts/create_ut.sh <Xxx.j>`。\n2. 该流程会调用 `Lua/tasks/TaskCreateUT.lua`，并使用模板 `Jass/template/UTTemplate.j`。\n3. 已存在 `_Test.j` 时默认不覆盖，仅更新 `Jass/config/UnitTest.h` 的 include 到当前测试文件。\n\n如果脚本不可用，再手动按 `UTTemplate.j` 结构补齐占位符：`{UnitTest}`、`LibraryName`、`#include`。\n\n## 3. 编写测试逻辑（参考 UnitUtils 风格）\n\n1. 在 `library UTXxx requires Xxx,...` 中按功能拆分 `Test_*` 私有函数。\n2. 使用 `UnitTestAutoTimer` 安排自动测试，避免初始化竞争。\n3. 聊天命令入口走 `s1..s10` 或 `-参数`，复用模板函数 `TTestUTXxx*` / `TTestActUTXxx1`。\n4. 断言优先使用 `UnitTestFramwork.assert`：`Boolean/Integer/Real/String`。\n5. 需要输出到日志时优先用 `Trace(...)`（YDLua），不要依赖仅本地可见的原生提示。\n\n## 4. 宏保护与命名\n\n1. 测试专用注册与入口放在测试文件中；若写在业务库，必须加：`#if (CURRENT_BUILD_VERSION != VERSION_RELEASE)`。\n2. 不使用 `_` 开头标识符。\n3. 用模块名前缀组织测试名与提示文案，保证日志可检索。\n\n## 5. 验收检查\n\n1. `Xxx.cfg` 关键词覆盖公开能力；`[chain]` 不漏基础库。\n2. `_Test.j` 可独立触发核心断言，失败日志能定位到具体测试。\n3. 若依赖物编，`Xxx.w3a/w3u/w3i` 与测试步骤匹配，并在说明中写出用途。\n\n## References（按需加载）\n\n- `references/ut-file-layout.md`\n- `references/assert-trace-pattern.md`\n- `references/examples.md`\n"},"lastSynced":"2026-03-08T02:05:51.773Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like AutoGPT and LangChain that need to automate War3 map testing, utilizing Lua tasks and Jass templates for efficient and reproducible testing.","zh":"适用于AutoGPT和LangChain等需要自动化War3地图测试的AI代理，利用Lua任务和Jass模板实现高效和可复制的测试。","ja":"AutoGPTやLangChainなどのWar3マップテストの自動化が必要なAIエージェントに適しています。LuaタスクとJassテンプレートを使用して効率的で再現可能なテストを実現します。","ko":"AutoGPT와 LangChain 등의 War3 맵 테스트를 자동화해야 하는 AI 에이전트에게 적합합니다. Lua 태스크와 Jass 템플릿을 사용하여 효율적이고 재현 가능한 테스트를 구현합니다.","es":"Ideal para agentes de IA como AutoGPT y LangChain que necesitan automatizar la prueba de mapas de War3, utilizando tareas Lua y plantillas Jass para pruebas eficientes y reproducibles.","fr":"Idéal pour les agents IA comme AutoGPT et LangChain qui ont besoin d''automatiser les tests de cartes War3, en utilisant des tâches Lua et des modèles Jass pour des tests efficaces et reproductibles.","de":"Ideal für KI-Agents wie AutoGPT und LangChain, die War3-Karten-Tests automatisieren müssen, unter Verwendung von Lua-Aufgaben und Jass-Vorlagen für effiziente und reproduzierbare Tests.","pt":"Ideal para agentes de IA como AutoGPT e LangChain que precisam automatizar testes de mapas do War3, utilizando tarefas Lua e modelos Jass para testes eficientes e reproduzíveis.","ru":"Идеально подходит для агентов ИИ, таких как AutoGPT и LangChain, которые необходимо автоматизировать тестирование карт War3, используя задачи Lua и шаблоны Jass для эффективного и воспроизводимого тестирования.","ar":"مثالي لعمليات الوسيط الذكي مثل AutoGPT و LangChain التي تحتاج إلى 자동化 اختبار خريطة War3، باستخدام مهام Lua وقوالب Jass لاختبار كفؤ ومتماثل."},"recommendation":{"en":"Empowers agents to automate War3 map testing workflows using Lua tasks and Jass templates, streamlining the testing process with `_Test.j` generation and dependency injection via `[chain]` and `.cfg` files.","zh":"赋予代理自动化War3地图测试工作流的能力，使用Lua任务和Jass模板，通过 `_Test.j` 生成和 `[chain]` 及 `.cfg` 文件的依赖注入来简化测试过程。","ja":"エージェントにWar3マップテストワークフローの自動化能力を与え、LuaタスクとJassテンプレートを使用し、 `_Test.j` の生成と `[chain]` および `.cfg` ファイルの依存性インジェクションによってテストプロセスを簡素化します。","ko":"에이전트에게 War3 맵 테스트 워크플로우를 자동화할 수 있는 능력을 부여하며, Lua 태스크와 Jass 템플릿을 사용하여 `_Test.j` 생성과 `[chain]` 및 `.cfg` 파일의 의존성 주입으로 테스트 프로세스를 단순화합니다.","es":"Habilita a los agentes a automatizar flujos de trabajo de prueba de mapas de War3 utilizando tareas Lua y plantillas Jass, simplificando el proceso de prueba con la generación de `_Test.j` y la inyección de dependencias a través de `[chain]` y archivos `.cfg`.","fr":"Permet aux agents d''automatiser les flux de travail de test de cartes War3 en utilisant des tâches Lua et des modèles Jass, en simplifiant le processus de test avec la génération de `_Test.j` et l''injection de dépendances via `[chain]` et des fichiers `.cfg`.","de":"Ermöglicht es Agenten, War3-Karten-Testworkflows zu automatisieren, indem Lua-Aufgaben und Jass-Vorlagen verwendet werden, um den Testprozess mit der Generierung von `_Test.j` und der Abhängigkeitsinjektion über `[chain]` und `.cfg`-Dateien zu straffen.","pt":"Habilita os agentes a automatizar fluxos de trabalho de teste de mapas do War3 usando tarefas Lua e modelos Jass, otimizando o processo de teste com geração de `_Test.j` e injeção de dependência via `[chain]` e arquivos `.cfg`.","ru":"Наделяет агентов возможностью автоматизировать рабочие процессы тестирования карт War3, используя задачи Lua и шаблоны Jass, оптимизируя процесс тестирования с помощью генерации `_Test.j` и внедрения зависимостей через `[chain]` и файлы `.cfg`.","ar":"تمكّن الوكيل من تلقين عمليات اختبار خريطة War3 باستخدام مهام Lua وقوالب Jass، وبذلك يُسهل عملية الاختبار من خلال توليد `_Test.j` وحقن التبعية عن طريق `[chain]` وملفات `.cfg`."},"useCases":{"en":["Automating War3 map testing with Lua tasks and Jass templates","Generating `_Test.j` files for reproducible testing","Streamlining dependency injection with `.cfg` files and `[chain]`"],"zh":["使用Lua任务和Jass模板自动化War3地图测试","生成 `_Test.j` 文件以实现可复制的测试","使用 `.cfg` 文件和 `[chain]` 简化依赖注入"],"ja":["LuaタスクとJassテンプレートを使用してWar3マップテストを自動化する","`_Test.j` ファイルを生成して再現可能なテストを実現する","`.cfg` ファイルと `[chain]` を使用して依存性インジェクションを簡素化する"],"ko":["Lua 태스크와 Jass 템플릿을 사용하여 War3 맵 테스트를 자동화하는 것","`_Test.j` 파일을 생성하여 재현 가능한 테스트를 구현하는 것","`.cfg` 파일과 `[chain]`을 사용하여 의존성 주입을 단순화하는 것"],"es":["Automatizar la prueba de mapas de War3 con tareas Lua y plantillas Jass","Generar archivos `_Test.j` para pruebas reproducibles","Simplificar la inyección de dependencias con archivos `.cfg` y `[chain]`"],"fr":["Automatiser les tests de cartes War3 avec des tâches Lua et des modèles Jass","Générer des fichiers `_Test.j` pour des tests reproductibles","Simplifier l''injection de dépendances avec des fichiers `.cfg` et `[chain]`"],"de":["War3-Karten-Tests mit Lua-Aufgaben und Jass-Vorlagen zu automatisieren"," `_Test.j`-Dateien für reproduzierbare Tests generieren","Die Abhängigkeitsinjektion mit `.cfg`-Dateien und `[chain]` zu straffen"],"pt":["Automatizar testes de mapas do War3 com tarefas Lua e modelos Jass","Gerar arquivos `_Test.j` para testes reproduzíveis","Otimizar a injeção de dependência com arquivos `.cfg` e `[chain]`"],"ru":["Автоматизировать тестирование карт War3 с помощью задач Lua и шаблонов Jass","Генерировать файлы `_Test.j` для воспроизводимого тестирования","Оптимизировать внедрение зависимостей с помощью файлов `.cfg` и `[chain]`"],"ar":["تلقين اختبار خريطة War3 باستخدام مهام Lua وقوالب Jass","توليد ملفات `_Test.j` لاختبار متماثل","تسهيل حقن التبعية باستخدام ملفات `.cfg` و `[chain]`"]},"limitations":{"en":["Requires War3Lib and Lua setup","Limited to War3 map testing","Needs `Xxx.j`, `Xxx.cfg`, and potentially `Xxx.w3a`, `Xxx.w3u`, `Xxx.w3i` files for testing"],"zh":["需要War3Lib和Lua设置","仅限War3地图测试","需要 `Xxx.j`、`Xxx.cfg`以及可能的 `Xxx.w3a`、`Xxx.w3u`、`Xxx.w3i` 文件用于测试"],"ja":["War3LibとLuaの設定が必要","War3マップテストに限定される","`Xxx.j`、`Xxx.cfg`および可能な `Xxx.w3a`、`Xxx.w3u`、`Xxx.w3i` ファイルがテストに必要"],"ko":["War3Lib과 Lua 설정이 필요합니다","War3 맵 테스트에만 제한됩니다","`Xxx.j`、`Xxx.cfg` 및 가능한 `Xxx.w3a`、`Xxx.w3u`、`Xxx.w3i` 파일이 테스트에 필요합니다"],"es":["Requiere War3Lib y configuración de Lua","Limitado a la prueba de mapas de War3","Necesita archivos `Xxx.j`, `Xxx.cfg` y potencialmente `Xxx.w3a`, `Xxx.w3u`, `Xxx.w3i` para pruebas"],"fr":["Nécessite War3Lib et la configuration de Lua","Limité aux tests de cartes War3","Nécessite des fichiers `Xxx.j`, `Xxx.cfg` et potentiellement `Xxx.w3a`, `Xxx.w3u`, `Xxx.w3i` pour les tests"],"de":["Benötigt War3Lib und Lua-Einrichtung","Begrenzt auf War3-Karten-Tests","Benötigt `Xxx.j`-, `Xxx.cfg`-Dateien und potenziell `Xxx.w3a`-, `Xxx.w3u`-, `Xxx.w3i`-Dateien für Tests"],"pt":["Requer configuração do War3Lib e Lua","Limitado a testes de mapas do War3","Necessita de arquivos `Xxx.j`, `Xxx.cfg` e potencialmente `Xxx.w3a`, `Xxx.w3u`, `Xxx.w3i` para testes"],"ru":["Требует настройки War3Lib и Lua","Ограничен тестированием карт War3","Требует файлов `Xxx.j`, `Xxx.cfg` и потенциально `Xxx.w3a`, `Xxx.w3u`, `Xxx.w3i` для тестирования"],"ar":["يتطلب إعداد War3Lib و Lua","محدود باختبار خريطة War3","يحتاج إلى ملفات `Xxx.j` و `Xxx.cfg` وربما `Xxx.w3a` و `Xxx.w3u` و `Xxx.w3i` للاختبار"]},"version":4},"contentHash":"fd6f5965420e867b59a40e1fe6cb8e0c03df3626ac0e762b35ebe0bc96b3e6d4","qualityScore":23}');
