INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Crainax/War3Lib/zinc-unittest', 'zinc-unittest', 'Crainax', 'War3Lib', 'community', 'zinc-unittest Crainax War3Lib community The zinc-unittest skill automates War3 map testing for developers, utilizing Lua tasks and Jass templates to ensure efficient and reproducible testing. It benefits developers working with War3 maps by simplifying the testing process. zinc-unittest是一个自动化测试工具，用于War3 Maps Library的开发，通过脚本生成测试用例 zinc-unittestはWar3 Maps Libraryの開発に使用される自動化テストツールです。 Luaスクリプトを使用してテストケースを生成します zinc-unittest는 War3 Maps Library 개발을 위한 자동화 테스트 도구입니다. Lua 스크립트를 사용하여 테스트 케이스를 생성합니다 zinc-unittest es una herramienta para pruebas unitarias que utiliza Lua y War3Lib. Permite establecer un flujo de trabajo para generar tests de forma eficiente zinc-unittest est un outil de tests unitaires qui utilise Lua et War3Lib. Il permet d''établir un workflow pour générer des tests de manière efficace zinc-unittest ist ein Tool für Einheitenprüfungen, das Lua und War3Lib verwendet. Es ermöglicht die Einrichtung eines Workflows, um Tests effizient zu generieren O zinc-unittest é uma ferramenta para desenvolvedores que facilita a criação de testes unitários para bibliotecas de mapeamento de War3 zinc-unittest - это инструмент для разработчиков, который упрощает создание юнит-тестов для библиотек карт War3 zinc-unittest هو أداة لمنشئي التطبيقات التي تسهل إنشاء اختبارات وحدة لمكتبات رسم الخرائط War3 how to use zinc-unittest zinc-unittest setup guide War3 map testing automation Lua task automation Jass template testing zinc-unittest vs manual testing zinc-unittest install what is zinc-unittest zinc-unittest alternative zinc-unittest tutorial zinc-unittest War3 Maps Library 自动化测试 Lua脚本 脚本化测试 模板化测试 依存性注入 AI工具 自动化开发 Generates Xxx_Test.j files using the create_ut.sh script Creates Xxx.cfg files with external dependency injection and [chain] basics Supports material editing with optional Xxx.w3a, Xxx.w3u, and Xxx.w3i files Utilizes Lua/tasks/TaskCreateUT.lua for automated testing Leverages Jass/template/UTTemplate for consistent testing templates Runs bash scripts for automated testing and dependency management zinc-unittest is a skill that automates the testing of War3 maps using a Lua-based workflow and Jass templates, ensuring minimal changes and reproducibility.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('MykolaPinchuk/TML-bench/checkpoint', 'community', 'MykolaPinchuk', 'TML-bench', 'MykolaPinchuk/TML-bench', 'checkpoint', 0, 0, 23, '2026-03-08T01:57:15.386Z', '2026-03-08T02:05:53.401Z', '813bb91b0e653ffeb8197ccf8cb9dc015b7b8534a90428b874ca87862024dab5', '{"id":"MykolaPinchuk/TML-bench/checkpoint","name":"checkpoint","description":{"en":"The checkpoint skill provides a tabular ML benchmark, benefiting developers by ensuring Git consistency and safety. It automates preflight checks and sanity guardrails.","zh":"Checkpoint是一种Tabular ML Benchmark工具，用于确保代码版本控制和机器学习模型的准确性。它提供了Git状态检查和代码提交前的验证功能","ja":"Checkpointは、コードのバージョン管理と機械学習モデルの正確性を確保するためのTabular ML Benchmarkツールです。Gitの状態を確認し、コードをコミットする前に検証する機能を提供します","ko":"Checkpoint는 코드 버전 관리와 기계 학습 모델의 정확성을 보장하는 Tabular ML 벤치마크 도구입니다. Git 상태를 확인하고 코드를 커밋하기 전에 검증 기능을 제공합니다","es":"Checkpoint es una herramienta para tablas de benchmarking de ML que utiliza Git para el seguimiento de cambios y logs","fr":"Checkpoint est un outil pour les benchmarks de ML tabulaires qui utilise Git pour le suivi des modifications et des logs","de":"Checkpoint ist ein Tool für tabellarische ML-Benchmarks, das Git für die Änderungs- und Log-Verfolgung verwendet","pt":"O checkpoint é uma ferramenta de benchmarking de aprendizado de máquina em tabela que ajuda a garantir a integridade do código.","ru":"Точка контроля - это табличный бенчмарк машинного обучения, который помогает обеспечить целостность кода.","ar":"نقطة التحقق هي أداة اختبار الأداء للتعلم الآلي في الجداول التي تساعد في ضمان سلامة الكود."},"seo":{"title":{"en":"Checkpoint: Tabular ML Benchmark Setup Guide | AI Agent S...","zh":"Checkpoint Setup Guide: Git Status 和 Tabular ML Benchmark","ja":"Checkpoint セットアップガイド: Git Status と AIエージェントの Tabular ML B...","ko":"Checkpoint 설정 가이드: Git Status 및 Tabular ML 벤치마크","es":"Configuración de Checkpoint para Tablas de Benchmarking d...","fr":"Guide d''installation de Checkpoint pour les benchmarks de...","de":"Checkpoint-Setup für Tabellarische ML-Benchmarks","pt":"Guia de Configuração do Checkpoint para Ferramentas de IA","ru":"Настройка ИИ Агентов: Руководство по Checkpoint","ar":"إعداد نقطة التحقق لادوات الذكاء الاصطناعي"},"description":{"en":"Discover how to invoke the checkpoint skill for AI agents, ensuring synced logs and safe Git operations - learn more and get started now!","zh":"了解如何使用Checkpoint进行Git状态检查和Tabular ML Benchmark，确保代码版本控制和机器学习模型的准确性","ja":"Checkpointを使用してGitの状態を確認し、AIエージェントのTabular ML Benchmarkを実行する方法を学びましょう","ko":"Checkpoint를 사용하여 Git 상태를 확인하고 Tabular ML 벤치마크를 실행하여 코드 버전 관리와 기계 학습 모델의 정확성을 보장합니다","es":"Aprende a configurar Checkpoint para optimizar tus benchmarks de ML con Git y seguimiento de logs","fr":"Découvrez comment installer Checkpoint pour améliorer vos benchmarks de ML avec Git et suivi des logs","de":"Erfahren Sie, wie Sie Checkpoint für die Optimierung Ihrer ML-Benchmarks mit Git und Log-Verfolgung einrichten","pt":"Aprenda a configurar o checkpoint para garantir a integridade do seu código e evitar perdas de dados em ferramentas de IA","ru":"Изучите, как настроить точку контроля для обеспечения целостности кода и предотвращения потери данных в ИИ Агентах","ar":"تعرف على كيفية إعداد نقطة التحقق للحفاظ على سلامة الكود وتجنب فقدان البيانات في أدوات الذكاء الاصطناعي"},"definition":{"en":"Checkpoint is a skill that automates Git preflight checks and sanity guardrails for AI agents, ensuring log consistency and preventing harmful Git operations.","zh":"Checkpoint是一种用于确保代码版本控制和机器学习模型准确性的Tabular ML Benchmark工具","ja":"Checkpointは、コードのバージョン管理と機械学習モデルの正確性を確保するためのTabular ML Benchmarkツールです","ko":"Checkpoint는 코드 버전 관리와 기계 학습 모델의 정확성을 보장하는 Tabular ML 벤치마크 도구입니다","es":"Checkpoint es una herramienta de benchmarking de ML que utiliza comandos Git para verificar y sincronizar logs","fr":"Checkpoint est un outil de benchmarking de ML qui utilise des commandes Git pour vérifier et synchroniser les logs","de":"Checkpoint ist ein Tool für ML-Benchmarks, das Git-Befehle zur Überprüfung und Synchronisierung von Logs verwendet","pt":"O checkpoint é uma técnica de verificação de código que utiliza comandos Git para garantir a integridade dos dados.","ru":"Точка контроля - это техника проверки кода, использующая команды Git для обеспечения целостности данных.","ar":"نقطة التحقق هي تقنية للتحقق من الكود التي تستخدم أوامر Git لضمان سلامة البيانات."},"features":{"en":["Executes `git status` and `git diff --stat` for preflight checks","Verifies `agent_logs/current.md` id sync with kickoff `AgentNN`","Prevents execution of `git push`, `git commit --amend`, and other hazardous Git commands","Guards against staging or committing secrets and credentials","Ensures safe Git operations by avoiding `git reset --hard` and `git clean -fdx`"],"zh":["Git状态检查","代码提交前的验证","Tabular ML Benchmark","避免Git push、commit --amend、rebase、reset --hard等危险操作","保护代码中的秘密和凭证"],"ja":["Gitの状態を確認","コードをコミットする前の検証","Tabular ML Benchmark","Git push、commit --amend、rebase、reset --hardなどの危険な操作を避ける","コード内の秘密と資格情報を保護する"],"ko":["Git 상태 확인","코드 커밋 전 검증","Tabular ML 벤치마크","Git push, commit --amend, rebase, reset --hard 등의 위험한 작업을 피함","코드 내의 비밀과 자격 증명을 보호"],"es":["Verificación de estado de Git con `git status`","Diferenciación de estadísticas con `git diff --stat`","Sincronización de ID de logs con `agent_logs/current.md`","Protección contra la ejecución de comandos Git peligrosos","Exclusión de secretos y credenciales de los commits"],"fr":["Vérification de l''état de Git avec `git status`","Différenciation des statistiques avec `git diff --stat`","Synchronisation de l''ID de logs avec `agent_logs/current.md`","Protection contre l''exécution de commandes Git dangereuses","Exclusion des secrets et des informations d''identification des commits"],"de":["Überprüfung des Git-Status mit `git status`","Differenzierung von Statistiken mit `git diff --stat`","Synchronisierung der Log-ID mit `agent_logs/current.md`","Schutz vor der Ausführung gefährlicher Git-Befehle","Ausschluss von Geheimnissen und Anmeldeinformationen aus Commits"],"pt":["Executa `git status` e `git diff --stat` para verificar a integridade do código","Verifica se o `id:` em `agent_logs/current.md` está sincronizado com o kickoff `AgentNN`","Evita a execução de comandos Git perigosos, como `git push` e `git commit --amend`","Protege contra a perda de dados ao evitar a modificação de remotes Git","Não estagia ou comita segredos ou credenciais, como `.env*`, `*.pem` e `*.key`"],"ru":["Выполняет `git status` и `git diff --stat` для проверки целостности кода","Проверяет, синхронизирован ли `id:` в `agent_logs/current.md` с запуском `AgentNN`","Предотвращает выполнение опасных команд Git, таких как `git push` и `git commit --amend`","Защищает от потери данных, предотвращая изменение удаленных репозиториев Git","Не ставит и не коммитит секреты или учетные данные, такие как `.env*`, `*.pem` и `*.key`"],"ar":["ينفذ `git status` و `git diff --stat` للتحقق من سلامة الكود","يتحقق من是否 تم مزامنة `id:` في `agent_logs/current.md` مع إطلاق `AgentNN`","يمنع تنفيذ أوامر Git الخطرة، مثل `git push` و `git commit --amend`","يحمي من فقدان البيانات عن طريق منع تعديل مراكز Git عن بُعد","لا يضع أو يلتزم الأسرار أو بيانات الاعتماد، مثل `.env*` و `*.pem` و `*.key`"]},"keywords":{"en":["how to use checkpoint","checkpoint setup guide","tabular ML benchmark","git status command","git diff stat","agent logs current md","checkpoint vs gitflow","checkpoint install","what is checkpoint","checkpoint alternative"],"zh":["Checkpoint","Git状态检查","Tabular ML Benchmark","代码版本控制","机器学习模型","AI工具","代码提交","版本管理"],"ja":["Checkpoint","Gitの状態を確認","Tabular ML Benchmark","コードのバージョン管理","機械学習モデル","AIエージェント","コードをコミット","バージョン管理"],"ko":["Checkpoint","Git 상태 확인","Tabular ML 벤치마크","코드 버전 관리","기계 학습 모델","AI 도구","코드 커밋","버전 관리"],"es":["Checkpoint ML","benchmarking de ML","Git para ML","seguimiento de logs","optimización de ML","herramientas de ML","benchmarking tabular"," MACHINE LEARNING Agente"],"fr":["Checkpoint ML","benchmarking de ML","Git pour ML","suivi des logs","optimisation de ML","outils de ML","benchmarking tabulaire","AGENT IA"],"de":["Checkpoint ML","ML-Benchmarking","Git für ML","Log-Verfolgung","ML-Optimierung","ML-Tools","tabellarisches Benchmarking","KÜNSTLICHE INTELLIGENZ AGENT"],"pt":["checkpoint","ferramentas de IA","benchmarking de aprendizado de máquina","integridade do código","comandos Git","prevenção de perda de dados","segurança de código","desenvolvimento de software"],"ru":["точка контроля","ИИ Агенты","табличный бенчмарк машинного обучения","целостность кода","команды Git","предотвращение потери данных","безопасность кода","разработка программного обеспечения"],"ar":["نقطة التحقق","أدوات الذكاء الاصطناعي","اختبار الأداء للتعلم الآلي","سلامة الكود","أوامر Git","منع فقدان البيانات","أمان الكود","تطوير البرمجيات"]}},"owner":"MykolaPinchuk","repo":"TML-bench","repoPath":"MykolaPinchuk/TML-bench","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.386Z","topics":[],"category":"community","skillMd":{"name":"checkpoint","description":"Create a safe checkpoint git commit on the current branch (avoid competition data, runs, artifacts, secrets).","bodyPreview":"When invoked (or when the user says `checkpoint`), do this in order.\n\n## 1) Preflight (must do; show output)\n- `git status`\n- `git diff --stat`\n- Verify `agent_logs/current.md` `id:` is synced to the kickoff `AgentNN` for this chat. If stale, fix `current.md` before commit.\n\n## 2) Sanity guardrails (must do)\n- Never run: `git push`, `git commit --amend`, `git rebase`, `git reset --hard`, `git clean -fdx`, or modify git remotes.\n- Never stage/commit secrets/credentials: `.env*`, `*.pem`, `*.key`,","body":"When invoked (or when the user says `checkpoint`), do this in order.\n\n## 1) Preflight (must do; show output)\n- `git status`\n- `git diff --stat`\n- Verify `agent_logs/current.md` `id:` is synced to the kickoff `AgentNN` for this chat. If stale, fix `current.md` before commit.\n\n## 2) Sanity guardrails (must do)\n- Never run: `git push`, `git commit --amend`, `git rebase`, `git reset --hard`, `git clean -fdx`, or modify git remotes.\n- Never stage/commit secrets/credentials: `.env*`, `*.pem`, `*.key`, `id_rsa*`, `id_ed25519*`, tokens.\n- Never stage/commit competition data or run artifacts:\n  - `competitions/**/{public,private,raw,downloads}/**`\n  - `runs/**`\n  - sqlite/db files\n\n## 3) Stage (default: include safe tracked files)\nStage only source/docs/config files and small markdown:\n- root `*.md`, `*.yml`\n- `docs/**`\n- `local_context_enrichments/**`\n- `.codex/**`\n\nIf anything looks suspicious (bulk files, data-like payloads), stop and report before staging.\n\nBefore committing, show:\n- `git diff --cached --stat`\n\n## 4) Commit (auto message)\n- Create a structured message that includes the agent id:\n  - `agentNN: checkpoint(<area>): <short summary>`\n  - Derive `agentNN` from kickoff-synced `agent_logs/current.md` (field `id:`). If missing/ambiguous, stop and ask the human.\n  - Choose `<area>` from: `workflow`, `docs`, `orchestrator`, `competitions`, `prompts`, `ci`, `misc`.\n- Run `git commit -m \"<message>\"`.\n\n## 5) Postflight (must do; show output)\n- `git status`\n- Report the commit hash.\n"},"lastSynced":"2026-03-08T02:05:53.401Z","agentAnalysis":{"suitability":{"en":"Ideal for Git-integrated AI Agents requiring automated preflight checks and sanity guardrails for version control consistency.","zh":"适合需要自动化预飞检查和版本控制一致性防护的Git集成AI代理。","ja":"Git統合AIエージェントが自動化された事前フライトチェックとバージョン管理の一貫性を保証するためのガードレールを必要とする場合に最適です。","ko":"자동화된 사전 비행 검사 및 버전 관리 일관성을 위한 감시 레일이 필요한 Git 통합 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA integrados con Git que requieren comprobaciones de pre-vuelo automatizadas y barreras de seguridad para la consistencia del control de versiones.","fr":"Idéal pour les agents d''IA intégrés à Git nécessitant des vérifications de pré-vol automatisées et des gardes-fous de sécurité pour la cohérence du contrôle de version.","de":"Ideal für in Git integrierte KI-Agents, die automatisierte Vorflugchecks und Sicherungsschutz für die Konsistenz der Versionskontrolle erfordern.","pt":"Ideal para Agentes de IA integrados ao Git que requerem verificações de pré-voo automatizadas e guardrails de sanidade para consistência de controle de versão.","ru":"Идеально для агентов ИИ, интегрированных с Git, требующих автоматических предполетных проверок и барьеров санитарной обработки для обеспечения согласованности системы контроля версий.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي المتكاملة مع Git التي تتطلب فحوصات ما قبل الطيران الآلية وحدود حماية الصحة العقلية للاتساق في التحكم بالنسخة."},"recommendation":{"en":"Empowers agents to automate Git consistency checks using `git status` and `git diff --stat`, while ensuring `agent_logs/current.md` synchronization and preventing accidental pushes or commits of secrets via `.env*`, `*.pem`, or `*.key` files.","zh":"赋予代理人使用`git status`和`git diff --stat`自动化Git一致性检查的能力，同时确保`agent_logs/current.md`同步并防止通过`.env*`、`*.pem`或`*.key`文件意外推送或提交机密数据。","ja":"`git status`および`git diff --stat`を使用してGitの一貫性チェックを自動化するエージェントの能力を提供し、同時に`agent_logs/current.md`の同期を確保し、`.env*`、`*.pem`、または`*.key`ファイルを介した機密データの意図しないプッシュまたはコミットを防止します。","ko":"`git status` 및 `git diff --stat`를 사용하여 Git 일관성 검사를 자동화하는 에이전트의 능력을 제공하며, 동시에 `agent_logs/current.md`의 동기화를 보장하고 `.env*`, `*.pem`, 또는 `*.key` 파일을 통해 기밀 데이터의 의도하지 않은 푸시 또는 커밋을 방지합니다.","es":"Habilita a los agentes a automatizar las comprobaciones de coherencia de Git utilizando `git status` y `git diff --stat`, al mismo tiempo que garantiza la sincronización de `agent_logs/current.md` y evita los empujes o confirmaciones accidentales de secretos a través de archivos `.env*`, `*.pem` o `*.key`.","fr":"Permet aux agents d''automatiser les vérifications de cohérence de Git en utilisant `git status` et `git diff --stat`, tout en assurant la synchronisation de `agent_logs/current.md` et en empêchant les poussées ou les validations accidentelles de secrets via des fichiers `.env*`, `*.pem` ou `*.key`.","de":"Ermächtigt Agents, Git-Konsistenzchecks mithilfe von `git status` und `git diff --stat` zu automatisieren, während gleichzeitig die Synchronisation von `agent_logs/current.md` sichergestellt und unbeabsichtigte Push- oder Commit-Vorgänge von Geheimnissen über `.env*`-, `*.pem`- oder `*.key`-Dateien verhindert werden.","pt":"Habilita os agentes a automatizar verificações de consistência do Git usando `git status` e `git diff --stat`, garantindo a sincronização de `agent_logs/current.md` e prevenindo pushs ou commits acidentais de segredos via arquivos `.env*`, `*.pem` ou `*.key`.","ru":"Наделяет агентов возможностью автоматизировать проверки согласованности Git с помощью `git status` и `git diff --stat`, обеспечивая синхронизацию `agent_logs/current.md` и предотвращая случайные публикации или фиксации секретов через файлы `.env*`, `*.pem` или `*.key`.","ar":"تمكّن الوكيل من توفير عمليات تلقائية للتحقق من الاتساق مع Git باستخدام `git status` و `git diff --stat`، مع ضمان مزامنة `agent_logs/current.md` ومنع الضغط العرضي أو الالتزام ببيانات سرية عبر الملفات `.env*` و `*.pem` و `*.key`."},"useCases":{"en":["Automating preflight checks for Git commits","Verifying `agent_logs/current.md` synchronization","Preventing accidental pushes of sensitive data"],"zh":["自动化Git提交的预飞检查","验证`agent_logs/current.md`同步","防止敏感数据的意外推送"],"ja":["Gitコミットの事前フライトチェックの自動化","`agent_logs/current.md`の同期の検証","機密データの意図しないプッシュの防止"],"ko":["Git 커밋의 사전 비행 검사 자동화","`agent_logs/current.md` 동기화 검증","기밀 데이터의 의도하지 않은 푸시 방지"],"es":["Automatización de comprobaciones de pre-vuelo para confirmaciones de Git","Verificación de la sincronización de `agent_logs/current.md`","Prevención de empujes accidentales de datos sensibles"],"fr":["Automatisation des vérifications de pré-vol pour les validations Git","Vérification de la synchronisation de `agent_logs/current.md`","Prévention des poussées accidentelles de données sensibles"],"de":["Automatisierung von Vorflugchecks für Git-Commits","Überprüfung der Synchronisation von `agent_logs/current.md`","Verhinderung unbeabsichtigter Push-Vorgänge von sensiblen Daten"],"pt":["Automatizar verificações de pré-voo para commits do Git","Verificar a sincronização de `agent_logs/current.md`","Prevenir pushs acidentais de dados sensíveis"],"ru":["Автоматизировать предполетные проверки для коммитов Git","Проверять синхронизацию `agent_logs/current.md`","Предотвращать случайные публикации конфиденциальных данных"],"ar":["توفير عمليات تلقائية للتحقق من ما قبل الطيران لعمليات الالتزام بالنسخة","التحقق من مزامنة `agent_logs/current.md`","منع عمليات الضغط العرضية لبيانات سرية"]},"limitations":{"en":["Requires Git installation and configuration","Limited to preventing specific Git commands like `git push`, `git commit --amend`, and `git rebase`"],"zh":["需要Git安装和配置","仅限防止特定的Git命令，如`git push`、`git commit --amend`和`git rebase`"],"ja":["Gitのインストールとコンフィギュレーションが必要","特定のGitコマンド（`git push`、`git commit --amend`、`git rebase`など）を防止することのみに限定"],"ko":["Git 설치 및 구성이 필요","특정 Git 명령어(`git push`, `git commit --amend`, `git rebase` 등)만 방지하는 것에 한정"],"es":["Requiere la instalación y configuración de Git","Limitado a la prevención de comandos de Git específicos como `git push`, `git commit --amend` y `git rebase`"],"fr":["Nécessite l''installation et la configuration de Git","Limité à la prévention de commandes Git spécifiques comme `git push`, `git commit --amend` et `git rebase`"],"de":["Erfordert die Installation und Konfiguration von Git","Begrenzt auf die Verhinderung spezifischer Git-Befehle wie `git push`, `git commit --amend` und `git rebase`"],"pt":["Requer instalação e configuração do Git","Limitado a prevenir comandos Git específicos como `git push`, `git commit --amend` e `git rebase`"],"ru":["Требует установки и настройки Git","Ограничен предотвращением конкретных команд Git, таких как `git push`, `git commit --amend` и `git rebase`"],"ar":["يتطلب تثبيت وتكوين Git","محدود بمنع أوامر Git المحددة مثل `git push` و `git commit --amend` و `git rebase`"]},"version":4},"contentHash":"813bb91b0e653ffeb8197ccf8cb9dc015b7b8534a90428b874ca87862024dab5","qualityScore":23}');
