INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('MykolaPinchuk/TML-bench/checkpoint', 'checkpoint', 'MykolaPinchuk', 'TML-bench', 'community', 'checkpoint MykolaPinchuk TML-bench community The checkpoint skill provides a tabular ML benchmark, benefiting developers by ensuring Git consistency and safety. It automates preflight checks and sanity guardrails. Checkpoint是一种Tabular ML Benchmark工具，用于确保代码版本控制和机器学习模型的准确性。它提供了Git状态检查和代码提交前的验证功能 Checkpointは、コードのバージョン管理と機械学習モデルの正確性を確保するためのTabular ML Benchmarkツールです。Gitの状態を確認し、コードをコミットする前に検証する機能を提供します Checkpoint는 코드 버전 관리와 기계 학습 모델의 정확성을 보장하는 Tabular ML 벤치마크 도구입니다. Git 상태를 확인하고 코드를 커밋하기 전에 검증 기능을 제공합니다 Checkpoint es una herramienta para tablas de benchmarking de ML que utiliza Git para el seguimiento de cambios y logs Checkpoint est un outil pour les benchmarks de ML tabulaires qui utilise Git pour le suivi des modifications et des logs Checkpoint ist ein Tool für tabellarische ML-Benchmarks, das Git für die Änderungs- und Log-Verfolgung verwendet O checkpoint é uma ferramenta de benchmarking de aprendizado de máquina em tabela que ajuda a garantir a integridade do código. Точка контроля - это табличный бенчмарк машинного обучения, который помогает обеспечить целостность кода. نقطة التحقق هي أداة اختبار الأداء للتعلم الآلي في الجداول التي تساعد في ضمان سلامة الكود. how to use checkpoint checkpoint setup guide tabular ML benchmark git status command git diff stat agent logs current md checkpoint vs gitflow checkpoint install what is checkpoint checkpoint alternative Checkpoint Git状态检查 Tabular ML Benchmark 代码版本控制 机器学习模型 AI工具 代码提交 版本管理 Executes `git status` and `git diff --stat` for preflight checks Verifies `agent_logs/current.md` id sync with kickoff `AgentNN` Prevents execution of `git push`, `git commit --amend`, and other hazardous Git commands Guards against staging or committing secrets and credentials Ensures safe Git operations by avoiding `git reset --hard` and `git clean -fdx` Checkpoint is a skill that automates Git preflight checks and sanity guardrails for AI agents, ensuring log consistency and preventing harmful Git operations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lluisaliano/dotfilesUltra/gh-address-comments', 'community', 'lluisaliano', 'dotfilesUltra', 'lluisaliano/dotfilesUltra', 'gh-address-comments', 0, 0, 23, '2026-03-08T01:57:15.387Z', '2026-03-08T02:05:55.826Z', '77389eefd3fb6584210668ca8e43f4b8de87e7722ddd953474bc9e24cdfaaedd', '{"id":"lluisaliano/dotfilesUltra/gh-address-comments","name":"gh-address-comments","description":{"en":"The gh-address-comments skill helps developers find and address open PR comments using the gh CLI, ensuring seamless GitHub workflow management.","zh":"gh-address-comments是一个AIエージェント，用于自动化PR评论处理。它使用gh CLI来检视和回复评论。","ja":"gh-address-commentsは、PRコメントの処理を自動化するAIエージェントです。gh CLIを使用してコメントを検査し、返信します。","ko":"gh-address-comments는 PR 댓글 처리를 자동화하는 AI 에이전트입니다. gh CLI를 사용하여 댓글을 검토하고 응답합니다.","es":"gh-address-comments es una herramienta que ayuda a gestionar comentarios de PR con gh CLI. Requiere autenticación con gh y permisos elevados","fr":"gh-address-comments est un outil qui aide à gérer les commentaires de PR avec gh CLI. Il nécessite une authentification avec gh et des autorisations élevées","de":"gh-address-comments ist ein Tool, das dabei hilft, PR-Kommentare mit gh CLI zu verwalten. Es erfordert eine Authentifizierung mit gh und erweiterte Berechtigungen","pt":"O gh-address-comments é uma ferramenta de automação de comentários que ajuda a gerenciar PRs com o CLI gh. Ele inspeciona comentários que precisam de atenção e executa scripts para resolver problemas","ru":"ИИ Агент gh-address-comments - это инструмент для автоматизации комментариев, который помогает управлять PR с помощью CLI gh. Он проверяет комментарии, требующие внимания, и выполняет скрипты для решения проблем","ar":"أداة gh-address-comments هي أداة خودومة للتعليقات التي تساعد في إدارة PRs باستخدام واجهة سطر الأوامر gh. وهي تفحص التعليقات التي تحتاج إلى الانتباه وتشغيل البرامج النصية لحل المشاكل"},"seo":{"title":{"en":"gh-address-comments: PR Comment Handler Setup Guide | AI ...","zh":"gh-address-comments Setup Guide - AIエージェント for PR Comment...","ja":"gh-address-comments ベストプラクティス - AIエージェントによるPRコメントハンドリング","ko":"gh-address-comments 설정 가이드 - AI 에이전트를 통한 PR 댓글 처리","es":"Guía de configuración de gh-address-comments para manejo ...","fr":"Guide de configuration de gh-address-comments pour la ges...","de":"Konfigurationsleitfaden für gh-address-comments zur Verwa...","pt":"Guia de Configuração do gh-address-comments: Ferramentas ...","ru":"ИИ Агенты: Настройка gh-address-comments для Автоматизаци...","ar":"دليل إعداد أداة gh-address-comments: أدوات خودومة التعليقات"},"description":{"en":"Streamline your GitHub workflow by addressing PR comments with gh CLI - learn how to authenticate and run commands with elevated network access","zh":"使用gh-address-comments AIエージェント自动化PR评论处理，提高开发效率。了解如何设置和使用gh CLI。","ja":"gh-address-comments AIエージェントを使用してPRコメントの処理を自動化し、開発効率を向上させる。設定方法とgh CLIの使い方を学ぶ。","ko":"gh-address-comments AI 에이전트를 사용하여 PR 댓글 처리를 자동화하고 개발 효율성을 높여보세요. 설정 방법과 gh CLI 사용법을 배우세요.","es":"Aprende a configurar gh-address-comments para gestionar comentarios de PR de forma efectiva y mejorar tu flujo de trabajo","fr":"Découvrez comment configurer gh-address-comments pour gérer les commentaires de PR de manière efficace et améliorer votre flux de travail","de":"Erfahren Sie, wie Sie gh-address-comments konfigurieren, um PR-Kommentare effektiv zu verwalten und Ihren Arbeitsablauf zu verbessern","pt":"Aprenda a configurar o gh-address-comments para automatizar comentários em PRs com o CLI gh e melhorar a produtividade do seu time de desenvolvimento","ru":"Узнайте, как настроить gh-address-comments для автоматизации комментариев в PR с помощью CLI gh и повысить производительность вашей команды разработчиков","ar":"تعرف على كيفية إعداد أداة gh-address-comments لتحسين إنتاجية فريقك من خلال تلقين التعليقات في PRs باستخدام واجهة سطر الأوامر gh"},"definition":{"en":"gh-address-comments is a skill that provides a guide to handling PR comments using the gh command-line interface","zh":"gh-address-comments是用于自动化PR评论处理的AIエージェント，使用gh CLI来检视和回复评论。","ja":"gh-address-commentsは、PRコメントの処理を自動化するAIエージェントで、gh CLIを使用してコメントを検査し、返信します。","ko":"gh-address-comments는 PR 댓글 처리를 자동화하는 AI 에이전트로 gh CLI를 사용하여 댓글을 검토하고 응답합니다.","es":"gh-address-comments es un agente de AI que gestiona comentarios de PR con gh CLI y autenticación","fr":"gh-address-comments est un agent IA qui gère les commentaires de PR avec gh CLI et l''authentification","de":"gh-address-comments ist ein KI-Agent, der PR-Kommentare mit gh CLI und Authentifizierung verwaltet","pt":"O gh-address-comments é uma ferramenta de automação que utiliza o CLI gh para gerenciar comentários em PRs","ru":"ИИ Агент gh-address-comments - это инструмент для автоматизации комментариев, основанный на CLI gh","ar":"أداة gh-address-comments هي أداة خودومة للتعليقات التي تستخدم واجهة سطر الأوامر gh"},"features":{"en":["Runs gh commands with elevated network access","Authenticates using gh auth login and gh auth status","Supports escalated permissions with workflow and repo scopes","Handles sandboxing blocks with sandbox_permissions=require_escalated","Inspects comments needing attention with custom scripts"],"zh":["使用gh CLI检视和回复PR评论","支持授权和权限设置","可以在工作流和仓库中使用","支持sandbox权限设置","可以与gh auth status命令结合使用"],"ja":["gh CLIを使用してPRコメントを検査し、返信する","認証と権限設定をサポート","ワークフローとリポジトリで使用可能","サンドボックス権限設定をサポート","gh auth statusコマンドと組み合わせて使用可能"],"ko":["gh CLI를 사용하여 PR 댓글을 검토하고 응답","인증 및 권한 설정 지원","워크플로우 및 리포지토리에서 사용 가능","샌드박스 권한 설정 지원","gh auth status 명령어와 함께 사용 가능"],"es":["Inspección de comentarios que requieren atención","Uso de gh CLI para gestionar comentarios de PR","Requiere autenticación con gh y permisos elevados","Compatibilidad con sandboxing y permisos escalados","Integración con flujos de trabajo y repositorios"],"fr":["Inspection des commentaires qui nécessitent une attention","Utilisation de gh CLI pour gérer les commentaires de PR","Nécessite une authentification avec gh et des autorisations élevées","Compatibilité avec le sandboxing et les autorisations escalées","Intégration avec les flux de travail et les référentiels"],"de":["Überprüfung von Kommentaren, die Aufmerksamkeit erfordern","Verwendung von gh CLI zur Verwaltung von PR-Kommentaren","Erfordert Authentifizierung mit gh und erweiterte Berechtigungen","Kompatibilität mit Sandboxing und eskalierten Berechtigungen","Integration mit Arbeitsabläufen und Repositorien"],"pt":["Inspeciona comentários que precisam de atenção","Executa scripts para resolver problemas","Utiliza o CLI gh para gerenciar PRs","Requer autenticação com o gh auth login","Suporta permissões escalonadas com sandbox_permissions=require_escalated"],"ru":["Проверяет комментарии, требующие внимания","Выполняет скрипты для решения проблем","Использует CLI gh для управления PR","Требует аутентификации с помощью gh auth login","Поддерживает повышенные разрешения с sandbox_permissions=require_escalated"],"ar":["تفحص التعليقات التي تحتاج إلى الانتباه","تشغيل البرامج النصية لحل المشاكل","استخدام واجهة سطر الأوامر gh لإدارة PRs","يتطلب المصادقة مع gh auth login","يدعم الصلاحيات المعززة مع sandbox_permissions=require_escalated"]},"keywords":{"en":["how to use gh-address-comments","gh-address-comments setup guide","gh-address-comments alternative","gh-address-comments vs GitHub CLI","gh-address-comments install","what is gh-address-comments","gh-address-comments authentication","gh-address-comments workflow management"],"zh":["gh-address-comments","AIエージェント","PR评论处理","gh CLI","自动化","开发效率","权限设置","工作流","仓库"],"ja":["gh-address-comments","AIエージェント","PRコメントハンドリング","gh CLI","自動化","開発効率","権限設定","ワークフロー","リポジトリ"],"ko":["gh-address-comments","AI 에이전트","PR 댓글 처리","gh CLI","자동화","개발 효율성","권한 설정","워크플로우","리포지토리"],"es":["gh-address-comments","agente de AI para PR","gestión de comentarios de PR","gh CLI","autenticación con gh","permisos elevados","sandboxing","flujos de trabajo"],"fr":["gh-address-comments","agent IA pour PR","gestion des commentaires de PR","gh CLI","authentification avec gh","autorisations élevées","sandboxing","flux de travail"],"de":["gh-address-comments","KI-Agent für PR","Verwaltung von PR-Kommentaren","gh CLI","Authentifizierung mit gh","erweiterte Berechtigungen","Sandboxing","Arbeitsabläufe"],"pt":["gh-address-comments","automação de comentários","CLI gh","gerenciamento de PRs","desenvolvimento de software","ferramentas de automação","gh auth login","permissões escalonadas"],"ru":["ИИ Агенты","автоматизация комментариев","CLI gh","управление PR","разработка программного обеспечения","инструменты автоматизации","gh auth login","повышенные разрешения"],"ar":["أدوات خودومة","تلقين التعليقات","واجهة سطر الأوامر gh","إدارة PRs","تطوير البرمجيات","أدوات خودومة","gh auth login","الصلاحيات المعززة"]}},"owner":"lluisaliano","repo":"dotfilesUltra","repoPath":"lluisaliano/dotfilesUltra","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.387Z","topics":[],"category":"community","skillMd":{"name":"gh-address-comments","description":"Help address review/issue comments on the open GitHub PR for the current branch using gh CLI; verify gh auth first and prompt the user to authenticate if not logged in.","bodyPreview":"# PR Comment Handler\n\nGuide to find the open PR for the current branch and address its comments with gh CLI. Run all `gh` commands with elevated network access.\n\nPrereq: ensure `gh` is authenticated (for example, run `gh auth login` once), then run `gh auth status` with escalated permissions (include workflow/repo scopes) so `gh` commands succeed. If sandboxing blocks `gh auth status`, rerun it with `sandbox_permissions=require_escalated`.\n\n## 1) Inspect comments needing attention\n- Run scripts/","body":"# PR Comment Handler\n\nGuide to find the open PR for the current branch and address its comments with gh CLI. Run all `gh` commands with elevated network access.\n\nPrereq: ensure `gh` is authenticated (for example, run `gh auth login` once), then run `gh auth status` with escalated permissions (include workflow/repo scopes) so `gh` commands succeed. If sandboxing blocks `gh auth status`, rerun it with `sandbox_permissions=require_escalated`.\n\n## 1) Inspect comments needing attention\n- Run scripts/fetch_comments.py which will print out all the comments and review threads on the PR\n\n## 2) Ask the user for clarification\n- Number all the review threads and comments and provide a short summary of what would be required to apply a fix for it\n- Ask the user which numbered comments should be addressed\n\n## 3) If user chooses comments\n- Apply fixes for the selected comments\n\nNotes:\n- If gh hits auth/rate issues mid-run, prompt the user to re-authenticate with `gh auth login`, then retry.\n"},"lastSynced":"2026-03-08T02:05:55.826Z","agentAnalysis":{"suitability":{"en":"Perfect for GitHub Workflow Agents needing automated PR comment management using the gh CLI.","zh":"非常适合需要使用 gh CLI 进行自动化 PR 评论管理的 GitHub Workflow Agents。","ja":"GitHub Workflow Agents が gh CLI を使用して自動化された PR コメント管理を必要とする場合に最適です。","ko":"gh CLI를 사용하여 자동화된 PR 댓글 관리가 필요한 GitHub Workflow Agents에 적합합니다.","es":"Perfecto para agentes de flujo de trabajo de GitHub que necesitan una gestión automatizada de comentarios de PR utilizando el CLI de gh.","fr":"Parfait pour les agents de workflow GitHub ayant besoin d''une gestion automatique des commentaires de PR en utilisant le CLI gh.","de":"Perfekt für GitHub-Workflow-Agents, die eine automatisierte PR-Kommentarverwaltung unter Verwendung des gh-CLI benötigen.","pt":"Perfeito para Agentes de Fluxo de Trabalho do GitHub que necessitam de gerenciamento automatizado de comentários de PR usando o gh CLI.","ru":"Идеально подходит для агентов GitHub Workflow, которым требуется автоматизированное управление комментариями PR с помощью gh CLI.","ar":"مثالي للوكلاء في سير عمل جيت هب الذين يحتاجون إلى إدارة تعليقات المراجعة الم-automatic باستخدام واجهة سطر الأوامر gh."},"recommendation":{"en":"Empowers agents to inspect and address open PR comments using the gh CLI, ensuring seamless GitHub workflow management with elevated network access and workflow/repo scopes.","zh":"赋予代理人使用 gh CLI 检查和处理打开的 PR 评论的能力，确保 GitHub 工作流管理的顺畅进行并具有提高的网络访问和工作流/仓库范围。","ja":"エージェントが gh CLI を使用してオープンの PR コメントを検査および処理できるようにし、GitHub ワークフロー管理をシームレスに実行し、ネットワーク アクセスとワークフロー/リポジトリの範囲を高める。","ko":"에이전트가 gh CLI를 사용하여 열린 PR 댓글을 검사 및 처리할 수 있도록 하여 GitHub 워크플로우 관리를 원활하게 진행하고 네트워크 접근 및 워크플로우/리포지토리 범위를 높입니다.","es":"Habilita a los agentes a inspeccionar y abordar comentarios de PR abiertos utilizando el CLI de gh, garantizando una gestión de flujo de trabajo de GitHub sin problemas con acceso de red elevado y alcance de flujo/repo.","fr":"Permet aux agents d''inspecter et de traiter les commentaires de PR ouverts en utilisant le CLI gh, garantissant ainsi une gestion de workflow GitHub fluide avec un accès réseau élevé et des étendues de workflow/repo.","de":"Ermächtigt Agents, offene PR-Kommentare unter Verwendung des gh-CLI zu überprüfen und anzusprechen, sodass eine reibungslose GitHub-Workflow-Verwaltung mit erhöhtem Netzwerkzugriff und Workflow/Repo-Berechtigungen gewährleistet ist.","pt":"Habilita os agentes a inspecionar e abordar comentários de PR abertos usando o gh CLI, garantindo uma gestão de fluxo de trabalho do GitHub sem interrupções com acesso de rede elevado e escopos de fluxo de trabalho/repositório.","ru":"Наделяет агентов возможностью проверять и решать проблемы открытых комментариев PR с помощью gh CLI, обеспечивая бесперебойное управление рабочим процессом GitHub с повышенным доступом к сети и областями действия рабочего процесса/репозитория.","ar":"تمكّن الوكلاء من فحص التعليقات المفتوحة للمراجعة وتناولها باستخدام واجهة سطر الأوامر gh، مما يضمن إدارة سير عمل جيت هب بسلاسة مع وصول الشبكة المعزز ونطاقات سير العمل/المستودع."},"useCases":{"en":["Automating PR comment inspection","Addressing open PR comments with gh CLI","Streamlining GitHub workflow management"],"zh":["自动化 PR 评论检查","使用 gh CLI 处理打开的 PR 评论","简化 GitHub 工作流管理"],"ja":["PR コメントの検査の自動化","gh CLI を使用してオープンの PR コメントに応答","GitHub ワークフローの管理をストリームライン化"],"ko":["PR 댓글 검사의 자동화","gh CLI를 사용하여 열린 PR 댓글에 응답","GitHub 워크플로우 관리를 간소화"],"es":["Automatización de la inspección de comentarios de PR","Abordar comentarios de PR abiertos con gh CLI","Optimización de la gestión del flujo de trabajo de GitHub"],"fr":["Automatisation de l''inspection des commentaires de PR","Traiter les commentaires de PR ouverts avec le CLI gh","Optimisation de la gestion du workflow GitHub"],"de":["Automatisierung der Überprüfung von PR-Kommentaren","Abordnen von offenen PR-Kommentaren mit gh-CLI","Optimierung der GitHub-Workflow-Verwaltung"],"pt":["Automatização da inspeção de comentários de PR","Abordagem de comentários de PR abertos com gh CLI","Otimização da gestão de fluxo de trabalho do GitHub"],"ru":["Автоматизация проверки комментариев PR","Решение открытых комментариев PR с помощью gh CLI","Оптимизация управления рабочим процессом GitHub"],"ar":["أتمتة فحص تعليقات المراجعة","معالجة تعليقات المراجعة المفتوحة باستخدام واجهة سطر الأوامر gh","تسهيل إدارة سير عمل جيت هب"]},"limitations":{"en":["Requires gh authentication and authorization","Needs escalated permissions for workflow/repo scopes","Dependent on gh CLI version and compatibility"],"zh":["需要 gh 身份验证和授权","需要提高的权限来访问工作流/仓库范围","依赖于 gh CLI 版本和兼容性"],"ja":["gh の認証と認可が必要","ワークフロー/リポジトリの範囲にアクセスするために昇格された権限が必要","gh CLI のバージョンと互換性に依存"],"ko":["gh 인증 및 권한 부여가 필요","워크플로우/리포지토리 범위에 접근하기 위해 상승된 권한 필요","gh CLI 버전 및 호환성에 의존"],"es":["Requiere autenticación y autorización de gh","Necesita permisos elevados para el alcance de flujo/repo","Dependiente de la versión y la compatibilidad del CLI de gh"],"fr":["Nécessite une authentification et une autorisation gh","Nécessite des autorisations élevées pour les étendues de workflow/repo","Dépend de la version et de la compatibilité du CLI gh"],"de":["Erfordert gh-Authentifizierung und Autorisierung","Benötigt erhöhte Berechtigungen für Workflow/Repo-Berechtigungen","Abhängig von der Version und der Kompatibilität des gh-CLI"],"pt":["Requer autenticação e autorização do gh","Necessita de permissões elevadas para escopos de fluxo de trabalho/repositório","Dependente da versão e compatibilidade do gh CLI"],"ru":["Требует аутентификации и авторизации gh","Требует повышенных разрешений для областей действия рабочего процесса/репозитория","Зависит от версии и совместимости gh CLI"],"ar":["يتطلب مصادقة وتأشير gh","يحتاج إلى صلاحيات معززة لمجالات سير العمل/المستودع","يعتمد على إصدار واجهة سطر الأوامر gh ومتطلبات التوافق"]},"version":4},"contentHash":"77389eefd3fb6584210668ca8e43f4b8de87e7722ddd953474bc9e24cdfaaedd","qualityScore":23}');
