INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('impactaky/shelffiles-spec/workflow', 'workflow', 'impactaky', 'shelffiles-spec', 'community', 'workflow impactaky shelffiles-spec community The workflow skill automates OpenSpec file management for shelffiles, benefiting developers who need to streamline their workflow processes. It chains key OpenSpec skills with self-review and git commits. 自动化工作流通过OpenSpec文件链式调用$openspec-proposal、$openspec-apply和$openspec-archive 自動化ワークフローはOpenSpecファイルを使用して$openspec-proposal、$openspec-apply、$openspec-archiveを連結する 自動化 워크플로우는 OpenSpec 파일을 사용하여 $openspec-proposal, $openspec-apply, $openspec-archive를 연쇄적으로 호출 El flujo de trabajo con OpenSpec permite la automatización de tareas con $openspec-proposal, $openspec-apply y $openspec-archive. Le workflow avec OpenSpec permet l''automatisation de tâches avec $openspec-proposal, $openspec-apply et $openspec-archive. Der Workflow mit OpenSpec ermöglicht die Automatisierung von Aufgaben mit $openspec-proposal, $openspec-apply und $openspec-archive. O workflow com OpenSpec automatiza a criação de propostas e commits de código, permitindo uma gestão eficiente de projetos. Рабочий процесс с OpenSpec автоматизирует создание предложений и коммитов кода, обеспечивая эффективное управление проектами с помощью ИИ Агентов سير العمل مع OpenSpec يؤتمة إنشاء المقترحات والكتابة في كود، مما يتيح إدارة مشاريع فعالة how to use workflow with OpenSpec workflow automation setup guide OpenSpec file management workflow workflow vs manual process what is workflow automation install workflow skill for AI agents 工作流自动化 OpenSpec文件 自动化测试 CI/CD DevOps 自动化脚本 CLI工具 AI工具 自动化工作流 Generates proposals using $openspec-proposal skill Performs self-review for completeness and correctness Chains $openspec-apply and $openspec-archive skills for seamless workflow Utilizes git commits at each stage for version control Executes automated workflow without human interaction Workflow is an automated process that chains OpenSpec skills like $openspec-proposal, $openspec-apply, and $openspec-archive with self-review and git commits for efficient management.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zylos-ai/zylos-core/scheduler', 'community', 'zylos-ai', 'zylos-core', 'zylos-ai/zylos-core', 'scheduler', 0, 0, 23, '2026-03-08T01:57:15.401Z', '2026-03-08T02:06:45.643Z', 'a377be3231b1212f1afdc367c0dd0bcffc57ed969ef350ceca775da8b4ea576c', '{"id":"zylos-ai/zylos-core/scheduler","name":"scheduler","description":{"en":"The scheduler skill enables AI agents to work autonomously by dispatching scheduled tasks. It benefits developers by providing a self-maintaining infrastructure for persistent AI companions.","zh":"Scheduler 是一种开源基础设施，允许 AI 伴侣持久存在和自我维护。它通过 C4 通信桥接实现调度任务的分发","ja":"Scheduler は、AI エージェントが持続的に存在し、自己維持できるオープンソースインフラストラクチャです。C4 コミュニケーションブリッジを介してスケジュールタスクを配信します","ko":"Scheduler 는 지속적이고 자율적인 AI 동반자를 위한 오픈소스 인프라스트럭처로 C4 커뮤니케이션 브릿지를 통해 스케줄 태스크를 배포","es":"El programador de tareas de AI permite la autonomía en tus proyectos de inteligencia artificial mediante la ejecución de tareas programadas","fr":"Le planificateur de tâches d''IA permet l''autonomie dans vos projets d''intelligence artificielle en exécutant des tâches planifiées","de":"Der Aufgabenplaner von AI ermöglicht Autonomie in Ihren KI-Projekten durch die Ausführung geplanter Aufgaben","pt":"O agendador de tarefas permite que a IA trabalhe de forma autônoma, enviando tarefas agendadas via C4 comm-bridge. Funciona com Activity Monitor e Claude Code.","ru":"Планировщик задач позволяет ИИ работать автономно, отправляя запланированные задачи через C4 comm-bridge. Работает с Activity Monitor и Claude Code.","ar":"مجدول المهام يسمح للوكلاء الذكيين بالعمل بشكل مستقل، بإرسال المهام المجدولة عبر C4 comm-bridge. يعمل مع Activity Monitor و Claude Code."},"seo":{"title":{"en":"Scheduler: Autonomous Task Management for AI Agents | AI ...","zh":"Scheduler 设置指南 - 持续集成 AI 伴侣","ja":"Scheduler 導入ガイド - 自動化 AI エージェント","ko":"Scheduler 설정 가이드 - 지속적 AI 동반자","es":"Guía de configuración del programador de tareas de AI","fr":"Guide d''installation du planificateur de tâches d''IA","de":"Einrichtungsanleitung für den Aufgabenplaner von AI","pt":"Guia de Configuração do Agendador de Tarefas AI","ru":"Руководство по настройке планировщика задач ИИ Агентов","ar":"دليل إعداد جدول المهام للوكلاء الذكيين"},"description":{"en":"Unlock autonomous AI capabilities with the scheduler skill - learn how to dispatch scheduled tasks via C4 comm-bridge and prioritize execution control","zh":"了解 Scheduler 的功能和优势，实现 AI 伴侣的持续集成和自主工作","ja":"Scheduler の機能と利点を学び、AI エージェントの自動化と自律性を実現","ko":"Scheduler 의 기능과 이점을 알아보고 지속적 AI 동반자와 자율성을 실현","es":"Aprende a configurar el programador de tareas de AI para habilitar la autonomía en tus proyectos de inteligencia artificial","fr":"Découvrez comment installer le planificateur de tâches d''IA pour permettre l''autonomie dans vos projets d''intelligence artificielle","de":"Erfahren Sie, wie Sie den Aufgabenplaner von AI einrichten, um Autonomie in Ihren KI-Projekten zu ermöglichen","pt":"Aprenda a configurar o agendador de tarefas para seus companheiros de IA autônomos, com tecnologias como C4 comm-bridge e Claude Code.","ru":"Узнайте, как настроить планировщик задач для автономных компаньонов ИИ, с технологиями như C4 comm-bridge и Claude Code.","ar":"تعرف على كيفية إعداد جدول المهام للوكلاء الذكيين المستقلين، مع تقنيات مثل C4 comm-bridge و Claude Code."},"definition":{"en":"Scheduler is an open-source infrastructure that enables autonomous AI task management via the C4 comm-bridge, prioritizing execution control and idle waiting","zh":"Scheduler 是一种任务调度器，允许 AI 伴侣自主工作","ja":"Scheduler は、AI エージェントが自律的に動作できるタスクスケジューラーです","ko":"Scheduler 는 AI 동반자가 자율적으로 동작할 수 있는 태스크 스케줄러","es":"Un programador de tareas de AI es un componente que permite la ejecución automática de tareas en función de una programación definida","fr":"Un planificateur de tâches d''IA est un composant qui permet l''exécution automatique de tâches en fonction d''une planification définie","de":"Ein Aufgabenplaner von AI ist ein Komponente, der die automatische Ausführung von Aufgaben basierend auf einer definierten Planung ermöglicht","pt":"O agendador de tarefas é uma infraestrutura de código aberto que permite que a IA trabalhe de forma autônoma.","ru":"Планировщик задач - это открытое программное обеспечение, которое позволяет ИИ работать автономно.","ar":"مجدول المهام هو بنية مفتوحة المصدر تسمح للوكلاء الذكيين بالعمل بشكل مستقل."},"features":{"en":["Dispatches scheduled tasks via C4 comm-bridge","Writes state to ~/zylos/activity-monitor/claude-status.json for activity monitoring","Handles execution control with idle waiting and priority queueing","Utilizes CLI scripts for task management via ~/zylos/.claude/skills/scheduler/scripts/c","Supports runtime checks for pending tasks and priority-based task execution"],"zh":["支持持久存在和自我维护的 AI 伴侣","通过 C4 通信桥接实现调度任务的分发","支持 Activity Monitor 和 Claude 状态的监控","支持 CLI 脚本的执行","支持任务的优先级和空闲要求的管理"],"ja":["持続的存在と自己維持が可能な AI エージェントのサポート","C4 コミュニケーションブリッジを介したスケジュールタスクの配信","Activity Monitor と Claude 状態のモニタリングのサポート","CLI スクリプトの実行のサポート","タスクの優先度とアイドル要件の管理のサポート"],"ko":["지속적 존재와 자율성을 가진 AI 동반자의 지원","C4 커뮤니케이션 브릿지를 통해 스케줄 태스크의 배포","액티비티 모니터와 클라우드 상태의 모니터링 지원","CLI 스크립트의 실행 지원","태스크의 우선순위와 아이들 요구사항의 관리 지원"],"es":["Ejecución de tareas programadas mediante C4 comm-bridge","Monitoreo de actividad y estado de la tarea","Priorización de tareas basada en la disponibilidad del runtime","Integración con la CLI para una fácil configuración","Compatibilidad con Claude Code para una mayor flexibilidad"],"fr":["Exécution de tâches planifiées via C4 comm-bridge","Surveillance de l''activité et de l''état de la tâche","Priorisation des tâches basée sur la disponibilité du runtime","Intégration avec la CLI pour une configuration facile","Compatibilité avec Claude Code pour une plus grande flexibilité"],"de":["Ausführung geplanter Aufgaben über C4 comm-bridge","Überwachung der Aktivität und des Aufgabenstatus","Priorisierung von Aufgaben basierend auf der Verfügbarkeit des Runtime","Integration mit der CLI für eine einfache Konfiguration","Kompatibilität mit Claude Code für eine größere Flexibilität"],"pt":["Envio de tarefas agendadas via C4 comm-bridge","Integração com Activity Monitor","Suporte a Claude Code","Funcionamento autônomo","Priorização de tarefas","Controle de execução via C4"],"ru":["Отправка запланированных задач через C4 comm-bridge","Интеграция с Activity Monitor","Поддержка Claude Code","Автономная работа","Приоритезация задач","Контроль выполнения через C4"],"ar":["إرسال المهام المجدولة عبر C4 comm-bridge","التكامل مع Activity Monitor","دعم Claude Code","العمل المستقل","تنظيم الأولوية للمهام","مراقبة التنفيذ عبر C4"]},"keywords":{"en":["how to use scheduler for AI agents","scheduler alternative for autonomous task management","scheduler setup guide for C4 comm-bridge","what is scheduler in AI development","scheduler vs cron job for task scheduling","scheduler install for Claude Code infrastructure"],"zh":["AI 伴侣","Scheduler","任务调度","C4 通信桥接","持久存在","自我维护","Activity Monitor","CLI 脚本"],"ja":["AI エージェント","Scheduler","タスクスケジューラー","C4 コミュニケーションブリッジ","持続的存在","自己維持","Activity Monitor","CLI スクリプト"],"ko":["AI 동반자","Scheduler","태스크 스케줄러","C4 커뮤니케이션 브릿지","지속적 존재","자율성","액티비티 모니터","CLI 스크립트"],"es":["programador de tareas de AI","planificador de tareas de inteligencia artificial","autonomía en proyectos de IA","ejecución de tareas programadas","C4 comm-bridge","CLI","Claude Code","desarrollo de aplicaciones de IA"],"fr":["planificateur de tâches d''IA","planificateur de tâches d''intelligence artificielle","autonomie dans les projets d''IA","exécution de tâches planifiées","C4 comm-bridge","CLI","Claude Code","développement d''applications d''IA"],"de":["Aufgabenplaner von AI","Aufgabenplaner von KI","Autonomie in KI-Projekten","Ausführung geplanter Aufgaben","C4 comm-bridge","CLI","Claude Code","Entwicklung von KI-Anwendungen"],"pt":["agendador de tarefas IA","configuração de agendador de tarefas","C4 comm-bridge","Claude Code","Activity Monitor","autonomia de IA","priorização de tarefas","controle de execução"],"ru":["планировщик задач ИИ","настройка планировщика задач","C4 comm-bridge","Claude Code","Activity Monitor","автономность ИИ","приоритезация задач","контроль выполнения"],"ar":["مجدول المهام الذكي","إعداد جدول المهام","C4 comm-bridge","Claude Code","Activity Monitor","الاستقلالية الذكية","تنظيم الأولوية للمهام","مراقبة التنفيذ"]}},"owner":"zylos-ai","repo":"zylos-core","repoPath":"zylos-ai/zylos-core","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.401Z","topics":[],"category":"community","skillMd":{"name":"scheduler","description":"Use when user wants to schedule tasks for future, recurring, or interval execution. Manages one-time, cron, and interval tasks dispatched via C4 comm-bridge.","bodyPreview":"# Task Scheduler (C5)\n\nEnables Claude to work autonomously by dispatching scheduled tasks via C4 comm-bridge.\n\n## How It Works\n\n1. Activity Monitor writes state to `~/zylos/activity-monitor/claude-status.json`\n2. Scheduler checks for pending tasks that are due\n3. If runtime is alive, dispatches task to C4 comm-bridge\n4. C4 handles execution control (idle waiting, priority queueing)\n5. Task sent to Claude based on priority and idle requirements\n\n## CLI\n\n`~/zylos/.claude/skills/scheduler/scripts/c","body":"# Task Scheduler (C5)\n\nEnables Claude to work autonomously by dispatching scheduled tasks via C4 comm-bridge.\n\n## How It Works\n\n1. Activity Monitor writes state to `~/zylos/activity-monitor/claude-status.json`\n2. Scheduler checks for pending tasks that are due\n3. If runtime is alive, dispatches task to C4 comm-bridge\n4. C4 handles execution control (idle waiting, priority queueing)\n5. Task sent to Claude based on priority and idle requirements\n\n## CLI\n\n`~/zylos/.claude/skills/scheduler/scripts/cli.js <command>`\n\n| Command | Description | Reference |\n|---------|-------------|-----------|\n| `add <prompt> [options]` | Add a new task | `references/add.md` |\n| `update <task-id> [options]` | Update an existing task | `references/update.md` |\n| `list` / `next` / `running` / `history` | Query tasks | `references/query.md` |\n| `done` / `remove` / `pause` / `resume` | Task lifecycle | `references/lifecycle.md` |\n\n## Timezone\n\nResolves TZ: `~/zylos/.env` > `process.env.TZ` > `UTC`. Times are parsed and displayed in configured timezone. DB stores UTC. See `references/config.md` for details.\n"},"lastSynced":"2026-03-08T02:06:45.643Z","agentAnalysis":{"suitability":{"en":"Perfect for Autonomous Agents needing task automation and dispatching capabilities via C4 comm-bridge.","zh":"适用于需要通过C4 comm-bridge实现任务自动化和调度能力的自主代理。","ja":"C4 comm-bridgeを介してタスクの自動化とディスパッチング機能を必要とする自律エージェントに最適です。","ko":"C4 comm-bridge를 통해 태스크 자동화 및 디스패치 기능을 필요한 자율 에이전트에 적합합니다.","es":"Perfecto para Agentes Autónomos que necesitan automatización de tareas y capacidades de despacho a través del puente de comunicación C4.","fr":"Parfait pour les Agents Autonomes ayant besoin d''automatisation de tâches et de capacités de dispatch via le pont de communication C4.","de":"Perfekt für autonome Agenten, die eine Automatisierung von Aufgaben und Dispatch-Funktionen über die C4-Kommunikationsbrücke benötigen.","pt":"Perfeito para Agentes Autônomos que precisam de automação de tarefas e capacidades de despacho via C4 comm-bridge.","ru":"Идеально для автономных агентов, которым необходима автоматизация задач и возможности диспетчеризации через C4 comm-bridge.","ar":"مثالي لتقنيات الوكيل المستقلة التي تحتاج إلى توفير تلقائي للمهام وقدرات الإرسال عبر جسر الاتصالات C4."},"recommendation":{"en":"Empowers agents to work autonomously by dispatching scheduled tasks, utilizing activity monitoring and priority queueing via JSON state files and the C4 comm-bridge protocol.","zh":"通过调度任务、利用活动监控和优先队列（通过JSON状态文件和C4 comm-bridge协议）来赋予代理自主工作的能力。","ja":"スケジュールされたタスクの.dispatch、活動監視および優先キュー（JSON状態ファイルおよびC4 comm-bridgeプロトコルを使用）により、エージェントが自律的に動作できるようにします。","ko":"스케줄된 태스크의 디스패치, 활동 모니터링 및 우선순위 큐（JSON 상태 파일 및 C4 comm-bridge 프로토콜을 통해）를 통해 에이전트가 자율적으로 작동할 수 있는 능력을 제공합니다.","es":"Habilita a los agentes a trabajar de forma autónoma mediante el despacho de tareas programadas, utilizando el monitoreo de actividades y la cola de prioridad a través de archivos de estado JSON y el protocolo de puente de comunicación C4.","fr":"Permet aux agents de travailler de manière autonome en dispatchant des tâches planifiées, en utilisant la surveillance d''activité et la file d''attente de priorité via des fichiers d''état JSON et le protocole de pont de communication C4.","de":"Ermächtigt die Agenten, autonom zu arbeiten, indem geplante Aufgaben dispatcht werden, Aktivitäten überwacht und eine Prioritätsliste über JSON-Zustandsdateien und das C4-Kommunikationsbrückenprotokoll verwendet wird.","pt":"Habilita os agentes a trabalhar de forma autônoma, enviando tarefas agendadas, utilizando monitoramento de atividades e fila de prioridade via arquivos de estado JSON e o protocolo C4 comm-bridge.","ru":"Наделяет агентов возможностью работать автономно, отправляя запланированные задачи, используя мониторинг активности и очереди приоритета через файлы состояния JSON и протокол C4 comm-bridge.","ar":"يمنح الوكلاء القدرة على العمل بشكل مستقل من خلال إرسال المهام المجدولة، واستخدام مراقبة النشاطات وترتيب الأ ưu tiên عبر ملفات الحالة JSON وبروتوكول جسر الاتصالات C4."},"useCases":{"en":["Automating recurring tasks","Dispatching priority tasks to Claude","Monitoring agent activity via claude-status.json"],"zh":["自动化重复任务","通过C4 comm-bridge将优先任务分发给Claude","通过claude-status.json监控代理活动"],"ja":["定期実行タスクの自動化","C4 comm-bridgeを介して優先タスクのClaudeへのdispatch","claude-status.jsonによるエージェント活動の監視"],"ko":["반복되는 태스크의 자동화","C4 comm-bridge를 통해 우선 태스크를 Claude에게 디스패치","claude-status.json을 통해 에이전트 활동 모니터링"],"es":["Automatizar tareas recurrentes","Despachar tareas de prioridad a Claude","Monitorear la actividad del agente a través de claude-status.json"],"fr":["Automatiser des tâches récurrentes","Dispatch des tâches de priorité à Claude","Surveiller l''activité de l''agent via claude-status.json"],"de":["Wiederkehrende Aufgaben automatisieren","Prioritätsaufgaben an Claude dispatchen","Überwachung der Agentenaktivität über claude-status.json"],"pt":["Automatizar tarefas recorrentes","Enviar tarefas de prioridade para Claude","Monitorar a atividade do agente via claude-status.json"],"ru":["Автоматизировать повторяющиеся задачи","Отправлять задачи с приоритетом в Claude","Мониторить активность агента через claude-status.json"],"ar":["توفير المهام المتكررة","إرسال المهام ذات الأولوية إلى كلود","مراقبة نشاط الوكيل عبر ملف claude-status.json"]},"limitations":{"en":["Requires C4 comm-bridge infrastructure","Runtime must be alive for task dispatching","Dependent on ~/zylos/activity-monitor/claude-status.json file"],"zh":["需要C4 comm-bridge基础设施","运行时必须存活以实现任务调度","依赖于~/zylos/activity-monitor/claude-status.json文件"],"ja":["C4 comm-bridgeインフラストラクチャの必要性","タスクのdispatchにはランタイムが存続している必要がある","~/zylos/activity-monitor/claude-status.jsonファイルへの依存"],"ko":["C4 comm-bridge 인프라스트럭처가 필요","태스크 디스패치에는 런타임이 유지되어야 함","~/zylos/activity-monitor/claude-status.json 파일에 의존"],"es":["Requiere infraestructura de puente de comunicación C4","El tiempo de ejecución debe estar vivo para el despacho de tareas","Dependiente del archivo ~/zylos/activity-monitor/claude-status.json"],"fr":["Nécessite une infrastructure de pont de communication C4","Le runtime doit être actif pour le dispatch des tâches","Dépendant du fichier ~/zylos/activity-monitor/claude-status.json"],"de":["Benötigt C4-Kommunikationsbrückeninfrastruktur","Laufzeit muss zum Dispatchen von Aufgaben am Leben sein","Abhängig von der Datei ~/zylos/activity-monitor/claude-status.json"],"pt":["Requer infraestrutura C4 comm-bridge","O tempo de execução deve estar ativo para o envio de tarefas","Dependente do arquivo ~/zylos/activity-monitor/claude-status.json"],"ru":["Требует инфраструктуры C4 comm-bridge","Время выполнения должно быть активным для отправки задач","Зависит от файла ~/zylos/activity-monitor/claude-status.json"],"ar":["يتطلب بنية تحتية لجسر الاتصالات C4","يجب أن يكون وقت التشغيل نشطًا لإرسال المهام","يعتمد على ملف ~/zylos/activity-monitor/claude-status.json"]},"version":4},"contentHash":"a377be3231b1212f1afdc367c0dd0bcffc57ed969ef350ceca775da8b4ea576c","qualityScore":23}');
