INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zylos-ai/zylos-core/scheduler', 'scheduler', 'zylos-ai', 'zylos-core', 'community', 'scheduler zylos-ai zylos-core community The scheduler skill enables AI agents to work autonomously by dispatching scheduled tasks. It benefits developers by providing a self-maintaining infrastructure for persistent AI companions. Scheduler 是一种开源基础设施，允许 AI 伴侣持久存在和自我维护。它通过 C4 通信桥接实现调度任务的分发 Scheduler は、AI エージェントが持続的に存在し、自己維持できるオープンソースインフラストラクチャです。C4 コミュニケーションブリッジを介してスケジュールタスクを配信します Scheduler 는 지속적이고 자율적인 AI 동반자를 위한 오픈소스 인프라스트럭처로 C4 커뮤니케이션 브릿지를 통해 스케줄 태스크를 배포 El programador de tareas de AI permite la autonomía en tus proyectos de inteligencia artificial mediante la ejecución de tareas programadas Le planificateur de tâches d''IA permet l''autonomie dans vos projets d''intelligence artificielle en exécutant des tâches planifiées Der Aufgabenplaner von AI ermöglicht Autonomie in Ihren KI-Projekten durch die Ausführung geplanter Aufgaben O agendador de tarefas permite que a IA trabalhe de forma autônoma, enviando tarefas agendadas via C4 comm-bridge. Funciona com Activity Monitor e Claude Code. Планировщик задач позволяет ИИ работать автономно, отправляя запланированные задачи через C4 comm-bridge. Работает с Activity Monitor и Claude Code. مجدول المهام يسمح للوكلاء الذكيين بالعمل بشكل مستقل، بإرسال المهام المجدولة عبر C4 comm-bridge. يعمل مع Activity Monitor و Claude Code. how to use scheduler for AI agents scheduler alternative for autonomous task management scheduler setup guide for C4 comm-bridge what is scheduler in AI development scheduler vs cron job for task scheduling scheduler install for Claude Code infrastructure AI 伴侣 Scheduler 任务调度 C4 通信桥接 持久存在 自我维护 Activity Monitor CLI 脚本 Dispatches scheduled tasks via C4 comm-bridge Writes state to ~/zylos/activity-monitor/claude-status.json for activity monitoring Handles execution control with idle waiting and priority queueing Utilizes CLI scripts for task management via ~/zylos/.claude/skills/scheduler/scripts/c Supports runtime checks for pending tasks and priority-based task execution Scheduler is an open-source infrastructure that enables autonomous AI task management via the C4 comm-bridge, prioritizing execution control and idle waiting');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cyzus/suzent/notebook-skill', 'community', 'cyzus', 'suzent', 'cyzus/suzent', 'notebook-skill', 0, 0, 23, '2026-03-08T01:57:15.403Z', '2026-03-08T02:06:49.343Z', '62a253c8351025e860473a3a70687064175adb6e3686d97e277ca125fcfcb9f3', '{"id":"cyzus/suzent/notebook-skill","name":"notebook-skill","description":{"en":"The notebook-skill enables AI agents to access and edit user notebooks using Obsidian Flavored Markdown, supporting CommonMark, GitHub Flavored Markdown, and LaTeX. This skill benefits developers working with AI agents and markdown files.","zh":"SUZENT笔记本技能允许代理访问用户的笔记本vault，创建和编辑Obsidian Flavored Markdown文档。支持CommonMark、GitHub Flavored Markdown和LaTeX","ja":"SUZENTノートブックスキルは、エージェントがユーザーのノートブックボールトにアクセスし、Obsidian Flavored Markdownドキュメントを作成して編集できるようにします。CommonMark、GitHub Flavored Markdown、LaTeXをサポートしています","ko":"SUZENT 노트북 스킬은 에이전트가 사용자의 노트북 보관소에 액세스하여 Obsidian Flavored Markdown 문서를 생성하고 편집할 수 있도록 합니다. CommonMark, GitHub Flavored Markdown, LaTeX를 지원합니다","es":"El notebook-skill permite a los agentes acceder a vaults de notas y editar Markdown con sabor a Obsidian, soportando CommonMark, GitHub Flavored Markdown y LaTeX","fr":"Le notebook-skill permet aux agents d''accéder aux vaults de notes et d''éditer le Markdown avec saveur Obsidian, en prenant en charge CommonMark, GitHub Flavored Markdown et LaTeX","de":"Das notebook-skill ermöglicht es Agenten, auf Notizvaults zuzugreifen und Obsidian-Markdown zu bearbeiten, mit Unterstützung für CommonMark, GitHub Flavored Markdown und LaTeX","pt":"O notebook-skill permite que agentes de IA acessem e editem arquivos Markdown no Obsidian. Saiba mais sobre como configurá-lo.","ru":"Notebook-skill позволяет ИИ Агентам доступ и редактирование файлов Markdown в Obsidian. Узнайте больше о его настройке.","ar":"يسمح skill الحواشي للعاملات الذكية بالوصول إلى وتحرير ملفات Markdown في Obsidian. تعرف على المزيد حول إعدادته."},"seo":{"title":{"en":"notebook-skill: Obsidian Markdown Editor for AI Agents | ...","zh":"SUZENT笔记本技能配置指南 - Obsidian Flavored Markdown","ja":"SUZENTノートブックスキルセットアップガイド - Obsidian Flavored Markdown","ko":"SUZENT 노트북 스킬 설정 가이드 - Obsidian Flavored Markdown","es":"Guía de configuración de notebook-skill para agentes de i...","fr":"Guide de configuration de notebook-skill pour les agents ...","de":"Einrichtungsleitfaden für notebook-skill in KI-Agenten","pt":"Guia de Configuração do notebook-skill para Ferramentas d...","ru":"Настройка ИИ Агентов с помощью notebook-skill","ar":"دليل إعدادskill الحواشي للعاملات الذكية"},"description":{"en":"Unlock the power of Obsidian Flavored Markdown with notebook-skill. Learn how to access and edit user notebooks with ease. Get started now!","zh":"学习如何使用SUZENT笔记本技能访问和编辑Obsidian Flavored Markdown文档，包括CommonMark、GitHub Flavored Markdown和LaTeX","ja":"SUZENTノートブックスキルを使用してObsidian Flavored Markdownドキュメントにアクセスして編集する方法を学びます。CommonMark、GitHub Flavored Markdown、LaTeXが含まれます","ko":"SUZENT 노트북 스킬을 사용하여 Obsidian Flavored Markdown 문서에 액세스하고 편집하는 방법을 알아보세요. CommonMark, GitHub Flavored Markdown, LaTeX가 포함되어 있습니다","es":"Aprende a configurar notebook-skill para acceder a vaults de notas y editar Markdown con sabor a Obsidian","fr":"Découvrez comment configurer notebook-skill pour accéder aux vaults de notes et éditer le Markdown avec saveur Obsidian","de":"Erfahren Sie, wie Sie notebook-skill konfigurieren, um auf Notizvaults zuzugreifen und Obsidian-Markdown zu bearbeiten","pt":"Aprenda a configurar o notebook-skill para acessar e editar arquivos Markdown no Obsidian com suas ferramentas de IA","ru":"Узнайте, как настроить notebook-skill для доступа и редактирования файлов Markdown в Obsidian с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد skill الحواشي للوصول إلى وتحرير ملفات Markdown في Obsidian باستخدام العاملات الذكية"},"definition":{"en":"notebook-skill is a technical capability that allows AI agents to interact with user notebooks, creating and editing Obsidian Flavored Markdown files.","zh":"SUZENT笔记本技能是一种AI工具，允许代理访问和编辑Obsidian Flavored Markdown文档","ja":"SUZENTノートブックスキルは、エージェントがObsidian Flavored Markdownドキュメントにアクセスして編集できるAIエージェントです","ko":"SUZENT 노트북 스킬은 에이전트가 Obsidian Flavored Markdown 문서에 액세스하고 편집할 수 있는 AI 도구입니다","es":"El notebook-skill es una habilidad que permite a los agentes de inteligencia artificial acceder y editar notas en formato Markdown","fr":"Le notebook-skill est une compétence qui permet aux agents d''intelligence artificielle d''accéder et de modifier des notes au format Markdown","de":"Das notebook-skill ist eine Fähigkeit, die es KI-Agenten ermöglicht, auf Notizen im Markdown-Format zuzugreifen und zu bearbeiten","pt":"O notebook-skill é uma habilidade que permite que agentes de IA acessem e editem arquivos Markdown no Obsidian","ru":"Notebook-skill - это способность, которая позволяет ИИ Агентам доступ и редактирование файлов Markdown в Obsidian","ar":"skill الحواشي هو مهارة تسمح للعاملات الذكية بالوصول إلى وتحرير ملفات Markdown في Obsidian"},"features":{"en":["Accesses user notebook vault via `/mnt/notebook` or `$MOUNT_NOTEBOOK`","Creates and edits Obsidian Flavored Markdown files","Supports CommonMark and GitHub Flavored Markdown syntax","Includes LaTeX support for math expressions","Utilizes Obsidian extensions, such as wikilinks `[[page]]` and callouts"],"zh":["访问用户的笔记本vault","创建和编辑Obsidian Flavored Markdown文档","支持CommonMark、GitHub Flavored Markdown和LaTeX","使用/mnt/notebook或$MOUNT_NOTEBOOK路径访问","支持wikilinks和callouts","Obsidian Flavored Markdown的扩展功能"],"ja":["ユーザーのノートブックボールトにアクセス","Obsidian Flavored Markdownドキュメントを作成して編集","CommonMark、GitHub Flavored Markdown、LaTeXをサポート","/mnt/notebookまたは$MOUNT_NOTEBOOKパスを使用してアクセス","wikilinksとcalloutsをサポート","Obsidian Flavored Markdownの拡張機能"],"ko":["사용자의 노트북 보관소에 액세스","Obsidian Flavored Markdown 문서 생성 및 편집","CommonMark, GitHub Flavored Markdown, LaTeX 지원","/mnt/notebook 또는 $MOUNT_NOTEBOOK 경로 사용","wikilinks와 callouts 지원","Obsidian Flavored Markdown의 확장 기능"],"es":["Acceso a vaults de notas","Edición de Markdown con sabor a Obsidian","Soporte para CommonMark","Soporte para GitHub Flavored Markdown","Soporte para LaTeX para matemáticas","Enlaces wiki y llamadas"],"fr":["Accès aux vaults de notes","Édition de Markdown avec saveur Obsidian","Prise en charge de CommonMark","Prise en charge de GitHub Flavored Markdown","Prise en charge de LaTeX pour les mathématiques","Liens wiki et appels"],"de":["Zugriff auf Notizvaults","Bearbeitung von Markdown mit Obsidian-Geschmack","Unterstützung für CommonMark","Unterstützung für GitHub Flavored Markdown","Unterstützung für LaTeX für Mathematik","Wiki-Links und Aufrufe"],"pt":["Acesso ao vault de notas do usuário via `/mnt/notebook`","Criação e edição de arquivos Markdown no Obsidian","Suporte a CommonMark, GitHub Flavored Markdown e LaTeX","Extensões do Obsidian, incluindo wikilinks e callouts","Integração com ferramentas de IA para automação de tarefas"],"ru":["Доступ к хранилищу заметок пользователя через `/mnt/notebook`","Создание и редактирование файлов Markdown в Obsidian","Поддержка CommonMark, GitHub Flavored Markdown и LaTeX","Расширения Obsidian, включая wikilinks и callouts","Интеграция с ИИ Агентами для автоматизации задач"],"ar":["الوصول إلى مخزن الملاحظات الخاص بالمستخدم عبر `/mnt/notebook`","إنشاء وتحرير ملفات Markdown في Obsidian","دعم CommonMark و GitHub Flavored Markdown و LaTeX","امتدادات Obsidian، بما في ذلك wikilinks و callouts","التكامل مع العاملات الذكية لآلية المهام"]},"keywords":{"en":["how to use notebook-skill","notebook-skill setup guide","Obsidian Flavored Markdown editor","notebook-skill alternative","notebook-skill vs markdown editor","install notebook-skill","notebook-skill documentation","AI agent notebook integration","markdown file editing with notebook-skill"],"zh":["SUZENT笔记本技能","Obsidian Flavored Markdown","AI工具","笔记本vault","CommonMark","GitHub Flavored Markdown","LaTeX","wikilinks","callouts"],"ja":["SUZENTノートブックスキル","Obsidian Flavored Markdown","AIエージェント","ノートブックボールト","CommonMark","GitHub Flavored Markdown","LaTeX","wikilinks","callouts"],"ko":["SUZENT 노트북 스킬","Obsidian Flavored Markdown","AI 도구","노트북 보관소","CommonMark","GitHub Flavored Markdown","LaTeX","wikilinks","callouts"],"es":["notebook-skill","agentes de inteligencia artificial","Markdown","Obsidian","CommonMark","GitHub Flavored Markdown","LaTeX","vaults de notas","edição de notas"],"fr":["notebook-skill","agents d''intelligence artificielle","Markdown","Obsidian","CommonMark","GitHub Flavored Markdown","LaTeX","vaults de notes","édition de notes"],"de":["notebook-skill","KI-Agents","Markdown","Obsidian","CommonMark","GitHub Flavored Markdown","LaTeX","Notizvaults","Notizbearbeitung"],"pt":["notebook-skill","ferramentas de IA","Obsidian","Markdown","CommonMark","GitHub Flavored Markdown","LaTeX","wikilinks","callouts","automatização de tarefas"],"ru":["notebook-skill","ИИ Агенты","Obsidian","Markdown","CommonMark","GitHub Flavored Markdown","LaTeX","wikilinks","callouts","автоматизация задач"],"ar":["skill الحواشي","العاملات الذكية","Obsidian","Markdown","CommonMark","GitHub Flavored Markdown","LaTeX","wikilinks","callouts","آلية المهام"]}},"owner":"cyzus","repo":"suzent","repoPath":"cyzus/suzent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.403Z","topics":[],"category":"community","skillMd":{"name":"notebook-skill","description":"Gain access to the notebook vault.","bodyPreview":"# Notebook Skill\n\nThis skill enables agents to access the user''s notebook vault, create and edit Obsidian Flavored Markdown.\n\n## Access Path\n\n| Mode | Path |\n|------|------|\n| **Sandbox** | `/mnt/notebook` |\n| **Host** | `$MOUNT_NOTEBOOK` or `cd $MOUNT_NOTEBOOK` |\n\n## Obsidian Markdown Flavor\n\n- [CommonMark](https://commonmark.org/)\n- [GitHub Flavored Markdown](https://github.github.com/gfm/)\n- [LaTeX](https://www.latex-project.org/) for math\n- Obsidian extensions: wikilinks `[[page]]`, callouts","body":"# Notebook Skill\n\nThis skill enables agents to access the user''s notebook vault, create and edit Obsidian Flavored Markdown.\n\n## Access Path\n\n| Mode | Path |\n|------|------|\n| **Sandbox** | `/mnt/notebook` |\n| **Host** | `$MOUNT_NOTEBOOK` or `cd $MOUNT_NOTEBOOK` |\n\n## Obsidian Markdown Flavor\n\n- [CommonMark](https://commonmark.org/)\n- [GitHub Flavored Markdown](https://github.github.com/gfm/)\n- [LaTeX](https://www.latex-project.org/) for math\n- Obsidian extensions: wikilinks `[[page]]`, callouts, embeds `![[file]]`\n\n## Notebook Hierarchy & Organization\n\nBefore creating new notes, **always** explore the existing folder structure to understand the notebook''s hierarchy.\n- Use tools (like `GlobTool` or `BashTool`) to list directories and find where your note best fits.\n- **Do not** simply dump new notes into the root directory unless explicitly asked or if it''s a general index.\n- If the appropriate folder does not exist, consider creating it to maintain an organized vault.\n- If you are unsure where a note belongs after reviewing the hierarchy, ask the user for clarification.\n"},"lastSynced":"2026-03-08T02:06:49.343Z","agentAnalysis":{"suitability":{"en":"Ideal for Developer Agents requiring seamless integration with markdown files and Obsidian Flavored Markdown capabilities.","zh":"适用于需要与 markdown 文件和 Obsidian Flavored Markdown 功能进行无缝集成的 Developer Agents。","ja":"Markdown ファイルや Obsidian Flavored Markdown 機能とのシームレスな統合を必要とする Developer Agents に適しています。","ko":"마크다운 파일 및 Obsidian Flavored Markdown 기능과 무결점 통합을 필요로 하는 Developer Agents 에 적합합니다.","es":"Ideal para Agentes de Desarrollador que requieren una integración sin problemas con archivos markdown y capacidades de Obsidian Flavored Markdown.","fr":"Idéal pour les agents de développement nécessitant une intégration transparente avec des fichiers markdown et des fonctionnalités de Obsidian Flavored Markdown.","de":"Ideal für Entwickleragenten, die eine nahtlose Integration mit Markdown-Dateien und Obsidian Flavored Markdown-Funktionen erfordern.","pt":"Ideal para Agentes de Desenvolvedor que exigem integração perfeita com arquivos markdown e capacidades de Obsidian Flavored Markdown.","ru":"Идеально подходит для агентов разработчиков, требующих бесшовной интеграции с файлами markdown и возможностями Obsidian Flavored Markdown.","ar":"مثالي لعميل المطور الذين يتطلبون تكاملًا без مشاكل مع ملفات markdown وقدرات Obsidian Flavored Markdown."},"recommendation":{"en":"Empowers agents to access and edit user notebooks using Obsidian Flavored Markdown, supporting CommonMark, GitHub Flavored Markdown, and LaTeX, enabling advanced content creation and management through wikilinks and callouts.","zh":"赋予代理访问和编辑用户笔记本使用 Obsidian Flavored Markdown 的能力，支持 CommonMark、GitHub Flavored Markdown 和 LaTeX，实现通过 wikilinks 和 callouts 进行高级内容创建和管理。","ja":"Obsidian Flavored Markdown を使用してユーザーのノートブックにアクセスおよび編集できるエージェントを可能にし、CommonMark、GitHub Flavored Markdown、LaTeX をサポートし、wikilinks と callouts を介した高度なコンテンツ作成および管理を可能にします。","ko":"Obsidian Flavored Markdown를 사용하여 사용자의 노트북에 액세스 및 편집할 수 있는 에이전트를 가능하게 하며 CommonMark, GitHub Flavored Markdown, LaTeX를 지원하여 wikilinks 및 callouts를 통한 고급 컨텐츠 생성 및 관리를 가능하게 합니다.","es":"Habilita a los agentes para acceder y editar cuadernos de usuario utilizando Obsidian Flavored Markdown, que admite CommonMark, GitHub Flavored Markdown y LaTeX, lo que permite la creación y gestión de contenido avanzado a través de wikilinks y llamadas.","fr":"Permet aux agents d''accéder et de modifier les cahiers des utilisateurs à l''aide d''Obsidian Flavored Markdown, prenant en charge CommonMark, GitHub Flavored Markdown et LaTeX, permettant ainsi une création et une gestion de contenu avancées via des wikilinks et des appels.","de":"Ermächtigt Agenten, auf Benutzer-Notebooks zuzugreifen und zu bearbeiten, indem sie Obsidian Flavored Markdown verwenden, das CommonMark, GitHub Flavored Markdown und LaTeX unterstützt, und ermöglicht so eine erweiterte Erstellung und Verwaltung von Inhalten durch Wikilinks und Aufrufe.","pt":"Habilita os agentes a acessarem e editarem notebooks de usuário usando Obsidian Flavored Markdown, suportando CommonMark, GitHub Flavored Markdown e LaTeX, permitindo a criação e gerenciamento de conteúdo avançado por meio de wikilinks e callouts.","ru":"Наделяет агентов возможностью доступа и редактирования пользовательских ноутбуков с помощью Obsidian Flavored Markdown, поддерживая CommonMark, GitHub Flavored Markdown и LaTeX, что позволяет создавать и управлять контентом на основе wikilinks и callouts.","ar":"يمنح الوكيل khảية الوصول إلى دفاتر ملاحظات المستخدمين وتحريرها باستخدام Obsidian Flavored Markdown، مع دعم CommonMark و GitHub Flavored Markdown و LaTeX، مما يتيح إنشاء وإدارة محتوى متقدم من خلال wikilinks و callouts."},"useCases":{"en":["Editing Obsidian Flavored Markdown files for knowledge base management","Creating and managing wikilinks for interconnected note systems","Utilizing LaTeX for mathematical expressions in markdown documents"],"zh":["编辑 Obsidian Flavored Markdown 文件以进行知识库管理","创建和管理 wikilinks 以进行相互连接的笔记系统","在 markdown 文档中使用 LaTeX 进行数学表达式"],"ja":["知識ベース管理のために Obsidian Flavored Markdown ファイルを編集する","相互接続ノートシステムのための wikilinks を作成および管理する","Markdown ドキュメントで LaTeX を使用して数学表現を行う"],"ko":["지식 베이스 관리를 위해 Obsidian Flavored Markdown 파일을 편집합니다.","상호 연결 노트 시스템을 위한 wikilinks를 생성 및 관리합니다.","마크다운 문서에서 LaTeX를 사용하여 수학적 표현을 합니다."],"es":["Edición de archivos Obsidian Flavored Markdown para la gestión de la base de conocimientos","Creación y gestión de wikilinks para sistemas de notas interconectados","Uso de LaTeX para expresiones matemáticas en documentos markdown"],"fr":["Édition de fichiers Obsidian Flavored Markdown pour la gestion de la base de connaissances","Création et gestion de wikilinks pour des systèmes de notes interconnectés","Utilisation de LaTeX pour des expressions mathématiques dans des documents markdown"],"de":["Bearbeitung von Obsidian Flavored Markdown-Dateien für das Wissensmanagement","Erstellung und Verwaltung von Wikilinks für vernetzte Notizsysteme","Verwendung von LaTeX für mathematische Ausdrücke in Markdown-Dokumenten"],"pt":["Edição de arquivos Obsidian Flavored Markdown para gerenciamento de base de conhecimento","Criação e gerenciamento de wikilinks para sistemas de notas interconectados","Utilização de LaTeX para expressões matemáticas em documentos markdown"],"ru":["Редактирование файлов Obsidian Flavored Markdown для управления базой знаний","Создание и управление wikilinks для взаимосвязанных систем заметок","Использование LaTeX для математических выражений в документах markdown"],"ar":["تحرير ملفات Obsidian Flavored Markdown لإدارة قاعدة المعرفة","إنشاء وإدارة wikilinks لنظم الملاحظات المتواصل","استخدام LaTeX للتعبيرات الرياضية في مستندات markdown"]},"limitations":{"en":["Requires access to the user''s notebook vault","Limited to Obsidian Flavored Markdown and its supported extensions","Dependent on the availability of the $MOUNT_NOTEBOOK environment variable for host mode access"],"zh":["需要访问用户的笔记本保险库","仅限 Obsidian Flavored Markdown 及其支持的扩展","依赖于 $MOUNT_NOTEBOOK 环境变量的可用性以进行主机模式访问"],"ja":["ユーザーのノートブック・ボールトへのアクセスが必要","Obsidian Flavored Markdown とそのサポートされている拡張機能のみ","ホストモードアクセスを行うために $MOUNT_NOTEBOOK 環境変数の可用性に依存している"],"ko":["사용자의 노트북 보관소에 액세스해야 합니다.","Obsidian Flavored Markdown 및 해당 지원 확장 기능만 해당됩니다.","호스트 모드 액세스를 위해 $MOUNT_NOTEBOOK 환경 변수의 가용성에 종속됩니다."],"es":["Requiere acceso al vault de cuadernos del usuario","Limitado a Obsidian Flavored Markdown y sus extensiones admitidas","Dependiente de la disponibilidad de la variable de entorno $MOUNT_NOTEBOOK para el acceso en modo host"],"fr":["Nécessite un accès au coffre de cahiers de l''utilisateur","Limité à Obsidian Flavored Markdown et ses extensions prises en charge","Dépend de la disponibilité de la variable d''environnement $MOUNT_NOTEBOOK pour l''accès en mode hôte"],"de":["Benötigt Zugriff auf das Notebook-Vault des Benutzers","Begrenzt auf Obsidian Flavored Markdown und seine unterstützten Erweiterungen","Abhängig von der Verfügbarkeit der Umgebungsvariable $MOUNT_NOTEBOOK für den Host-Modus-Zugriff"],"pt":["Exige acesso ao cofre de notebooks do usuário","Limitado a Obsidian Flavored Markdown e suas extensões suportadas","Depende da disponibilidade da variável de ambiente $MOUNT_NOTEBOOK para acesso no modo host"],"ru":["Требует доступа к хранилищу ноутбуков пользователя","Ограничен Obsidian Flavored Markdown и поддерживаемыми расширениями","Зависит от наличия переменной среды $MOUNT_NOTEBOOK для доступа в режиме хоста"],"ar":["يتطلب الوصول إلى خزنة دفاتر ملاحظات المستخدم","محدود ب Obsidian Flavored Markdown والمدمجة المدعومة","يعتمد على توافر متغير البيئة $MOUNT_NOTEBOOK للوصول إلى وضع المضيف"]},"version":4},"contentHash":"62a253c8351025e860473a3a70687064175adb6e3686d97e277ca125fcfcb9f3","qualityScore":23}');
