INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cyzus/suzent/notebook-skill', 'notebook-skill', 'cyzus', 'suzent', 'community', 'notebook-skill cyzus suzent community The notebook-skill enables AI agents to access and edit user notebooks using Obsidian Flavored Markdown, supporting CommonMark, GitHub Flavored Markdown, and LaTeX. This skill benefits developers working with AI agents and markdown files. SUZENT笔记本技能允许代理访问用户的笔记本vault，创建和编辑Obsidian Flavored Markdown文档。支持CommonMark、GitHub Flavored Markdown和LaTeX SUZENTノートブックスキルは、エージェントがユーザーのノートブックボールトにアクセスし、Obsidian Flavored Markdownドキュメントを作成して編集できるようにします。CommonMark、GitHub Flavored Markdown、LaTeXをサポートしています SUZENT 노트북 스킬은 에이전트가 사용자의 노트북 보관소에 액세스하여 Obsidian Flavored Markdown 문서를 생성하고 편집할 수 있도록 합니다. CommonMark, GitHub Flavored Markdown, LaTeX를 지원합니다 El notebook-skill permite a los agentes acceder a vaults de notas y editar Markdown con sabor a Obsidian, soportando CommonMark, GitHub Flavored Markdown y LaTeX Le notebook-skill permet aux agents d''accéder aux vaults de notes et d''éditer le Markdown avec saveur Obsidian, en prenant en charge CommonMark, GitHub Flavored Markdown et LaTeX Das notebook-skill ermöglicht es Agenten, auf Notizvaults zuzugreifen und Obsidian-Markdown zu bearbeiten, mit Unterstützung für CommonMark, GitHub Flavored Markdown und LaTeX O notebook-skill permite que agentes de IA acessem e editem arquivos Markdown no Obsidian. Saiba mais sobre como configurá-lo. Notebook-skill позволяет ИИ Агентам доступ и редактирование файлов Markdown в Obsidian. Узнайте больше о его настройке. يسمح skill الحواشي للعاملات الذكية بالوصول إلى وتحرير ملفات Markdown في Obsidian. تعرف على المزيد حول إعدادته. how to use notebook-skill notebook-skill setup guide Obsidian Flavored Markdown editor notebook-skill alternative notebook-skill vs markdown editor install notebook-skill notebook-skill documentation AI agent notebook integration markdown file editing with notebook-skill SUZENT笔记本技能 Obsidian Flavored Markdown AI工具 笔记本vault CommonMark GitHub Flavored Markdown LaTeX wikilinks callouts Accesses user notebook vault via `/mnt/notebook` or `$MOUNT_NOTEBOOK` Creates and edits Obsidian Flavored Markdown files Supports CommonMark and GitHub Flavored Markdown syntax Includes LaTeX support for math expressions Utilizes Obsidian extensions, such as wikilinks `[[page]]` and callouts notebook-skill is a technical capability that allows AI agents to interact with user notebooks, creating and editing Obsidian Flavored Markdown files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('evanfang0054/cc-system-creator-scripts/doc-learner', 'community', 'evanfang0054', 'cc-system-creator-scripts', 'evanfang0054/cc-system-creator-scripts', 'doc-learner', 0, 0, 23, '2026-03-08T01:57:15.409Z', '2026-03-08T02:06:58.486Z', '88f83f870c79b2a98a1216b872815788072950b1e89c5b3b957bc92d187f4737', '{"id":"evanfang0054/cc-system-creator-scripts/doc-learner","name":"doc-learner","description":{"en":"The doc-learner skill provides a systematic approach to document analysis and content imitation, enabling users to create high-quality content based on excellent examples. It benefits developers and AI practitioners seeking to automate document processing tasks.","zh":"doc-learner技能提供文档学习和内容模仿解决方案，支持结构分析、风格分析和模板化生成","ja":"doc-learner AIエージェントは文書学習とコンテンツ模倣を提供し、構造分析、文体分析、テンプレート生成をサポート","ko":"doc-learner는 문서 학습 및 콘텐츠 모방을 위한 기술로 구조 분석, 스타일 분석, 템플릿 생성을 지원","es":"doc-learner es un sistema de aprendizaje de documentos que analiza estructuras, estilos y patrones de expresión para generar contenido de alta calidad","fr":"doc-learner est un système d''apprentissage de documents qui analyse les structures, les styles et les modèles d''expression pour générer du contenu de haute qualité","de":"doc-learner ist ein Dokumentenlernsystem, das Strukturen, Stile und Ausdrucksmuster analysiert, um hochwertigen Inhalt zu generieren","pt":"O doc-learner é uma habilidade de análise de documentos avançada que utiliza técnicas de aprendizado de máquina para criar conteúdo de alta qualidade","ru":"doc-learner - это навык расширенного анализа документов, который использует методы машинного обучения для создания высококачественного контента для ИИ Агентов","ar":"doc-learner هو مهارة تحليل مستندات متقدمة تستخدم تقنيات التعلم الآلي لإنشاء محتوى عالي الجودة للأدوات الذكية"},"seo":{"title":{"en":"doc-learner: Document Analysis and Imitation Skill for AI...","zh":"doc-learner 文档学习技能集成指南","ja":"doc-learner AIエージェントの文書学習機能設定","ko":"doc-learner 문서 학습 및 콘텐츠 모방 기술 가이드","es":"Guía de configuración de doc-learner para análisis de doc...","fr":"Guide d''installation de doc-learner pour l''analyse de doc...","de":"Einrichtungsanleitung für doc-learner zur Dokumentenanalyse","pt":"Guia de Configuração do doc-learner: Análise de Documento...","ru":"Настройка doc-learner: Расширенный анализ документов для ...","ar":"دليل إعداد doc-learner: تحليل مستندات متقدم للأدوات الذكية"},"description":{"en":"Unlock advanced document learning capabilities with doc-learner. Discover how to analyze and imitate document structures, styles, and content patterns. Get s...","zh":"了解doc-learner技能的技术优势，实现文档结构分析、写作风格模仿和内容生成","ja":"doc-learner AIエージェントを使用して、文書の構造解析、文体模倣、コンテンツ生成を実現","ko":"doc-learner 기술을 활용하여 문서 구조 분석, 작성 스타일 모방, 콘텐츠 생성을 자동화","es":"Aprende a configurar doc-learner para analizar documentos y crear contenido de alta calidad con esta guía paso a paso","fr":"Découvrez comment configurer doc-learner pour analyser des documents et créer du contenu de haute qualité avec ce guide étape par étape","de":"Erfahren Sie, wie Sie doc-learner konfigurieren, um Dokumente zu analysieren und hochwertigen Inhalt zu erstellen, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o doc-learner para análise de documentos avançada e criação de conteúdo de alta qualidade com técnicas de aprendizado de máquina","ru":"Узнайте, как настроить doc-learner для расширенного анализа документов и создания высококачественного контента с помощью методов машинного обучения для ИИ Аг...","ar":"تعرف على كيفية إعداد doc-learner لتحليل المستندات المتقدم وإنشاء محتوى عالي الجودة باستخدام تقنيات التعلم الآلي للأدوات الذكية"},"definition":{"en":"doc-learner is a specialized skill for analyzing and imitating document structures, writing styles, and expression patterns to generate high-quality content.","zh":"doc-learner是一种文档学习和内容模仿技能，用于分析文档结构和写作风格","ja":"doc-learnerは文書学習とコンテンツ模倣を実現するAIエージェントのスキル","ko":"doc-learner는 문서 구조와 작성 스타일을 분석하여 콘텐츠를 자동 생성하는 기술","es":"doc-learner es un sistema de aprendizaje de documentos que utiliza técnicas de análisis de estructuras y estilos para generar contenido","fr":"doc-learner est un système d''apprentissage de documents qui utilise des techniques d''analyse de structures et de styles pour générer du contenu","de":"doc-learner ist ein Dokumentenlernsystem, das Techniken zur Analyse von Strukturen und Stilen verwendet, um Inhalt zu generieren","pt":"O doc-learner é uma habilidade de análise de documentos que utiliza aprendizado de máquina para criar conteúdo","ru":"doc-learner - это навык анализа документов, который использует машинное обучение для создания контента","ar":"doc-learner هو مهارة تحليل مستندات تستخدم التعلم الآلي لإنشاء محتوى"},"features":{"en":["Supports multiple document types, including prompts, technical documentation, API documentation, and user manuals","Performs deep document analysis, including structure, style, and content pattern examination","Identifies learning objectives, such as mimicking structure, style, format, or content patterns","Generates content based on analyzed documents, including prompts, documents, and templates","Analyzes document organization, information architecture, and modularization"],"zh":["支持多种文档类型的结构分析","实现写作风格和表达模式的模仿","提供模板化生成和内容重用功能","支持用户定义的学习目标和内容模式","实现文档的深度分析和自动化处理"],"ja":["複数の文書タイプの構造解析をサポート","文体と表現パターンの模倣を実現","テンプレート生成とコンテンツの再利用機能を提供","ユーザー定義の学習目標とコンテンツパターンをサポート","文書の深度解析と自動化処理を実現"],"ko":["다양한 문서 형식의 구조 분석 지원","작성 스타일과 표현 패턴의 모방 기능","템플릿 생성과 콘텐츠 재사용 기능 제공","사용자 정의 학습 목표와 콘텐츠 패턴 지원","문서의 심층 분석과 자동화 처리 기능"],"es":["Análisis de estructuras de documentos","Análisis de estilos de escritura","Generación de contenido basado en patrones de expresión","Compatibilidad con diferentes tipos de documentos (técnico, API, manual de usuario, etc.)","Capacidad para identificar y emular patrones de contenido","Integración con flujos de trabajo automatizados"],"fr":["Analyse de structures de documents","Analyse de styles d''écriture","Génération de contenu basé sur des modèles d''expression","Compatibilité avec différents types de documents (technique, API, manuel utilisateur, etc.)","Capacité à identifier et à imiter des modèles de contenu","Intégration avec des flux de travail automatisés"],"de":["Analyse von Dokumentenstrukturen","Analyse von Schreibstilen","Generierung von Inhalt basierend auf Ausdrucksmustern","Kompatibilität mit verschiedenen Dokumententypen (technisch, API, Benutzerhandbuch usw.)","Fähigkeit, Inhaltsmuster zu identifizieren und zu imitieren","Integration mit automatisierten Arbeitsabläufen"],"pt":["Análise de estrutura de documentos","Análise de estilo de escrita","Suporte a vários tipos de documentos","Criação de conteúdo de alta qualidade","Utilização de técnicas de aprendizado de máquina"],"ru":["Анализ структуры документов","Анализ стиля письма","Поддержка нескольких типов документов","Создание высококачественного контента","Использование методов машинного обучения"],"ar":["تحليل هيكل المستندات","تحليل أسلوب الكتابة","دعم أنواع متعددة من المستندات","إنشاء محتوى عالي الجودة","استخدام تقنيات التعلم الآلي"]},"keywords":{"en":["how to use doc-learner","doc-learner alternative","document analysis AI","content imitation techniques","doc-learner setup guide","doc-learner vs competitors","document learning algorithms","AI document processing","doc-learner installation"],"zh":["doc-learner","文档学习","内容模仿","结构分析","写作风格","模板化生成","AI工具","文档自动化"],"ja":["doc-learner","AIエージェント","文書学習","コンテンツ模倣","構造解析","文体","テンプレート生成","自動化"],"ko":["doc-learner","문서 학습","콘텐츠 모방","구조 분석","작성 스타일","템플릿 생성","AI工具","문서 자동화"],"es":["doc-learner","análisis de documentos","generación de contenido","aprendizaje de documentos","agentes de IA","herramientas de IA","desarrollo de contenido","automatización de flujos de trabajo","análisis de estructuras","estilos de escritura"],"fr":["doc-learner","analyse de documents","génération de contenu","apprentissage de documents","agents d''IA","outils d''IA","développement de contenu","automatisation de flux de travail","analyse de structures","styles d''écriture"],"de":["doc-learner","Dokumentenanalyse","Inhaltsgenerierung","Dokumentenlernsystem","IA-Agenten","IA-Tools","Inhaltsentwicklung","Automatisierung von Arbeitsabläufen","Strukturanalyse","Schreibstile"],"pt":["doc-learner","análise de documentos","aprendizado de máquina","criação de conteúdo","técnicas de aprendizado de máquina","análise de estrutura de documentos","análise de estilo de escrita"],"ru":["doc-learner","анализ документов","машинное обучение","создание контента","методы машинного обучения","анализ структуры документов","анализ стиля письма","ИИ Агенты"],"ar":["doc-learner","تحليل المستندات","التعلم الآلي","إنشاء المحتوى","تقنيات التعلم الآلي","تحليل هيكل المستندات","تحليل أسلوب الكتابة","الأدوات الذكية"]}},"owner":"evanfang0054","repo":"cc-system-creator-scripts","repoPath":"evanfang0054/cc-system-creator-scripts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.409Z","topics":[],"category":"community","skillMd":{"name":"doc-learner","description":"智能文档学习和内容模仿技能。当需要：(1) 分析和学习优秀文档的结构、风格和写作模式，(2) 从文档中提炼关键要素和模板，(3) 基于学习内容生成模仿材料，或 (4) 创建新的提示词或技术文档时使用此技能。支持提示词工程、技术文档、API文档、用户手册等多种文档类型的学习和模仿。","bodyPreview":"# 文档学习与内容模仿技能\n\n## 概述\n\n本技能提供了一套系统化的文档学习和内容模仿方法，能够深入分析各类文档的结构特征、写作风格和表达模式，帮助用户基于优秀范例创建高质量的内容。\n\n## 工作流程\n\n### 阶段 1：文档接收与分类\n\n当用户请求学习文档时，首先识别文档类型和目标：\n\n**支持的文档类型：**\n- 提示词（Prompt Engineering）\n- 技术文档（Technical Documentation）\n- API 文档\n- 用户手册\n- 产品说明\n- 其他结构化文档\n\n**确认学习目标：**\n- 用户想要模仿什么？（结构、风格、格式、内容模式）\n- 最终要生成什么内容？（提示词、文档、模板）\n\n### 阶段 2：深度文档分析\n\n对提供的文档进行多维度分析：\n\n#### 2.1 结构分析\n- 文档组织方式（层次结构、章节划分）\n- 信息架构（逻辑流程、内容组块）\n- 模块化程度（可重用组件、模板化元素）\n\n#### 2.2 风格分析\n- 语言风格（正式/非正式、技术/通俗）\n- 语气和表达方式（权威、友好、简洁等）\n- 术语使用和命名规范\n\n#### 2.3 模","body":"# 文档学习与内容模仿技能\n\n## 概述\n\n本技能提供了一套系统化的文档学习和内容模仿方法，能够深入分析各类文档的结构特征、写作风格和表达模式，帮助用户基于优秀范例创建高质量的内容。\n\n## 工作流程\n\n### 阶段 1：文档接收与分类\n\n当用户请求学习文档时，首先识别文档类型和目标：\n\n**支持的文档类型：**\n- 提示词（Prompt Engineering）\n- 技术文档（Technical Documentation）\n- API 文档\n- 用户手册\n- 产品说明\n- 其他结构化文档\n\n**确认学习目标：**\n- 用户想要模仿什么？（结构、风格、格式、内容模式）\n- 最终要生成什么内容？（提示词、文档、模板）\n\n### 阶段 2：深度文档分析\n\n对提供的文档进行多维度分析：\n\n#### 2.1 结构分析\n- 文档组织方式（层次结构、章节划分）\n- 信息架构（逻辑流程、内容组块）\n- 模块化程度（可重用组件、模板化元素）\n\n#### 2.2 风格分析\n- 语言风格（正式/非正式、技术/通俗）\n- 语气和表达方式（权威、友好、简洁等）\n- 术语使用和命名规范\n\n#### 2.3 模式识别\n- 句式模式和表达习惯\n- 常用句型和过渡词\n- 标准化表达和固定搭配\n\n#### 2.4 要素提取\n- 关键信息点\n- 核心概念和术语\n- 必需组成部分\n\n### 阶段 3：模式提炼与模板创建\n\n基于分析结果创建可重用的模式和模板：\n\n#### 3.1 结构模板\n- 文档骨架\n- 章节组织框架\n- 标准化结构\n\n#### 3.2 写作模式\n- 句式模板库\n- 表达模式集合\n- 风格指南\n\n#### 3.3 关键要素清单\n- 必备内容检查表\n- 核心要素列表\n- 质量标准\n\n### 阶段 4：内容生成与优化\n\n使用提炼的模式生成新内容：\n\n#### 4.1 内容生成\n- 根据用户需求应用学习到的模式\n- 填充结构模板\n- 应用写作风格\n\n#### 4.2 质量验证\n- 检查是否遵循学习到的模式\n- 验证结构完整性\n- 确保风格一致性\n\n#### 4.3 迭代优化\n- 根据用户反馈调整\n- 持续改进模板库\n\n## 核心能力\n\n### 1. 文档分析引擎\n\n系统能够从多个维度分析文档：\n\n**结构维度：**\n- 识别文档类型和体裁\n- 提取组织架构和层次关系\n- 分析信息流和逻辑顺序\n\n**风格维度：**\n- 分析语言特征（词汇选择、句式结构）\n- 识别语气和表达习惯\n- 提取风格标记和特征\n\n**模式维度：**\n- 发现重复出现的表达模式\n- 提取可重用的句式和段落\n- 识别标准化表达\n\n### 2. 智能模板提取\n\n自动从文档中提炼可重用元素：\n\n**结构模板：**\n- 文档框架\n- 章节模板\n- 段落结构\n\n**内容模式：**\n- 句式库\n- 表达模式\n- 术语集合\n\n**风格指南：**\n- 语言风格规范\n- 表达习惯总结\n- 最佳实践集合\n\n### 3. 内容生成支持\n\n基于学习结果辅助创作：\n\n**模板化生成：**\n- 填空式内容创建\n- 结构化内容组装\n- 模块化内容复用\n\n**风格迁移：**\n- 应用学习到的写作风格\n- 模仿表达方式\n- 保持风格一致性\n\n**质量保证：**\n- 模式匹配验证\n- 结构完整性检查\n- 风格一致性评估\n\n## 使用场景示例\n\n### 场景 1：学习优秀提示词\n\n**用户请求：** \"我想学习这些优秀提示词的写作方法，然后创建自己的版本\"\n\n**工作流程：**\n1. 分析提供的提示词样本\n2. 识别提示词结构（角色设定、任务描述、约束条件、输出格式等）\n3. 提炼写作模式和技巧\n4. 创建提示词模板\n5. 帮助用户基于模板生成新提示词\n\n### 场景 2：模仿技术文档风格\n\n**用户请求：** \"分析这份技术文档的写作风格，帮我写出类似风格的新文档\"\n\n**工作流程：**\n1. 分析技术文档的结构和风格\n2. 识别文档组织方式\n3. 提炼术语使用规范\n4. 创建风格指南和模板\n5. 指导用户生成新文档\n\n### 场景 3：文档质量提升\n\n**用户请求：** \"根据优秀文档范例，改进我的文档质量\"\n\n**工作流程：**\n1. 对比分析优秀范例和用户文档\n2. 识别差距和改进点\n3. 应用优秀范例的模式\n4. 优化用户文档\n5. 提供改进建议\n\n## 参考资料\n\n### references/prompt_analysis_guide.md\n提示词分析框架和方法论，包含：\n- 提示词结构分析模型\n- 常见提示词模式分类\n- 提示词质量评估标准\n- 最佳实践案例\n\n**何时使用：** 当需要深度分析提示词结构或学习提示词工程技巧时。\n\n### references/tech_doc_patterns.md\n技术文档写作模式和模板，包含：\n- 技术文档标准结构\n- 常用表达模式和句式\n- 术语使用规范\n- 格式和样式指南\n\n**何时使用：** 当需要分析或生成技术文档时。\n\n### references/style_analysis_framework.md\n文档风格分析框架，包含：\n- 风格维度分析模型\n- 语言特征识别方法\n- 风格迁移技巧\n- 一致性保持策略\n\n**何时使用：** 当需要深度分析文档风格或进行风格模仿时。\n\n## 资产文件\n\n### assets/prompts/\n提示词模板集合，包含各种类型的提示词模板：\n- 角色设定模板\n- 任务描述模板\n- 约束条件模板\n- 输出格式模板\n\n### assets/doc_templates/\n文档模板集合，包含：\n- 技术文档模板\n- API 文档模板\n- 用户手册模板\n- 其他文档类型模板\n\n## 最佳实践\n\n### 1. 多样本学习\n- 尽量收集多个同类型文档进行学习\n- 识别共性模式和个性特征\n- 提炼最稳定、最有效的模式\n\n### 2. 模式验证\n- 在实际应用中验证学习到的模式\n- 根据效果调整和优化\n- 持续改进模板库\n\n### 3. 灵活应用\n- 不要机械套用模板\n- 根据具体需求灵活调整\n- 保持创造性思维\n\n### 4. 质量优先\n- 注重内容质量而非形式模仿\n- 确保生成的内容有价值\n- 避免为了模仿而模仿\n\n## 常见问题\n\n**Q: 学习多少个文档样本比较合适？**\nA: 建议 3-10 个高质量样本。太少可能导致模式不准确，太多可能增加分析复杂度。\n\n**Q: 如何处理不同风格的文档？**\nA: 可以分别学习不同风格，创建多个风格模板，根据需要选择应用。\n\n**Q: 生成的内容是否完全模仿原文？**\nA: 不是。本技能帮助学习和应用优秀文档的模式和结构，但内容本身应该是原创的。\n\n**Q: 能否学习非中文文档？**\nA: 可以。本技能支持多语言文档的学习和模仿。\n"},"lastSynced":"2026-03-08T02:06:58.486Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude Code and AutoGPT needing advanced document analysis and content imitation capabilities.","zh":"适用于Claude Code和AutoGPT等需要高级文档分析和内容模拟能力的AI代理。","ja":"Claude CodeやAutoGPTなどの高度な文書分析およびコンテンツの模倣機能を必要とするAIエージェントに適しています。","ko":"Claude Code와 AutoGPT 같은 고급 문서 분석 및 콘텐츠 모방 기능이 필요한 AI 에이전트에 적합합니다.","es":"Ideal para agentes de IA como Claude Code y AutoGPT que necesitan capacidades avanzadas de análisis de documentos y simulación de contenido.","fr":"Idéal pour les agents d''IA comme Claude Code et AutoGPT nécessitant des capacités avancées d''analyse de documents et d''imitation de contenu.","de":"Ideal für KI-Agents wie Claude Code und AutoGPT, die erweiterte Dokumentenanalyse- und Inhaltssimulationsfunktionen benötigen.","pt":"Ideal para agentes de IA como Claude Code e AutoGPT que necessitam de capacidades avançadas de análise de documentos e imitação de conteúdo.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и AutoGPT, которые требуют продвинутых возможностей анализа документов и имитации контента.","ar":"مثالي لعمليات إيه آي مثل Claude Code و AutoGPT التي تحتاج إلى قدرات متقدمة لتحليل الوثائق وتقليد المحتوى."},"recommendation":{"en":"Empowers agents to generate high-quality content based on excellent examples by analyzing document structures, writing styles, and expression patterns, utilizing techniques such as prompt engineering and technical documentation analysis, and supporting various document types including API documentation and user manuals.","zh":"使代理能够通过分析文档结构、写作风格和表达模式，利用诸如提示工程和技术文档分析等技术，生成基于优秀示例的高质量内容，并支持包括API文档和用户手册在内的各种文档类型。","ja":"エージェントが文書構造、文章スタイル、表現パターンを分析し、プロンプトエンジニアリングや技術文書分析などの手法を使用して、優れた例に基づいた高品質コンテンツを生成し、APIドキュメントやユーザーマニュアルを含むさまざまな文書タイプをサポートします。","ko":"에이전트가 문서 구조, 글쓰기 스타일 및 표현 패턴을 분석하고 프롬프트 엔지니어링 및 기술 문서 분석 등을 통해 우수한 예시에 기반한 고품질 콘텐츠를 생성하며 API 문서 및 사용자 매뉴얼을 포함한 다양한 문서 형식을 지원합니다.","es":"Permite a los agentes generar contenido de alta calidad basado en ejemplos excelentes analizando estructuras de documentos, estilos de escritura y patrones de expresión, utilizando técnicas como la ingeniería de solicitudes y el análisis de documentación técnica, y admitiendo varios tipos de documentos, incluida la documentación de API y manuales de usuario.","fr":"Permet aux agents de générer du contenu de haute qualité basé sur d''excellents exemples en analysant les structures de documents, les styles d''écriture et les modèles d''expression, en utilisant des techniques telles que l''ingénierie de requêtes et l''analyse de la documentation technique, et en prenant en charge divers types de documents, notamment la documentation API et les manuels d''utilisation.","de":"Ermöglicht es den Agents, hochwertigen Inhalt auf der Grundlage hervorragender Beispiele zu erzeugen, indem sie Dokumentenstrukturen, Schreibstile und Ausdrucksmuster analysieren, Techniken wie Prompt-Engineering und technische Dokumentenanalyse verwenden und verschiedene Dokumententypen, einschließlich API-Dokumentation und Benutzerhandbücher, unterstützen.","pt":"Habilita os agentes a gerar conteúdo de alta qualidade com base em excelentes exemplos, analisando estruturas de documentos, estilos de escrita e padrões de expressão, utilizando técnicas como engenharia de prompts e análise de documentação técnica, e suportando vários tipos de documentos, incluindo documentação de API e manuais do usuário.","ru":"Наделяет агентов возможностью генерировать контент высокого качества на основе отличных примеров, анализируя структуры документов, стили письма и закономерности выражения, используя такие методы, как инженерия запросов и анализ технической документации, и поддерживая различные типы документов, включая документацию API и руководства пользователя.","ar":"تمكّن العميل من توليد محتوى عالي الجودة بالاعتماد على أمثلة ممتازة من خلال تحليل هياكل الوثائق وأساليب الكتابة وأنماط التعبير، باستخدام تقنيات مثل هندسة الدفعات وتحليل الوثائق الفنية، ودعم أنواع متعددة من الوثائق بما في ذلك توثيق واجهة برمجة التطبيقات ودلائل المستخدم."},"useCases":{"en":["Automating technical documentation generation","Imitating writing styles for content creation","Analyzing document structures for information extraction"],"zh":["自动化技术文档生成","模拟写作风格以创建内容","分析文档结构以提取信息"],"ja":["技術文書の自動生成","コンテンツ作成のための文章スタイルの模倣","情報抽出のための文書構造の分析"],"ko":["기술 문서 자동 생성","콘텐츠 생성을 위한 글쓰기 스타일 모방","정보 추출을 위한 문서 구조 분석"],"es":["Automatización de la generación de documentación técnica","Imitación de estilos de escritura para la creación de contenido","Análisis de estructuras de documentos para la extracción de información"],"fr":["Automatisation de la génération de documentation technique","Imitation de styles d''écriture pour la création de contenu","Analyse de structures de documents pour l''extraction d''informations"],"de":["Automatisierung der Generierung von technischer Dokumentation","Imitation von Schreibstilen für die Inhaltserschaffung","Analyse von Dokumentenstrukturen für die Informationsextraktion"],"pt":["Automatizar a geração de documentação técnica","Imitar estilos de escrita para criação de conteúdo","Analizar estruturas de documentos para extração de informações"],"ru":["Автоматизировать генерацию технической документации","Имитировать стили письма для создания контента","Анализировать структуры документов для извлечения информации"],"ar":["أتمتة توليد الوثائق الفنية","تقليد أساليب الكتابة لإنشاء المحتوى","تحليل هياكل الوثائق لاستخراج المعلومات"]},"limitations":{"en":["Requires comprehensive document samples for analysis","Limited to supported document types","Dependent on user-defined learning objectives"],"zh":["需要全面文档样本进行分析","仅限支持的文档类型","依赖于用户定义的学习目标"],"ja":["分析のための包括的な文書サンプルが必要","サポートされている文書タイプのみ","ユーザー定義の学習目標に依存"],"ko":["분석을 위한 포괄적인 문서 샘플이 필요합니다","지원되는 문서 유형만 해당","사용자 정의 학습 목표에 의존"],"es":["Requiere muestras de documentos exhaustivas para el análisis","Limitado a los tipos de documentos admitidos","Dependiente de los objetivos de aprendizaje definidos por el usuario"],"fr":["Nécessite des échantillons de documents exhaustifs pour l''analyse","Limité aux types de documents pris en charge","Dépendant des objectifs d''apprentissage définis par l''utilisateur"],"de":["Benötigt umfassende Dokumentenbeispiele für die Analyse","Begrenzt auf unterstützte Dokumententypen","Abhängig von den vom Benutzer definierten Lernzielen"],"pt":["Exige amostras de documentos abrangentes para análise","Limitado a tipos de documentos suportados","Dependente de objetivos de aprendizado definidos pelo usuário"],"ru":["Требует всесторонних образцов документов для анализа","Ограничен поддерживаемыми типами документов","Зависит от целей обучения, определенных пользователем"],"ar":["يتطلب عينات وثائق شاملة للتحليل","محدود بالأنواع المدعومة من الوثائق","يعتمد على أهداف التعلم المحددة من قبل المستخدم"]},"version":4},"contentHash":"88f83f870c79b2a98a1216b872815788072950b1e89c5b3b957bc92d187f4737","qualityScore":23}');
