INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('khaledbashir/therag2thealmostapproved/natalia-rules', 'natalia-rules', 'khaledbashir', 'therag2thealmostapproved', 'community', 'natalia-rules khaledbashir therag2thealmostapproved community The natalia-rules AI Agent skill performs exact mirroring of Excel data into PDF outputs. It directly copies Excel totals, preserves original section and row order, and includes all alternates without filtering. This is essential for technical proposal teams requiring strict data fidelity. Natalia 规则是一套确保数据镜像精确性的技术规则，包括无计算和保留行项顺序等 Natalia ルールは、データのミラーを正確にする技術的なルールです。計算不要、行項目の順序を維持など Natalia 규칙은 데이터 미러를 정확하게 유지하기 위한 기술 규칙입니다. 계산 없음, 행 항목 순서 유지 등 Natalia Rules es un conjunto de reglas para la creación de espejos exactos de datos en Excel y PDF, sin cálculos ni filtrados. Permite preservar la secuencia de líneas y secciones Natalia Rules est un ensemble de règles pour la création de miroirs exacts de données dans Excel et PDF, sans calculs ni filtrages. Il permet de préserver la séquence de lignes et de sections Natalia Rules ist ein Satz von Regeln für die Erstellung genauer Spiegel von Daten in Excel und PDF, ohne Berechnungen oder Filter. Es ermöglicht die Erhaltung der Reihenfolge von Zeilen und Abschnitten As regras de Natalia são um conjunto de diretrizes para ferramentas de IA que visam garantir a exatidão e a consistência Правила Натальи - это набор руководящих принципов для ИИ Агентов, целью которых является обеспечение точности и последовательности قواعد ناتاليا هي مجموعة من المبادئ التوجيهية لأدوات الذكاء الاصطناعي التي تهدف إلى ضمان الدقة والاتساق what is natalia-rules how to use natalia-rules for Excel natalia-rules vs data transformation tools natalia-rules alternative install natalia-rules AI agent natalia-rules setup guide Excel to PDF mirroring tool preserve Excel row order Natalia Kovaleva proposal rules Natalia 规则 AI 에이전트 数据镜像 镜像模式 无计算 保留行项顺序 显示替代项 Excel 总计值 Directly copies Excel totals without any recalculation (NO MATH rule) Preserves the exact order of sections as defined in the source Excel file Maintains the precise sequence of line items within each section Includes all alternate rows without any filtering or removal natalia-rules is an AI Agent skill that enforces strict mirroring of Excel data into PDF documents. It operates under non-negotiable rules to prevent recalculation, preserve exact sequence, and ensure all alternates are shown without any data filtering.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('juninmd/KamisamaLoader/Modding Core Logic', 'community', 'juninmd', 'KamisamaLoader', 'juninmd/KamisamaLoader', 'Modding Core Logic', 0, 0, 23, '2026-03-08T01:57:15.416Z', '2026-03-08T02:07:15.841Z', '2253d998dd3e57c7836e9895e1a7243d81d47acb37cd8a47f829d58a3a63b5b0', '{"id":"juninmd/KamisamaLoader/Modding Core Logic","name":"Modding Core Logic","description":{"en":"Modding Core Logic enables developers to manage mods and profiles efficiently. It leverages dependencies like adm-zip and fetch for streamlined mod handling.","zh":"Modding Core Logic 是一个用于管理游戏模组的技术，涉及 Zip 处理、网络请求和路径操作","ja":"Modding Core Logic は、ゲームモッドを管理するための技術であり、Zip 処理、ネットワークリクエスト、パス操作を含む","ko":"Modding Core Logic는 게임 모드를 관리하기 위한 기술로, Zip 처리, 네트워크 요청 및 경로 조작을 포함합니다","es":"Modding Core Logic es una habilidad que permite a los desarrolladores crear mods personalizados para juegos utilizando tecnologías como adm-zip y fetch","fr":"Modding Core Logic est une compétence qui permet aux développeurs de créer des mods personnalisés pour les jeux en utilisant des technologies telles que adm-zip et fetch","de":"Modding Core Logic ist eine Fähigkeit, die es Entwicklern ermöglicht, benutzerdefinierte Mods für Spiele zu erstellen, indem sie Technologien wie adm-zip und fetch verwenden","pt":"O Modding Core Logic é uma habilidade que permite a modificação de jogos com dependências como adm-zip e fetch.","ru":"Modding Core Logic — это навык, который позволяет модифицировать игры с помощью зависимостей adm-zip и fetch.","ar":"Modding Core Logic هو مهارة تسمح بتعديل الألعاب باستخدام التبعيات مثل adm-zip و fetch."},"seo":{"title":{"en":"Modding Core Logic: Setup Guide for AI Agents | AI Agent ...","zh":"Modding Core Logic 设置指南 - AI工具","ja":"Modding Core Logic のベストプラクティス - AIエージェント","ko":"Modding Core Logic 구축 가이드 - AI 도구","es":"Guía de configuración de Modding Core Logic para desarrol...","fr":"Configurer le Modding Core Logic : Guide pour les dévelop...","de":"Modding Core Logic Einrichtungsleitfaden für Entwickler","pt":"Guia de Configuração de Modding Core Logic para Desenvolv...","ru":"ИИ Агенты: Руководство по Настройке Modding Core Logic","ar":"دليل إعداد Modding Core Logic للأدوات الذكية"},"description":{"en":"Unlock modding capabilities with Modding Core Logic. Learn how to integrate adm-zip, fetch, and path manipulation for seamless mod management. Get started now!","zh":"了解 Modding Core Logic 的技术细节，包括依赖项、域实体和关键目录，实现游戏模组的高效管理","ja":"Modding Core Logic の技術的な詳細を学び、依存関係、ドメインエンティティ、重要なディレクトリを理解し、ゲームモッドの効率的な管理を実現する","ko":"Modding Core Logic의 기술적 세부 사항을 알아보고, 의존성, 도메인 엔티티, 주요 디렉토리를 이해하여 게임 모드의 효율적인 관리를 구현하십시오","es":"Aprende a configurar Modding Core Logic con adm-zip, fetch y path para crear mods personalizados para juegos","fr":"Découvrez comment configurer Modding Core Logic avec adm-zip, fetch et path pour créer des mods personnalisés pour les jeux","de":"Erfahren Sie, wie Sie Modding Core Logic mit adm-zip, fetch und path konfigurieren, um benutzerdefinierte Mods für Spiele zu erstellen","pt":"Aprenda a configurar o Modding Core Logic com dependências como adm-zip e fetch. Desbloqueie o poder dos mods para games.","ru":"Узнайте, как настроить Modding Core Logic с помощью зависимостей adm-zip и fetch. Раскройте потенциал модов для игр.","ar":"تعرف على كيفية إعداد Modding Core Logic باستخدام التبعيات مثل adm-zip و fetch. قم بتفعيل قوة المودات للألعاب."},"definition":{"en":"Modding Core Logic is a technical framework for managing modifications, utilizing dependencies like adm-zip, fetch, and path for efficient mod integration.","zh":"Modding Core Logic 是一种用于管理游戏模组的核心技术","ja":"Modding Core Logic は、ゲームモッドを管理するための核心技術です","ko":"Modding Core Logic는 게임 모드를 관리하기 위한 핵심 기술입니다","es":"Modding Core Logic es una habilidad que se refiere a la creación de mods personalizados para juegos","fr":"Modding Core Logic est une compétence qui fait référence à la création de mods personnalisés pour les jeux","de":"Modding Core Logic ist eine Fähigkeit, die sich auf die Erstellung benutzerdefinierter Mods für Spiele bezieht","pt":"Modding Core Logic é uma habilidade de modificação de jogos que utiliza dependências como adm-zip e fetch.","ru":"Modding Core Logic — это навык модификации игр, использующий зависимости adm-zip и fetch.","ar":"Modding Core Logic هو مهارة لتعديل الألعاب التي تستخدم التبعيات مثل adm-zip و fetch."},"features":{"en":["Utilizes adm-zip for zip handling and compression","Leverages fetch for networking and mod retrieval","Employs path manipulation via Node.js built-in path module","Supports mod management via GameBanana integration","Enables profile management for multiple mod collections","Streamlines mod storage and organization via Mods Directory"],"zh":["使用 adm-zip 处理 Zip 文件","支持 fetch 和 axios 网络请求","利用 path 模块进行路径操作","管理 Mod 和 Profile 实体","集成 GameBanana 模组平台","支持 Game Directory 和 Mods Directory"],"ja":["adm-zip を使用した Zip ファイルの処理","fetch と axios のネットワークリクエストのサポート","path モジュールを使用したパス操作","Mod と Profile エンティティの管理","GameBanana モッドプラットフォームの統合","Game Directory と Mods Directory のサポート"],"ko":["adm-zip을 사용한 Zip 파일 처리","fetch 및 axios 네트워크 요청 지원","path 모듈을 사용한 경로 조작","Mod 및 Profile 엔티티 관리","GameBanana 모드 플랫폼 통합","Game Directory 및 Mods Directory 지원"],"es":["Utiliza adm-zip para manejar archivos zip","Soporta fetch para realizar solicitudes de red","Incluye path para manipular rutas de archivos","Permite la creación de perfiles de mods personalizados","Integra con GameBanana para obtener mods en línea","Soporta la instalación de mods en el directorio del juego"],"fr":["Utilise adm-zip pour gérer les fichiers zip","Prend en charge fetch pour effectuer des requêtes réseau","Inclut path pour manipuler les chemins de fichiers","Permet la création de profils de mods personnalisés","Intègre GameBanana pour obtenir des mods en ligne","Prend en charge l''installation de mods dans le répertoire du jeu"],"de":["Verwenden Sie adm-zip, um Zip-Dateien zu verwalten","Unterstützt fetch für Netzwerkanfragen","Enthält path für die Manipulation von Dateipfaden","Ermöglicht die Erstellung benutzerdefinierter Mod-Profile","Integriert GameBanana, um Online-Mods zu erhalten","Unterstützt die Installation von Mods im Spielverzeichnis"],"pt":["Utiliza adm-zip para manipulação de arquivos zip","Suporta fetch para requisições de rede","Integração com o diretório de mods do GameBanana","Permite a criação de perfis de mods personalizados","Manipulação de caminhos com o módulo path do Node.js"],"ru":["Использует adm-zip для манипуляции файлами zip","Поддерживает fetch для сетевых запросов","Интегрируется с каталогом модов GameBanana","Позволяет создавать пользовательские профили модов","Манипулирует путями с помощью модуля path в Node.js"],"ar":["يستخدم adm-zip لتعديل الملفات zip","يدعم fetch لطلبات الشبكة","يتكامل مع دليل المودات في GameBanana","يسمح بإنشاء ملفات تعريف مودات مخصصة","يعالج المسارات باستخدام وحدة path في Node.js"]},"keywords":{"en":["how to use Modding Core Logic","what is Modding Core Logic","Modding Core Logic alternative","Modding Core Logic vs mod managers","Modding Core Logic install guide","Modding Core Logic setup tutorial","mod management with adm-zip","fetch API for mod retrieval","Node.js path module for mod organization"],"zh":["Modding Core Logic","游戏模组管理","Zip 处理","网络请求","路径操作","adm-zip","fetch","axios","path","GameBanana"],"ja":["Modding Core Logic","ゲームモッド管理","Zip 処理","ネットワークリクエスト","パス操作","adm-zip","fetch","axios","path","GameBanana"],"ko":["Modding Core Logic","게임 모드 관리","Zip 처리","네트워크 요청","경로 조작","adm-zip","fetch","axios","path","GameBanana"],"es":["modding core logic","creación de mods","adm-zip","fetch","path","gamebanana","mods personalizados","desarrollo de juegos","herramientas de modding","guias de configuración"],"fr":["modding core logic","création de mods","adm-zip","fetch","path","gamebanana","mods personnalisés","développement de jeux","outils de modding","guides de configuration"],"de":["modding core logic","erstellung von mods","adm-zip","fetch","path","gamebanana","benutzerdefinierte mods","spieleentwicklung","modding-tools","konfigurationsleitfäden"],"pt":["Modding Core Logic","adm-zip","fetch","GameBanana","mods de jogos","desenvolvimento de jogos","Node.js","path module"],"ru":["Modding Core Logic","ИИ Агенты","adm-zip","fetch","GameBanana","моды для игр","разработка игр","Node.js","модуль path"],"ar":["Modding Core Logic","الأدوات الذكية","adm-zip","fetch","GameBanana","مودات الألعاب","تطوير الألعاب","Node.js","وحدة path"]}},"owner":"juninmd","repo":"KamisamaLoader","repoPath":"juninmd/KamisamaLoader","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.416Z","topics":[],"category":"community","skillMd":{"name":"Modding Core Logic","description":"Domain logic for mod management, GameBanana integration, and file handling","bodyPreview":"# Modding Core Logic\n\n## Dependencies\n- **Zip Handling**: `adm-zip`\n- **Networking**: `fetch` (native) or `axios` (if added)\n- **Path Manipulation**: `path` (Node.js built-in)\n\n## Domain Entities\n- **Mod**: A modifiction package.\n- **Profile**: A collection of enabled mods.\n- **GameBanana**: The primary source for online mods.\n\n## Key Directories\n- **Game Directory**: Where the game is installed (e.g., `Steam/steamapps/common/...`).\n- **Mods Directory**: Where mods are stored (often a subfolder","body":"# Modding Core Logic\n\n## Dependencies\n- **Zip Handling**: `adm-zip`\n- **Networking**: `fetch` (native) or `axios` (if added)\n- **Path Manipulation**: `path` (Node.js built-in)\n\n## Domain Entities\n- **Mod**: A modifiction package.\n- **Profile**: A collection of enabled mods.\n- **GameBanana**: The primary source for online mods.\n\n## Key Directories\n- **Game Directory**: Where the game is installed (e.g., `Steam/steamapps/common/...`).\n- **Mods Directory**: Where mods are stored (often a subfolder of the game or a dedicated `mods` folder).\n\n## Common Tasks\n\n### Installing a Mod\n1. Extract the zip file using `adm-zip`.\n2. Validate the structure (check for specific mod files).\n3. Move files to the correct destination in the game directory.\n4. Record the installation in `installed-mods.json` (or database).\n\n### Uninstalling a Mod\n1. Look up files associated with the mod.\n2. Remove files safely.\n3. Update specific config files if necessary.\n4. Remove entry from `installed-mods.json`.\n\n### GameBanana Integration\n- Fetch mod info using GameBanana API endpoints.\n- Map API responses to the internal `OnlineMod` interface.\n- Handle rate limiting and errors gracefully.\n"},"lastSynced":"2026-03-08T02:07:15.841Z","agentAnalysis":{"suitability":{"en":"Ideal for Game Development Agents requiring efficient mod management and profile handling","zh":"非常适合需要高效模组管理和配置文件处理的游戏开发AI Agent","ja":"効率的なmod管理とプロファイル処理を必要とするゲーム開発エージェントに理想的です","ko":"효율적인 모드 관리 및 프로필 처리가 필요한 게임 개발 에이전트에 이상적입니다","es":"Ideal para agentes de desarrollo de juegos que requieren una gestión de modos y perfiles eficientes","fr":"Idéal pour les agents de développement de jeux nécessitant une gestion de mods et de profils efficace","de":"Ideal für Game-Entwicklungsagenten, die eine effiziente Mod- und Profilverwaltung benötigen","pt":"Ideal para Agentes de Desenvolvimento de Jogos que requerem gerenciamento de mod eficiente e manipulação de perfis","ru":"Идеально для агентов разработки игр, требующих эффективного управления модами и обработки профилей","ar":"مثالي لعميل تطوير الألعاب الذي يتطلب إدارة ملحقات فعالة ومعالجة ملفات تعريف"},"recommendation":{"en":"Empowers agents to streamline mod handling using adm-zip for zip management and fetch for networking, while manipulating paths with Node.js built-in ''path'' module, enabling seamless interactions with GameBanana and local game directories","zh":"赋能Agent使用adm-zip进行压缩包管理，使用fetch进行网络操作，同时利用Node.js内置的''path''模块处理路径，从而简化模组处理流程，实现与GameBanana及本地游戏目录的无缝交互","ja":"adm-zipを使用したzip管理とfetchを使用したネットワーキングにより、mod処理を効率化し、Node.js組み込みの''path''モジュールでパス操作を行うことで、エージェントがGameBananaおよびローカルゲームディレクトリとのシームレスな連携を可能にします","ko":"adm-zip을 사용한 zip 관리와 fetch를 사용한 네트워킹으로 모드 처리를 간소화하고, Node.js 내장 ''path'' 모듈로 경로를 조작하여 에이전트가 GameBanana 및 로컬 게임 디렉토리와 원활하게 상호작용할 수 있도록 합니다","es":"Habilita a los agentes a simplificar la gestión de mods utilizando adm-zip para la gestión de zip y fetch para la red, mientras manipula rutas con el módulo ''path'' integrado de Node.js, lo que permite interacciones sin problemas con GameBanana y directorios de juegos locales","fr":"Permet aux agents de rationaliser la gestion des mods en utilisant adm-zip pour la gestion des zip et fetch pour le réseau, tout en manipulant les chemins avec le module ''path'' intégré de Node.js, permettant des interactions sans problème avec GameBanana et les répertoires de jeux locaux","de":"Ermächtigt Agenten, die Mod-Verwaltung mithilfe von adm-zip für Zip-Verwaltung und fetch für Netzwerk zu rationalisieren, während Pfade mit dem integrierten ''path''-Modul von Node.js manipuliert werden, ermöglicht eine nahtlose Interaktion mit GameBanana und lokalen Spielverzeichnissen","pt":"Habilita os agentes a otimizar o gerenciamento de mods usando adm-zip para gerenciamento de zip e fetch para rede, enquanto manipula caminhos com o módulo ''path'' integrado do Node.js, permitindo interações sem problemas com GameBanana e diretórios de jogos locais","ru":"Наделяет агентов возможностью оптимизировать обработку модов с помощью adm-zip для управления zip и fetch для сетевых взаимодействий, а также манипулировать путями с помощью встроенного модуля ''path'' Node.js, обеспечивая бесперебойные взаимодействия с GameBanana и локальными игровыми директориями","ar":"يمنح الوكلاء khảية تحسين التعامل مع الملحقات باستخدام adm-zip لإدارة zip و fetch للشبكة، مع تحرير المسارات باستخدام وحدة ''path'' المدمجة في Node.js، مما يتيح التفاعلات السلسة مع GameBanana والمجلدات اللعبة المحلية"},"useCases":{"en":["Managing mods and profiles efficiently across different game directories","Automating mod downloads from GameBanana using fetch or axios","Debugging mod conflicts by analyzing profile configurations and dependencies"],"zh":["跨不同游戏目录高效管理模组和配置文件","使用fetch或axios从GameBanana自动下载模组","通过分析配置文件与依赖关系来调试模组冲突"],"ja":["異なるゲームディレクトリ間でのmodとプロファイルの効率的な管理","fetchまたはaxiosを使用したGameBananaからのmodの自動ダウンロード","プロファイル構成と依存関係を分析することによるmod競合のデバッグ"],"ko":["다양한 게임 디렉토리에서 모드와 프로필을 효율적으로 관리","fetch 또는 axios를 사용하여 GameBanana에서 모드 자동 다운로드","프로필 구성과 종속성을 분석하여 모드 충돌 디버깅"],"es":["Gestión eficiente de mods y perfiles en diferentes directorios de juegos","Automatización de descargas de mods desde GameBanana utilizando fetch o axios","Depuración de conflictos de mods analizando configuraciones de perfiles y dependencias"],"fr":["Gestion efficace des mods et des profils dans différents répertoires de jeux","Automatisation des téléchargements de mods à partir de GameBanana en utilisant fetch ou axios","Débogage des conflits de mods en analysant les configurations de profils et les dépendances"],"de":["Effiziente Verwaltung von Mods und Profilen in verschiedenen Spielverzeichnissen","Automatisierung von Mod-Downloads von GameBanana mithilfe von fetch oder axios","Fehlerbehebung bei Mod-Konflikten durch Analyse von Profilkonfigurationen und Abhängigkeiten"],"pt":["Gerenciar mods e perfis de forma eficiente em diferentes diretórios de jogos","Automatizar downloads de mods do GameBanana usando fetch ou axios","Depurar conflitos de mods analisando configurações de perfis e dependências"],"ru":["Эффективно управлять модами и профилями в разных игровых директориях","Автоматизировать скачивание модов с GameBanana с помощью fetch или axios","Отлаживать конфликты модов, анализируя конфигурации профилей и зависимости"],"ar":["إدارة الملحقات وملفات التعريف بفعالية عبر مجلدات الألعاب المختلفة","تأتمة تحميل الملحقات من GameBanana باستخدام fetch أو axios","تصحيح أخطاء الملحقات من خلال تحليل إعدادات ملفات التعريف والاعتماديات"]},"limitations":{"en":["Requires Node.js environment for path manipulation","Dependent on adm-zip for zip handling and fetch or axios for networking","Limited to managing mods and profiles for games with compatible directory structures"],"zh":["路径操作需要Node.js环境","压缩包处理依赖adm-zip，网络操作依赖fetch或axios","仅限于管理具有兼容目录结构的游戏的模组和配置文件"],"ja":["パス操作にNode.js環境が必要","zip処理はadm-zip、ネットワーキングはfetchまたはaxiosに依存","互換性のあるディレクトリ構造を持つゲームのmodとプロファイルの管理に限定される"],"ko":["경로 조작을 위해 Node.js 환경이 필요함","zip 처리는 adm-zip에, 네트워킹은 fetch 또는 axios에 의존","호환 가능한 디렉토리 구조를 가진 게임의 모드 및 프로필 관리로 제한됨"],"es":["Requiere un entorno Node.js para la manipulación de rutas","Dependiente de adm-zip para la gestión de zip y fetch o axios para la red","Limitado a la gestión de mods y perfiles para juegos con estructuras de directorios compatibles"],"fr":["Nécessite un environnement Node.js pour la manipulation des chemins","Dépendant de adm-zip pour la gestion des zip et fetch ou axios pour le réseau","Limité à la gestion des mods et des profils pour les jeux avec des structures de répertoires compatibles"],"de":["Benötigt eine Node.js-Umgebung für die Pfadmanipulation","Abhängig von adm-zip für die Zip-Verwaltung und fetch oder axios für das Netzwerk","Begrenzt auf die Verwaltung von Mods und Profilen für Spiele mit kompatiblen Verzeichnisstrukturen"],"pt":["Requer ambiente Node.js para manipulação de caminhos","Dependente de adm-zip para manipulação de zip e fetch ou axios para rede","Limitado ao gerenciamento de mods e perfis para jogos com estruturas de diretório compatíveis"],"ru":["Требует среды Node.js для манипулирования путями","Зависит от adm-zip для обработки zip и fetch или axios для сетевых взаимодействий","Ограничен обработкой модов и профилей для игр с совместимыми структурами директорий"],"ar":["يتطلب بيئة Node.js لتحليل المسارات","يعتمد على adm-zip لمعالجة zip و fetch أو axios للشبكة","محدود بمعالجة الملحقات وملفات التعريف لألعاب ذات هيكل مجلدات متوافق"]},"version":4},"contentHash":"2253d998dd3e57c7836e9895e1a7243d81d47acb37cd8a47f829d58a3a63b5b0","qualityScore":23}');
