INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('juninmd/KamisamaLoader/Modding Core Logic', 'Modding Core Logic', 'juninmd', 'KamisamaLoader', 'community', 'Modding Core Logic juninmd KamisamaLoader community Modding Core Logic enables developers to manage mods and profiles efficiently. It leverages dependencies like adm-zip and fetch for streamlined mod handling. Modding Core Logic 是一个用于管理游戏模组的技术，涉及 Zip 处理、网络请求和路径操作 Modding Core Logic は、ゲームモッドを管理するための技術であり、Zip 処理、ネットワークリクエスト、パス操作を含む Modding Core Logic는 게임 모드를 관리하기 위한 기술로, Zip 처리, 네트워크 요청 및 경로 조작을 포함합니다 Modding Core Logic es una habilidad que permite a los desarrolladores crear mods personalizados para juegos utilizando tecnologías como adm-zip y fetch Modding Core Logic est une compétence qui permet aux développeurs de créer des mods personnalisés pour les jeux en utilisant des technologies telles que adm-zip et fetch Modding Core Logic ist eine Fähigkeit, die es Entwicklern ermöglicht, benutzerdefinierte Mods für Spiele zu erstellen, indem sie Technologien wie adm-zip und fetch verwenden O Modding Core Logic é uma habilidade que permite a modificação de jogos com dependências como adm-zip e fetch. Modding Core Logic — это навык, который позволяет модифицировать игры с помощью зависимостей adm-zip и fetch. Modding Core Logic هو مهارة تسمح بتعديل الألعاب باستخدام التبعيات مثل adm-zip و fetch. how to use Modding Core Logic what is Modding Core Logic Modding Core Logic alternative Modding Core Logic vs mod managers Modding Core Logic install guide Modding Core Logic setup tutorial mod management with adm-zip fetch API for mod retrieval Node.js path module for mod organization Modding Core Logic 游戏模组管理 Zip 处理 网络请求 路径操作 adm-zip fetch axios path GameBanana Utilizes adm-zip for zip handling and compression Leverages fetch for networking and mod retrieval Employs path manipulation via Node.js built-in path module Supports mod management via GameBanana integration Enables profile management for multiple mod collections Streamlines mod storage and organization via Mods Directory Modding Core Logic is a technical framework for managing modifications, utilizing dependencies like adm-zip, fetch, and path for efficient mod integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pasindudilshan1/Time-managemtn-app-ralph/writing-prd', 'community', 'pasindudilshan1', 'Time-managemtn-app-ralph', 'pasindudilshan1/Time-managemtn-app-ralph', 'writing-prd', 0, 0, 23, '2026-03-08T01:57:15.417Z', '2026-03-08T02:07:18.623Z', 'd505fc56b8892662473222174cab0b778456b6df7ec69079be56828287dcd192', '{"id":"pasindudilshan1/Time-managemtn-app-ralph/writing-prd","name":"writing-prd","description":{"en":"The writing-prd AI skill automates the creation of structured Product Requirements Documents for software features. It benefits developers, product managers, and technical teams by formalizing requirements with a standard technical structure.","zh":"Writing PRD技能创建结构化的产品需求文档，包括概述、问题陈述、目标和成功指标等","ja":"Writing PRDスキルは、PRDの構造化された文書を作成するために使用され、概要、問題の説明、目標、成功の指標などを含む","ko":"Writing PRD 에이전트는 제품 요구 사항 문서를 구조화하여 기능을 구축하고 성능을 최적화하는 데 사용됩니다","es":"La habilidad de escritura de PRD crea documentos de requisitos de producto estructurados para características de software con secciones como descripción general, declaración de problemas y requisitos funcionales","fr":"La compétence d''écriture de PRD crée des documents de spécifications de produit structurés pour les fonctionnalités logicielles avec des sections telles que description générale, énoncé de problèmes et exigences fonctionnelles","de":"Die Fähigkeit zum Schreiben von PRD erstellt strukturierte Produktanforderungsdokumente für Softwarefunktionen mit Abschnitten wie Überblick, Problembeschreibung und funktionalen Anforderungen","pt":"A escrita de PRD é um processo crucial para o desenvolvimento de software, e as Ferramentas de IA podem ajudar a criar documentos de requisitos de produto estruturados e eficazes.","ru":"Написание PRD является важным процессом для разработки программного обеспечения, и ИИ Агенты могут помочь создать структурированные и эффективные документы требований продукта","ar":"كتابة مواصفات المنتج هي عملية حاسمة لتطوير البرمجيات، وأدوات الذكاء الاصطناعي يمكن أن تساعد في إنشاء مستندات متطلبات المنتج المهيكلة والفعالة"},"seo":{"title":{"en":"writing-prd: Structured Product Requirements Document Gen...","zh":"AI工具：Writing PRD 技术指南","ja":"AIエージェント：PRD作成ベストプラクティス","ko":"AI 에이전트: Writing PRD 설정 가이드","es":"Guía para escribir PRD: Creación de documentos de requisi...","fr":"Guide pour écrire un PRD : Création de documents de spéci...","de":"Anleitung zum Schreiben von PRD: Erstellung strukturierte...","pt":"Guia de Configuração para Escrita de PRD com Ferramentas ...","ru":"Руководство по настройке ИИ Агентов для написания PRD","ar":"دليل إعداد كتابة مواصفات المنتج باستخدام أدوات الذكاء الا..."},"description":{"en":"Automate your PRD creation. This AI agent skill generates comprehensive Product Requirements Documents, including User Stories, Functional & Non-Functional R...","zh":"了解Writing PRD技能，创建结构化的产品需求文档，包括概述、问题陈述、目标和成功指标等","ja":"PRD作成を効率化するAIエージェントのWriting PRDスキルを紹介。ユーザーストーリー、機能要件、非機能要件などを含む","ko":"Writing PRD 에이전트를 사용하여 제품 요구 사항 문서를 구조화하여 기능을 구축하고 성능을 최적화하는 방법을 알아보세요","es":"Aprende a crear documentos de requisitos de producto estructurados con nuestra guía de escritura de PRD y herramientas de AI Agent para desarrolladores","fr":"Découvrez comment créer des documents de spécifications de produit structurés avec notre guide d''écriture de PRD et outils d''Outil IA pour les développeurs","de":"Erfahren Sie, wie Sie strukturierte Produktanforderungsdokumente mit unserer Anleitung zum Schreiben von PRD und KI-Tool für Entwickler erstellen","pt":"Aprenda a criar documentos de requisitos de produto estruturados com as melhores práticas de escrita de PRD e Ferramentas de IA","ru":"Изучите, как создавать структурированные документы требований продукта с помощью ИИ Агентов и лучших практик написания PRD","ar":"تعلم كيفية إنشاء مستندات متطلبات المنتج المهيكلة باستخدام أدوات الذكاء الاصطناعي وأفضل الممارسات لكتابة مواصفات المنتج"},"definition":{"en":"writing-prd is an AI agent skill that creates structured Product Requirements Documents for software features. It systematically generates documents containing an Overview, Problem Statement, Goals & Success Metrics, User Stories, and Functional/Non-Functional Requirements.","zh":"Writing PRD是指创建产品需求文档的技能，包括概述、问题陈述、目标和成功指标等","ja":"Writing PRDとは、PRDの構造化された文書を作成するスキルであり、概要、問題の説明、目標、成功の指標などを含む","ko":"Writing PRD는 제품 요구 사항 문서를 작성하는 기술로, 기능을 구축하고 성능을 최적화하는 데 사용됩니다","es":"Un PRD es un documento que describe los requisitos de un producto de software, incluyendo la descripción general, la declaración de problemas y los requisitos funcionales","fr":"Un PRD est un document qui décrit les spécifications d''un produit logiciel, incluant la description générale, l''énoncé de problèmes et les exigences fonctionnelles","de":"Ein PRD ist ein Dokument, das die Anforderungen an ein Softwareprodukt beschreibt, einschließlich des Überblicks, der Problembeschreibung und der funktionalen Anforderungen","pt":"A escrita de PRD é o processo de criação de documentos de requisitos de produto que descrevem as funcionalidades e requisitos de um software","ru":"Написание PRD является процессом создания документов требований продукта, которые описывают функциональность и требования программного обеспечения","ar":"كتابة مواصفات المنتج هي عملية إنشاء مستندات متطلبات المنتج التي تصف ميزات ومتطلبات البرمجيات"},"features":{"en":["Generates a structured PRD Overview section","Articulates a formal Problem Statement for the feature","Defines measurable Goals & Success Metrics","Creates User Stories to capture user needs","Specifies Functional Requirements for feature behavior","Outlines Non-Functional Requirements for performance, security, and accessibility"],"zh":["创建结构化的产品需求文档","包括概述、问题陈述、目标和成功指标","支持用户故事、功能要件、非功能要件","技术方法和性能、安全性、可访问性的考虑"],"ja":["PRDの構造化された文書を作成","概要、問題の説明、目標、成功の指標を含む","ユーザーストーリー、機能要件、非機能要件をサポート","技術的アプローチとパフォーマンス、セキュリティ、可達性の考慮"],"ko":["제품 요구 사항 문서 구조화","개요, 문제 설명, 목표 및 성공 지표 포함","사용자 스토리, 기능 요구 사항, 비기능 요구 사항 지원","기술적 접근 및 성능, 보안, 접근성 고려"],"es":["Estructura de PRD con secciones como descripción general y declaración de problemas","Requisitos funcionales y no funcionales para características de software","Enfoque técnico para el desarrollo de software","Historias de usuario y métricas de éxito para el seguimiento del progreso","Requisitos de rendimiento, seguridad y accesibilidad para software","Creación de documentos de requisitos de producto estructurados con AI Agent"],"fr":["Structure de PRD avec des sections telles que description générale et énoncé de problèmes","Exigences fonctionnelles et non fonctionnelles pour les fonctionnalités logicielles","Approche technique pour le développement de logiciels","Histoires d''utilisateurs et métriques de succès pour le suivi des progrès","Exigences de performances, de sécurité et d''accessibilité pour les logiciels","Création de documents de spécifications de produit structurés avec Outil IA"],"de":["PRD-Struktur mit Abschnitten wie Überblick und Problembeschreibung","Funktionale und nicht-funktionale Anforderungen für Softwarefunktionen","Technischer Ansatz für die Softwareentwicklung","Benutzerstories und Erfolgsmetriken für die Verfolgung des Fortschritts","Anforderungen an Leistung, Sicherheit und Zugänglichkeit für Software","Erstellung strukturierter Produktanforderungsdokumente mit KI-Tool"],"pt":["Criação de documentos de requisitos de produto estruturados","Definição de visão geral e declaração de problemas","Estabelecimento de metas e métricas de sucesso","Desenvolvimento de histórias de usuário e requisitos funcionais","Definição de requisitos não funcionais, como desempenho e segurança","Escolha da abordagem técnica para o desenvolvimento do software"],"ru":["Создание структурированных документов требований продукта","Определение обзора и заявления проблемы","Установление целей и метрик успеха","Разработка историй пользователей и функциональных требований","Определение нефункциональных требований, таких как производительность и безопасность","Выбор технического подхода для разработки программного обеспечения"],"ar":["إنشاء مستندات متطلبات المنتج المهيكلة","تعريف نظرة عامة وبيان المشكلة","تحديد الأهداف ومقاييس النجاح","تطوير قصص المستخدمين والمتطلبات الوظيفية","تعريف المتطلبات غير الوظيفية، مثل الأداء والأمان","اختيار النهج التقني لتطوير البرمجيات"]},"keywords":{"en":["how to use writing-prd","what is writing-prd","writing-prd vs manual prd creation","writing-prd alternative","writing-prd install guide","writing-prd setup for ai agents","ai product requirements document generator","automated prd creation"],"zh":["AI工具","Writing PRD","产品需求文档","结构化文档","功能要件","非功能要件","技术方法","性能优化"],"ja":["AIエージェント","Writing PRD","PRD作成","構造化文書","ユーザーストーリー","機能要件","非機能要件","技術的アプローチ"],"ko":["AI 에이전트","Writing PRD","제품 요구 사항 문서","구조화 문서","사용자 스토리","기능 요구 사항","비기능 요구 사항","기술적 접근"],"es":["escritura de PRD","creación de documentos de requisitos de producto","AI Agent para desarrolladores","requisitos funcionales y no funcionales","enfoque técnico para el desarrollo de software","historias de usuario y métricas de éxito","requisitos de rendimiento y seguridad","estructura de PRD","desarrollo de software con AI"],"fr":["écriture de PRD","création de documents de spécifications de produit","Outil IA pour les développeurs","exigences fonctionnelles et non fonctionnelles","approche technique pour le développement de logiciels","histoires d''utilisateurs et métriques de succès","exigences de performances et de sécurité","structure de PRD","développement de logiciels avec Outil IA"],"de":["Schreiben von PRD","Erstellung strukturierter Produktanforderungsdokumente","KI-Tool für Entwickler","funktionale und nicht-funktionale Anforderungen","technischer Ansatz für die Softwareentwicklung","Benutzerstories und Erfolgsmetriken","Anforderungen an Leistung und Sicherheit","PRD-Struktur","Softwareentwicklung mit KI-Tool"],"pt":["escrita de PRD","ferramentas de IA para escrita de PRD","melhores práticas de escrita de PRD","documentos de requisitos de produto","desenvolvimento de software","requisitos funcionais","requisitos não funcionais","abordagem técnica","histórias de usuário"],"ru":["написание PRD","ИИ Агенты для написания PRD","лучшие практики написания PRD","документы требований продукта","разработка программного обеспечения","функциональные требования","нефункциональные требования","технический подход","истории пользователей"],"ar":["كتابة مواصفات المنتج","أدوات الذكاء الاصطناعي لكتابة مواصفات المنتج","أفضل الممارسات لكتابة مواصفات المنتج","مستندات متطلبات المنتج","تطوير البرمجيات","المتطلبات الوظيفية","المتطلبات غير الوظيفية","النهج التقني","قصص المستخدمين"]}},"owner":"pasindudilshan1","repo":"Time-managemtn-app-ralph","repoPath":"pasindudilshan1/Time-managemtn-app-ralph","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.417Z","topics":[],"category":"community","skillMd":{"name":"writing-prd","description":"Creates Product Requirements Documents (PRDs) for software features. Use when asked to write a PRD, product spec, or feature requirements.","bodyPreview":"# Writing PRD Skill\n\nCreates structured Product Requirements Documents for software features.\n\n## PRD Structure\n\nEvery PRD should include:\n\n1. **Overview** - Brief description of the feature\n2. **Problem Statement** - What problem this solves\n3. **Goals & Success Metrics** - Measurable outcomes\n4. **User Stories** - Who needs this and why\n5. **Functional Requirements** - What the feature must do\n6. **Non-Functional Requirements** - Performance, security, accessibility\n7. **Technical Approach** -","body":"# Writing PRD Skill\n\nCreates structured Product Requirements Documents for software features.\n\n## PRD Structure\n\nEvery PRD should include:\n\n1. **Overview** - Brief description of the feature\n2. **Problem Statement** - What problem this solves\n3. **Goals & Success Metrics** - Measurable outcomes\n4. **User Stories** - Who needs this and why\n5. **Functional Requirements** - What the feature must do\n6. **Non-Functional Requirements** - Performance, security, accessibility\n7. **Technical Approach** - High-level implementation strategy\n8. **UI/UX Considerations** - Visual and interaction design\n9. **Out of Scope** - What this PRD does NOT cover\n10. **Timeline & Milestones** - Phases of delivery\n\n## Workflow\n\n1. Understand the existing codebase structure\n2. Identify the feature request and context\n3. Write the PRD in `docs/prd/` directory\n4. Name file descriptively: `feature-name-prd.md`\n\n## Best Practices\n\n- Be specific with requirements (avoid \"should be fast\")\n- Include acceptance criteria for each requirement\n- Reference existing code patterns when applicable\n- Consider edge cases and error states\n- Keep scope focused and achievable\n"},"lastSynced":"2026-03-08T02:07:18.623Z","agentAnalysis":{"suitability":{"en":"Perfect for Product Management Agents automating structured technical documentation.","zh":"非常适合用于自动化结构化技术文档的产品管理Agent。","ja":"構造化された技術文書を自動化するプロダクトマネジメントAgentに最適です。","ko":"구조화된 기술 문서를 자동화하는 제품 관리 에이전트에 완벽하게 적합합니다.","es":"Perfecto para Agentes de Gestión de Productos que automatizan la documentación técnica estructurada.","fr":"Parfait pour les Agents de Gestion de Produit qui automatisent la documentation technique structurée.","de":"Perfekt für Produktmanagement-Agenten, die strukturierte technische Dokumentation automatisieren.","pt":"Perfeito para Agentes de Gestão de Produto que automatizam documentação técnica estruturada.","ru":"Идеально подходит для Агентов Управления Продуктом, автоматизирующих структурированную техническую документацию.","ar":"مثالي لوكلاء إدارة المنتج لأتمتة الوثائق التقنية المنظمة."},"recommendation":{"en":"Empowers agents to generate comprehensive Product Requirements Documents with standardized sections including Problem Statements, Functional Requirements, and Technical Approach. Formalizes software feature specifications with measurable success metrics and user story frameworks.","zh":"使Agent能够生成包含问题陈述、功能需求和技术方法等标准化章节的全面产品需求文档（PRD）。通过可衡量的成功指标和用户故事框架，将软件功能规范正式化。","ja":"問題陈述、機能要件、技術的アプローチなどの標準化されたセクションを含む包括的なプロダクト要件ドキュメント（PRD）を生成するようにAgentを強化します。測定可能な成功指標とユーザーストーリーフレームワークを使用して、ソフトウェア機能仕様を正式化します。","ko":"에이전트가 문제 진술, 기능 요구사항 및 기술적 접근법과 같은 표준화된 섹션을 포함한 포괄적인 제품 요구사항 문서(PRD)를 생성할 수 있도록 지원합니다. 측정 가능한 성공 지표와 사용자 스토리 프레임워크를 통해 소프트웨어 기능 사양을 공식화합니다.","es":"Habilita a los agentes a generar documentos de requisitos de producto comprehensivos con secciones estandarizadas que incluyen declaraciones de problemas, requisitos funcionales y enfoque técnico. Formaliza las especificaciones de características de software con métricas de éxito medibles y frameworks de historias de usuario.","fr":"Permet aux agents de générer des documents de spécifications de produit complets avec des sections standardisées comprenant des énoncés de problèmes, des exigences fonctionnelles et une approche technique. Formalise les spécifications de fonctionnalités logicielles avec des métriques de succès mesurables et des frameworks d''histoires utilisateur.","de":"Ermächtigt Agenten, umfassende Produktanforderungsdokumente mit standardisierten Abschnitten zu erstellen, darunter Problembeschreibungen, Funktionsanforderungen und technischer Ansatz. Formalisiert Software-Funktionsspezifikationen mit messbaren Erfolgsmetriken und Benutzerstory-Frameworks.","pt":"Capacita os agentes a gerar Documentos de Requisitos de Produto abrangentes com secções padronizadas, incluindo Declarações de Problema, Requisitos Funcionais e Abordagem Técnica. Formaliza as especificações de funcionalidades de software com métricas de sucesso mensuráveis e estruturas de user stories.","ru":"Позволяет агентам генерировать всеобъемлющие Документы Требований к Продукту со стандартизированными разделами, включая Формулировки Проблем, Функциональные Требования и Технический Подход. Формализует спецификации функций программного обеспечения с измеримыми метриками успеха и структурами пользовательских историй.","ar":"يمكن الوكلاء من إنشاء وثائق متطلبات المنتج الشاملة مع أقسام موحدة تشمل بيان المشكلة، المتطلبات الوظيفية، والنهج التقني. يهيكل مواصفات ميزات البرنامج بمقاييس نجاح قابلة للقياس وأطر قصص المستخدم."},"useCases":{"en":["Automating PRD creation for new features","Generating technical requirement documentation","Structuring user story frameworks","Formalizing success metrics for development teams"],"zh":["自动化新功能的PRD创建","生成技术需求文档","构建用户故事框架","为开发团队正式化成功指标"],"ja":["新機能のPRD作成の自動化","技術要件ドキュメントの生成","ユーザーストーリーフレームワークの構築","開発チームのための成功指標の正式化"],"ko":["신규 기능에 대한 PRD 생성 자동화","기술 요구사항 문서 생성","사용자 스토리 프레임워크 구조화","개발 팀을 위한 성공 지표 공식화"],"es":["Automatización de la creación de PRD para nuevas características","Generación de documentación de requisitos técnicos","Estructuración de frameworks de historias de usuario","Formalización de métricas de éxito para equipos de desarrollo"],"fr":["Automatisation de la création de PRD pour de nouvelles fonctionnalités","Génération de documentation de spécifications techniques","Structuration de frameworks d''histoires utilisateur","Formalisation de métriques de succès pour les équipes de développement"],"de":["Automatisierung der PRD-Erstellung für neue Funktionen","Generierung von technischer Anforderungsdokumentation","Strukturierung von Benutzerstory-Frameworks","Formalisierung von Erfolgsmetriken für Entwicklungsteams"],"pt":["Automatizar a criação de PRD para novas funcionalidades","Gerar documentação de requisitos técnicos","Estruturar enquadramentos de user stories","Formalizar métricas de sucesso para equipas de desenvolvimento"],"ru":["Автоматизация создания PRD для новых функций","Генерация документации по техническим требованиям","Структурирование frameworks пользовательских историй","Формализация метрик успеха для команд разработчиков"],"ar":["أتمتة إنشاء PRD للميزات الجديدة","إنشاء وثائق المتطلبات التقنية","هيكلة أطر قصص المستخدم","إضفاء الطابع الرسمي على مقاييس النجاح لفرق التطوير"]},"limitations":{"en":["Requires detailed feature input parameters","Limited to software development contexts"],"zh":["需要详细的功能输入参数","仅限于软件开发背景"],"ja":["詳細な機能入力パラメータが必要","ソフトウェア開発のコンテキストに限定される"],"ko":["상세한 기능 입력 매개변수가 필요함","소프트웨어 개발 컨텍스트로 제한됨"],"es":["Requiere parámetros de entrada de características detallados","Limitado a contextos de desarrollo de software"],"fr":["Nécessite des paramètres d''entrée de fonctionnalités détaillés","Limité aux contextes de développement de logiciels"],"de":["Benötigt detaillierte Funktions-Eingabeparameter","Begrenzt auf Software-Entwicklungskontexte"],"pt":["Requer parâmetros de entrada detalhados da funcionalidade","Limitado a contextos de desenvolvimento de software"],"ru":["Требует детальных входных параметров функций","Ограничено контекстами разработки программного обеспечения"],"ar":["يتطلب معلمات إدخال مفصلة للميزة","يقتصر على سياقات تطوير البرمجيات"]},"version":4},"contentHash":"d505fc56b8892662473222174cab0b778456b6df7ec69079be56828287dcd192","qualityScore":23}');
DELETE FROM skills_fts WHERE id = 'pasindudilshan1/Time-managemtn-app-ralph/writing-prd';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pasindudilshan1/Time-managemtn-app-ralph/writing-prd', 'writing-prd', 'pasindudilshan1', 'Time-managemtn-app-ralph', 'community', 'writing-prd pasindudilshan1 Time-managemtn-app-ralph community The writing-prd AI skill automates the creation of structured Product Requirements Documents for software features. It benefits developers, product managers, and technical teams by formalizing requirements with a standard technical structure. Writing PRD技能创建结构化的产品需求文档，包括概述、问题陈述、目标和成功指标等 Writing PRDスキルは、PRDの構造化された文書を作成するために使用され、概要、問題の説明、目標、成功の指標などを含む Writing PRD 에이전트는 제품 요구 사항 문서를 구조화하여 기능을 구축하고 성능을 최적화하는 데 사용됩니다 La habilidad de escritura de PRD crea documentos de requisitos de producto estructurados para características de software con secciones como descripción general, declaración de problemas y requisitos funcionales La compétence d''écriture de PRD crée des documents de spécifications de produit structurés pour les fonctionnalités logicielles avec des sections telles que description générale, énoncé de problèmes et exigences fonctionnelles Die Fähigkeit zum Schreiben von PRD erstellt strukturierte Produktanforderungsdokumente für Softwarefunktionen mit Abschnitten wie Überblick, Problembeschreibung und funktionalen Anforderungen A escrita de PRD é um processo crucial para o desenvolvimento de software, e as Ferramentas de IA podem ajudar a criar documentos de requisitos de produto estruturados e eficazes. Написание PRD является важным процессом для разработки программного обеспечения, и ИИ Агенты могут помочь создать структурированные и эффективные документы требований продукта كتابة مواصفات المنتج هي عملية حاسمة لتطوير البرمجيات، وأدوات الذكاء الاصطناعي يمكن أن تساعد في إنشاء مستندات متطلبات المنتج المهيكلة والفعالة how to use writing-prd what is writing-prd writing-prd vs manual prd creation writing-prd alternative writing-prd install guide writing-prd setup for ai agents ai product requirements document generator automated prd creation AI工具 Writing PRD 产品需求文档 结构化文档 功能要件 非功能要件 技术方法 性能优化 Generates a structured PRD Overview section Articulates a formal Problem Statement for the feature Defines measurable Goals & Success Metrics Creates User Stories to capture user needs Specifies Functional Requirements for feature behavior Outlines Non-Functional Requirements for performance, security, and accessibility writing-prd is an AI agent skill that creates structured Product Requirements Documents for software features. It systematically generates documents containing an Overview, Problem Statement, Goals & Success Metrics, User Stories, and Functional/Non-Functional Requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TbK0ng/silver-bullet-kernel/before-backend-dev', 'community', 'TbK0ng', 'silver-bullet-kernel', 'TbK0ng/silver-bullet-kernel', 'before-backend-dev', 0, 0, 23, '2026-03-08T01:57:15.422Z', '2026-03-08T02:07:23.478Z', '4537ccee0071353beee636a052c01642a27a87b6b0a73e7bc872b2501547fa64', '{"id":"TbK0ng/silver-bullet-kernel/before-backend-dev","name":"before-backend-dev","description":{"en":"The before-backend-dev skill helps developers plan their backend development tasks based on trellis specifications. It guides users to read relevant guidelines for database work, error handling, and logging.","zh":"before-backend-dev是后端开发前的必备步骤，通过阅读trellis规范文档，了解数据库、错误处理、日志记录等指南","ja":"before-backend-devはバックエンド開発前の重要なステップです。trellisのガイドラインを読んで、開発を効率化しましょう","ko":"before-backend-dev는 백엔드 개발前的 필수 단계입니다. trellis 규격을 읽고 개발을 효율화하세요","es":"Planifica tu proyecto de programación con base en trellis y sigue las pautas de desarrollo backend","fr":"Planifiez votre projet de programmation basé sur trellis et suivez les directives de développement backend","de":"Planen Sie Ihr Programmierprojekt auf Basis von trellis und folgen Sie den Backend-Entwicklungsrichtlinien","pt":"O before-backend-dev é uma habilidade que ajuda a configurar projetos backend com base nas diretrizes do Trellis","ru":"ИИ Агенты: before-backend-dev - это навык, который помогает настроить проекты backend на основе руководства Trellis","ar":"الوكلاء الذكية: before-backend-dev هو مهارة تساعد على إعداد مشاريع الخلفية根据 إرشادات تريليس"},"seo":{"title":{"en":"before-backend-dev: Backend Development Setup Guide | AI ...","zh":"before-backend-dev 入门指南：后端开发前必读","ja":"before-backend-dev Setup Guide：AIエージェントを使ったバックエンド開発の準備","ko":"before-backend-dev 시작하기：백엔드 개발을 위한 준비 단계","es":"Guía de configuración antes del desarrollo backend","fr":"Guide de configuration avant le développement