INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TbK0ng/silver-bullet-kernel/before-backend-dev', 'before-backend-dev', 'TbK0ng', 'silver-bullet-kernel', 'community', 'before-backend-dev TbK0ng silver-bullet-kernel community The before-backend-dev skill helps developers plan their backend development tasks based on trellis specifications. It guides users to read relevant guidelines for database work, error handling, and logging. before-backend-dev是后端开发前的必备步骤，通过阅读trellis规范文档，了解数据库、错误处理、日志记录等指南 before-backend-devはバックエンド開発前の重要なステップです。trellisのガイドラインを読んで、開発を効率化しましょう before-backend-dev는 백엔드 개발前的 필수 단계입니다. trellis 규격을 읽고 개발을 효율화하세요 Planifica tu proyecto de programación con base en trellis y sigue las pautas de desarrollo backend Planifiez votre projet de programmation basé sur trellis et suivez les directives de développement backend Planen Sie Ihr Programmierprojekt auf Basis von trellis und folgen Sie den Backend-Entwicklungsrichtlinien O before-backend-dev é uma habilidade que ajuda a configurar projetos backend com base nas diretrizes do Trellis ИИ Агенты: before-backend-dev - это навык, который помогает настроить проекты backend на основе руководства Trellis الوكلاء الذكية: before-backend-dev هو مهارة تساعد على إعداد مشاريع الخلفية根据 إرشادات تريليس how to use before-backend-dev before-backend-dev setup guide before-backend-dev vs backend development frameworks what is before-backend-dev before-backend-dev install before-backend-dev alternative trellis specifications for backend development backend development guidelines error handling in before-backend-dev before-backend-dev 后端开发 trellis规范 数据库开发 错误处理 日志记录 类型安全 Reads .trellis/spec/backend/index.md for available guidelines Executes steps for database work using .trellis/spec/backend/database-guidelines.md Handles errors based on .trellis/spec/backend/error-handling.md Implements logging using .trellis/spec/backend/logging-guidelines.md Ensures type safety with .trellis/spec/backend/type-safety.md before-backend-dev is a skill that provides a final plan for programming based on trellis, guiding developers through backend development guidelines and specifications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('liqiongyu/agentpack/agentpack-dev', 'community', 'liqiongyu', 'agentpack', 'liqiongyu/agentpack', 'agentpack-dev', 0, 0, 23, '2026-03-08T01:57:15.423Z', '2026-03-08T02:07:25.501Z', '99df11d8952ee13dee0047aabaaa6b7be2c108a73bc3f3c62312bcde9ba10454', '{"id":"liqiongyu/agentpack/agentpack-dev","name":"agentpack-dev","description":{"en":"agentpack-dev provides a declarative control plane for deploying coding-agent assets across tools, benefiting developers working with AI agents. It offers a spec-driven workflow and authoritative implementation contract.","zh":"agentpack-dev是一个declarative的安全控制平面，用于部署coding-agent资产。它提供了一个规范驱动的工作流程","ja":"agentpack-devは、AIエージェントのdeclarative_control_planeを提供することで、coding-agentアセットのデプロイを支援する","ko":"agentpack-dev는 코딩 에이전트 자산을 배포하는 선언적 제어 평면을 제공하는 것으로, 규격 주도 워크플로우를 지원","es":"Agentpack-dev es un plano de control declarativo y seguro para desplegar activos de código en herramientas de desarrollo.","fr":"Agentpack-dev est un plan de contrôle déclaratif et sécurisé pour déployer des actifs de code dans les outils de développement.","de":"Agentpack-dev ist eine deklarative und sichere Steuerungsebene für die Bereitstellung von Codierungs-Assets in Entwicklungstools.","pt":"O agentpack-dev é um plano de controle declarativo e seguro para deploy de ativos de agentes de codificação em ferramentas.","ru":"Agentpack-dev — это декларативная и безопасная контрольная плоскость для развертывания активов кодирования агентов в инструментах.","ar":"agentpack-dev هو مخطط تحكم إعلاني وأمن لتنصيب مخزونات وكلاء الترميز في الأدوات."},"seo":{"title":{"en":"agentpack-dev: Declarative Control Plane Setup Guide | AI...","zh":"agentpack-dev_SETUP GUIDE:declarative_control_plane","ja":"agentpack-dev_BEST_PRACTICES:AIエージェント_declarative_control...","ko":"agentpack-dev_SETUP_TUTORIAL:declarative_control_plane_fo...","es":"Guía de configuración de agentpack-dev para entornos de d...","fr":"Guide de mise en place d''agentpack-dev pour les environne...","de":"Einrichtungsleitfaden für agentpack-dev in Entwicklungsum...","pt":"Guia de Configuração do agentpack-dev: Plano de Execução ...","ru":"Настройка agentpack-dev: Лучшие Практики для ИИ Агентов","ar":"دليل إعداد agentpack-dev: خطة تنفيذ أولية بالذكاء الاصطناعي"},"description":{"en":"Discover how to deploy coding-agent assets safely with agentpack-dev. Explore the OpenSpec workflow and JSON API contract today!","zh":"了解agentpack-dev的declarative控制平面，用于部署coding-agent资产。阅读Canonical文档和Spec-driven工作流程","ja":"AIエージェントのdeclarative_control_planeを使用してcoding-agentアセットをデプロイする方法について。CanonicalドキュメントとSpec-drivenワークフローを参照","ko":"코딩 에이전트 자산을 배포하는 선언적 제어 평면인 agentpack-dev에 대해 알아보기. Canoncal 문서 및 Spec-driven 워크플로 참조","es":"Aprende a implementar agentpack-dev para una gestión segura de activos de código en tus proyectos de desarrollo","fr":"Découvrez comment mettre en œuvre agentpack-dev pour une gestion sécurisée des actifs de code dans vos projets de développement","de":"Erfahren Sie, wie Sie agentpack-dev implementieren, um Codierungs-Assets in Ihren Entwicklungsprojekten sicher zu verwalten","pt":"Aprenda a configurar o agentpack-dev para deploy de ativos de agentes de codificação em ferramentas com um plano de execução AI-First","ru":"Узнайте, как настроить agentpack-dev для развертывания активов кодирования агентов в инструментах с помощью плана выполнения ИИ","ar":"استكشف كيفية إعداد agentpack-dev لنشر مخزونات وكلاء الترميز في الأدوات بخطة تنفيذ الذكاء الاصطناعي"},"definition":{"en":"agentpack-dev is a declarative, safe control plane for deploying coding-agent assets across tools, utilizing OpenSpec and JSON API contracts.","zh":"agentpack-dev是用于开发agentpack仓库的declarative控制平面","ja":"agentpack-devは、AIエージェントのdeclarative_control_planeを使用したagentpackリポジトリの開発を支援する","ko":"agentpack-dev는 agentpack 저장소를 개발하기 위한 선언적 제어 평면","es":"Agentpack-dev es un plano de control para la gestión de activos de código en entornos de desarrollo","fr":"Agentpack-dev est un plan de contrôle pour la gestion des actifs de code dans les environnements de développement","de":"Agentpack-dev ist eine Steuerungsebene für die Verwaltung von Codierungs-Assets in Entwicklungsumgebungen","pt":"O que é agentpack-dev? É um plano de controle para deploy de ativos de agentes de codificação.","ru":"Что такое agentpack-dev? Это контрольная плоскость для развертывания активов кодирования агентов.","ar":"ما هو agentpack-dev؟ إنه مخطط تحكم لتنصيب مخزونات وكلاء الترميز."},"features":{"en":["Utilizes OpenSpec workflow for spec-driven development","Implements authoritative implementation contract via SPEC.md","Supports JSON API contract with stable error codes via ERROR_CODES.md","Enables creation of proposals via openspec/changes/<change-id>/ directory","Follows AI-first execution roadmap outlined in CODEX_EXEC_PLAN.md"],"zh":["declarative控制平面","安全部署coding-agent资产","规范驱动工作流程","支持JSON_API和ERROR_CODES","OpenSpec工作流程"],"ja":["declarative_control_plane","AIエージェントの安全なデプロイ","Spec-drivenワークフロー","JSON_APIとERROR_CODESのサポート","OpenSpecワークフロー"],"ko":["선언적 제어 평면","코딩 에이전트 자산의 안전한 배포","규격 주도 워크플로우","JSON_API와 ERROR_CODES 지원","OpenSpec 워크플로우"],"es":["Control plano declarativo para desplegar activos de código","Compatibilidad con OpenSpec para flujos de trabajo basados en especificaciones","Soporte para ejecución de planes de código en formato JSON","Gestión de códigos de error estables para una depuración efectiva","Integración con la cartera de agentes para una gestión centralizada"],"fr":["Plan de contrôle déclaratif pour déployer des actifs de code","Compatibilité avec OpenSpec pour des flux de travail basés sur des spécifications","Prise en charge de l''exécution de plans de code au format JSON","Gestion de codes d''erreur stables pour un débogage efficace","Intégration avec le portefeuille d''agents pour une gestion centralisée"],"de":["Deklarative Steuerungsebene für die Bereitstellung von Codierungs-Assets","Kompatibilität mit OpenSpec für spezifikationsbasierte Workflows","Unterstützung für die Ausführung von Codeplänen im JSON-Format","Verwaltung von stabilen Fehlercodes für eine effektive Fehlersuche","Integration mit dem Agenten-Portfolio für eine zentrale Verwaltung"],"pt":["Plano de execução AI-First","Controle declarativo e seguro","Deploy de ativos de agentes de codificação em ferramentas","Suporte a OpenSpec","Documentação em JSON_API e ERROR_CODES"],"ru":["План выполнения ИИ","Декларативное и безопасное управление","Развертывание активов кодирования агентов в инструментах","Поддержка OpenSpec","Документация в JSON_API и ERROR_CODES"],"ar":["خطة تنفيذ أولية بالذكاء الاصطناعي","التحكم الإعلاني والأمن","نشر مخزونات وكلاء الترميز في الأدوات","دعم OpenSpec","توثيق بالـ JSON_API و ERROR_CODES"]},"keywords":{"en":["how to use agentpack-dev","agentpack-dev setup guide","agentpack-dev alternative","agentpack-dev vs other control planes","agentpack-dev install","what is agentpack-dev","agentpack-dev OpenSpec workflow","agentpack-dev JSON API contract"],"zh":["agentpack-dev","declarative控制平面","coding-agent资产","规范驱动工作流程","JSON_API","ERROR_CODES","OpenSpec"],"ja":["agentpack-dev","AIエージェント","declarative_control_plane","coding-agentアセット","Spec-drivenワークフロー","JSON_API","ERROR_CODES","OpenSpec"],"ko":["agentpack-dev","코딩 에이전트 자산","선언적 제어 평면","규격 주도 워크플로우","JSON_API","ERROR_CODES","OpenSpec"],"es":["agentpack-dev","desarrollo de software","gestión de activos de código","OpenSpec","JSON","plan de control declarativo","Agente AI","herramientas de desarrollo","codificación"],"fr":["agentpack-dev","développement de logiciels","gestion des actifs de code","OpenSpec","JSON","plan de contrôle déclaratif","Agent IA","outils de développement","codage"],"de":["agentpack-dev","Software-Entwicklung","Verwaltung von Codierungs-Assets","OpenSpec","JSON","deklarative Steuerungsebene","KI-Agent","Entwicklungstools","Codierung"],"pt":["agentpack-dev","plano de execução AI-First","controle declarativo","deploy de ativos de agentes de codificação","OpenSpec","JSON_API","ERROR_CODES","ferramentas de desenvolvimento"],"ru":["agentpack-dev","план выполнения ИИ","декларативное управление","развертывание активов кодирования агентов","OpenSpec","JSON_API","ERROR_CODES","инструменты разработки"],"ar":["agentpack-dev","خطة تنفيذ أولية بالذكاء الاصطناعي","التحكم الإعلاني","نشر مخزونات وكلاء الترميز","OpenSpec","JSON_API","ERROR_CODES","أدوات التطوير"]}},"owner":"liqiongyu","repo":"agentpack","repoPath":"liqiongyu/agentpack","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.423Z","topics":[],"category":"community","skillMd":{"name":"agentpack-dev","description":"Contribute to Agentpack itself (spec-driven changes, tests, releases).","bodyPreview":"# agentpack-dev\n\nThis skill is for developing the `agentpack` repo (not for operating agentpack on another project).\n\n## Canonical docs (read first)\n- `docs/CODEX_EXEC_PLAN.md` (AI-first execution roadmap)\n- `docs/SPEC.md` (authoritative implementation contract)\n- `docs/JSON_API.md` + `docs/ERROR_CODES.md` (`--json` contract + stable error codes)\n\n## Spec-driven workflow (OpenSpec)\n- Read: `openspec/AGENTS.md` and `openspec/project.md`\n- Create proposal: `openspec/changes/<change-id>/` (verb-led","body":"# agentpack-dev\n\nThis skill is for developing the `agentpack` repo (not for operating agentpack on another project).\n\n## Canonical docs (read first)\n- `docs/CODEX_EXEC_PLAN.md` (AI-first execution roadmap)\n- `docs/SPEC.md` (authoritative implementation contract)\n- `docs/JSON_API.md` + `docs/ERROR_CODES.md` (`--json` contract + stable error codes)\n\n## Spec-driven workflow (OpenSpec)\n- Read: `openspec/AGENTS.md` and `openspec/project.md`\n- Create proposal: `openspec/changes/<change-id>/` (verb-led kebab-case)\n- Validate: `openspec validate <change-id> --strict --no-interactive`\n- After merge: archive via `openspec archive <change-id> --yes` (separate PR)\n\n## Local verification\n- `cargo fmt --all -- --check`\n- `cargo clippy --all-targets --all-features -- -D warnings`\n- `cargo test --all --locked`\n"},"lastSynced":"2026-03-08T02:07:25.501Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agent Developers seeking declarative control over coding-agent assets across tools","zh":"适合于寻求对编码代理资产在各个工具中进行声明式控制的AI代理开发人员","ja":"ツール間のコーディングエージェント資産に対する宣言的制御を求めるAIエージェント開発者に適しています","ko":"도구 간의 코딩 에이전트 자산에 대한 선언적 제어를尋求하는 AI 에이전트 개발자에게 적합합니다","es":"Ideal para desarrolladores de Agentes de Inteligencia Artificial que buscan control declarativo sobre activos de codificación de agentes en varias herramientas","fr":"Idéal pour les développeurs d''agents d''intelligence artificielle qui recherchent un contrôle déclaratif sur les actifs de codage d''agents à travers les outils","de":"Ideal für Entwickler von KI-Agenten, die eine deklarative Kontrolle über Codierungsagenten-Assets in verschiedenen Tools suchen","pt":"Ideal para Desenvolvedores de Agentes de IA que buscam controle declarativo sobre ativos de agentes de codificação em várias ferramentas","ru":"Идеально для разработчиков агентов ИИ, стремящихся к декларативному контролю над активами кодирования агентов в различных инструментах","ar":"مثالي لمطوري وكلاء الذكاء الاصطناعي الذين يبحثون عن التحكم الإعلاني في أصول وكيل التشفير عبر الأدوات"},"recommendation":{"en":"Empowers agents to manage spec-driven workflows and authoritative implementation contracts using OpenSpec, enabling seamless integration with tools through JSON APIs and stable error codes","zh":"赋予代理管理基于规格的工作流程和权威的实现合同，使用OpenSpec，实现与工具的无缝集成，通过JSON API和稳定的错误代码","ja":"OpenSpecを使用して、エージェントに仕様ベースのワークフローと権威ある実装契約を管理する権限を与え、JSON APIと安定したエラーコードを介してツールとのシームレスな統合を実現する","ko":"OpenSpec를 사용하여 에이전트가 사양 기반의 워크플로우와 권위적인 구현 계약을 관리하도록 허용하며, JSON API와 안정적인 오류 코드를 통해 도구와의無縫な統合을 실현합니다","es":"Habilita a los agentes para administrar flujos de trabajo impulsados por especificaciones y contratos de implementación autorizados utilizando OpenSpec, lo que permite una integración sin problemas con herramientas a través de APIs JSON y códigos de error estables","fr":"Permet aux agents de gérer des flux de travail pilotés par des spécifications et des contrats d''implémentation autorisés en utilisant OpenSpec, ce qui permet une intégration transparente avec des outils via des API JSON et des codes d''erreur stables","de":"Ermächtigt Agenten, spezifikationsgetriebene Workflows und autorisierte Implementierungsverträge mithilfe von OpenSpec zu verwalten, was eine nahtlose Integration mit Tools über JSON-APIs und stabile Fehlercodes ermöglicht","pt":"Habilita agentes a gerenciar fluxos de trabalho impulsionados por especificações e contratos de implementação autoritativos usando OpenSpec, permitindo integração sem problemas com ferramentas por meio de APIs JSON e códigos de erro estáveis","ru":"Наделяет агентов возможностью управлять рабочими процессами, основанными на спецификациях, и авторитетными контрактами реализации с помощью OpenSpec, обеспечивая бесшовную интеграцию с инструментами через JSON API и стабильные коды ошибок","ar":"يتمكن الوكلاء من إدارة تدفقات العمل المدفوعة بالمواصفات والعقود التنفيذية للحصول على سلطة باستخدام OpenSpec، وتمكين التكامل السلس مع الأدوات من خلال واجهات برمجة التطبيقات JSON وأكواد الخطأ المستقرة"},"useCases":{"en":["Deploying coding-agent assets across multiple tools","Creating proposal-driven changes to the agentpack repository","Implementing spec-driven workflows for AI agent development"],"zh":["在多个工具中部署编码代理资产","创建驱动提案的更改到agentpack仓库","实现基于规格的工作流程用于AI代理开发"],"ja":["複数のツールにコーディングエージェント資産をデプロイする","提案駆動の変更をagentpackリポジトリに作成する","AIエージェント開発のための仕様ベースのワークフローを実装する"],"ko":["여러 도구에 코딩 에이전트 자산을 배포하는こと","agentpack 저장소에 제안 기반의 변경을 생성하는 것","AI 에이전트 개발을 위한 사양 기반 워크플로우를 구현하는 것"],"es":["Implementación de activos de codificación de agentes en varias herramientas","Creación de cambios impulsados por propuestas en el repositorio de agentpack","Implementación de flujos de trabajo impulsados por especificaciones para el desarrollo de agentes de inteligencia artificial"],"fr":["Déploiement d''actifs de codage d''agents sur plusieurs outils","Création de modifications pilotées par des propositions sur le référentiel d''agentpack","Mise en œuvre de flux de travail pilotés par des spécifications pour le développement d''agents d''intelligence artificielle"],"de":["Bereitstellung von Codierungsagenten-Assets in mehreren Tools","Erstellung von vorschlagsgetriebenen Änderungen im agentpack-Repository","Implementierung von spezifikationsgetriebenen Workflows für die Entwicklung von KI-Agenten"],"pt":["Implantação de ativos de agente de codificação em várias ferramentas","Criação de alterações baseadas em propostas no repositório agentpack","Implementação de fluxos de trabalho impulsionados por especificações para desenvolvimento de agentes de IA"],"ru":["Развертывание активов кодирования агентов в нескольких инструментах","Создание изменений, основанных на предложениях, в репозитории agentpack","Реализация рабочих процессов, основанных на спецификациях, для разработки агентов ИИ"],"ar":["تثبيت أصول وكيل التشفير عبر أدوات متعددة","إنشاء تغييرات مدفوعة بال提議 في مستودع agentpack","تنفيذ تدفقات العمل المدفوعة بالمواصفات لتطوير وكلاء الذكاء الاصطناعي"]},"limitations":{"en":["Requires understanding of OpenSpec and JSON API contracts","Limited to development of the agentpack repository","Needs adherence to the authoritative implementation contract specified in SPEC.md"],"zh":["需要理解OpenSpec和JSON API合同","仅限于agentpack仓库的开发","需要遵守SPEC.md中指定的权威实现合同"],"ja":["OpenSpecとJSON API契約の理解が必要","agentpackリポジトリの開発のみに限定される","SPEC.mdに記載された権威ある実装契約の遵守が必要"],"ko":["OpenSpec와 JSON API 계약을 이해해야 함","agentpack 저장소 개발에만 제한됨","SPEC.md에 지정된 권위적인 구현 계약을 준수해야 함"],"es":["Requiere comprensión de OpenSpec y contratos de API JSON","Limitado al desarrollo del repositorio de agentpack","Necesita adherirse al contrato de implementación autorizado especificado en SPEC.md"],"fr":["Nécessite une compréhension d''OpenSpec et de contrats d''API JSON","Limité au développement du référentiel d''agentpack","Nécessite l''adérence au contrat d''implémentation autorisé spécifié dans SPEC.md"],"de":["Erfordert Verständnis von OpenSpec und JSON-API-Verträgen","Begrenzt auf die Entwicklung des agentpack-Repositorys","Benötigt die Einhaltung des autorisierten Implementierungsvertrags, der in SPEC.md angegeben ist"],"pt":["Exige compreensão de OpenSpec e contratos de API JSON","Limitado ao desenvolvimento do repositório agentpack","Necessita de adesão ao contrato de implementação autoritativo especificado em SPEC.md"],"ru":["Требует понимания OpenSpec и контрактов JSON API","Ограничен разработкой репозитория agentpack","Требует соблюдения авторитетного контракта реализации, указанного в SPEC.md"],"ar":["يتطلب فهم OpenSpec وعقود واجهة برمجة التطبيقات JSON","محدود بالتطوير لمستودع agentpack","يتطلب اتباع عقد التنفيذ المخول المحدد في SPEC.md"]},"version":4},"contentHash":"99df11d8952ee13dee0047aabaaa6b7be2c108a73bc3f3c62312bcde9ba10454","qualityScore":23}');
