INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('liqiongyu/agentpack/agentpack-dev', 'agentpack-dev', 'liqiongyu', 'agentpack', 'community', 'agentpack-dev liqiongyu agentpack community agentpack-dev provides a declarative control plane for deploying coding-agent assets across tools, benefiting developers working with AI agents. It offers a spec-driven workflow and authoritative implementation contract. agentpack-dev是一个declarative的安全控制平面，用于部署coding-agent资产。它提供了一个规范驱动的工作流程 agentpack-devは、AIエージェントのdeclarative_control_planeを提供することで、coding-agentアセットのデプロイを支援する agentpack-dev는 코딩 에이전트 자산을 배포하는 선언적 제어 평면을 제공하는 것으로, 규격 주도 워크플로우를 지원 Agentpack-dev es un plano de control declarativo y seguro para desplegar activos de código en herramientas de desarrollo. Agentpack-dev est un plan de contrôle déclaratif et sécurisé pour déployer des actifs de code dans les outils de développement. Agentpack-dev ist eine deklarative und sichere Steuerungsebene für die Bereitstellung von Codierungs-Assets in Entwicklungstools. O agentpack-dev é um plano de controle declarativo e seguro para deploy de ativos de agentes de codificação em ferramentas. Agentpack-dev — это декларативная и безопасная контрольная плоскость для развертывания активов кодирования агентов в инструментах. agentpack-dev هو مخطط تحكم إعلاني وأمن لتنصيب مخزونات وكلاء الترميز في الأدوات. how to use agentpack-dev agentpack-dev setup guide agentpack-dev alternative agentpack-dev vs other control planes agentpack-dev install what is agentpack-dev agentpack-dev OpenSpec workflow agentpack-dev JSON API contract agentpack-dev declarative控制平面 coding-agent资产 规范驱动工作流程 JSON_API ERROR_CODES OpenSpec Utilizes OpenSpec workflow for spec-driven development Implements authoritative implementation contract via SPEC.md Supports JSON API contract with stable error codes via ERROR_CODES.md Enables creation of proposals via openspec/changes/<change-id>/ directory Follows AI-first execution roadmap outlined in CODEX_EXEC_PLAN.md agentpack-dev is a declarative, safe control plane for deploying coding-agent assets across tools, utilizing OpenSpec and JSON API contracts.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('joelklabo/markdowntown-cli/markdowntown-cli', 'community', 'joelklabo', 'markdowntown-cli', 'joelklabo/markdowntown-cli', 'markdowntown-cli', 0, 0, 23, '2026-03-08T01:57:15.424Z', '2026-03-08T02:07:26.860Z', 'deb84f9d8c8578935e2d8322ebc62d1b5515e2f3597b19bb8077efd31fda0e4a', '{"id":"joelklabo/markdowntown-cli/markdowntown-cli","name":"markdowntown-cli","description":{"en":"markdowntown-cli is a scan CLI tool that benefits developers by providing a efficient way to build and test scan CLIs. It utilizes `rg` for search and keeps changes small and deterministic.","zh":"markdowntown-cli是一种使用rg进行搜索和扫描的CLI工具，通过保持小而确定的变化并确保CI测试通过来构建可靠的扫描功能","ja":"markdowntown-cliは、rgを使用した検索とスキャンを行うCLIツールで、小さく決定的な変更を保持し、CIテストを通過して信頼性の高いスキャン機能を構築します","ko":"markdowntown-cli는 rg를 사용한 검색 및 스캔을 수행하는 CLI 도구로, 작은 변경 사항을 유지하고 CI 테스트를 통과하여 안정적인 스캔 기능을 구축합니다.","es":"markdowntown-cli es una herramienta de escaneo CLI que utiliza rg para búsqueda y sigue las especificaciones de scan-spec-v1.md","fr":"markdowntown-cli est un outil d''analyse CLI qui utilise rg pour la recherche et suit les spécifications de scan-spec-v1.md","de":"markdowntown-cli ist ein CLI-Scan-Tool, das rg für die Suche verwendet und den Spezifikationen von scan-spec-v1.md folgt","pt":"O markdowntown-cli é uma ferramenta de scan CLI para desenvolvedores, projetada para trabalhar com `rg` para busca e testes automatizados.","ru":"Markdowntown-cli - это инструмент сканирования CLI для разработчиков, предназначенный для работы с `rg` для поиска и автоматизированного тестирования для ИИ Агентов","ar":"markdowntown-cli هي أداة مسح CLI للوكلاء الذكيين، مصممة للعمل مع `rg` للبحث واختبارات أوتوماتيكية"},"seo":{"title":{"en":"markdowntown-cli: Setup Guide for AI Agents | CLI Scan Tool","zh":"markdowntown-cli 设置指南：使用rg进行搜索和扫描","ja":"markdowntown-cli Setup Guide: rgを使用した検索とスキャン","ko":