INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('joelklabo/markdowntown-cli/markdowntown-cli', 'markdowntown-cli', 'joelklabo', 'markdowntown-cli', 'community', 'markdowntown-cli joelklabo markdowntown-cli community markdowntown-cli is a scan CLI tool that benefits developers by providing a efficient way to build and test scan CLIs. It utilizes `rg` for search and keeps changes small and deterministic. markdowntown-cli是一种使用rg进行搜索和扫描的CLI工具，通过保持小而确定的变化并确保CI测试通过来构建可靠的扫描功能 markdowntown-cliは、rgを使用した検索とスキャンを行うCLIツールで、小さく決定的な変更を保持し、CIテストを通過して信頼性の高いスキャン機能を構築します markdowntown-cli는 rg를 사용한 검색 및 스캔을 수행하는 CLI 도구로, 작은 변경 사항을 유지하고 CI 테스트를 통과하여 안정적인 스캔 기능을 구축합니다. markdowntown-cli es una herramienta de escaneo CLI que utiliza rg para búsqueda y sigue las especificaciones de scan-spec-v1.md markdowntown-cli est un outil d''analyse CLI qui utilise rg pour la recherche et suit les spécifications de scan-spec-v1.md markdowntown-cli ist ein CLI-Scan-Tool, das rg für die Suche verwendet und den Spezifikationen von scan-spec-v1.md folgt O markdowntown-cli é uma ferramenta de scan CLI para desenvolvedores, projetada para trabalhar com `rg` para busca e testes automatizados. Markdowntown-cli - это инструмент сканирования CLI для разработчиков, предназначенный для работы с `rg` для поиска и автоматизированного тестирования для ИИ Агентов markdowntown-cli هي أداة مسح CLI للوكلاء الذكيين، مصممة للعمل مع `rg` للبحث واختبارات أوتوماتيكية how to use markdowntown-cli markdowntown-cli setup guide markdowntown-cli alternative markdowntown-cli vs other CLI tools what is markdowntown-cli markdowntown-cli install markdowntown-cli tutorial markdowntown-cli documentation markdowntown-cli best practices markdowntown-cli rg搜索 CLI工具 扫描功能 CI测试 make lint make test AIエージェント AI工具 Builds scan CLI according to `cli/docs/scan-spec-v1.md` specifications Utilizes `rg` for efficient search functionality Runs `cd cli && make lint` and `cd cli && make test` for CI validation Avoids destructive git commands unless explicitly requested Follows `apps/web/AGENTS.md` guidelines for web app changes markdowntown-cli is a command-line interface tool for building and testing scan CLIs, following specifications outlined in `cli/docs/scan-spec-v1.md`.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('gordonwatts/atlas-mcp/python-function-caching', 'community', 'gordonwatts', 'atlas-mcp', 'gordonwatts/atlas-mcp', 'python-function-caching', 0, 0, 23, '2026-03-08T01:57:15.426Z', '2026-03-08T02:07:28.909Z', '33dec9b69ffd4ae8dbc962d4e805b941c31eb2919c3651ee46eee8c03462ebf5', '{"id":"gordonwatts/atlas-mcp/python-function-caching","name":"python-function-caching","description":{"en":"This Python Function Caching skill provides a decorator-based caching mechanism for pure functions, storing results on disk to eliminate redundant computations. It is designed for developers working with expensive calculations or external service calls like LLMs.","zh":"Python 函数缓存是一种提高性能的技术，通过缓存纯函数的结果，减少计算和外部服务调用次数","ja":"Python 関数キャッシュは、純粋な関数の結果をキャッシュすることで、計算と外部サービス呼び出しの回数を削減します","ko":"파이썬 함수 캐싱은 순수 함수의 결과를 캐싱하여 계산과 외부 서비스 호출 횟수를 줄여 성능을 개선합니다","es":"El caché de funciones de Python es una técnica para almacenar los resultados de funciones puras y evitar cálculos costosos","fr":"Le cache de fonctions Python est une technique pour stocker les résultats de fonctions pures et éviter les calculs coûteux","de":"Das Caching von Python-Funktionen ist eine Technik, um die Ergebnisse reiner Funktionen zu speichern und teure Berechnungen zu vermeiden","pt":"O cache de funções Python é uma técnica para melhorar o desempenho de aplicações com chamadas caras. Ele funciona copiando o conteúdo do arquivo disk_cache.py.","ru":"Кэширование функций Python - это метод для улучшения производительности приложений с дорогими вызовами. Он работает путем копирования содержимого файла disk_cache.py.","ar":"ذاكرة التخزين المؤقت للوظائف البايثونية هي تقنية لتحسين أداء التطبيقات مع المكالمات المكلفة. تعمل عن طريق نسخ محتوى ملف disk_cache.py."},"seo":{"title":{"en":"Python Function Caching: Setup Guide for AI Agents | Skill","zh":"Python 函数缓存设置指南","ja":"Python 関数キャッシュのベストプラクティス","ko":"Python 함수 캐싱 구현 가이드","es":"Guía de configuración de caché de funciones de Python","fr":"Guide de mise en cache des fonctions Python","de":"Einrichtungsleitfaden für Python-Funktionen-Caching","pt":"Guia de Configuração de Cache de Funções Python","ru":"Настройка кэширования функций Python: ИИ Агенты","ar":"دليل إعداد ذاكرة التخزين المؤقت للوظائف البايثونية"},"description":{"en":"Learn how to implement a disk-based cache for expensive Python function calls, including LLM API requests. This guide covers integrating the `disk_cache.py` ...","zh":"了解如何使用 Python 函数缓存提高性能，特别适用于计算密集型函数和外部服务调用","ja":"Python 関数キャッシュを使用してパフォーマンスを向上させる方法を学びましょう","ko":"파이썬 함수 캐싱을 사용하여 성능을 개선하는 방법을 알아보세요","es":"Aprende a implementar el caché de funciones de Python para optimizar el rendimiento de tus aplicaciones","fr":"Découvrez comment mettre en cache les fonctions Python pour améliorer les performances de vos applications","de":"Erfahren Sie, wie Sie das Caching von Python-Funktionen implementieren, um die Leistung Ihrer Anwendungen zu optimieren","pt":"Aprenda a configurar o cache de funções Python para melhorar o desempenho de suas aplicações com chamadas caras","ru":"Узнайте, как настроить кэширование функций Python для улучшения производительности ваших приложений с дорогими вызовами","ar":"تعرف على كيفية إعداد ذاكرة التخزين المؤقت للوظائف البايثونية لتحسين أداء تطبيقاتك مع المكالمات المكلفة"},"definition":{"en":"python-function-caching is a developer skill that implements a disk-based cache decorator for Python functions. It is intended for pure functions that depend solely on their inputs, caching results to avoid re-running expensive operations like complex calculations or calls to external APIs.","zh":"Python 函数缓存是一种技术，用于缓存函数结果以提高性能","ja":"Python 関数キャッシュは、関数の結果をキャッシュしてパフォーマンスを向上させる技術です","ko":"파이썬 함수 캐싱은 함수 결과를 캐싱하여 성능을 개선하는 기술입니다","es":"El caché de funciones de Python es una técnica de optimización que almacena los resultados de funciones","fr":"Le cache de fonctions Python est une technique d''optimisation qui stocke les résultats de fonctions","de":"Das Caching von Python-Funktionen ist eine Optimierungstechnik, die die Ergebnisse von Funktionen speichert","pt":"Cache de funções Python é uma técnica de otimização que armazena resultados de funções para evitar cálculos repetitivos","ru":"Кэширование функций Python - это метод оптимизации, который хранит результаты функций для避ания повторных вычислений","ar":"ذاكرة التخزين المؤقت للوظائف البايثونية هي تقنية تحسين تقوم بتخزين نتائج الوظائف لتجنب الحسابات المتكررة"},"features":{"en":["Caches function results using a decorator pattern for pure functions","Stores cached data on disk in a configurable directory (e.g., `~/.cache/project_name`)","Integrates via a provided `disk_cache.py` module file","Requires manual configuration of the `project_name` variable within the cache instance","Optimizes performance for expensive calls like LLM API requests or heavy calculations"],"zh":["支持纯函数缓存","减少计算和外部服务调用次数","提高性能","易于集成到现有项目中","支持自定义缓存路径"],"ja":["純粋な関数のキャッシュをサポート","計算と外部サービス呼び出しの回数を削減","パフォーマンスを向上させる","既存のプロジェクトへの容易な統合","カスタムキャッシュパスのサポート"],"ko":["순수 함수 캐싱 지원","계산과 외부 서비스 호출 횟수 감소","성능 개선","기존 프로젝트에 쉽게 통합","사용자 정의 캐시 경로 지원"],"es":["Almacenamiento de resultados de funciones puras","Evita cálculos costosos y llamadas a servicios externos","Implementación sencilla con el archivo `disk_cache.py`","Personalizable con el nombre del proyecto","Optimiza el rendimiento de aplicaciones de Python","Compatible con llamadas a servicios externos como LLM"],"fr":["Stockage des résultats de fonctions pures","Évite les calculs coûteux et les appels à des services externes","Mise en œuvre simple avec le fichier `disk_cache.py`","Personnalisation avec le nom du projet","Optimise les performances des applications Python","Compatible avec les appels à des services externes comme LLM"],"de":["Speicherung von Ergebnissen reiner Funktionen","Vermeidung teurer Berechnungen und Aufrufe von externen Diensten","Einfache Implementierung mit der Datei `disk_cache.py`","Anpassbar mit dem Projektname","Optimiert die Leistung von Python-Anwendungen","Kompatibel mit Aufrufen von externen Diensten wie LLM"],"pt":["Caching de resultados de funções puras","Otimização de chamadas caras","Compatibilidade com cálculos e chamadas externas","Configuração personalizada com o arquivo disk_cache.py","Melhoria do desempenho de aplicações"],"ru":["Кэширование результатов чистых функций","Оптимизация дорогих вызовов","Совместимость с вычислениями и внешними вызовами","Настройка с помощью файла disk_cache.py","Улучшение производительности приложений"],"ar":["ذاكرة التخزين المؤقت للنتائج الوظائف النقية","تحسين المكالمات المكلفة","التوافق مع الحسابات والاستدعاءات الخارجية","إعدادات مخصصة مع ملف disk_cache.py","تحسين أداء التطبيقات"]},"keywords":{"en":["how to use python function caching","what is python-function-caching","python disk cache decorator","python-function-caching vs functools.lru_cache","cache LLM API calls python","python-function-caching install","python-function-caching setup guide","configure disk_cache.py project_name"],"zh":["Python 函数缓存","AIエージェント","函数缓存技术","性能优化","计算密集型函数","外部服务调用","缓存路径自定义"],"ja":["Python 関数キャッシュ","AIエージェント","関数キャッシュ技術","パフォーマンス最適化","計算密度の高い関数","外部サービス呼び出し","キャッシュパスのカスタマイズ"],"ko":["파이썬 함수 캐싱","AI 에이전트","함수 캐싱 기술","성능 최적화","계산 집중적인 함수","외부 서비스 호출","캐시 경로 사용자 정의"],"es":["caché de funciones de Python","optimización de rendimiento","funciones puras","llamadas a servicios externos","Python","desarrollo de aplicaciones","caché de resultados","mejora del rendimiento","guía de configuración"],"fr":["cache de fonctions Python","optimisation des performances","fonctions pures","appels à des services externes","Python","développement d''applications","cache de résultats","amélioration des performances","guide de mise en œuvre"],"de":["Caching von Python-Funktionen","Leistungsoptimierung","reine Funktionen","Aufrufe von externen Diensten","Python","Anwendungsentwicklung","Ergebnisspeicherung","Leistungsverbesserung","Einrichtungsleitfaden"],"pt":["cache de funções python","otimização de aplicações","chamadas caras","cálculos repetitivos","disk_cache.py","desempenho de aplicações"],"ru":["кэширование функций python","оптимизация приложений","дорогие вызовы","повторные вычисления","disk_cache.py","производительность приложений"],"ar":["ذاكرة التخزين المؤقت للوظائف البايثونية","تحسين التطبيقات","المكالمات المكلفة","الحسابات المتكررة","disk_cache.py","أداء التطبيقات"]}},"owner":"gordonwatts","repo":"atlas-mcp","repoPath":"gordonwatts/atlas-mcp","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.426Z","topics":[],"category":"community","skillMd":{"name":"python-function-caching","description":"Provide a reusable pattern for memoizing deterministic function calls to reduce latency and repeated computation. Backed by the `python` diskcache package. Use skill when updating or editing everything.","bodyPreview":"# Python Function Caching Skill\n\n## Purpose\n\n- Caching the function result. Works for pure functions that depend only on their inputs and have no side effects.\n- Perfect for expensive calls (calculations, or calls to external services like LLM''s).\n\n## Workflow\n\n1. Copy the contents of the file `assets/disk_cache.py` into the project.\n2. In the file update the `project_name` in the line `cache = Cache(\"~/.cache/project_name\")` to be the appropriate name. Also replace `project_name` further down i","body":"# Python Function Caching Skill\n\n## Purpose\n\n- Caching the function result. Works for pure functions that depend only on their inputs and have no side effects.\n- Perfect for expensive calls (calculations, or calls to external services like LLM''s).\n\n## Workflow\n\n1. Copy the contents of the file `assets/disk_cache.py` into the project.\n2. In the file update the `project_name` in the line `cache = Cache(\"~/.cache/project_name\")` to be the appropriate name. Also replace `project_name` further down in the docstring.\n3. Use `@diskcache_decorator` or `@diskcache_decorator(seconds-till-expired)` for any function the user wants cached.\n    - By default, the cache should not expire.\n    - If it makes sense that it should expire, 1 hour (3600 seconds seconds), 1 day (86400 seconds), or 1 week (604800 seconds) are common settings.\n4. Tricky part is invoking tests to make sure that the cache isn''t used. Tests should use the `ignore_cache=True` to get around this unless otherwise requested by the user.\n\n## Behavior\n\n- Uses the function arguments to compute the hash\n- Unless `ignore_cache` is `True`, the result is returned right away.\n- If the function is called, the result is always stored in the cache.\n- Current code does not have an eviction policy.\n"},"lastSynced":"2026-03-08T02:07:28.909Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Cursor, Windsurf, and Claude Code needing efficient function caching for expensive calculations or external service calls.","zh":"适合像Cursor、Windsurf和Claude Code这样的AI Agent，需要高效的函数缓存来进行昂贵的计算或外部服务调用。","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しており、高価な計算や外部サービスへの呼び出しに効率的な関数キャッシュが必要です。","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합하며, 비싼 계산 또는 외부 서비스 호출에 효율적인 함수 캐싱이 필요합니다.","es":"Perfecto para agentes de IA como Cursor, Windsurf y Claude Code que necesitan una caché de funciones eficiente para cálculos costosos o llamadas a servicios externos.","fr":"Parfait pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant un cache de fonctions efficace pour des calculs coûteux ou des appels de services externes.","de":"Perfekt für KI-Agents wie Cursor, Windsurf und Claude Code, die eine effiziente Funktionscachierung für teure Berechnungen oder Aufrufe externer Dienste benötigen.","pt":"Perfeito para agentes de IA como Cursor, Windsurf e Claude Code que precisam de caching de função eficiente para cálculos caros ou chamadas de serviço externas.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих эффективного кэширования функций для дорогих вычислений или внешних вызовов служб.","ar":"مثالي لعميل الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذي يحتاج إلى تخزين مؤشرات الدالة بشكل فعال للحسابات المكلفة أو مكالمات الخدمة الخارجية."},"recommendation":{"en":"Empowers agents to eliminate redundant computations by storing function results on disk using a decorator-based caching mechanism, ideal for pure functions with dependencies on external services like LLMs, and supporting protocols like disk caching.","zh":"使得代理能够通过使用基于装饰器的缓存机制将函数结果存储在磁盘上，消除冗余计算，特别适用于具有外部服务依赖（如LLMs）的纯函数，并支持诸如磁盘缓存的协议。","ja":"エージェントがデコレーターベースのキャッシュメカニズムを使用して関数結果をディスクに保存することで、冗長な計算を排除し、外部サービス（LLMsなど）に依存する純粋関数に最適です。ディスクキャッシュなどのプロトコルもサポートしています。","ko":"데코레이터 기반 캐싱 메커니즘을 사용하여 함수 결과를 디스크에 저장함으로써, 에이전트가冗余 계산을 제거할 수 있으며, 외부 서비스(예: LLMs)에 의존하는纯函数에 적합하며, 디스크 캐싱과 같은 프로토콜을 지원합니다.","es":"Habilita a los agentes a eliminar cálculos redundantes almacenando los resultados de las funciones en disco mediante un mecanismo de caché basado en decoradores, ideal para funciones puras con dependencias de servicios externos como LLMs y que admiten protocolos como la caché en disco.","fr":"Permet aux agents d''éliminer les calculs redondants en stockant les résultats de fonctions sur disque à l''aide d''un mécanisme de cache basé sur des décorateurs, idéal pour les fonctions pures avec des dépendances de services externes comme les LLM et prenant en charge des protocoles comme la mise en cache sur disque.","de":"Ermöglicht es den Agents, redundante Berechnungen durch Speicherung der Funktionsergebnisse auf der Festplatte mithilfe eines dekoratorbasierten Cachemechanismus zu eliminieren, ideal für reine Funktionen mit Abhängigkeiten von externen Diensten wie LLMs und unterstützt Protokolle wie Disk-Caching.","pt":"Permite que os agentes eliminem computações redundantes armazenando resultados de funções no disco usando um mecanismo de caching baseado em decoradores, ideal para funções puras com dependências de serviços externos como LLMs e suportando protocolos como caching de disco.","ru":"Позволяет агентам исключить избыточные вычисления, храня результаты функций на диске с помощью механизма кэширования на основе декораторов, идеального для чистых функций с зависимостями от внешних служб, таких как LLMs, и поддерживающего протоколы, такие как кэширование на диске.","ar":"يمكن للعميل القضاء على الحسابات الزائدة عن طريق تخزين نتائج الدوال على القرص باستخدام آلية تخزين مؤشرات تعتمد على الزينة، مثالية للدوال النقية التي تعتمد على خدمات خارجية مثل LLMs وداعمة لبروتوكولات مثل تخزين القرص."},"useCases":{"en":["Caching results of expensive calculations","Optimizing external service calls to LLMs","Reducing computation time for pure functions"],"zh":["缓存昂贵计算的结果","优化对LLMs的外部服务调用","减少纯函数的计算时间"],"ja":["高価な計算の結果をキャッシュする","LLMsへの外部サービス呼び出しを最適化する","純粋関数の計算時間を短縮する"],"ko":["비싼 계산 결과 캐싱","LLMs에 대한 외부 서비스 호출 최적화","순수 함수의 계산 시간 단축"],"es":["Almacenar en caché los resultados de cálculos costosos","Optimizar las llamadas a servicios externos a LLMs","Reducir el tiempo de cálculo para funciones puras"],"fr":["Mettre en cache les résultats de calculs coûteux","Optimiser les appels de services externes aux LLM","Réduire le temps de calcul pour les fonctions pures"],"de":["Ergebnisse teurer Berechnungen im Cache speichern","Optimieren von Aufrufen externer Dienste an LLMs","Berechnungszeit für reine Funktionen reduzieren"],"pt":["Armazenar resultados de cálculos caros","Otimizar chamadas de serviço externas para LLMs","Reduzir tempo de computação para funções puras"],"ru":["Кэширование результатов дорогих вычислений","Оптимизация внешних вызовов служб для LLMs","Сокращение времени вычисления для чистых функций"],"ar":["تخزين نتائج الحسابات المكلفة","تحسين مكالمات الخدمة الخارجية إلى LLMs","تقليل وقت الحساب للدوال النقية"]},"limitations":{"en":["Requires disk storage access","Limited to pure functions with no side effects","Python environment required"],"zh":["需要磁盘存储访问","仅限于无副作用的纯函数","需要Python环境"],"ja":["ディスクストレージへのアクセスが必要","副作用のない純粋関数のみ","Python環境が必要"],"ko":["디스크 저장소 액세스가 필요","부작용이 없는 순수 함수로 제한","Python 환경이 필요"],"es":["Requiere acceso al almacenamiento en disco","Limitado a funciones puras sin efectos secundarios","Entorno de Python requerido"],"fr":["Nécessite un accès au stockage sur disque","Limité aux fonctions pures sans effets secondaires","Environnement Python requis"],"de":["Benötigt Zugriff auf die Festplattenspeicherung","Begrenzt auf reine Funktionen ohne Nebeneffekte","Python-Umgebung erforderlich"],"pt":["Requer acesso ao armazenamento de disco","Limitado a funções puras sem efeitos colaterais","Ambiente Python necessário"],"ru":["Требуется доступ к дисковому хранилищу","Ограничен чистыми функциями без побочных эффектов","Требуется среда Python"],"ar":["يتطلب الوصول إلى تخزين القرص","محدود بالدوال النقية بدون آثار جانبية","يتطلب بيئة Python"]},"version":4},"contentHash":"33dec9b69ffd4ae8dbc962d4e805b941c31eb2919c3651ee46eee8c03462ebf5","qualityScore":23}');
