INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('gordonwatts/atlas-mcp/python-function-caching', 'python-function-caching', 'gordonwatts', 'atlas-mcp', 'community', 'python-function-caching gordonwatts atlas-mcp community This Python Function Caching skill provides a decorator-based caching mechanism for pure functions, storing results on disk to eliminate redundant computations. It is designed for developers working with expensive calculations or external service calls like LLMs. Python 函数缓存是一种提高性能的技术，通过缓存纯函数的结果，减少计算和外部服务调用次数 Python 関数キャッシュは、純粋な関数の結果をキャッシュすることで、計算と外部サービス呼び出しの回数を削減します 파이썬 함수 캐싱은 순수 함수의 결과를 캐싱하여 계산과 외부 서비스 호출 횟수를 줄여 성능을 개선합니다 El caché de funciones de Python es una técnica para almacenar los resultados de funciones puras y evitar cálculos costosos Le cache de fonctions Python est une technique pour stocker les résultats de fonctions pures et éviter les calculs coûteux Das Caching von Python-Funktionen ist eine Technik, um die Ergebnisse reiner Funktionen zu speichern und teure Berechnungen zu vermeiden O cache de funções Python é uma técnica para melhorar o desempenho de aplicações com chamadas caras. Ele funciona copiando o conteúdo do arquivo disk_cache.py. Кэширование функций Python - это метод для улучшения производительности приложений с дорогими вызовами. Он работает путем копирования содержимого файла disk_cache.py. ذاكرة التخزين المؤقت للوظائف البايثونية هي تقنية لتحسين أداء التطبيقات مع المكالمات المكلفة. تعمل عن طريق نسخ محتوى ملف disk_cache.py. how to use python function caching what is python-function-caching python disk cache decorator python-function-caching vs functools.lru_cache cache LLM API calls python python-function-caching install python-function-caching setup guide configure disk_cache.py project_name Python 函数缓存 AIエージェント 函数缓存技术 性能优化 计算密集型函数 外部服务调用 缓存路径自定义 Caches function results using a decorator pattern for pure functions Stores cached data on disk in a configurable directory (e.g., `~/.cache/project_name`) Integrates via a provided `disk_cache.py` module file Requires manual configuration of the `project_name` variable within the cache instance Optimizes performance for expensive calls like LLM API requests or heavy calculations python-function-caching is a developer skill that implements a disk-based cache decorator for Python functions. It is intended for pure functions that depend solely on their inputs, caching results to avoid re-running expensive operations like complex calculations or calls to external APIs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mplemay/brussels/commit-and-push', 'community', 'mplemay', 'brussels', 'mplemay/brussels', 'commit-and-push', 0, 0, 23, '2026-03-08T01:57:15.426Z', '2026-03-08T02:07:29.331Z', '68093abe6ff14905c1407901ec3e905a68c6840d3165677c13c9ce6b6ccfe45b', '{"id":"mplemay/brussels/commit-and-push","name":"commit-and-push","description":{"en":"The commit-and-push skill automates testing and deployment for developers, using pytest for unit and integration tests. It benefits developers by validating changes and pushing code.","zh":"commit-and-push 是一个自动化 AI 代理技能，用于在代码提交前运行 pytest 测试套件，自动修复失败用例，并遵循约定式提交规范将更改推送至 Git 仓库。","ja":"commit-and-push は、コードコミット前に pytest テストスイートを実行し、失敗したテストケースを自動修正し、規約に準拠したコミットを作成して Git リポジトリにプッシュする自動化 AIエージェントスキルです。","ko":"commit-and-push는 코드 커밋 전에 pytest 테스트 스위트를 실행하고, 실패한 테스트 케이스를 자동으로 수정하며, 규약 커밋을 생성해 Git 저장소로 푸시하는 자동화 AI 에이전트 스킬입니다.","es":"Este flujo de trabajo de commit y push utiliza Pytest para validar cambios y crear commits convencionales","fr":"Ce workflow de commit et push utilise Pytest pour valider les modifications et créer des commits conventionnels","de":"Dieser Commit- und Push-Workflow verwendet Pytest, um Änderungen zu überprüfen und konventionelle Commits zu erstellen","pt":"O commit e push é uma ferramenta de automação que valida alterações, corrige falhas e cria commits convencionais. Aprenda a configurá-la para melhorar a produtividade do seu time","ru":"Коммит и пуш - это инструмент автоматизации, который проверяет изменения, исправляет ошибки и создает конвенциональные коммиты. Узнайте, как настроить его для повышения производительности вашей команды","ar":"Commit و Push هو أداة أتمتة لتحقق التغييرات وتصحيح الأخطاء وإنشاء إلتزامات تقليدية. تعلم كيفية تهيئته لتحسين إنتاجية فريقك"},"seo":{"title":{"en":"commit-and-push: Automated Testing and Deployment Setup G...","zh":"commit-and-push AI 代理设置指南：自动化测试与 Git 推送","ja":"commit-and-push AIエージェントのベストプラクティス：自動テストとGitプッシュ","ko":"commit-and-push AI 에이전트 설정 가이드: 자동화된 테스트 및 Git 푸시","es":"Guía de Configuración de Commit y Push con Pytest","fr":"Guide de Configuration de Commit et Push avec Pytest","de":"Einrichtungsleitfaden für Commit und Push mit Pytest","pt":"Guia de Configuração do Commit e Push para Desenvolvedores","ru":"Настройка коммита и пуша: ИИ Агенты для автоматизации","ar":"دليل إعداد Commit و Push لمنصة الفريق"},"description":{"en":"Streamline your development workflow with commit-and-push, automating tests and deployments. Learn how to set up and use this AI agent skill today!","zh":"专为开发者设计的 commit-and-push AI 代理工作流，使用 uv 和 pytest 自动化运行测试、修复代码、创建约定式提交并推送至 Git 仓库，提升开发效率。","ja":"開発者向け commit-and-push AIエージェントワークフロー。uv と pytest を使用してテストの自動実行、コード修正、規約コミットの作成、Gitリポジトリへのプッシュを自動化し、開発効率を向上させます。","ko":"개발자를 위한 commit-and-push AI 에이전트 워크플로우입니다. uv와 pytest를 사용하여 테스트 자동 실행, 코드 수정, 규약 커밋 생성, Git 저장소 푸시를 자동화하여 개발 효율성을 높입니다.","es":"Aprende a validar cambios, solucionar errores y crear commits convencionales con este flujo de trabajo de commit y push","fr":"Découvrez comment valider les modifications, résoudre les échecs et créer des commits conventionnels avec ce workflow de commit et push","de":"Erfahren Sie, wie Sie Änderungen überprüfen, Fehler beheben und konventionelle Commits erstellen können, mit diesem Commit- und Push-Workflow","pt":"Aprenda a configurar o commit e push com testes automatizados e convenções de commit. Melhore a produtividade do seu time com essa ferramenta de automação","ru":"Узнайте, как настроить коммит и пуш с автоматизированными тестами и конвенциями коммита. Повысьте производительность вашей команды с помощью ИИ Агентов","ar":"تعلم كيفية تهيئة Commit و Push مع الاختبارات الآلية وتوافق الإلتزام. تحسين إنتاجية فريقك مع منصة الفريق"},"definition":{"en":"commit-and-push is a workflow automation skill that validates changes, runs tests using pytest, and pushes code, following a conventional commit format.","zh":"commit-and-push 是一个 AI 代理工作流技能，它使用 uv 工具运行 pytest 测试，自动修复测试失败，创建符合约定的 Git 提交消息，并将代码更改推送至远程版本库。","ja":"commit-and-push は、uv ツールを使用して pytest テストを実行し、テストの失敗を自動修正し、規約に準拠した Git コミットメッセージを作成し、コード変更をリモートリポジトリにプッシュする AIエージェントワークフロースキルです。","ko":"commit-and-push는 uv 도구로 pytest 테스트를 실행하고, 테스트 실패를 자동 수정하며, 규약을 준수하는 Git 커밋 메시지를 생성한 후 코드 변경 사항을 원격 저장소로 푸시하는 AI 에이전트 워크플로우 스킬입니다.","es":"Un flujo de trabajo de commit y push es una secuencia de pasos para validar cambios y crear commits convencionales","fr":"Un workflow de commit et push est une séquence d''étapes pour valider les modifications et créer des commits conventionnels","de":"Ein Commit- und Push-Workflow ist eine Sequenz von Schritten zur Überprüfung von Änderungen und Erstellung konventioneller Commits","pt":"O commit e push é uma ferramenta de automação que executa testes automatizados e cria commits convencionais","ru":"Коммит и пуш - это инструмент автоматизации, который выполняет автоматизированные тесты и создает конвенциональные коммиты","ar":"Commit و Push هو أداة أتمتة لتنفيذ الاختبارات الآلية وإنشاء إلتزامات تقليدية"},"features":{"en":["Runs unit and integration tests using pytest","Fixes code and test failures based on test results","Creates conventional commits following a standard format","Pushes validated code changes","Uses pyproject.toml for pytest settings","Organizes tests in a mirror layout of the source code"],"zh":["使用 `uv run pytest` 命令执行自动化测试","自动检测并修复测试失败，直至通过","测试文件位于 `src/belgie/__test__/` 目录并镜像源代码结构","单元测试使用匹配的文件名，集成测试使用 `_integration` 后缀","测试函数必须以 `test_` 前缀命名","Pytest 配置位于 `pyproject.toml` 文件中"],"ja":["`uv run pytest` コマンドを使用した自動テストの実行","テスト失敗の自動検出と修正（成功するまで）","テストファイルは `src/belgie/__test__/` ディレクトリに配置され、ソースコード構造をミラーリング","ユニットテストは一致するファイル名を使用し、結合テストは `_integration` サフィックスを使用","テスト関数は `test_` プレフィックスで命名必須","Pytest 設定は `pyproject.toml` ファイル内に定義"],"ko":["`uv run pytest` 명령어를 사용한 자동화 테스트 실행","테스트 실패 자동 감지 및 수정 (성공할 때까지)","테스트 파일은 `src/belgie/__test__/` 디렉토리에 위치하며 소스 코드 구조를 미러링","단위 테스트는 일치하는 파일명 사용, 통합 테스트는 `_integration` 접미사 사용","테스트 함수는 `test_` 접두사로命名 필수","Pytest 설정은 `pyproject.toml` 파일 내에 정의됨"],"es":["Ejecución de pruebas unitarias e integradas con Pytest","Validación de cambios y creación de commits convencionales","Configuración de Pytest en pyproject.toml","Soporte para pruebas unitarias y de integración","Uso de funciones de prueba con prefijo test_"],"fr":["Exécution de tests unitaires et d''intégration avec Pytest","Validation des modifications et création de commits conventionnels","Configuration de Pytest dans pyproject.toml","Prise en charge des tests unitaires et d''intégration","Utilisation de fonctions de test avec préfixe test_"],"de":["Ausführung von Einheitstests und Integrationstests mit Pytest","Überprüfung von Änderungen und Erstellung konventioneller Commits","Konfiguration von Pytest in pyproject.toml","Unterstützung für Einheitstests und Integrationstests","Verwendung von Testfunktionen mit Präfix test_"],"pt":["Executa testes automatizados com Pytest","Corrige falhas e cria commits convencionais","Valida alterações e executa testes em src/belgie/__test__/","Suporta testes unitários e de integração","Utiliza configurações de Pytest em pyproject.toml"],"ru":["Выполняет автоматизированные тесты с помощью Pytest","Исправляет ошибки и создает конвенциональные коммиты","Проверяет изменения и выполняет тесты в src/belgie/__test__/","Поддерживает юнит-тесты и тесты интеграции","Использует настройки Pytest в pyproject.toml"],"ar":["ينفذ الاختبارات الآلية مع Pytest","يصلح الأخطاء وينشئ إلتزامات تقليدية","يحقق التغييرات وينفذ الاختبارات في src/belgie/__test__/","يدعم الاختبارات الوحدة واختبارات الإندماج","يستخدم إعدادات Pytest في pyproject.toml"]},"keywords":{"en":["how to use commit-and-push","commit-and-push setup guide","automated testing with pytest","conventional commit format","commit-and-push alternative","commit-and-push vs git flow","install commit-and-push","commit-and-push for developers","pytest integration testing"],"zh":["commit-and-push AI 代理","uv pytest 自动化测试","Python 测试自动化工作流","约定式提交 Git 代理","AI 代理自动修复测试","pyproject.toml pytest 配置","belgie 测试目录结构","集成测试 _integration 后缀"],"ja":["commit-and-push AIエージェント","uv pytest 自動テスト","Python テスト自動化ワークフロー","規約コミット Git エージェント","AIエージェント 自動テスト修正","pyproject.toml pytest 設定","belgie テストディレクトリ構造","結合テスト _integration サフィックス"],"ko":["commit-and-push AI 에이전트","uv pytest 자동화 테스트","Python 테스트 자동화 워크플로우","규약 커밋 Git 에이전트","AI 에이전트 자동 테스트 수정","pyproject.toml pytest 설정","belgie 테스트 디렉토리 구조","통합 테스트 _integration 접미사"],"es":["commit y push","pytest","pruebas unitarias","pruebas de integración","commits convencionales","flujo de trabajo de commit y push","configuración de pytest","pyproject.toml","herramientas de desarrollo"],"fr":["commit et push","pytest","tests unitaires","tests d''intégration","commits conventionnels","workflow de commit et push","configuration de pytest","pyproject.toml","outils de développement"],"de":["commit und push","pytest","einheitstests","integrationstests","konventionelle commits","commit- und push-workflow","konfiguration von pytest","pyproject.toml","entwicklertools"],"pt":["commit e push","automatizar commit","pytest","testes automatizados","convenções de commit","produtividade do time","ferramentas de automação","desenvolvimento de software"],"ru":["коммит и пуш","автоматизация коммита","pytest","автоматизированные тесты","конвенции коммита","производительность команды","инструменты автоматизации","разработка программного обеспечения"],"ar":["commit و push","أتمتة commit","pytest","اختبارات آلية","توافق إلتزام","إنتاجية الفريق","أدوات أتمتة","تطوير البرمجيات"]}},"owner":"mplemay","repo":"brussels","repoPath":"mplemay/brussels","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.426Z","topics":[],"category":"community","skillMd":{"name":"commit-and-push","description":"Run the repos finalize workflow (uv pytest, pre-commit with per-hook fixes, conventional commit, git push). Use when asked to run tests/lint, fix hook failures, commit changes, or push updates.","bodyPreview":"# Commit And Push\n\n## Overview\n\nUse this workflow to validate changes, fix failures, create a conventional commit, and push.\n\n## Workflow\n\n### 1) Run tests\n\n- Run `uv run pytest`.\n- If tests fail, fix the code/tests and re-run until green.\n- Tests live in `src/belgie/__test__/`; mirror the source layout.\n- Unit tests use the matching file name; integration tests use `_integration` suffix.\n- Test functions must be prefixed with `test_`.\n- Pytest settings live in `pyproject.toml`.\n- If failures ar","body":"# Commit And Push\n\n## Overview\n\nUse this workflow to validate changes, fix failures, create a conventional commit, and push.\n\n## Workflow\n\n### 1) Run tests\n\n- Run `uv run pytest`.\n- If tests fail, fix the code/tests and re-run until green.\n- Tests live in `src/belgie/__test__/`; mirror the source layout.\n- Unit tests use the matching file name; integration tests use `_integration` suffix.\n- Test functions must be prefixed with `test_`.\n- Pytest settings live in `pyproject.toml`.\n- If failures are unrelated or require product decisions, stop and ask.\n\n### 2) Run pre-commit and fix hooks\n\n- Run `uv run pre-commit run --all`.\n- For each failing hook:\n  - Diagnose the root cause and fix it directly.\n  - Avoid ignores unless the issue is a true edge case or false positive.\n  - Re-run only the failing hook by name: `uv run pre-commit run <hook-name> --all`.\n  - If hooks conflict (format vs. lint), resolve the underlying formatting/code issue, then re-run the affected hooks.\n- When all hooks pass, run `uv run pre-commit run --all` again to confirm.\n- Ruff is the linter; rules are in `pyproject.toml`.\n- Type checking uses `ty`. Use specific ignores only when needed, e.g. `# ty: ignore[attr-defined]` with a short reason\n  when not obvious.\n- Pre-commit configuration is in `.pre-commit-config.yaml`.\n\n### 3) Commit\n\n- Ensure tests and pre-commit pass before committing.\n- Use a conventional commit message (single line, lowercase, <72 chars when possible).\n- If needed, inspect changes to choose the correct type: `git status -sb`, `git diff --stat`.\n- If the changes are already known, skip `git status` and `git diff` and choose the type directly.\n- Examples: `feat: added config validator with schema builder`, `fix: corrected validation error message formatting`.\n- Avoid multi-line messages or vague subjects.\n- Branch names should be kebab-case and prefixed: `feature/`, `bugfix/`, `refactor/`, `docs/`, `test/`.\n\n### 4) Push\n\n- Push with `git push` (autoSetupRemote/autoSetupMerge is configured).\n"},"lastSynced":"2026-03-08T02:07:29.331Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents requiring automated testing and deployment workflows.","zh":"非常适合需要自动化测试和部署工作流程的 Python Development Agents。","ja":"自動テストとデプロイメントワークフローを必要とする Python Development Agents に最適です。","ko":"자동화된 테스트 및 배포 워크플로우가 필요한 Python Development Agents에 완벽합니다.","es":"Ideal para Agentes de Desarrollo de Python que requieren flujos de trabajo de prueba y despliegue automatizados.","fr":"Parfait pour les Agents de Développement Python nécessitant des flux de travail de test et de déploiement automatisés.","de":"Perfekt für Python-Entwicklungsagenten, die automatisierte Test- und Deploy-Workflows erfordern.","pt":"Perfeito para Agentes de Desenvolvimento Python que requerem fluxos de trabalho automatizados de teste e implantação.","ru":"Идеально подходит для Агентов Разработки на Python, требующих автоматизированных процессов тестирования и развертывания.","ar":"مثالي لوكلاء تطوير Python التي تتطلب سير عمل اختبار ونشر تلقائي."},"recommendation":{"en":"Enables automated pytest execution for unit and integration tests, validates code changes against test suites in src/belgie/__test__/, and performs conventional commits with push operations. Provides continuous integration capabilities directly within the development workflow.","zh":"支持为单元测试和集成测试自动执行 pytest，针对 src/belgie/__test__/ 中的测试套件验证代码更改，并执行包含 push 操作的常规提交。直接在开发工作流程中提供持续集成功能。","ja":"単体テストと統合テストのための pytest 実行の自動化を可能にし、src/belgie/__test__/ 内のテストスイートに対してコード変更を検証し、プッシュ操作を含むコンベンショナルコミットを実行します。開発ワークフロー内で直接継続的インテグレーション機能を提供します。","ko":"단위 및 통합 테스트를 위한 자동화된 pytest 실행을 가능하게 하며, src/belgie/__test__/ 내의 테스트 스위트에 대해 코드 변경 사항을 검증하고, 푸시 작업이 포함된 컨벤셔널 커밋을 수행합니다. 개발 워크플로우 내에서 직접 지속적 통합 기능을 제공합니다.","es":"Habilita la ejecución automática de pytest para pruebas unitarias y de integración, valida los cambios de código contra conjuntos de pruebas en src/belgie/__test__/ y realiza commits convencionales con operaciones de push. Proporciona capacidades de integración continua directamente dentro del flujo de trabajo de desarrollo.","fr":"Permet l''exécution automatisée de pytest pour les tests unitaires et d''intégration, valide les modifications de code contre des suites de tests dans src/belgie/__test__/ et effectue des commits conventionnels avec des opérations de push. Fournit des capacités d''intégration continue directement dans le flux de travail de développement.","de":"Ermöglicht die automatische Ausführung von pytest für Einheit- und Integrations-tests, validiert Code-Änderungen gegen Test-Suiten in src/belgie/__test__/ und führt konventionelle Commits mit Push-Operationen aus. Bietet kontinuierliche Integration-Fähigkeiten direkt innerhalb des Entwicklungs-Workflows.","pt":"Permite a execução automatizada do pytest para testes de unidade e integração, valida alterações de código em relação aos conjuntos de testes em src/belgie/__test__/, e realiza commits convencionais com operações de push. Fornece capacidades de integração contínua diretamente dentro do fluxo de trabalho de desenvolvimento.","ru":"Обеспечивает автоматизированное выполнение pytest для модульных и интеграционных тестов, проверяет изменения кода на соответствие наборам тестов в src/belgie/__test__/ и выполняет conventional commits с операциями push. Обеспечивает возможности непрерывной интеграции непосредственно в рабочем процессе разработки.","ar":"يتيح التنفيذ التلقائي لـ pytest لاختبارات الوحدة والتكامل، يتحقق من صحة تغييرات الكود مقابل مجموعات الاختبار في src/belgie/__test__/، وينفذ عمليات الالتزام التقليدية (conventional commits) مع عمليات الدفع (push). يوفر إمكانيات التكامل المستمر مباشرة داخل سير عمل التطوير."},"useCases":{"en":["Automating test validation before commits","Running unit tests with matching file name patterns","Executing integration tests with _integration suffix","Performing conventional commit creation","Pushing validated code changes to repositories"],"zh":["在提交前自动进行测试验证","运行具有匹配文件名模式的单元测试","执行带有 _integration 后缀的集成测试","执行常规提交创建","将经过验证的代码更改推送到代码库"],"ja":["コミット前のテスト検証の自動化","一致するファイル名パターンでの単体テストの実行","_integration サフィックス付きの統合テストの実行","コンベンショナルコミットの作成の実行","検証済みのコード変更をリポジトリにプッシュ"],"ko":["커밋 전 테스트 검증 자동화","일치하는 파일명 패턴으로 단위 테스트 실행","_integration 접미사가 있는 통합 테스트 실행","컨벤셔널 커밋 생성 수행","검증된 코드 변경 사항을 저장소로 푸시"],"es":["Automatizar la validación de pruebas antes de los commits","Ejecutar pruebas unitarias con patrones de nombres de archivo coincidentes","Ejecutar pruebas de integración con sufijo _integration","Crear commits convencionales","Push de cambios de código validados a los repositorios"],"fr":["Automatiser la validation des tests avant les commits","Exécuter des tests unitaires avec des modèles de noms de fichiers correspondants","Exécuter des tests d''intégration avec le suffixe _integration","Créer des commits conventionnels","Push des modifications de code validées vers les référentiels"],"de":["Automatisieren der Test-Validierung vor Commits","Ausführen von Einheit-Tests mit übereinstimmenden Dateinamensmustern","Ausführen von Integrations-Tests mit _integration-Suffix","Erstellen von konventionellen Commits","Push von validierten Code-Änderungen an die Repositorys"],"pt":["Automatização da validação de testes antes dos commits","Execução de testes de unidade com padrões de nome de arquivo correspondentes","Execução de testes de integração com sufixo _integration","Criação de commits convencionais","Push de alterações de código validadas para repositórios"],"ru":["Автоматизация проверки тестов перед коммитами","Запуск модульных тестов с соответствующими шаблонами имен файлов","Выполнение интеграционных тестов с суффиксом _integration","Создание conventional commits","Отправка проверенных изменений кода в репозитории"],"ar":["أتمتة التحقق من صحة الاختبار قبل عمليات الالتزام (commits)","تشغيل اختبارات الوحدة بأنماط أسماء ملفات مطابقة","تنفيذ اختبارات التكامل مع اللاحقة _integration","إنشاء عمليات الالتزام التقليدية (conventional commits)","دفع تغييرات الكود التي تم التحقق منها إلى المستودعات"]},"limitations":{"en":["Requires pytest configuration in pyproject.toml","Depends on uv package manager for test execution","Test functions must follow test_ prefix convention","Test directory structure must mirror source layout"],"zh":["需要在 pyproject.toml 中配置 pytest","测试执行依赖于 uv 包管理器","测试函数必须遵循 test_ 前缀约定","测试目录结构必须镜像源代码布局"],"ja":["pyproject.toml での pytest の設定が必要","テスト実行は uv パッケージマネージャーに依存","テスト関数は test_ プレフィックスの規則に従う必要がある","テストディレクトリ構造はソースレイアウトを反映している必要がある"],"ko":["pyproject.toml에서 pytest 구성이 필요함","테스트 실행을 위해 uv 패키지 관리자에 의존","테스트 함수는 test_ 접두사 규칙을 따라야 함","테스트 디렉토리 구조는 소스 레이아웃을 반영해야 함"],"es":["Requiere configuración de pytest en pyproject.toml","Depende del administrador de paquetes uv para la ejecución de pruebas","Las funciones de prueba deben seguir la convención de prefijo test_","La estructura del directorio de pruebas debe reflejar la disposición de la fuente"],"fr":["Nécessite une configuration de pytest dans pyproject.toml","Dépend du gestionnaire de paquets uv pour l''exécution des tests","Les fonctions de test doivent suivre la convention de préfixe test_","La structure du répertoire de tests doit refléter la disposition de la source"],"de":["Benötigt pytest-Konfiguration in pyproject.toml","Hängt vom uv-Paket-Manager für die Test-Ausführung ab","Test-Funktionen müssen die test_-Präfix-Konvention befolgen","Die Test-Verzeichnisstruktur muss der Quell-Layout widerspiegeln"],"pt":["Requer configuração do pytest no pyproject.toml","Depende do gerenciador de pacotes uv para execução de testes","As funções de teste devem seguir a convenção do prefixo test_","A estrutura do diretório de testes deve espelhar o layout da fonte"],"ru":["Требует настройки pytest в pyproject.toml","Зависит от менеджера пакетов uv для выполнения тестов","Тестовые функции должны следовать соглашению о префиксе test_","Структура тестового каталога должна зеркально отражать структуру исходного кода"],"ar":["يتطلب تكوين pytest في ملف pyproject.toml","يعتمد على مدير الحزم uv لتنفيذ الاختبار","يجب أن تتبع دوال الاختبار اصطلاح البادئة test_","يجب أن تعكس بنية دليل الاختبار تخطيط المصدر"]},"version":4},"contentHash":"68093abe6ff14905c1407901ec3e905a68c6840d3165677c13c9ce6b6ccfe45b","qualityScore":23}');
