INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mplemay/brussels/commit-and-push', 'commit-and-push', 'mplemay', 'brussels', 'community', 'commit-and-push mplemay brussels community The commit-and-push skill automates testing and deployment for developers, using pytest for unit and integration tests. It benefits developers by validating changes and pushing code. commit-and-push 是一个自动化 AI 代理技能，用于在代码提交前运行 pytest 测试套件，自动修复失败用例，并遵循约定式提交规范将更改推送至 Git 仓库。 commit-and-push は、コードコミット前に pytest テストスイートを実行し、失敗したテストケースを自動修正し、規約に準拠したコミットを作成して Git リポジトリにプッシュする自動化 AIエージェントスキルです。 commit-and-push는 코드 커밋 전에 pytest 테스트 스위트를 실행하고, 실패한 테스트 케이스를 자동으로 수정하며, 규약 커밋을 생성해 Git 저장소로 푸시하는 자동화 AI 에이전트 스킬입니다. Este flujo de trabajo de commit y push utiliza Pytest para validar cambios y crear commits convencionales Ce workflow de commit et push utilise Pytest pour valider les modifications et créer des commits conventionnels Dieser Commit- und Push-Workflow verwendet Pytest, um Änderungen zu überprüfen und konventionelle Commits zu erstellen O commit e push é uma ferramenta de automação que valida alterações, corrige falhas e cria commits convencionais. Aprenda a configurá-la para melhorar a produtividade do seu time Коммит и пуш - это инструмент автоматизации, который проверяет изменения, исправляет ошибки и создает конвенциональные коммиты. Узнайте, как настроить его для повышения производительности вашей команды Commit و Push هو أداة أتمتة لتحقق التغييرات وتصحيح الأخطاء وإنشاء إلتزامات تقليدية. تعلم كيفية تهيئته لتحسين إنتاجية فريقك how to use commit-and-push commit-and-push setup guide automated testing with pytest conventional commit format commit-and-push alternative commit-and-push vs git flow install commit-and-push commit-and-push for developers pytest integration testing commit-and-push AI 代理 uv pytest 自动化测试 Python 测试自动化工作流 约定式提交 Git 代理 AI 代理自动修复测试 pyproject.toml pytest 配置 belgie 测试目录结构 集成测试 _integration 后缀 Runs unit and integration tests using pytest Fixes code and test failures based on test results Creates conventional commits following a standard format Pushes validated code changes Uses pyproject.toml for pytest settings Organizes tests in a mirror layout of the source code commit-and-push is a workflow automation skill that validates changes, runs tests using pytest, and pushes code, following a conventional commit format.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Chronote-gg/Chronote/investigate-and-plan', 'community', 'Chronote-gg', 'Chronote', 'Chronote-gg/Chronote', 'investigate-and-plan', 0, 0, 23, '2026-03-08T01:57:15.431Z', '2026-03-08T02:07:32.783Z', '17288fe84b952637175e5560bbc78a2e1ea5aa2b2483de59eb539b10f50385e8', '{"id":"Chronote-gg/Chronote/investigate-and-plan","name":"investigate-and-plan","description":{"en":"The investigate-and-plan skill helps developers research external sources, inspect codebase areas, and create a plan for changesets. It benefits developers by streamlining the investigation process.","zh":"Investigate And Plan技能用于记录和转录对话、调查请求和研究外部源，使用GitHub CLI和代码库检查","ja":"Investigate And Planスキルは、会話の記録と転記、リクエストの調査、外部ソースのリサーチに使用され、GitHub CLIとコードベースの検査を使用","ko":"Investigate And Plan 스킬은 대화 기록과 전사, 요청 조사 및 외부 소스 연구에 사용되며 GitHub CLI 및 코드베이스 검사를 사용","es":"La habilidad investigate-and-plan permite investigar solicitudes, buscar fuentes externas y código, y crear un plan antes de escribir código para Discord","fr":"La compétence investigate-and-plan permet d''enquêter sur les demandes, de rechercher des sources externes et du code, et de créer un plan avant d''écrire du code pour Discord","de":"Die Fähigkeit investigate-and-plan ermöglicht die Untersuchung von Anfragen, die Suche nach externen Quellen und Code sowie die Erstellung eines Plans vor dem Schreiben von Code für Discord","pt":"O Investigate-and-Plan é uma habilidade que ajuda a investigar solicitações e produzir planos para alterações no código","ru":"Investigate-and-Plan - это навык, помогающий исследовать запросы и производить планы для изменений в коде","ar":"Investigate-and-Plan هو مهارة تساعد على التحقيق في الطلبات وإنتاج خطط لتغييرات في الكود"},"seo":{"title":{"en":"investigate-and-plan: Code Investigation Setup Guide | AI...","zh":"Investigate And Plan 设置指南 - AI工具","ja":"Investigate And Plan 導入ガイド - AIエージェント","ko":"Investigate And Plan 설정 가이드 - AI 에이전트","es":"Guía de configuración para investigate-and-plan: Agentes ...","fr":"Guide de démarrage pour investigate-and-plan: Outils d''IA...","de":"Einrichtungsleitfaden für investigate-and-plan: KI-Tools ...","pt":"Guia de Configuração do Investigate-and-Plan para Ferrame...","ru":"Настройка ИИ Агентов: Руководство по Investigate-and-Plan","ar":"دليل إعداد Investigate-and-Plan لأدوات الذكاء الاصطناعي"},"description":{"en":"Unlock efficient code review with investigate-and-plan. Learn how to confirm scope, gather context, and produce a plan for changesets before writing code.","zh":"了解Investigate And Plan技能的技术细节，包括GitHub CLI、代码库检查和对话记录","ja":"Investigate And Planスキルの技術的詳細を学びます。GitHub CLI、コードベースの検査、会話の記録など","ko":"Investigate And Plan 스킬의 기술적 세부 사항을 알아보세요. GitHub CLI, 코드베이스 검사, 대화 기록 등","es":"Aprende a utilizar la habilidad investigate-and-plan para registrar y transcribir conversaciones en Discord con GitHub CLI y código abierto","fr":"Découvrez comment utiliser la compétence investigate-and-plan pour enregistrer et transcrire des conversations sur Discord avec GitHub CLI et code ouvert","de":"Erfahren Sie, wie Sie die Fähigkeit investigate-and-plan verwenden, um Gespräche in Discord mit GitHub CLI und Open-Source-Code aufzuzeichnen und zu transkri...","pt":"Aprenda a configurar o Investigate-and-Plan para Ferramentas de IA e melhore o desenvolvimento de software com nossa guia passo a passo","ru":"Узнайте, как настроить Investigate-and-Plan для ИИ Агентов и улучшить разработку программного обеспечения с нашей пошаговой инструкцией","ar":"تعرف على كيفية إعداد Investigate-and-Plan لأدوات الذكاء الاصطناعي وتحسين تطوير البرمجيات مع دليلنا الخطوة بخطوة"},"definition":{"en":"investigate-and-plan is a skill that enables thorough code investigation, research, and planning for changesets, utilizing tools like the GitHub CLI.","zh":"Investigate And Plan是一种AI工具技能，用于记录和转录对话、调查请求和研究外部源","ja":"Investigate And Planは、会話の記録と転記、リクエストの調査、外部ソースのリサーチを行うAIエージェントスキル","ko":"Investigate And Plan은 대화 기록과 전사, 요청 조사 및 외부 소스 연구를 수행하는 AI 에이전트 스킬","es":"Investigate-and-plan es una habilidad de agente de IA que investiga y planea cambios en el código antes de implementarlos","fr":"Investigate-and-plan est une compétence d''outil d''IA qui enquête et planifie des modifications de code avant de les mettre en œuvre","de":"Investigate-and-plan ist eine Fähigkeit von KI-Tools, die Untersuchungen und Planungen von Codeänderungen durchführt, bevor sie implementiert","pt":"O que é Investigate-and-Plan? É uma habilidade de IA que investiga e planeja alterações no código","ru":"Что такое Investigate-and-Plan? Это навык ИИ, исследующий и планирующий изменения в коде","ar":"ما هو Investigate-and-Plan؟ هو مهارة ذكاء اصطناعي تحقق وتخطط لتغييرات في الكود"},"features":{"en":["Confirms scope and gathers context using GitHub CLI","Identifies exact errors, feature ideas, or decisions to investigate","Lists codebase areas to inspect for changeset planning","Produces a plan for changesets before writing code","Asks open clarifying questions with defaults for efficient investigation","Implements changes only after the plan is agreed upon"],"zh":["使用GitHub CLI获取PR和Issue详情","代码库检查和错误识别","记录和转录Discord对话","研究外部源和决策","生成changeset计划"],"ja":["GitHub CLIを使用してPRとIssueの詳細を取得","コードベースの検査とエラーの識別","Discordの会話の記録と転記","外部ソースのリサーチと意思決定","changesetプランの生成"],"ko":["GitHub CLI를 사용하여 PR 및 Issue 세부 정보 가져오기","코드베이스 검사 및 오류 식별","Discord 대화 기록 및 전사","외부 소스 연구 및 의사 결정","changeset 계획 생성"],"es":["Investigación de solicitudes y búsqueda de fuentes externas","Uso de GitHub CLI para obtener detalles y comentarios","Creación de un plan de cambios antes de escribir código","Identificación de áreas del código para inspeccionar","Implementación de preguntas abiertas y aclaratorias con valores predeterminados"],"fr":["Enquête sur les demandes et recherche de sources externes","Utilisation de GitHub CLI pour obtenir des détails et des commentaires","Création d''un plan de modifications avant d''écrire du code","Identification des zones de code à inspecter","Mise en œuvre de questions ouvertes et clarificatrices avec des valeurs par défaut"],"de":["Untersuchung von Anfragen und Suche nach externen Quellen","Verwendung von GitHub CLI, um Details und Kommentare zu erhalten","Erstellung eines Plans für Codeänderungen vor dem Schreiben von Code","Identifizierung von Codebereichen zur Inspektion","Implementierung offener und klärender Fragen mit Standardwerten"],"pt":["Confirmação do escopo e coleta de contexto","Uso do GitHub CLI para buscar detalhes e comentários","Listagem de áreas do código para inspecionar","Implementação de perguntas abertas e clarificadoras","Criação de um plano para alterações no código"],"ru":["Подтверждение объема и сбор контекста","Использование GitHub CLI для поиска деталей и комментариев","Перечисление областей кода для инспекции","Реализация открытых и разъяснительных вопросов","Создание плана для изменений в коде"],"ar":["التأكد من النطاق وجمع السياق","استخدام GitHub CLI للبحث عن التفاصيل والتعليقات","قائمة بمناطق الكود للتفتيش","تنفيذ أسئلة مفتوحة وواضحة","إنشاء خطة لتغييرات في الكود"]},"keywords":{"en":["how to use investigate-and-plan","investigate-and-plan alternative","investigate-and-plan setup guide","what is investigate-and-plan","investigate-and-plan vs code review tools","investigate-and-plan install","github cli investigate-and-plan","code investigation best practices","investigate-and-plan for ai agents","investigate-and-plan workflow optimization"],"zh":["Investigate And Plan","AI工具","GitHub CLI","代码库检查","对话记录","外部源研究","changeset计划","Discord对话转录"],"ja":["Investigate And Plan","AIエージェント","GitHub CLI","コードベースの検査","会話の記録","外部ソースのリサーチ","changesetプラン","Discord会話の転記"],"ko":["Investigate And Plan","AI 에이전트","GitHub CLI","코드베이스 검사","대화 기록","외부 소스 연구","changeset 계획","Discord 대화 전사"],"es":["agentes de ia para discord","investigate and plan","github cli","código abierto","desarrollo de software","planificación de cambios","investigación de solicitudes","discord bot"],"fr":["outils d''ia pour discord","investigate and plan","github cli","code ouvert","développement de logiciels","planification de modifications","enquête sur les demandes","discord bot"],"de":["ki-tools für discord","investigate and plan","github cli","open-source-code","softwareentwicklung","änderungsplanung","anfrageuntersuchung","discord bot"],"pt":["Investigate-and-Plan","Ferramentas de IA","Desenvolvimento de software","GitHub CLI","Planejamento de código","Investigação de solicitações"],"ru":["Investigate-and-Plan","ИИ Агенты","Разработка программного обеспечения","GitHub CLI","Планирование кода","Исследование запросов"],"ar":["Investigate-and-Plan","أدوات الذكاء الاصطناعي","تطوير البرمجيات","GitHub CLI","تخطيط الكود","تحقيق الطلبات"]}},"owner":"Chronote-gg","repo":"Chronote","repoPath":"Chronote-gg/Chronote","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.431Z","topics":[],"category":"community","skillMd":{"name":"investigate-and-plan","description":"Investigate errors, incidents, or product ideas using both internet research and repo-wide codebase research, then propose a concrete changeset plan with clarifying questions before any implementation. Use when a user asks to investigate, root-cause, or plan changes, or when an Issue or PR is referenced and needs a plan.","bodyPreview":"# Investigate And Plan\n\n## Overview\n\nInvestigate the request, research external sources and the codebase, and produce a plan for a changeset before writing code. Ask open clarifying questions with defaults, then implement only after the plan is agreed.\n\n## Workflow\n\n### 1) Confirm scope and gather context\n\n- Identify the exact error, feature idea, or decision to investigate.\n- If a PR or Issue is referenced, use the GitHub CLI to fetch details and comments.\n- List the codebase areas to inspect,","body":"# Investigate And Plan\n\n## Overview\n\nInvestigate the request, research external sources and the codebase, and produce a plan for a changeset before writing code. Ask open clarifying questions with defaults, then implement only after the plan is agreed.\n\n## Workflow\n\n### 1) Confirm scope and gather context\n\n- Identify the exact error, feature idea, or decision to investigate.\n- If a PR or Issue is referenced, use the GitHub CLI to fetch details and comments.\n- List the codebase areas to inspect, including backend, frontend, bot, infra, scripts, tests, docs, and configuration.\n\n### 2) Research\n\n- Use web.run for internet research, then cite sources for any external facts.\n- Search the codebase broadly with targeted deep dives into relevant subsystems.\n- Capture findings, constraints, and risks, including any existing TODOs or comments.\n\n### 3) Propose the changeset\n\n- Provide a concrete plan with files to touch, key edits, data migrations, and test updates.\n- Call out assumptions and viable alternatives.\n- Ask open questions that block implementation, and provide defaults for each question.\n- Do not write code yet.\n\n### 4) Implement after agreement\n\n- Wait for the plan to be accepted or adjusted.\n- Implement the agreed changes, keeping the scope aligned to the plan.\n- If new information changes the plan, pause and confirm the update.\n\n### 5) Validate\n\n- Run the repo check command, prefer `yarn run check` unless a no-auto-fix run is required.\n- Ensure tests, build, lint, end-to-end, and complexity or code stats pass as required by the project.\n- Report command outcomes and any remaining gaps.\n"},"lastSynced":"2026-03-08T02:07:32.783Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing advanced investigation and planning capabilities for changesets.","zh":"非常适合需要高级调查和规划功能的代码审查代理，用于更改集。","ja":"コードレビュー代理が変更セットの高度な調査と計画機能を必要とする場合に最適です。","ko":"변경 세트에 대한 고급 조사 및 계획 기능이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan capacidades de investigación y planificación avanzadas para conjuntos de cambios.","fr":"Parfait pour les Agents de Revue de Code ayant besoin de capacités d''enquête et de planification avancées pour les jeux de modifications.","de":"Perfekt für Code-Review-Agenten, die erweiterte Untersuchungs- und Planungsfunktionen für Änderungssätze benötigen.","pt":"Perfeito para Agentes de Revisão de Código que necessitam de capacidades de investigação e planejamento avançadas para changesets.","ru":"Идеально подходит для агентов кодового обзора, которым необходимы расширенные возможности расследования и планирования для наборов изменений.","ar":"مثالي للوكلاء مراجعة الكود الذين يحتاجون إلى قدرات تحقيق وتخطيط متقدمة للchangesets."},"recommendation":{"en":"Empowers agents to streamline the investigation process by researching external sources, inspecting codebase areas, and creating a plan for changesets using GitHub CLI and open clarifying questions.","zh":"通过研究外部资源、检查代码库区域、使用 GitHub CLI 和开放性问题创建更改集计划，实现代理调查流程的简化。","ja":"GitHub CLI およびオープンな質問を使用して、外部リソースの調査、コードベースの領域の調査、変更セットの計画の作成により、エージェントの調査プロセスを合理化します。","ko":"외부 리소스 조사, 코드베이스 영역 조사, GitHub CLI 및 공개 질문을 사용하여 변경 세트 계획을 생성하여 에이전트의 조사 프로세스를 간소화합니다.","es":"Permite a los agentes simplificar el proceso de investigación mediante la búsqueda de fuentes externas, la inspección de áreas del código base y la creación de un plan para los conjuntos de cambios utilizando GitHub CLI y preguntas clarificadoras abiertas.","fr":"Permet aux agents de rationaliser le processus d''enquête en recherchant des sources externes, en inspectant des zones du code base et en créant un plan pour les jeux de modifications à l''aide de GitHub CLI et de questions clarificatrices ouvertes.","de":"Ermächtigt Agenten, den Untersuchungsprozess zu rationalisieren, indem sie externe Quellen recherchieren, Bereiche des Codebases untersuchen und mithilfe von GitHub CLI und offenen Klärungsfragen einen Plan für Änderungssätze erstellen.","pt":"Habilita os agentes a agilizar o processo de investigação, pesquisando fontes externas, inspecionando áreas do codebase e criando um plano para changesets usando GitHub CLI e esclarecendo perguntas.","ru":"Наделяет агентов возможностью оптимизировать процесс расследования, изучая внешние источники, инспектируя области кодовой базы и создавая план для наборов изменений с помощью GitHub CLI и открытых вопросов для уточнения.","ar":"يمنح الوكلاء القدرة على تسريع عملية التحقيق، من خلال البحث في المصادر الخارجية، وفحص مناطق قاعدة الشفرة، وإنشاء خطة للchangesets باستخدام GitHub CLI والأسئلة الإيضاحية المفتوحة."},"useCases":{"en":["Researching external sources for feature implementation","Inspecting codebase areas for bug fixes","Generating plans for changesets before writing code"],"zh":["研究外部资源以实现功能实现","检查代码库区域以修复错误","在编写代码之前为更改集生成计划"],"ja":["機能実装のための外部リソースの調査","バグ修正のためのコードベースの領域の調査","コードを書く前に変更セットの計画を生成"],"ko":["기능 구현을 위한 외부 리소스 조사","버그 수정을 위한 코드베이스 영역 조사","코드를 작성하기 전에 변경 세트 계획을 생성"],"es":["Investigación de fuentes externas para la implementación de características","Inspección de áreas del código base para correcciones de errores","Generación de planes para conjuntos de cambios antes de escribir código"],"fr":["Recherche de sources externes pour la mise en œuvre de fonctionnalités","Inspection de zones du code base pour les corrections de bogues","Génération de plans pour les jeux de modifications avant d''écrire du code"],"de":["Recherche externer Quellen für die Implementierung von Funktionen","Untersuchung von Bereichen des Codebases für Fehlerkorrekturen","Erstellung von Plänen für Änderungssätze vor dem Schreiben von Code"],"pt":["Pesquisando fontes externas para implementação de recursos","Inspecionando áreas do codebase para correções de bugs","Gerando planos para changesets antes de escrever código"],"ru":["Изучение внешних источников для реализации функций","Инспекция областей кодовой базы для исправления ошибок","Генерация планов для наборов изменений до написания кода"],"ar":["البحث في المصادر الخارجية لتنفيذ الميزات","فحص مناطق قاعدة الشفرة لتصحيح الأخطاء","توليد خطط للchangesets قبل كتابة الشفرة"]},"limitations":{"en":["Requires GitHub CLI access","Limited to codebase inspection and planning"],"zh":["需要 GitHub CLI 访问","仅限代码库检查和规划"],"ja":["GitHub CLI アクセスが必要","コードベースの検査と計画のみ"],"ko":["GitHub CLI 액세스가 필요","코드베이스 검사 및 계획만"],"es":["Requiere acceso a GitHub CLI","Limitado a la inspección del código base y la planificación"],"fr":["Nécessite un accès à GitHub CLI","Limité à l''inspection du code base et à la planification"],"de":["Benötigt Zugriff auf GitHub CLI","Begrenzt auf die Untersuchung des Codebases und die Planung"],"pt":["Exige acesso ao GitHub CLI","Limitado à inspeção do codebase e planejamento"],"ru":["Требует доступа к GitHub CLI","Ограничен инспекцией кодовой базы и планированием"],"ar":["يتطلب الوصول إلى GitHub CLI","محدود bằng فحص قاعدة الشفرة والتخطيط"]},"version":4},"contentHash":"17288fe84b952637175e5560bbc78a2e1ea5aa2b2483de59eb539b10f50385e8","qualityScore":23}');
