INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rocket-generator/next-template/database-schema-design', 'database-schema-design', 'rocket-generator', 'next-template', 'community', 'database-schema-design rocket-generator next-template community The database-schema-design skill provides guidelines for designing relational database schemas, specifically for PostgreSQL. It benefits developers by establishing a unified set of rules for database design, making maintenance easier and reducing conflicts. 数据库架构设计是数据存储和管理的关键步骤，本指南提供了表名、主键和RDBMS系统选定的最佳实践 データベーススキーマ設計はデータの保存と管理において重要なステップです。このガイドでは、テーブル名、主キー、RDBMSシステム選定のベストプラクティスを提供します 데이터베이스 스키마 설계는 데이터 저장 및 관리의 중요한 단계입니다. 이 가이드는 테이블 이름, 기본 키 및 RDBMS 시스템 선택에 대한 모범 사례를 제공합니다 El diseño de esquema de base de datos es crucial para una base de datos relacional bien organizada. Aprenda a diseñar esquemas con PostgreSQL La conception de schéma de base de données est essentielle pour une base de données relationnelle bien organisée. Découvrez comment concevoir des schémas avec PostgreSQL Das Datenbank-Schemadesign ist entscheidend für eine gut organisierte relationale Datenbank. Erfahren Sie, wie Sie Schemata mit PostgreSQL entwerfen Desenvolva esquemas de banco de dados robustos e escaláveis com PostgreSQL, seguindo as diretrizes de design de tabelas e chaves primárias Разрабатывайте надежные и масштабируемые схемы базы данных с помощью PostgreSQL, следуя рекомендациям по проектированию таблиц и первичных ключей от ИИ Агентов طور مخططات قواعد البيانات القوية والمرنة مع PostgreSQL، متبعة إرشادات تصميم الجداول والمفاتيح الرئيسية مع أدوات الذكاء الاصطناعي how to design database schema PostgreSQL database schema setup RDBMS schema design best practices database-schema-design vs entity-relationship modeling database-schema-design install guide what is database-schema-design database-schema-design alternative tools database-schema-design for AI agents database-schema-design tutorial 数据库架构设计 关系型数据库 PostgreSQL 表名设计 主键设计 RDBMS系统选定 数据存储 数据管理 Utilizes PostgreSQL as the primary RDBMS Enforces table naming conventions using plural nouns Specifies primary key column names as ''id'' Avoids using ''data'' as a table name due to ambiguity Excludes singular nouns and words with the same form in singular and plural database-schema-design is a set of rules and guidelines for designing and developing relational database schemas, focusing on PostgreSQL and RDBMS systems.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rrih/rrih.github.io/achievement-tree-design-system', 'community', 'rrih', 'rrih.github.io', 'rrih/rrih.github.io', 'achievement-tree-design-system', 0, 0, 23, '2026-03-08T01:57:15.434Z', '2026-03-08T02:07:35.657Z', 'b962197957c5ccd1805b34e45a77e48bcda0c76a7d9208e85f995575a76341b5', '{"id":"rrih/rrih.github.io/achievement-tree-design-system","name":"achievement-tree-design-system","description":{"en":"The achievement-tree-design-system skill generates custom UI designs that feel crafted, not default. It benefits developers who want to create unique and consistent user interfaces.","zh":"Achievement Tree 设计系统是一种用于创建独特 AI エージェント界面的设计方法，通过定义一致的布局节奏和视觉系统来实现个性化设计","ja":"Achievement Tree デザインシステムは、独自の AI エージェント UI を作成するための設計方法で、一貫したレイアウトリズムと視覚システムを定義することで、カスタマイズされたデザインを実現します","ko":"Achievement Tree 디자인 시스템은 고유한 AI 에이전트 인터페이스를 만들기 위한 디자인 방법으로 일관된 레이아웃 리듬과 시각 시스템을 정의하여 개성 있는 디자인을 구현합니다","es":"Achievement-tree-design-system es un sistema de diseño que permite crear interfaces de usuario personalizadas y coherentes para agentes de IA, utilizando un conjunto pequeño de elementos primitivos y un ritmo de diseño consistente","fr":"Achievement-tree-design-system est un système de conception qui permet de créer des interfaces utilisateur personnalisées et cohérentes pour les outils d''IA, en utilisant un petit ensemble d''éléments primitifs et un rythme de conception cohérent","de":"Achievement-tree-design-system ist ein Designsystem, das die Erstellung von benutzerdefinierten und konsistenten Benutzeroberflächen für KI-Agenten ermöglicht, unter Verwendung eines kleinen Satzes von Primitiven und eines konsistenten Designrhythmus","pt":"O sistema de design de árvore de conquistas permite criar uma UI personalizada e coesa, com um ritmo de layout consistente","ru":"Система дизайна дерева достижений позволяет создать индивидуальный и последовательный интерфейс пользователя, с единым ритмом расположения элементов","ar":"نظام تصميم شجرة الإنجازات يسمح بإنشاء واجهة مستخدم فريدة ومتسقة، مع إيقاع تخطيط موحد"},"seo":{"title":{"en":"achievement-tree-design-system: Custom UI Design Setup Gu...","zh":"AIエージェント个性化设计系统 - Achievement Tree 设计指南","ja":"AIエージェント用 Achievement Tree デザインシステム セットアップガイド","ko":"AI 에이전트를 위한 Achievement Tree 디자인 시스템 구축 방법","es":"Guía de configuración de achievement-tree-design-system p...","fr":"Mise en place de achievement-tree-design-system pour les ...","de":"Einrichtungsleitfaden für achievement-tree-design-system ...","pt":"Configurando o Sistema de Design de Árvore de Conquistas","ru":"ИИ Агенты: Руководство по Настройке Системы Дизайна Дерев...","ar":"إعداد نظام تصميم شجرة الإنجازات مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create unique UIs with achievement-tree-design-system. Learn to avoid generic patterns and create coherent designs with a small set of primit...","zh":"了解 Achievement Tree 设计系统如何帮助您创建独特的 AI エージェント界面，摆脱默认风格，实现个性化设计","ja":"Achievement Tree デザインシステムを使用して、独自の AI エージェント UI を作成しましょう。カスタマイズされたデザインを実現するためのベストプラクティス","ko":"AI 에이전트의 고유한 인터페이스를 만들기 위해 Achievement Tree 디자인 시스템을 사용하는 방법을 알아보세요. 기본 스타일을 탈피한 개성 있는 디자인을 구현하는 방법","es":"Aprende a crear una UI personalizada con achievement-tree-design-system, evitando patrones genéricos y creando una experiencia de usuario única para tus agen...","fr":"Découvrez comment concevoir une UI sur mesure avec achievement-tree-design-system, en évitant les modèles génériques et en créant une expérience utilisateur ...","de":"Erfahren Sie, wie Sie mit achievement-tree-design-system eine benutzerdefinierte Benutzeroberfläche erstellen, generische Muster vermeiden und eine einzigart...","pt":"Aprenda a criar uma UI personalizada com o sistema de design de árvore de conquistas, sem depender de CSS global ou Tailwind","ru":"Откройте для себя, как создать уникальный интерфейс пользователя с помощью системы дизайна дерева достижений, без использования глобального CSS или Tailwind","ar":"اكتشف كيفية إنشاء واجهة مستخدم فريدة باستخدام نظام تصميم شجرة الإنجازات، دون الاعتماد على CSS العالمي أو Tailwind"},"definition":{"en":"achievement-tree-design-system is a design system that produces custom UIs with a consistent rhythm, using a base spacing unit of 8px and avoiding generic patterns.","zh":"Achievement Tree 设计系统是一种用于创建独特 AI エージェント界面的设计方法","ja":"Achievement Tree デザインシステムは、独自の AI エージェント UI を作成するための設計方法","ko":"Achievement Tree 디자인 시스템은 고유한 AI 에이전트 인터페이스를 만들기 위한 디자인 방법","es":"Achievement-tree-design-system es un sistema de diseño que permite crear interfaces de usuario personalizadas y coherentes para agentes de IA","fr":"Achievement-tree-design-system est un système de conception qui permet de créer des interfaces utilisateur personnalisées et cohérentes pour les outils d''IA","de":"Achievement-tree-design-system ist ein Designsystem, das die Erstellung von benutzerdefinierten und konsistenten Benutzeroberflächen für KI-Agenten ermöglicht","pt":"O sistema de design de árvore de conquistas é um conjunto de diretrizes para criar uma UI personalizada e coesa","ru":"Система дизайна дерева достижений - это набор руководств для создания индивидуального и последовательного интерфейса пользователя","ar":"نظام تصميم شجرة الإنجازات هو مجموعة من الإرشادات لإنشاء واجهة مستخدم فريدة ومتسقة"},"features":{"en":["Uses Shadow DOM to ship its own reset and styles","Avoids generic card and soft shadow patterns","Employs a small, coherent set of primitives with consistent rhythm","Defines a layout rhythm with a base spacing unit of 8px","Creates custom UI designs that feel crafted, not default"],"zh":["使用一致的布局节奏","定义视觉系统","避免默认的全局 CSS 样式","使用 Shadow DOM 实现独立的样式","小巧、连贯的基本组件"],"ja":["一貫したレイアウトリズムを使用","視覚システムを定義","既定のグローバル CSS スタイルを避ける","Shadow DOM を使用して独立したスタイルを実現","小さくて一貫した基本コンポーネント"],"ko":["일관된 레이아웃 리듬을 사용","시각 시스템을 정의","기본적인 전역 CSS 스타일을 피함","Shadow DOM을 사용하여 독립적인 스타일을 구현","작고 일관된 기본 구성 요소"],"es":["Diseño de interfaz de usuario personalizada sin頼ar en CSS/Tailwind existente","Uso de un conjunto pequeño de elementos primitivos con ritmo de diseño consistente","Evitación de patrones genéricos como ''tarjeta + sombra suave + borde redondeado''","Uso de un espaciado base de 8px para el ritmo de diseño","Creación de una experiencia de usuario única y coherente para agentes de IA"],"fr":["Conception d''une interface utilisateur personnalisée sans dépendance à CSS/Tailwind existant","Utilisation d''un petit ensemble d''éléments primitifs avec un rythme de conception cohérent","Évitement des modèles génériques tels que ''carte + ombre douce + bord arrondi''","Utilisation d''un espacement de base de 8px pour le rythme de conception","Création d''une expérience utilisateur unique et cohérente pour les outils d''IA"],"de":["Erstellung von benutzerdefinierten Benutzeroberflächen ohne Abhängigkeit von vorhandenem CSS/Tailwind","Verwendung eines kleinen Satzes von Primitiven mit konsistentem Designrhythmus","Vermeidung von generischen Mustern wie ''Karte + weicher Schatten + abgerundeter Rand''","Verwendung eines Basis-Abstands von 8px für den Designrhythmus","Erstellung einer einzigartigen und konsistenten Benutzererfahrung für KI-Agenten"],"pt":["Utiliza um pequeno conjunto de primitivas com ritmo consistente","Base de espaçamento de 8px para layout","Evita padrões genéricos de cartão e sombra","Permite a criação de uma UI personalizada e coesa","Não depende de CSS global ou Tailwind"],"ru":["Использует небольшой набор примитивов с последовательным ритмом","Базовая единица расстояния 8px для расположения элементов","Избегает общих шаблонов карт и тени","Позволяет создать индивидуальный и последовательный интерфейс пользователя","Не зависит от глобального CSS или Tailwind"],"ar":["يستخدم مجموعة صغيرة من البريمتيفات مع إيقاع موحد","وحدة المسافة الأساسية 8px لترتيب العناصر","يتجنب الأنماط العامة للبطاقات والظلال","يسمح بإنشاء واجهة مستخدم فريدة ومتسقة","لا يعتمد على CSS العالمي أو Tailwind"]},"keywords":{"en":["how to use achievement-tree-design-system","achievement-tree-design-system alternative","achievement-tree-design-system setup guide","custom UI design with Shadow DOM","avoiding generic card patterns in UI design","achievement-tree-design-system vs material design"],"zh":["AIエージェント设计","Achievement Tree 设计系统","个性化设计","Shadow DOM","CSS 样式","布局节奏","视觉系统"],"ja":["AIエージェント設計","Achievement Tree デザインシステム","カスタマイズされたデザイン","Shadow DOM","CSS スタイル","レイアウトリズム","視覚システム"],"ko":["AI 에이전트 디자인","Achievement Tree 디자인 시스템","개성 있는 디자인","Shadow DOM","CSS 스타일","레이아웃 리듬","시각 시스템"],"es":["achievement-tree-design-system","agentes de IA","diseño de interfaz de usuario","sistema de diseño"," Shadow DOM","CSS personalizado"," Tailwind","ritmo de diseño","patrones de diseño"],"fr":["achievement-tree-design-system","outils d''IA","conception d''interface utilisateur","système de conception","Shadow DOM","CSS personnalisé","Tailwind","rythme de conception","modèles de conception"],"de":["achievement-tree-design-system","KI-Agenten","Benutzeroberflächendesign","Designsystem","Shadow DOM","benutzerdefiniertes CSS","Tailwind","Designrhythmus","Designmuster"],"pt":["sistema de design de árvore de conquistas","UI personalizada","ritmo de layout consistente","primitivas de design","CSS personalizado","Tailwind","desenvolvimento de interfaces de usuário","design de experiência do usuário"],"ru":["ИИ Агенты","система дизайна дерева достижений","индивидуальный интерфейс пользователя","последовательный ритм расположения элементов","примитивы дизайна","CSS настройка","Tailwind","разработка интерфейсов пользователя","дизайн пользовательского опыта"],"ar":["أدوات الذكاء الاصطناعي","نظام تصميم شجرة الإنجازات","واجهة مستخدم فريدة","إيقاع تخطيط موحد","بريمتيفات التصميم","CSS مخصص","Tailwind","تطوير واجهات المستخدم","تصميم تجربة المستخدم"]}},"owner":"rrih","repo":"rrih.github.io","repoPath":"rrih/rrih.github.io","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.434Z","topics":[],"category":"community","skillMd":{"name":"achievement-tree-design-system","description":"Use when building UI for the achievement-tree app. Enforces a distinctive, zero-base visual + interaction system (NOT generic Codex UI).","bodyPreview":"# Goal\nProduce a UI that does NOT look like default agent-generated apps. It must feel like a crafted product.\n\n# Non-negotiables\n- No reliance on existing global CSS/Tailwind look. The app UI lives in Shadow DOM and ships its own reset + styles.\n- Avoid generic \"card + soft shadow + rounded-lg + gray background\" patterns unless explicitly justified.\n- Use a small, coherent set of primitives with consistent rhythm.\n\n# Visual system (define + follow)\n1) Layout rhythm\n- Base spacing unit: 8px. Use","body":"# Goal\nProduce a UI that does NOT look like default agent-generated apps. It must feel like a crafted product.\n\n# Non-negotiables\n- No reliance on existing global CSS/Tailwind look. The app UI lives in Shadow DOM and ships its own reset + styles.\n- Avoid generic \"card + soft shadow + rounded-lg + gray background\" patterns unless explicitly justified.\n- Use a small, coherent set of primitives with consistent rhythm.\n\n# Visual system (define + follow)\n1) Layout rhythm\n- Base spacing unit: 8px. Use 8/16/24/32/48… only.\n- Typography: define a clear scale (e.g. 12/14/16/20/28/36) and apply intentionally.\n- Use high-contrast text by default. Avoid washed-out gray UI.\n\n2) Shape language\n- Choose one distinctive shape rule and stick to it:\n  - Option: “squircle-ish” nodes + sharp UI chrome\n  - Option: “hard-edge” UI + playful node shapes\n- Buttons are not default rectangles. Define a signature.\n\n3) Motion language (crucial for delight)\n- Micro-interactions are springy and responsive (but not noisy).\n- Panning has subtle inertia; zoom anchors to cursor position.\n- Node add/edit/done transitions must communicate cause→effect.\n\n4) Color strategy\n- Use a limited palette with one accent + one warning + one success.\n- URL capacity meter has a memorable, instrument-like look (not a plain progress bar).\n\n# Interaction principles\n- Every frequent action is 1–2 steps max: add child, edit title, toggle collapse, mark done.\n- Inline edit is default; avoid form-heavy panels.\n- Provide keyboard paths: Enter confirm, Esc cancel, Tab add child, Cmd/Ctrl+Z undo.\n\n# Deliverables expectation\nBefore coding, draft a “UI spec summary” in the response:\n- palette tokens\n- type scale\n- spacing scale\n- shape rules\n- motion rules (durations + easing/spring)\nThen implement to match.\n"},"lastSynced":"2026-03-08T02:07:35.657Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing custom UI design capabilities with Shadow DOM and CSS reset.","zh":"非常适合需要自定义UI设计能力的前端代理，具有Shadow DOM和CSS重置功能。","ja":"Shadow DOMとCSSリセットを使用したカスタムUIデザイン機能を必要とするフロントエンドエージェントに最適です。","ko":"Shadow DOM과 CSS 리셋을 사용한 사용자 정의 UI 디자인 기능이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para agentes Frontend que necesitan capacidades de diseño de UI personalizadas con Shadow DOM y restablecimiento de CSS.","fr":"Parfait pour les agents Frontend ayant besoin de capacités de conception d''interface utilisateur personnalisées avec Shadow DOM et reset CSS.","de":"Perfekt für Frontend-Agents, die benutzerdefinierte UI-Designfunktionen mit Shadow DOM und CSS-Reset benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de capacidades de design de UI personalizadas com Shadow DOM e reset de CSS.","ru":"Идеально подходит для агентов Frontend, которым необходимы настраиваемые возможности дизайна UI с использованием Shadow DOM и сброса CSS.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى إمكانيات تصميم واجهة المستخدم المخصصة مع Shadow DOM وإعادة تعيين CSS."},"recommendation":{"en":"Empowers agents to generate unique and consistent user interfaces with a small, coherent set of primitives, consistent rhythm, and custom layout spacing units, avoiding generic patterns and leveraging Shadow DOM for isolated styling.","zh":"赋予代理生成独特且一致的用户界面，具有小型、连贯的原语集、一致的节奏和自定义布局间距单位，避免通用模式并利用Shadow DOM进行隔离样式。","ja":"Shadow DOMを使用してスタイルを分離し、少量のまとまりのあるプリミティブ、一定のリズム、およびカスタムレイアウト間隔ユニットを使用して、独自で一貫したユーザーインターフェイスを生成できるエージェントをエンパワーします。","ko":"_shadow DOM을 사용하여 스타일을 분리하고, 작은 규모의 일관된 원시集合, 일관된 리듬 및 사용자 지정 레이아웃 간격 단위를 사용하여 고유하고 일관된 사용자 인터페이스를 생성할 수 있는 에이전트를 강화합니다.","es":"Habilita a los agentes a generar interfaces de usuario únicas y coherentes con un pequeño conjunto coherente de primitivas, ritmo consistente y unidades de espaciado de diseño personalizadas, evitando patrones genéricos y aprovechando Shadow DOM para estilos aislados.","fr":"Permet aux agents de générer des interfaces utilisateur uniques et cohérentes avec un petit ensemble cohérent de primitives, un rythme constant et des unités d''espacement de disposition personnalisées, en évitant les modèles génériques et en exploitant Shadow DOM pour un style isolé.","de":"Ermöglicht es den Agenten, einzigartige und konsistente Benutzeroberflächen mit einem kleinen, kohärenten Satz von Primitiven, konsistentem Rhythmus und benutzerdefinierten Layout-Abständen zu generieren, vermeidet dabei generische Muster und nutzt Shadow DOM für isolierte Stilvorlagen.","pt":"Permite que os agentes gerem interfaces de usuário únicas e coerentes com um pequeno conjunto coeso de primitivos, ritmo consistente e unidades de espaçamento de layout personalizadas, evitando padrões genéricos e aproveitando Shadow DOM para estilização isolada.","ru":"Наделяет агентов возможностью генерировать уникальные и последовательные пользовательские интерфейсы с помощью небольшого, сплоченного набора примитивов, последовательного ритма и настраиваемых единиц расположения макета, избегая общих шаблонов и используя Shadow DOM для изолированного стиля.","ar":"تمكّن الوكلاء من توليد واجهات مستخدم فريدة ومنسقة مع مجموعة صغيرة متجانسة من البدائيات، وإيقاع منتظم، ووحدات مساحة تخطيط مخصصة، وتجنب الأنماط العامة وت활ية Shadow DOM لتحسين التخطيط المعزول."},"useCases":{"en":["Designing custom UI components with 8px base spacing unit","Creating consistent visual systems with custom CSS reset and styles","Avoiding generic card-based layouts with soft shadows and rounded corners"],"zh":["使用8px基间距单位设计自定义UI组件","使用自定义CSS重置和样式创建一致的视觉系统","避免使用带有软阴影和圆角的通用卡片布局"],"ja":["8pxベースの間隔ユニットを使用してカスタムUIコンポーネントを設計する","カスタムCSSリセットとスタイルを使用して一貫した視覚システムを作成する","ソフトシャドウと丸みを帯びた角を持つ汎用カードレイアウトを避ける"],"ko":["8px 기본 간격 유닛을 사용하여 사용자 정의 UI 구성 요소를 설계하는 것","사용자 지정 CSS 리셋 및 스타일을 사용하여 일관된 시각적 시스템을 생성하는 것","소프트 섀도우 및 둥근 모서리가 있는 일반적인 카드 레이아웃을 피하는 것"],"es":["Diseñar componentes de UI personalizados con una unidad de espaciado base de 8 píxeles","Crear sistemas visuales coherentes con restablecimiento de CSS personalizado y estilos","Evitar diseños de tarjeta genéricos con sombras suaves y esquinas redondeadas"],"fr":["Concevoir des composants d''interface utilisateur personnalisés avec une unité d''espacement de base de 8 pixels","Créer des systèmes visuels cohérents avec un reset CSS personnalisé et des styles","Éviter les dispositions de carte génériques avec des ombres douces et des coins arrondis"],"de":["Benutzerdefinierte UI-Komponenten mit einer Basisabständeinheit von 8 Pixeln entwerfen","Konsistente visuelle Systeme mit benutzerdefiniertem CSS-Reset und Stilen erstellen","Vermeidung generischer Kartenlayouts mit weichen Schatten und abgerundeten Ecken"],"pt":["Projetar componentes de UI personalizados com unidade de espaçamento base de 8px","Criar sistemas visuais coerentes com reset de CSS personalizado e estilos","Evitar layouts baseados em cartões genéricos com sombras suaves e cantos arredondados"],"ru":["Проектировать настраиваемые компоненты UI с базовой единицей интервала 8px","Создавать последовательные визуальные системы с настраиваемым сбросом CSS и стилями","Избегать общих макетов на основе карточек с мягкими тенями и закругленными углами"],"ar":["تصميم مكونات واجهة المستخدم المخصصة مع وحدة مسافة أساسية 8px","إنشاء أنظمة بصرية متسقة مع إعادة تعيين CSS المخصصة والأسلوب","تجنب تخطيطات القائمة على بطاقات عامة مع ظلال ناعمة وأركان مدورة"]},"limitations":{"en":["No reliance on existing global CSS/Tailwind look","Requires custom CSS reset and styles to be shipped with the app","Limited to using a small, coherent set of primitives with consistent rhythm"],"zh":["不依赖现有的全局CSS/Tailwind外观","需要将自定义CSS重置和样式与应用程序一起提供","仅限使用小型、连贯的原语集和一致的节奏"],"ja":["既存のグローバルCSS/Tailwindの外観に依存しない","カスタムCSSリセットとスタイルをアプリと共に提供する必要がある","小さなまとまりのあるプリミティブと一定のリズムのみを使用する"],"ko":["既存의 전역 CSS/Tailwind 外観에 의존하지 않는다.","사용자 지정 CSS 리셋 및 스타일을 앱과 함께 제공해야 한다.","작은 규모의 일관된 원시集合 및 일관된 리듬만 사용한다."],"es":["No confiar en el CSS global existente/Tailwind","Requiere un restablecimiento de CSS personalizado y estilos para ser enviado con la aplicación","Limitado a usar un pequeño conjunto coherente de primitivas con ritmo consistente"],"fr":["Ne pas s''appuyer sur le CSS global existant/Tailwind","Nécessite un reset CSS personnalisé et des styles pour être expédié avec l''application","Limité à l''utilisation d''un petit ensemble cohérent de primitives avec un rythme constant"],"de":["Keine Abhängigkeit von bestehendem globalen CSS/Tailwind","Benötigt benutzerdefiniertes CSS-Reset und Stile, die mit der App ausgeliefert werden","Begrenzt auf die Verwendung eines kleinen, kohärenten Satzes von Primitiven mit konsistentem Rhythmus"],"pt":["Sem dependência de CSS/Tailwind global existente","Exige reset de CSS personalizado e estilos para serem enviados com o aplicativo","Limitado a usar um pequeno conjunto coeso de primitivos com ritmo consistente"],"ru":["Нет зависимости от существующего глобального CSS/Tailwind","Требует настраиваемого сброса CSS и стилей для отправки с приложением","Ограничен использованием небольшого, сплоченного набора примитивов с последовательным ритмом"],"ar":["بدون الاعتماد على CSS/Tailwind العالمي الحالي","يتطلب إعادة تعيين CSS المخصصة والأسلوب لإرسالها مع التطبيق","محدود باستخدام مجموعة صغيرة متجانسة من البدائيات بإيقاع منتظم"]},"version":4},"contentHash":"b962197957c5ccd1805b34e45a77e48bcda0c76a7d9208e85f995575a76341b5","qualityScore":23}');
DELETE FROM skills_fts WHERE id = 'rrih/rrih.github.io/achievement-tree-design-system';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rrih/rrih.github.io/achievement-tree-design-system', 'achievement-tree-design-system', 'rrih', 'rrih.github.io', 'community', 'achievement-tree-design-system rrih rrih.github.io community The achievement-tree-design-system skill generates custom UI designs that feel crafted, not default. It benefits developers who want to create unique and consistent user interfaces. Achievement Tree 设计系统是一种用于创建独特 AI エージェント界面的设计方法，通过定义一致的布局节奏和视觉系统来实现个性化设计 Achievement Tree デザインシステムは、独自の AI エージェント UI を作成するための設計方法で、一貫したレイアウトリズムと視覚システムを定義することで、カスタマイズされたデザインを実現します Achievement Tree 디자인 시스템은 고유한 AI 에이전트 인터페이스를 만들기 위한 디자인 방법으로 일관된 레이아웃 리듬과 시각 시스템을 정의하여 개성 있는 디자인을 구현합니다 Achievement-tree-design-system es un sistema de diseño que permite crear interfaces de usuario personalizadas y coherentes para agentes de IA, utilizando un conjunto pequeño de elementos primitivos y un ritmo de diseño consistente Achievement-tree-design-system est un système de conception qui permet de créer des interfaces utilisateur personnalisées et cohérentes pour les outils d''IA, en utilisant un petit ensemble d''éléments primitifs et un rythme de conception cohérent Achievement-tree-design-system ist ein Designsystem, das die Erstellung von benutzerdefinierten und konsistenten Benutzeroberflächen für KI-Agenten ermöglicht, unter Verwendung eines kleinen Satzes von Primitiven und eines konsistenten Designrhythmus O sistema de design de árvore de conquistas permite criar uma UI personalizada e coesa, com um ritmo de layout consistente Система дизайна дерева достижений позволяет создать индивидуальный и последовательный интерфейс пользователя, с единым ритмом расположения элементов نظام تصميم شجرة الإنجازات يسمح بإنشاء واجهة مستخدم فريدة ومتسقة، مع إيقاع تخطيط موحد how to use achievement-tree-design-system achievement-tree-design-system alternative achievement-tree-design-system setup guide custom UI design with Shadow DOM avoiding generic card patterns in UI design achievement-tree-design-system vs material design AIエージェント设计 Achievement Tree 设计系统 个性化设计 Shadow DOM CSS 样式 布局节奏 视觉系统 Uses Shadow DOM to ship its own reset and styles Avoids generic card and soft shadow patterns Employs a small, coherent set of primitives with consistent rhythm Defines a layout rhythm with a base spacing unit of 8px Creates custom UI designs that feel crafted, not default achievement-tree-design-system is a design system that produces custom UIs with a consistent rhythm, using a base spacing unit of 8px and avoiding generic patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Swader/proce/progressive-centralization-starter', 'community', 'Swader', 'proce', 'Swader/proce', 'progressive-centralization-starter', 0, 0, 23, '2026-03-08T01:57:15.435Z', '2026-03-08T02:07:37.863Z', 'f63640ef645c0e7a34f67ae279de22688d0a924790227568e194cbb9dfcc11c4', '{"id":"Swader/proce/progressive-centralization-starter","name":"progressive-centralization-starter","description":{"en":"The progressive-centralization-starter skill enables developers to scaffold new projects and manage templates using bun run commands. It benefits developers working with web3 and page templates.","zh":"Progressive Centralization Starter提供了一个快速搭建新项目的方法，包括页面和Web3模板的创建和部署","ja":"プログレッシブ・セントラリゼーション・スターターは、新しいプロジェクトを迅速に構築するための方法を提供します。ページとWeb3テンプレートの作成とデプロイが含まれます","ko":"진행형 중앙화 스타터는 새로운 프로젝트를 빠르게 구축하는 방법을 제공합니다. 페이지 및 Web3 템플릿의 생성 및 배포가 포함됩니다","es":"Progressive Centralization Starter es una herramienta para scaffold de proyectos, que permite inicializar y configurar proyectos web3 y páginas con facilidad","fr":"Progressive Centralization Starter est un outil de scaffold de projets, qui permet d''initialiser et de configurer des projets web3 et des pages avec facilité","de":"Progressive Centralization Starter ist ein Tool für das Scaffolden von Projekten, das die Initialisierung und Konfiguration von web3-Projekten und Seiten erleichtert","pt":"O Progressive Centralization Starter é uma ferramenta para inicializar projetos com templates de page e web3, permitindo uma configuração rápida e fácil.","ru":"Progressive Centralization Starter - это инструмент для инициализации проектов с шаблонами page и web3, позволяющий быстро и легко настроить проект для ИИ Агентов","ar":"Progressive Centralization Starter هو أداة لتشغيل مشاريع مع قوالب صفحة وويب3، مما يسمح بإعداد سريع وسهل"},"seo":{"title":{"en":"Progressive-Centralization-Starter: Setup Guide for AI Ag...","zh":"渐进式集中化入门指南 - Progressive Centralization Starter","ja":"AIエージェントのプログレッシブ・セントラリゼーション・スターター設定ガイド","ko":"진행형 중앙화 스타터 설정 가이드 - Progressive Centralization Starter","es":"Guía de configuración de Progressive Centralization Starter","fr":"Guide de démarrage de Progressive Centralization Starter","de":"Einrichtungsleitfaden für Progressive Centralization Starter","pt":"Guia de Configuração do Progressive Centralization Starter","ru":"Настройка Progressive Centralization Starter: ИИ Агенты","ar":"دليل إعداد Progressive Centralization Starter"},"description":{"en":"Discover how to scaffold new projects with progressive-centralization-starter. Learn to initialize, build, and deploy templates with bun run commands.","zh":"使用Progressive Centralization Starter快速搭建新项目，包括页面和Web3模板，使用Bun运行和部署","ja":"AIエージェントのプログレッシブ・セントラリゼーション・スターターを使って新しいプロジェクトを迅速に構築しましょう。ページとWeb3テンプレートを使用し、Bunで実行とデプロイを行います","ko":"진행형 중앙화 스타터를 사용하여 새로운 프로젝트를 빠르게 구축하세요. 페이지 및 Web3 템플릿을 사용하고 Bun으로 실행 및 배포합니다","es":"Aprende a configurar y utilizar Progressive Centralization Starter con nuestros pasos y ejemplos prácticos","fr":"Découvrez comment configurer et utiliser Progressive Centralization Starter avec nos étapes et exemples pratiques","de":"Erfahren Sie, wie Sie Progressive Centralization Starter konfigurieren und verwenden können, mit unseren Schritten und praktischen Beispielen","pt":"Aprenda a configurar o Progressive Centralization Starter com nosso guia passo a passo, incluindo inicialização de projetos e deploy","ru":"Узнайте, как настроить Progressive Centralization Starter с нашей пошаговой инструкцией, включая инициализацию проектов и deploy, для ИИ Агентов","ar":"تعلم كيفية إعداد Progressive Centralization Starter باستخدام دليلنا الخطوة بخطوة، بما في ذلك초期 化 المشاريع و النشر"},"definition":{"en":"progressive-centralization-starter is a skill that provides a foundation for initializing and managing projects with web3 and page templates using bun run commands.","zh":"Progressive Centralization Starter是一个用于快速搭建新项目的工具，支持页面和Web3模板的创建和部署","ja":"プログレッシブ・セントラリゼーション・スターターは、新しいプロジェクトを迅速に構築するためのツールです。ページとWeb3テンプレートの作成とデプロイをサポートします","ko":"진행형 중앙화 스타터는 새로운 프로젝트를 빠르게 구축하는 데 사용되는 도구입니다. 페이지 및 Web3 템플릿의 생성 및 배포를 지원합니다","es":"Progressive Centralization Starter es una herramienta de desarrollo que permite scaffold de proyectos y configurar entornos de desarrollo","fr":"Progressive Centralization Starter est un outil de développement qui permet le scaffold de projets et la configuration d''environnements de développement","de":"Progressive Centralization Starter ist ein Entwicklungstool, das das Scaffolden von Projekten und die Konfiguration von Entwicklungsumgebungen ermöglicht","pt":"Progressive Centralization Starter é uma ferramenta de inicialização de projetos que fornece templates para page e web3","ru":"Progressive Centralization Starter - это инструмент инициализации проектов, предоставляющий шаблоны для page и web3, для ИИ Агентов","ar":"Progressive Centralization Starter هو أداة لتشغيل المشاريع التي توفر قوالب للصفحة وويب3"},"features":{"en":["Scaffolds new projects using `bun run init` commands","Supports web3 and page templates with `--template` option","Initializes projects with `bun install` and `.env` configuration","Builds and deploys templates using `bun run build` and `bun run deploy` commands","Previews templates with `bun run preview` command","Manages project setup with `.env.example` and `.env` files"],"zh":["支持页面和Web3模板的创建","使用Bun运行和部署项目","快速搭建新项目","支持.env文件配置","提供默认和自定义模板选项"],"ja":["ページとWeb3テンプレートの作成をサポート","Bunを使用してプロジェクトを実行とデプロイ","新しいプロジェクトを迅速に構築",".envファイルの設定をサポート","デフォルトとカスタムテンプレートの選択肢を提供"],"ko":["페이지 및 Web3 템플릿의 생성을 지원","Bun을 사용하여 프로젝트를 실행 및 배포","新的 프로젝트를 빠르게 구축",".env 파일 구성 지원","기본 및 사용자 지정 템플릿 옵션 제공"],"es":["Inicialización de proyectos con plantillas de página y web3","Configuración de entornos de desarrollo con bun install y bun run","Compatibilidad con comandos de construcción y despliegue de proyectos","Soporte para la creación de entornos de vista previa de proyectos","Integración con herramientas de desarrollo como bun y env"],"fr":["Initialisation de projets avec des modèles de page et web3","Configuration d''environnements de développement avec bun install et bun run","Compatibilité avec les commandes de construction et de déploiement de projets","Support pour la création d''environnements de prévisualisation de projets","Intégration avec des outils de développement tels que bun et env"],"de":["Initialisierung von Projekten mit Seitenvorlagen und web3-Vorlagen","Konfiguration von Entwicklungsumgebungen mit bun install und bun run","Kompatibilität mit Befehlen zum Erstellen und Bereitstellen von Projekten","Unterstützung für die Erstellung von Vorschauumgebungen für Projekte","Integration mit Entwicklungstools wie bun und env"],"pt":["Iniciação de projetos com templates de page e web3","Comandos CLI para inicializar, build e deploy de projetos","Suporte a variáveis de ambiente com .env","Opção de pré-visualização de projetos","Integração com bun para gerenciamento de dependências"],"ru":["Инициализация проектов с шаблонами page и web3","Команды CLI для инициализации, build и deploy проектов","Поддержка переменных окружения с .env","Вариант предварительного просмотра проектов","Интеграция с bun для управления зависимостями, для ИИ Агентов"],"ar":["تشغيل المشاريع مع قوالب الصفحة وويب3","أوامر CLI لتشغيل و بناء و نشر المشاريع","دعم متغيرات البيئة مع .env","خيار معاينة المشاريع","التكامل مع bun لإدارة الإعتماديات"]},"keywords":{"en":["how to use progressive-centralization-starter","progressive-centralization-starter setup guide","progressive-centralization-starter vs bun","progressive-centralization-starter install","what is progressive-centralization-starter","progressive-centralization-starter alternative","bun run commands for progressive-centralization-starter","progressive-centralization-starter template management","progressive-centralization-starter web3 development"],"zh":["Progressive Centralization Starter","页面模板","Web3模板","Bun","新项目搭建","渐进式集中化"],"ja":["AIエージェント","プログレッシブ・セントラリゼーション・スターター","ページテンプレート","Web3テンプレート","Bun","新しいプロジェクトを構築"],"ko":["AI 도구","진행형 중앙화 스타터","페이지 템플릿","Web3 템플릿","Bun","新的 프로젝트 구축"],"es":["Progressive Centralization Starter","herramientas de desarrollo","scaffold de proyectos","configuración de entornos de desarrollo","bun install","bun run","despliegue de proyectos","vista previa de proyectos","Agente de IA para desarrollo"],"fr":["Progressive Centralization Starter","outils de développement","scaffold de projets","configuration d''environnements de développement","bun install","bun run","déploiement de projets","prévisualisation de projets","Agent IA pour le développement"],"de":["Progressive Centralization Starter","Entwicklungstools","Scaffolden von Projekten","Konfiguration von Entwicklungsumgebungen","bun install","bun run","Bereitstellung von Projekten","Vorschau von Projekten","KI-Agent für die Entwicklung"],"pt":["progressive centralization starter","inicialização de projetos","templates de page e web3","bun","cli","variáveis de ambiente","pré-visualização de projetos","deploy de projetos"],"ru":["progressive centralization starter","инициализация проектов","шаблоны page и web3","bun","cli","переменные окружения","предварительный просмотр проектов","deploy проектов","ИИ Агенты"],"ar":["progressive centralization starter","تشغيل المشاريع","قوالب الصفحة وويب3","bun","cli","متغيرات البيئة","معاينة المشاريع","نشر المشاريع","أدوات الذكاء الاصطناعي"]}},"owner":"Swader","repo":"proce","repoPath":"Swader/proce","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.435Z","topics":[],"category":"community","skillMd":{"name":"progressive-centralization-starter","description":"Bootstrap Bun-based single-file frontends with Filebase/IPFS, ENS, and Arweave/ArNS deploy tooling. Use when creating a progressive centralization starter project, setting up .env-driven deploys, or when the user asks to just do it for IPFS/ENS/Arweave hosting.","bodyPreview":"# Progressive Centralization Starter\n\n## Scaffold a new project\n\n- `bun run init -- --template page --dest ./my-page`\n- `bun run init -- --template web3 --dest ./my-web3`\n\n## Quick start (inside a template project)\n\n1. `bun install`\n2. `cp .env.example .env`\n3. Fill `.env`\n4. `bun run default <template>` (optional)\n5. `bun run build <template>` (or `bun run build` if default set)\n6. `bun run deploy <template>` (or `bun run deploy` if default set)\n7. `bun run preview <template>` (optional)\n8. `bu","body":"# Progressive Centralization Starter\n\n## Scaffold a new project\n\n- `bun run init -- --template page --dest ./my-page`\n- `bun run init -- --template web3 --dest ./my-web3`\n\n## Quick start (inside a template project)\n\n1. `bun install`\n2. `cp .env.example .env`\n3. Fill `.env`\n4. `bun run default <template>` (optional)\n5. `bun run build <template>` (or `bun run build` if default set)\n6. `bun run deploy <template>` (or `bun run deploy` if default set)\n7. `bun run preview <template>` (optional)\n8. `bun run dev` (local Anvil + deploy + build)\n\n## Configuration essentials\n\n- Townsquare app: `APP_CHAINS_JSON`, `APP_DEFAULT_CHAIN_ID`, `TOWNSQUARE_ADDRESSES_JSON`\n- Filebase IPFS: `FILEBASE_BUCKET`, `FILEBASE_ROOT_KEY`, `FILEBASE_ROOT_SECRET`\n- ENS: `ENS_NAME`, `PRIVATE_KEY`, `APP_CHAINS_JSON`, `ENS_CHAIN_ID` (or `ENS_RPC_URL`), optional `ENS_NAMEWRAPPER_ADDRESS`\n- Optional Arweave/ArNS: `ARWEAVE_KEY` / `ARWEAVE_KEYFILE`, `ARNS_NAME` or `ARNS_PROCESS_ID`\n\n## Deploy flags\n\n- `--dry-run` (build + upload only)\n- `--skip-ens` (skip ENS update)\n- `--cid <cid>` (use an existing CID)\n- `--name <ens>` (override ENS name)\n- `--no-resolver-switch` (avoid auto-switching resolver)\n\n## Customize the frontend\n\n- `templates/<template>/src/main.ts`: UI logic\n- `templates/<template>/src/styles.css`: styles\n- `templates/<template>/src/template.html`: metadata + placeholders\n- `templates/<template>/public/`: optional static assets copied into `dist/`\n- `contracts/Townsquare.sol`: on-chain template contract\n\n## Guardrails\n\n- Use Bun for all commands; do not use npm or Node.\n- Never commit `.env` or wallet keys.\n"},"lastSynced":"2026-03-08T02:07:37.863Z","agentAnalysis":{"suitability":{"en":"Ideal for Web3 and Page Template Agents requiring streamlined project initialization and template management via bun run commands.","zh":"适用于需要简化项目初始化和模板管理的Web3和页面模板代理，通过bun run命令实现模板管理。","ja":"Web3とページテンプレートエージェントに最適で、bun runコマンドを介したプロジェクト初期化とテンプレート管理をストリームライン化します。","ko":"Web3 및 페이지 템플릿 에이전트에 적합하며 bun run 명령을 통해 프로젝트 초기화 및 템플릿 관리를 간소화합니다.","es":"Ideal para Agentes Web3 y de Plantilla de Página que requieren una inicialización de proyecto y una administración de plantillas optimizadas a través de comandos bun run.","fr":"Idéal pour les Agents Web3 et de Modèle de Page nécessitant une initialisation de projet et une gestion de modèles rationalisées via des commandes bun run.","de":"Ideal für Web3- und Seitenvorlagen-Agents, die eine optimierte Projektinitialisierung und eine Vorlagenverwaltung über bun-Befehle erfordern.","pt":"Ideal para Agentes Web3 e de Modelo de Página que exigem inicialização de projeto e gerenciamento de modelo simplificados via comandos bun run.","ru":"Идеально подходит для агентов Web3 и шаблонов страниц, требующих упрощенной инициализации проекта и управления шаблонами через команды bun run.","ar":"مثالي لعميل الويب 3 وعميل قوالب الصفحة الذين يتطلبون تهيئة مشروع ومدير قوالب مبسط عبر أوامر تشغيل bun."},"recommendation":{"en":"Empowers agents to scaffold new projects and manage templates efficiently using bun run init commands, supporting web3 and page templates with seamless integration of .env configuration and build, deploy, and preview capabilities.","zh":"赋予代理人使用bun run init命令快速搭建新项目和高效管理模板的能力，支持web3和页面模板，并实现.env配置和构建、部署、预览功能的无缝集成。","ja":"bun run initコマンドを使用して新しいプロジェクトを迅速に作成し、テンプレートを効率的に管理するエージェントの能力を提供し、web3とページテンプレートをサポートし、.env構成とビルド、デプロイ、プレビュー機能のシームレスな統合を実現します。","ko":"bun run init 명령을 사용하여 새로운 프로젝트를 신속하게 생성하고 템플릿을 효율적으로 관리하는 에이전트의 능력을 제공하며 web3 및 페이지 템플릿을 지원하며 .env 구성 및 빌드, 배포, 미리 보기 기능의 무결점 통합을 구현합니다.","es":"Habilita a los agentes para crear nuevos proyectos y administrar plantillas de manera eficiente utilizando comandos bun run init, que admiten plantillas web3 y de página con una integración perfecta de la configuración .env y las capacidades de compilación, implementación y vista previa.","fr":"Permet aux agents de créer de nouveaux projets et de gérer des modèles de manière efficace en utilisant des commandes bun run init, qui prennent en charge les modèles web3 et de page avec une intégration transparente de la configuration .env et des capacités de construction, de déploiement et d''aperçu.","de":"Ermächtigt Agents, neue Projekte zu erstellen und Vorlagen effizient zu verwalten, indem sie Befehle von bun run init verwenden, die Web3- und Seitenvorlagen unterstützen, mit nahtloser Integration der .env-Konfiguration und der Build-, Deploy- und Vorschau-Funktionen.","pt":"Habilita os agentes a criar novos projetos e gerenciar modelos de forma eficiente usando comandos bun run init, com suporte a modelos web3 e de página com integração perfeita da configuração .env e capacidades de compilação, implantação e visualização.","ru":"Предоставляет агентам возможность создавать новые проекты и управлять шаблонами эффективно, используя команды bun run init, поддерживающие шаблоны web3 и страниц с бесшовной интеграцией конфигурации .env и возможностями сборки, развертывания и просмотра.","ar":"تمكّن العميل من إنشاء مشاريع جديدة وإدارة القوالب بفعالية باستخدام أوامر bun run init، مع دعم قوالب الويب 3 وقوالب الصفحة مع التكامل السلس لتهيئة .env وقدرات البناء والنشر والمعاينة."},"useCases":{"en":["Scaffolding new web3 projects with customized templates","Initializing page template projects with automated .env setup","Streamlining build, deploy, and preview processes for web3 and page template projects"],"zh":["使用自定义模板搭建新的Web3项目","使用自动化的.env设置初始化页面模板项目","简化Web3和页面模板项目的构建、部署和预览过程"],"ja":["カスタマイズされたテンプレートを使用して新しいWeb3プロジェクトをスケッチする","自動化された.env設定を使用してページテンプレートプロジェクトを初期化する","Web3とページテンプレートプロジェクトのビルド、デプロイ、プレビューのプロセスをストリームライン化する"],"ko":["사용자 지정 템플릿을 사용하여 새로운 Web3 프로젝트를 스케치하는 것","자동화된 .env 설정을 사용하여 페이지 템플릿 프로젝트를 초기화하는 것","Web3 및 페이지 템플릿 프로젝트의 빌드, 배포, 미리 보기 프로세스를 간소화하는 것"],"es":["Creación de nuevos proyectos web3 con plantillas personalizadas","Inicialización de proyectos de plantillas de página con configuración automática de .env","Optimización de los procesos de compilación, implementación y vista previa para proyectos web3 y de plantillas de página"],"fr":["Création de nouveaux projets web3 avec des modèles personnalisés","Initialisation de projets de modèles de page avec une configuration automatique de .env","Optimisation des processus de construction, de déploiement et d''aperçu pour les projets web3 et de modèles de page"],"de":["Erstellung neuer Web3-Projekte mit benutzerdefinierten Vorlagen","Initialisierung von Seitenvorlagenprojekten mit automatischer .env-Konfiguration","Optimierung der Build-, Deploy- und Vorschau-Prozesse für Web3- und Seitenvorlagenprojekte"],"pt":["Criação de novos projetos web3 com modelos personalizados","Inicialização de projetos de modelo de página com configuração automática .env","Otimização dos processos de compilação, implantação e visualização para projetos web3 e de modelo de página"],"ru":["Создание новых проектов web3 с настраиваемыми шаблонами","Инициализация проектов шаблонов страниц с автоматической настройкой .env","Оптимизация процессов сборки, развертывания и просмотра для проектов web3 и шаблонов страниц"],"ar":["إنشاء مشاريع جديدة من الويب 3 مع قوالب مخصصة","تهيئة مشاريع قوالب الصفحة مع إعداد tự động .env","تحسين عمليات البناء والنشر والمعاينة لمشاريع الويب 3 وقوالب الصفحة"]},"limitations":{"en":["Requires bun installation and configuration","Limited to web3 and page template projects","Dependent on .env file configuration for project setup"],"zh":["需要安装和配置bun","仅限于Web3和页面模板项目","依赖于.env文件配置进行项目设置"],"ja":["bunのインストールと構成が必要","Web3とページテンプレートプロジェクトのみに限定される",".envファイル構成に依存してプロジェクトを設定する"],"ko":["bun 설치 및 구성이 필요","Web3 및 페이지 템플릿 프로젝트에만 국한됨",".env 파일 구성에 의존하여 프로젝트를 설정"],"es":["Requiere la instalación y configuración de bun","Limitado a proyectos web3 y de plantillas de página","Dependiente de la configuración del archivo .env para la configuración del proyecto"],"fr":["Nécessite l''installation et la configuration de bun","Limité aux projets web3 et de modèles de page","Dépend de la configuration du fichier .env pour la configuration du projet"],"de":["Benötigt die Installation und Konfiguration von bun","Begrenzt auf Web3- und Seitenvorlagenprojekte","Abhängig von der Konfiguration der .env-Datei für die Projektsetup"],"pt":["Exige instalação e configuração do bun","Limitado a projetos web3 e de modelo de página","Dependente da configuração do arquivo .env para configuração do projeto"],"ru":["Требует установки и настройки bun","Ограничен проектами web3 и шаблонами страниц","Зависит от конфигурации файла .env для настройки проекта"],"ar":["يتطلب تثبيت bun وتهيئته","محدود بمشاريع الويب 3 وقوالب الصفحة","يعتمد على تهيئة ملف .env لتهيئة المشروع"]},"version":4},"contentHash":"f63640ef645c0e7a34f67ae279de22688d0a924790227568e194cbb9dfcc11c4","qualityScore":23}');
