INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('duplojs/utils/writeJsDoc', 'writeJsDoc', 'duplojs', 'utils', 'community', 'writeJsDoc duplojs utils community writeJsDoc generates JSDoc comments for TypeScript utilities, benefiting developers working with @duplojs/utils. It creates structured index.md files with descriptions and examples. writeJsDoc 是一个用于生成 JSDoc 的工具，专注于强类型、好 DX 和小型可组合的原语，用于提高代码文档质量。 writeJsDoc は JSDoc を生成するためのツールであり、強い型付け、良い DX、および小さな構成可能なプライミティブに焦点を当ててコード文書化の質を高める。 writeJsDoc는 JSDoc를 생성하기 위한 툴로, 강한 타입 지정, 좋은 DX, 및 작은 구성 가능한 원자로 코드 문서화의 질을 높인다. writeJsDoc es una herramienta para generar documentación de JavaScript con JSDoc y TypeScript, enfocada en tipado fuerte y DX writeJsDoc est un outil pour générer une documentation JavaScript avec JSDoc et TypeScript, axé sur le typage fort et le DX writeJsDoc ist ein Tool zum Erstellen von JavaScript-Dokumentation mit JSDoc und TypeScript, mit Fokus auf starkes Typisieren und DX O writeJsDoc é uma ferramenta para criar documentação de código em JavaScript, com foco em estruturas obrigatórias e exemplos de uso writeJsDoc - это инструмент для создания документации кода на JavaScript, с фокусом на обязательных структурах и примерах использования для ИИ Агентов writeJsDoc هو أداة لإنشاء وثائق تعليمات برمجية بلغة JavaScript، مع التركيز على الهياكل الإلزامية والأمثلة على الاستخدام how to use writeJsDoc writeJsDoc setup guide JSDoc generation for TypeScript writeJsDoc alternative writeJsDoc vs TypeScript documentation tools generate JSDoc comments with writeJsDoc writeJsDoc install writeJsDoc for @duplojs/utils TypeScript utility documentation with writeJsDoc writeJsDoc JSDoc 代码文档 强类型 好 DX AIエージェント 代码文档化 JavaScript 文档 TypeScript Generates JSDoc comments in Markdown format Creates index.md files with descriptions, examples, and usage information Supports TypeScript utilities with strong typing and good DX Organizes JSDoc comments in a namespace and function-based structure Utilizes {@include} tags for example usage Follows a specific structure for index.md files writeJsDoc is a skill that generates JSDoc comments for TypeScript utilities, following a specific structure and organization.');
